// @ts-nocheck
// 자동 생성 — 'SQLD 이론/_mockups/*.html' 의 <article class="theory-md"> 본문 추출.
// 다시 빌드: node scripts/build-theory-html.mjs
//
// 각 챕터 HTML 은 양파단 디자인 토큰(src/index.css) 과 .theory-md 인포그래픽 스타일을 사용.

export const THEORY_HTML: Record<string, string> = {
  c111: "<!-- 핵심 요약 -->\n    <h2 class=\"section-label sec-summary reveal\"><span class=\"label-tag\">핵심 요약</span><span class=\"label-rest\">정의</span></h2>\n    <blockquote class=\"reveal\">\n      데이터 모델이란 현실의 정보를 데이터베이스(DB)에 담기 위해 그린 <strong>설계 도면</strong>이다.\n    </blockquote>\n    <div class=\"ex-box reveal\">\n      회원·상품·주문 같은 정보를 어떻게 저장하고 연결할지 미리 그려보는 작업이다. 정보의 덩어리는 <a href=\"#\" data-chapter=\"c112\">엔터티</a>, 세부 항목은 <a href=\"#\" data-chapter=\"c113\">속성</a>, 엔터티 간 연결은 <a href=\"#\" data-chapter=\"c114\">관계</a>로 표현한다.\n    </div>\n\n    <!-- 개념 도식화 — 모델링 단계 흐름 -->\n    <h2 class=\"section-label sec-diagram reveal\"><span class=\"label-tag\">개념 도식화</span><span class=\"label-rest\">한 비즈니스가 데이터베이스가 되기까지</span></h2>\n    <p class=\"reveal\">같은 쇼핑몰 사례가 단계별로 어떻게 구체화되는지 직접 본다.</p>\n\n    <div class=\"step-flow cols-4 reveal\">\n      <div class=\"step-card\">\n        <div class=\"step\">STEP 1</div>\n        <div class=\"name\">개념적 모델 <small>큰 그림</small></div>\n        <div class=\"ex\">핵심 엔터티·관계 ERD. 속성·자료형은 아직 안 본다.</div>\n        <div class=\"arrow-next\">›</div>\n      </div>\n      <div class=\"step-card\">\n        <div class=\"step\">STEP 2</div>\n        <div class=\"name\">논리적 모델 <small>속성·키</small></div>\n        <div class=\"ex\">속성·PK·FK 채움 + <strong>정규화</strong>. DBMS와 무관.</div>\n        <div class=\"arrow-next\">›</div>\n      </div>\n      <div class=\"step-card\">\n        <div class=\"step\">STEP 3</div>\n        <div class=\"name\">물리적 모델 <small>실제 DBMS</small></div>\n        <div class=\"ex\">CREATE TABLE + 인덱스·파티션·자료형 명시.</div>\n        <div class=\"arrow-next\">›</div>\n      </div>\n      <div class=\"step-card\">\n        <div class=\"step\">STEP 4</div>\n        <div class=\"name\">데이터베이스 <small>운영</small></div>\n        <div class=\"ex\">데이터가 차곡차곡 쌓인 상태. SQL로 조회·입력·수정.</div>\n      </div>\n    </div>\n\n    <h3 class=\"reveal\">1단계 — 개념적 모델 (큰 그림)</h3>\n    <p class=\"reveal\">업무에서 다루는 핵심 명사(엔터티)와 그 사이의 연결을 큰 그림으로 그린다.</p>\n    <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">// 회원 1 : N 주문</span>\n<span class=\"sql-cm\">// 주문 1 : N 주문상세  ←  N : 1 상품</span></code></pre>\n\n    <h3 class=\"reveal\">2단계 — 논리적 모델 (속성·키·정규화)</h3>\n    <p class=\"reveal\">각 엔터티의 속성을 채우고 PK·FK 를 정한다. 이 단계에서 <a href=\"#\" data-chapter=\"c121\">정규화</a>(1NF → 2NF → 3NF)도 함께 수행한다.</p>\n\n    <h3 class=\"reveal\">3단계 — 물리적 모델 (실제 DBMS 구현)</h3>\n    <p class=\"reveal\">논리 모델을 실제 데이터베이스의 <strong>테이블</strong>로 만든다. 자료형·인덱스·제약조건을 명시.</p>\n    <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">CREATE TABLE</span> <span class=\"sql-name\">MEMBER</span> (\n    <span class=\"sql-type\">MEMBER_ID</span>  <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">10</span>) <span class=\"sql-kw\">PRIMARY KEY</span>,\n    <span class=\"sql-type\">NAME</span>       <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">50</span>) <span class=\"sql-kw\">NOT NULL</span>,\n    <span class=\"sql-type\">PHONE</span>      <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">20</span>)\n);\n\n<span class=\"sql-kw\">CREATE TABLE</span> <span class=\"sql-name\">PRODUCT</span> (\n    <span class=\"sql-type\">PROD_ID</span>    <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">10</span>) <span class=\"sql-kw\">PRIMARY KEY</span>,\n    <span class=\"sql-type\">PROD_NAME</span>  <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">100</span>) <span class=\"sql-kw\">NOT NULL</span>,\n    <span class=\"sql-type\">PRICE</span>      <span class=\"sql-type\">NUMBER</span>(<span class=\"sql-num\">10</span>) <span class=\"sql-kw\">NOT NULL</span>\n);\n\n<span class=\"sql-kw\">CREATE TABLE</span> <span class=\"sql-name\">ORDERS</span> (\n    <span class=\"sql-type\">ORDER_ID</span>   <span class=\"sql-type\">NUMBER</span> <span class=\"sql-kw\">PRIMARY KEY</span>,\n    <span class=\"sql-type\">MEMBER_ID</span>  <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">10</span>) <span class=\"sql-kw\">REFERENCES</span> <span class=\"sql-name\">MEMBER</span>(<span class=\"sql-type\">MEMBER_ID</span>),\n    <span class=\"sql-type\">ORD_DATE</span>   <span class=\"sql-type\">DATE</span> <span class=\"sql-kw\">DEFAULT</span> <span class=\"sql-kw\">SYSDATE</span>\n);\n\n<span class=\"sql-kw\">CREATE INDEX</span> <span class=\"sql-name\">IDX_ORDERS_MEMBER</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-name\">ORDERS</span>(<span class=\"sql-type\">MEMBER_ID</span>);  <span class=\"sql-cm\">-- 성능용 인덱스</span></code></pre>\n\n    <h3 class=\"reveal\">4단계 — 데이터베이스 (운영 중인 실제 데이터)</h3>\n    <p class=\"reveal\">만든 테이블에 데이터가 <strong>차곡차곡 쌓인 상태</strong>. 사용자가 SQL 로 조회·입력·수정.</p>\n\n    <p class=\"reveal\" style=\"font-size:13.5px;color:var(--fg-3);margin-top:12px;\">MEMBER</p>\n    <table class=\"reveal\">\n      <thead><tr><th>MEMBER_ID</th><th>NAME</th><th>PHONE</th></tr></thead>\n      <tbody>\n        <tr><td>M01</td><td>김철수</td><td>010-1111</td></tr>\n        <tr><td>M02</td><td>이영희</td><td>010-2222</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\" style=\"font-size:13.5px;color:var(--fg-3);\">PRODUCT</p>\n    <table class=\"reveal\">\n      <thead><tr><th>PROD_ID</th><th>PROD_NAME</th><th>PRICE</th></tr></thead>\n      <tbody>\n        <tr><td>P01</td><td>사과</td><td>1,000</td></tr>\n        <tr><td>P02</td><td>배</td><td>2,000</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\" style=\"font-size:13.5px;color:var(--fg-3);\">ORDERS</p>\n    <table class=\"reveal\">\n      <thead><tr><th>ORDER_ID</th><th>MEMBER_ID</th><th>ORD_DATE</th></tr></thead>\n      <tbody>\n        <tr><td>1001</td><td>M01</td><td>2026-04-01</td></tr>\n        <tr><td>1002</td><td>M02</td><td>2026-04-05</td></tr>\n      </tbody>\n    </table>\n\n    <h3 class=\"reveal\">단계 정리</h3>\n    <table class=\"reveal\">\n      <thead><tr><th>단계</th><th>이름</th><th>결과물</th><th>비유</th></tr></thead>\n      <tbody>\n        <tr><td>1</td><td>개념적 모델링</td><td>핵심 엔터티·관계 ERD (큰 그림)</td><td>손으로 그린 스케치</td></tr>\n        <tr><td>2</td><td>논리적 모델링</td><td>속성·키 상세 ERD + <strong>정규화</strong></td><td>정식 건축 도면</td></tr>\n        <tr><td>3</td><td>물리적 모델링</td><td>DBMS 별 CREATE TABLE + 인덱스·파티션</td><td>시공 계획서</td></tr>\n        <tr><td>→</td><td>운영</td><td>데이터가 쌓인 실제 데이터베이스</td><td>입주 완료된 건물</td></tr>\n      </tbody>\n    </table>\n\n    <!-- 3가지 관점 -->\n    <h2 class=\"reveal\">데이터 모델링의 3가지 관점</h2>\n    <div class=\"cls-row reveal\">\n      <div class=\"cls-card\">\n        <span class=\"badge b-info\">DATA</span>\n        <div class=\"name\">데이터 관점</div>\n        <div class=\"ex\">업무가 관리하는 데이터(엔터티·속성)<br><strong>무엇을(What) 저장하지</strong></div>\n      </div>\n      <div class=\"cls-card\">\n        <span class=\"badge\">PROCESS</span>\n        <div class=\"name\">프로세스 관점</div>\n        <div class=\"ex\">업무가 실제 하고 있는 일(또는 해야 할 일)<br><strong>어떻게(How) 처리하지</strong></div>\n      </div>\n      <div class=\"cls-card\">\n        <span class=\"badge b-event\">INTERACTION</span>\n        <div class=\"name\">상관 관점</div>\n        <div class=\"ex\">프로세스가 데이터에 미치는 영향(CRUD 매트릭스)<br><strong>언제(When) 어떤 데이터가 변하지</strong></div>\n      </div>\n    </div>\n\n    <!-- 좋은 모델의 6대 특징 -->\n    <h2 class=\"reveal\">좋은 데이터 모델의 특징</h2>\n    <div class=\"trait-grid cols-3 reveal\">\n      <div class=\"trait-card\"><div class=\"num\">1</div><div class=\"label\">완전성</div><div class=\"desc\">업무에 필요한 데이터를 빠짐없이 담았는가</div></div>\n      <div class=\"trait-card\"><div class=\"num\">2</div><div class=\"label\">중복 배제</div><div class=\"desc\">같은 데이터가 여러 곳에 흩어져 있지 않은가</div></div>\n      <div class=\"trait-card\"><div class=\"num\">3</div><div class=\"label\">업무 규칙</div><div class=\"desc\">회사의 규칙이 모델에 녹아 있는가</div></div>\n      <div class=\"trait-card\"><div class=\"num\">4</div><div class=\"label\">데이터 재사용</div><div class=\"desc\">다른 업무에서도 활용할 수 있는가</div></div>\n      <div class=\"trait-card\"><div class=\"num\">5</div><div class=\"label\">의사소통</div><div class=\"desc\">보는 사람마다 같은 의미로 읽히는가</div></div>\n      <div class=\"trait-card\"><div class=\"num\">6</div><div class=\"label\">통합성</div><div class=\"desc\">같은 데이터는 한 곳에 정의되어 있는가</div></div>\n    </div>\n\n    <!-- 3층 스키마 -->\n    <h2 class=\"reveal\">3층 스키마 (ANSI/SPARC)</h2>\n    <p class=\"reveal\">같은 쇼핑몰 데이터베이스를 <strong>세 가지 관점에서 본 모습</strong>. 누가 보느냐에 따라 같은 데이터가 전혀 다른 형태로 보인다.</p>\n\n    <div class=\"threelayer reveal\">\n      <div class=\"tl-row outer\">\n        <span class=\"tl-tag\">EXTERNAL</span><span class=\"tl-name\">외부 스키마 — 각 사용자/앱이 보는 화면</span>\n        <div class=\"tl-desc\">여러 개 · 사용자·개발자 · SQL의 <strong>VIEW</strong> 또는 응용 프로그램의 가공 데이터</div>\n      </div>\n      <div class=\"indep-line\">↑ <strong>논리적 독립성</strong> — 개념 스키마가 바뀌어도 외부 스키마는 영향 없음 ↑</div>\n      <div class=\"tl-row conceptual\">\n        <span class=\"tl-tag\" style=\"background:var(--point-100);color:var(--point-600);\">CONCEPTUAL</span><span class=\"tl-name\">개념 스키마 — 조직 전체가 공유하는 ERD</span>\n        <div class=\"tl-desc\">1개 · DA(Data Architect) · 모든 화면의 원본이 되는 통합 설계도</div>\n      </div>\n      <div class=\"indep-line\">↑ <strong>물리적 독립성</strong> — 내부 스키마가 바뀌어도 개념·외부 스키마는 영향 없음 ↑</div>\n      <div class=\"tl-row internal\">\n        <span class=\"tl-tag\" style=\"background:var(--bg-muted);color:var(--fg-3);\">INTERNAL</span><span class=\"tl-name\">내부 스키마 — 디스크 위 실제 저장 구조</span>\n        <div class=\"tl-desc\">1개 · DBA(DB Administrator) · 데이터 파일·인덱스·파티션·캐시</div>\n      </div>\n    </div>\n\n    <h3 class=\"reveal\">관점 1. 외부 스키마 (External) — 각 사용자/앱이 보는 화면</h3>\n    <table class=\"reveal\">\n      <thead><tr><th>누가 본다</th><th>화면 (View)</th><th>보이는 컬럼 예시</th></tr></thead>\n      <tbody>\n        <tr><td>김철수 (모바일앱)</td><td>\"내 주문 내역\"</td><td>주문번호 · 상품명 · 금액 · 주문일</td></tr>\n        <tr><td>이영희 (웹)</td><td>\"위시리스트\"</td><td>상품명 · 가격 · 이미지</td></tr>\n        <tr><td>관리자 (백오피스)</td><td>\"일별 매출\"</td><td>날짜 · 총매출 · 주문건수</td></tr>\n      </tbody>\n    </table>\n\n    <h3 class=\"reveal\">관점 2. 개념 스키마 (Conceptual) — 조직 전체가 공유하는 ERD</h3>\n    <p class=\"reveal\">위 모든 화면의 원본이 되는 <strong>하나의 통합 설계도</strong>. 회원·상품·주문·주문상세·결제·배송 등 모든 엔터티와 관계. 설계자(DA)가 관리하는 <strong>전사 데이터 모델</strong>. 데이터베이스에 단 하나만 존재.</p>\n\n    <h3 class=\"reveal\">관점 3. 내부 스키마 (Internal) — 디스크 위 실제 저장 구조</h3>\n    <p class=\"reveal\">개념 스키마가 <strong>물리적으로 어떻게 저장되는가</strong>. DBA·DBMS의 영역.</p>\n    <table class=\"reveal\">\n      <thead><tr><th>항목</th><th>예시</th></tr></thead>\n      <tbody>\n        <tr><td>데이터 파일</td><td><code>/oracle/data/SHOP_DATA01.dbf</code> (8KB 블록 단위)</td></tr>\n        <tr><td>인덱스</td><td><code>IDX_ORDERS_MEMBER</code> (B-Tree, 회원ID 정렬)</td></tr>\n        <tr><td>파티션</td><td>ORDERS 테이블을 월별로 분할 (<code>P_2026_04</code>, <code>P_2026_05</code> ...)</td></tr>\n        <tr><td>캐시</td><td>자주 조회되는 회원 데이터 메모리 캐시</td></tr>\n      </tbody>\n    </table>\n\n    <h3 class=\"reveal\">3층이 분리된 이유 — 데이터 독립성</h3>\n    <table class=\"reveal\">\n      <thead><tr><th>스키마</th><th>관점</th><th>개수</th><th>누가 다룬다</th></tr></thead>\n      <tbody>\n        <tr><td>외부 (External)</td><td>사용자·응용 프로그램</td><td><strong>여러 개</strong></td><td>사용자·개발자</td></tr>\n        <tr><td>개념 (Conceptual)</td><td>설계자 통합</td><td><strong>1개</strong></td><td>DA (Data Architect)</td></tr>\n        <tr><td>내부 (Internal)</td><td>물리 저장</td><td><strong>1개</strong></td><td>DBA (DB Administrator)</td></tr>\n      </tbody>\n    </table>\n\n    <h3 class=\"reveal\">데이터 독립성 2가지</h3>\n    <table class=\"reveal\">\n      <thead><tr><th>종류</th><th>의미</th></tr></thead>\n      <tbody>\n        <tr><td>논리적 독립성</td><td>개념 스키마가 변경돼도 외부 스키마(응용)는 영향 없음</td></tr>\n        <tr><td>물리적 독립성</td><td>내부 스키마가 변경돼도 개념·외부 스키마는 영향 없음</td></tr>\n      </tbody>\n    </table>\n\n    <!-- SQL 실전 -->\n    <h2 class=\"section-label sec-sql reveal\"><span class=\"label-tag\">SQL 실전</span><span class=\"label-rest\">모델이 곧 테이블이 된다</span></h2>\n    <p class=\"reveal\">논리 모델의 PK는 물리 모델에서 <a href=\"#\" data-chapter=\"c115\">식별자</a>(PRIMARY KEY 제약)가 된다.</p>\n    <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 논리 모델의 '고객' 엔터티 → 물리 모델의 CUSTOMER 테이블</span>\n<span class=\"sql-kw\">CREATE TABLE</span> <span class=\"sql-name\">CUSTOMER</span> (\n    <span class=\"sql-type\">CUST_ID</span>    <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">10</span>) <span class=\"sql-kw\">PRIMARY KEY</span>,  <span class=\"sql-cm\">-- 식별자</span>\n    <span class=\"sql-type\">CUST_NAME</span>  <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">50</span>) <span class=\"sql-kw\">NOT NULL</span>,     <span class=\"sql-cm\">-- 속성</span>\n    <span class=\"sql-type\">PHONE</span>      <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">20</span>)               <span class=\"sql-cm\">-- 속성</span>\n);\n\n<span class=\"sql-cm\">-- 외부 스키마(VIEW) — 응용 프로그램이 보는 화면</span>\n<span class=\"sql-kw\">CREATE VIEW</span> <span class=\"sql-name\">V_MY_ORDER</span> <span class=\"sql-kw\">AS</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">O</span>.<span class=\"sql-type\">ORDER_ID</span>, <span class=\"sql-type\">O</span>.<span class=\"sql-type\">ORD_DATE</span>, <span class=\"sql-type\">M</span>.<span class=\"sql-type\">NAME</span>\n  <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">ORDERS</span> <span class=\"sql-type\">O</span> <span class=\"sql-kw\">JOIN</span> <span class=\"sql-name\">MEMBER</span> <span class=\"sql-type\">M</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-type\">M</span>.<span class=\"sql-type\">MEMBER_ID</span> = <span class=\"sql-type\">O</span>.<span class=\"sql-type\">MEMBER_ID</span>;</code></pre>\n\n    <p class=\"reveal\" style=\"font-size:13px;color:var(--fg-3);margin:8px 0 4px;\">↓ V_MY_ORDER 조회 결과 (외부 스키마가 보는 화면)</p>\n    <table class=\"reveal\">\n      <thead><tr><th>ORDER_ID</th><th>ORD_DATE</th><th>NAME</th></tr></thead>\n      <tbody>\n        <tr><td>1001</td><td>2026-04-01</td><td>김철수</td></tr>\n        <tr><td>1002</td><td>2026-04-05</td><td>이영희</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\">개념 스키마(MEMBER + ORDERS 두 테이블)는 그대로지만, VIEW를 통해 외부 스키마는 \"주문번호·날짜·이름\" 한 화면처럼 보인다 — 같은 데이터를 보는 관점이 다른 것뿐이다.</p>\n\n    <!-- Before & After -->\n    <h2 class=\"section-label sec-compare reveal\"><span class=\"label-tag\">Before &amp; After</span><span class=\"label-rest\">모델링이 없을 때 vs 있을 때</span></h2>\n    <p class=\"reveal\">쇼핑몰에서 김철수가 사과·배·포도를 여러 번 주문한 상황. 한 테이블에 고객·상품을 다 욱여넣은 형태와, 고객·주문을 분리한 형태를 비교한다.</p>\n\n    <div class=\"ba-flow large-after reveal\">\n      <div class=\"ba-side before\">\n        <span class=\"ba-tag\">BEFORE</span>\n        <h4 class=\"ba-h\">모델링 없이 만든 테이블</h4>\n        <div class=\"mini-table cols-4\">\n          <div class=\"h\">주문</div><div class=\"h\">고객</div><div class=\"h\">상품1</div><div class=\"h\">상품2</div>\n          <div class=\"c\">1</div><div class=\"c\">김철수</div><div class=\"c\">사과</div><div class=\"c\">배</div>\n          <div class=\"c\">2</div><div class=\"c\">김철수</div><div class=\"c\">포도</div><div class=\"c is-null\">NULL</div>\n        </div>\n        <p style=\"font-size:12px;color:var(--fg-3);margin:10px 0 0;\">고객 정보 중복 + 상품 칸 부족</p>\n      </div>\n      <div class=\"ba-arrow\">→</div>\n      <div class=\"ba-side after\">\n        <span class=\"ba-tag\">AFTER</span>\n        <h4 class=\"ba-h\">엔터티 분리</h4>\n        <div class=\"ba-tables cols-2\">\n          <div class=\"ba-mini-table\">\n            <div class=\"h\">CUSTOMER</div>\n            <div class=\"row\">C001 / 김철수 / 010-1111</div>\n          </div>\n          <div class=\"ba-mini-table\">\n            <div class=\"h\">ORDER</div>\n            <div class=\"row\">1 / C001 / 사과</div>\n            <div class=\"row\">2 / C001 / 배</div>\n            <div class=\"row\">3 / C001 / 포도</div>\n          </div>\n        </div>\n        <p style=\"font-size:12px;color:var(--fg-3);margin:10px 0 0;\">중복 사라짐 + 상품 무한 추가 가능</p>\n      </div>\n    </div>\n\n    <h4 class=\"reveal\">Before — 모델링 없이 만든 테이블</h4>\n    <table class=\"reveal\">\n      <thead><tr><th>주문번호</th><th>고객이름</th><th>고객전화</th><th>상품1</th><th>상품2</th><th>상품3</th></tr></thead>\n      <tbody>\n        <tr><td>1</td><td>김철수</td><td>010-1111</td><td>사과</td><td>배</td><td>NULL</td></tr>\n        <tr><td>2</td><td>김철수</td><td>010-1111</td><td>포도</td><td>NULL</td><td>NULL</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\">고객 정보가 중복되고, 상품 칸이 모자라면 더 못 담는다.</p>\n\n    <h4 class=\"reveal\">After — 모델링 후 분리된 테이블</h4>\n    <p class=\"reveal\" style=\"font-size:13.5px;color:var(--fg-3);\">CUSTOMER</p>\n    <table class=\"reveal\">\n      <thead><tr><th>CUST_ID</th><th>NAME</th><th>PHONE</th></tr></thead>\n      <tbody><tr><td>C001</td><td>김철수</td><td>010-1111</td></tr></tbody>\n    </table>\n    <p class=\"reveal\" style=\"font-size:13.5px;color:var(--fg-3);\">ORDER</p>\n    <table class=\"reveal\">\n      <thead><tr><th>ORD_ID</th><th>CUST_ID</th><th>PRODUCT</th></tr></thead>\n      <tbody>\n        <tr><td>1</td><td>C001</td><td>사과</td></tr>\n        <tr><td>2</td><td>C001</td><td>배</td></tr>\n        <tr><td>3</td><td>C001</td><td>포도</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\">Before 구조는 \"상품1·상품2·상품3\" 같은 컬럼을 미리 박아두기 때문에 사람마다 다른 주문 개수에 대응할 수 없고, 고객 정보도 주문마다 똑같이 반복 저장되어 전화번호 한 번 바뀌면 모든 행을 손봐야 한다. 모델링은 이런 반복과 한계를 엔터티 분리로 해소한다 — 한 가지 의미는 한 곳에만 두고, 관계는 키로 잇는다는 원칙은 어떤 도메인이든 공통이다.</p>\n\n    <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n      <div>\n        <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n        <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n      </div>\n      <a href=\"./exam-review.html#ch-1-1-1\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n    </div>",
  c112: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    엔터티(Entity)란 업무에서 관리해야 할 <strong>정보의 덩어리(명사)</strong>다. 실제 테이블의 후보가 된다.\n  </blockquote>\n  <div class=\"ex-box reveal\">\n    쇼핑몰이라면 <strong>회원·상품·주문·배송</strong> 같은 명사 하나하나가 엔터티이며, 각 엔터티의 개별 사례(예: '김철수 회원')를 <strong>인스턴스(Instance, 한 행)</strong> 라고 부른다.\n  </div>\n\n  <!-- 개념 도식화 — 인포그래픽 1 -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">엔터티의 구성</span>\n  </h2>\n  <div class=\"entity-layers reveal\">\n    <div class=\"entity-layers-track\">\n      <div class=\"entity-layer\">\n        <div class=\"icon\">📋</div>\n        <div class=\"body\">\n          <div class=\"name\">엔터티 <small>(테이블)</small></div>\n          <div class=\"desc\">정보의 덩어리. <em>예: 회원</em></div>\n        </div>\n        <div class=\"arrow\">▼</div>\n      </div>\n      <div class=\"entity-layer\">\n        <div class=\"icon\">🏷️</div>\n        <div class=\"body\">\n          <div class=\"name\">속성 <small>(컬럼)</small></div>\n          <div class=\"desc\">정보의 세부 항목. <em>회원ID · 이름 · 전화번호</em></div>\n        </div>\n        <div class=\"arrow\">▼</div>\n      </div>\n      <div class=\"entity-layer\">\n        <div class=\"icon\">📄</div>\n        <div class=\"body\">\n          <div class=\"name\">인스턴스 <small>(행)</small></div>\n          <div class=\"desc\">개별 사례. <em>C001, 김철수, 010-1111</em></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3); margin: 18px 0 6px;\">↓ 위 엔터티가 실제 테이블이 되면 이렇게 채워진다</p>\n  <table class=\"reveal\">\n    <thead>\n      <tr><th>MEMBER_ID</th><th>NAME</th><th>PHONE</th><th>JOIN_DATE</th></tr>\n    </thead>\n    <tbody>\n      <tr><td><code>C001</code></td><td>김철수</td><td>010-1111-2222</td><td>2026-01-15</td></tr>\n      <tr><td><code>C002</code></td><td>이영희</td><td>010-2222-3333</td><td>2026-02-08</td></tr>\n      <tr><td><code>C003</code></td><td>박민수</td><td>010-3333-4444</td><td>2026-03-22</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px; padding-left: 10px;\">→ 표 자체가 <strong style=\"color:var(--point-600);\">엔터티(MEMBER)</strong>, 헤더가 <strong style=\"color:var(--point-600);\">속성</strong>, 각 행이 <strong style=\"color:var(--point-600);\">인스턴스</strong></p>\n\n  <h3 class=\"reveal\" style=\"font-size:16px;font-weight:700;color:var(--fg-1);margin:28px 0 10px;padding-left:12px;border-left:3px solid var(--point-500);\">ER 다이어그램으로 보는 엔터티</h3>\n  <p class=\"reveal\">엔터티 사이의 연결도 함께 본다 — 회원(MEMBER) 1명은 여러 주문(ORDER)을 만들 수 있다.</p>\n  <div class=\"mermaid reveal\">\nerDiagram\n    MEMBER ||--o{ ORDER : \"주문하다\"\n    MEMBER {\n        VARCHAR2 MEMBER_ID PK\n        VARCHAR2 NAME\n        VARCHAR2 PHONE\n        DATE JOIN_DATE\n    }\n    ORDER {\n        NUMBER ORDER_ID PK\n        VARCHAR2 MEMBER_ID FK\n        DATE ORD_DATE\n    }\n  </div>\n\n  <!-- 5가지 특징 — 인포그래픽 2 -->\n  <h2 class=\"reveal\">엔터티의 5가지 특징</h2>\n  <div class=\"trait-grid reveal\">\n    <div class=\"trait-card\">\n      <div class=\"glyph\">업</div>\n      <div class=\"label\">업무에서 필요</div>\n      <div class=\"desc\">관리할 가치가 있는 정보</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"glyph\">식</div>\n      <div class=\"label\">식별 가능</div>\n      <div class=\"desc\"><a href=\"#\" data-chapter=\"c115\">식별자</a>로 구분</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"glyph\">인</div>\n      <div class=\"label\">인스턴스 ≥ 2</div>\n      <div class=\"desc\">2개 이상의 행 존재</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"glyph\">속</div>\n      <div class=\"label\">속성 ≥ 2</div>\n      <div class=\"desc\">2개 이상의 <a href=\"#\" data-chapter=\"c113\">속성</a></div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"glyph\">관</div>\n      <div class=\"label\">관계 보유</div>\n      <div class=\"desc\">다른 엔터티와의 <a href=\"#\" data-chapter=\"c114\">관계</a></div>\n    </div>\n  </div>\n\n  <div class=\"mnemonic reveal\">\n    <div class=\"label-side\">\n      암기\n      <small>5대 특징</small>\n    </div>\n    <div class=\"glyphs\">\n      <div class=\"glyph-chip\">업</div>\n      <div class=\"glyph-chip\">식</div>\n      <div class=\"glyph-chip\">인</div>\n      <div class=\"glyph-chip\">속</div>\n      <div class=\"glyph-chip\">관</div>\n    </div>\n  </div>\n\n  <!-- 분류 — 인포그래픽 3 -->\n  <h2 class=\"reveal\">엔터티의 분류</h2>\n\n  <div class=\"classification-block reveal\">\n\n    <section class=\"classification-section\">\n      <h3 class=\"cls-h\">유무형에 따른 분류</h3>\n      <div class=\"cls-row\">\n        <div class=\"cls-card\">\n          <span class=\"badge b-physical\">유형</span>\n          <div class=\"name\">유형 엔터티</div>\n          <div class=\"ex\">물리적으로 존재 — <em>상품 · 사원 · 매장</em></div>\n        </div>\n        <div class=\"cls-card\">\n          <span class=\"badge b-conceptual\">개념</span>\n          <div class=\"name\">개념 엔터티</div>\n          <div class=\"ex\">개념적으로만 존재 — <em>부서 · 조직 · 학과</em></div>\n        </div>\n        <div class=\"cls-card\">\n          <span class=\"badge b-event\">사건</span>\n          <div class=\"name\">사건 엔터티</div>\n          <div class=\"ex\">행위로 발생 — <em>주문 · 결제 · 출입기록</em></div>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"classification-section\">\n      <h3 class=\"cls-h\">발생 시점에 따른 분류</h3>\n      <div class=\"timing-flow\">\n        <div class=\"timing-card\">\n          <div class=\"step\">STEP 1 · 독립</div>\n          <div class=\"name\">기본 엔터티 <small>(Key)</small></div>\n          <div class=\"ex\">다른 엔터티 없이도 성립<br><em>사원 · 부서 · 고객</em></div>\n          <div class=\"arrow-next\">→</div>\n        </div>\n        <div class=\"timing-card\">\n          <div class=\"step\">STEP 2 · 파생</div>\n          <div class=\"name\">중심 엔터티 <small>(Main)</small></div>\n          <div class=\"ex\">기본 엔터티에서 파생<br><em>주문 · 계약 · 매출</em></div>\n          <div class=\"arrow-next\">→</div>\n        </div>\n        <div class=\"timing-card\">\n          <div class=\"step\">STEP 3 · 행위</div>\n          <div class=\"name\">행위 엔터티 <small>(Action)</small></div>\n          <div class=\"ex\">2개 이상 엔터티의 관계에서 발생<br><em>주문상세 · 출고 · 입출금</em></div>\n        </div>\n      </div>\n    </section>\n\n  </div>\n\n  <!-- SQL 실전 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">엔터티는 테이블이 된다</span>\n  </h2>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — 입력할 인스턴스</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">MEMBER</span>\n    <h4 class=\"ba-h\">회원 엔터티 → 테이블</h4>\n    <div class=\"mini-table cols-4\">\n      <div class=\"h\">MEMBER_ID</div><div class=\"h\">NAME</div><div class=\"h\">PHONE</div><div class=\"h\">JOIN_DATE</div>\n      <div class=\"c\">M01</div><div class=\"c\">김철수</div><div class=\"c\">010-1111</div><div class=\"c\">2026-01-15</div>\n      <div class=\"c\">M02</div><div class=\"c\">이영희</div><div class=\"c\">010-2222</div><div class=\"c\">2026-02-08</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">CREATE TABLE</span> <span class=\"sql-name\">MEMBER</span> (\n    <span class=\"sql-type\">MEMBER_ID</span>    <span class=\"sql-kw\">VARCHAR2</span>(10) <span class=\"sql-kw\">PRIMARY KEY</span>,  <span class=\"sql-cm\">-- 식별자</span>\n    <span class=\"sql-type\">NAME</span>         <span class=\"sql-kw\">VARCHAR2</span>(50),\n    <span class=\"sql-type\">PHONE</span>        <span class=\"sql-kw\">VARCHAR2</span>(20),\n    <span class=\"sql-type\">JOIN_DATE</span>    <span class=\"sql-kw\">DATE</span>\n);\n\n<span class=\"sql-cm\">-- 인스턴스(행) 입력</span>\n<span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">MEMBER</span> <span class=\"sql-kw\">VALUES</span>(<span class=\"sql-str\">'M01'</span>, <span class=\"sql-str\">'김철수'</span>, <span class=\"sql-str\">'010-1111'</span>, <span class=\"sql-kw\">DATE</span> <span class=\"sql-str\">'2026-01-15'</span>);\n<span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">MEMBER</span> <span class=\"sql-kw\">VALUES</span>(<span class=\"sql-str\">'M02'</span>, <span class=\"sql-str\">'이영희'</span>, <span class=\"sql-str\">'010-2222'</span>, <span class=\"sql-kw\">DATE</span> <span class=\"sql-str\">'2026-02-08'</span>);\n\n<span class=\"sql-cm\">-- 조회</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">MEMBER_ID</span>, <span class=\"sql-type\">NAME</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">MEMBER</span>;</code></pre>\n\n  <p class=\"reveal\" style=\"font-size:13px;color:var(--fg-3);margin:8px 0 4px;\">↓ 결과</p>\n  <table class=\"reveal\">\n    <thead><tr><th>MEMBER_ID</th><th>NAME</th></tr></thead>\n    <tbody>\n      <tr><td>M01</td><td>김철수</td></tr>\n      <tr><td>M02</td><td>이영희</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ SELECT 문이 두 인스턴스(M01·M02)에서 두 속성(MEMBER_ID·NAME)만 골라 보여준다.</p>\n  <p class=\"reveal\" style=\"font-size:13px;color:var(--fg-3);\">엔터티(설계 단계) → 테이블(SQL 단계) → 행(인스턴스)으로 단계가 매핑된다.</p>\n\n  <!-- Before & After — 인포그래픽 4 -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">엔터티 도출 전후</span>\n  </h2>\n  <div class=\"ba-flow reveal\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">BEFORE</span>\n      <h4 class=\"ba-h\">엔터티 구분 없이 한 덩어리</h4>\n      <div class=\"ba-row\">김철수가 2026-04-01에 사과 2개 주문</div>\n      <div class=\"ba-row\">이영희가 2026-04-02에 배 1개 주문</div>\n    </div>\n    <div class=\"ba-arrow\">→</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">AFTER</span>\n      <h4 class=\"ba-h\">엔터티 분리 — 회원 · 상품 · 주문</h4>\n      <div class=\"ba-tables\">\n        <div class=\"ba-mini-table\">\n          <div class=\"h\">MEMBER</div>\n          <div class=\"row\">M01 · 김철수</div>\n          <div class=\"row\">M02 · 이영희</div>\n        </div>\n        <div class=\"ba-mini-table\">\n          <div class=\"h\">PRODUCT</div>\n          <div class=\"row\">P01 · 사과</div>\n          <div class=\"row\">P02 · 배</div>\n        </div>\n        <div class=\"ba-mini-table\">\n          <div class=\"h\">ORDER</div>\n          <div class=\"row\">1 · M01 · P01 · 2</div>\n          <div class=\"row\">2 · M02 · P02 · 1</div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-1-1-2\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c113: "<!-- 핵심 요약 -->\n    <h2 class=\"section-label sec-summary reveal\"><span class=\"label-tag\">핵심 요약</span><span class=\"label-rest\">정의</span></h2>\n    <blockquote class=\"reveal\">\n      속성(Attribute)이란 <a href=\"#\" data-chapter=\"c112\">엔터티</a>가 가지는 세부 정보 항목, 곧 <strong>컬럼</strong>이다. 엔터티를 설명하는 가장 작은 단위다.\n    </blockquote>\n    <div class=\"ex-box reveal\">\n      명함 한 장에서 명함 자체는 엔터티(사람), <strong>이름·전화번호·이메일</strong> 같은 각 항목이 속성이다. 이름은 더 이상 쪼개지지 않는 최소 단위.\n    </div>\n\n    <!-- 개념 도식화 -->\n    <h2 class=\"section-label sec-diagram reveal\"><span class=\"label-tag\">개념 도식화</span><span class=\"label-rest\">엔터티 / 인스턴스 / 속성 / 속성값</span></h2>\n    <p class=\"reveal\">회원(MEMBER) 테이블 예시 — 각 행 = <strong>인스턴스</strong>, 각 칸 = <strong>속성값</strong>, 각 컬럼 = <strong>속성</strong>.</p>\n    <table class=\"reveal\">\n      <thead><tr><th>ID (속성)</th><th>이름 (속성)</th><th>전화번호 (속성)</th></tr></thead>\n      <tbody>\n        <tr><td><strong>M01</strong></td><td><strong>김철수</strong></td><td><strong>010-1111</strong> ← 속성값(Value)</td></tr>\n        <tr><td>M02</td><td>이영희</td><td>010-2222</td></tr>\n      </tbody>\n    </table>\n\n    <p class=\"reveal\">엔터티 박스 안에 속성이 자리 잡는 모습을 ER로 본다.</p>\n    <div class=\"mermaid reveal\">\nerDiagram\n    MEMBER {\n        VARCHAR2 MEMBER_ID PK \"주식별자\"\n        VARCHAR2 NAME \"이름\"\n        VARCHAR2 PHONE \"전화\"\n        DATE BIRTH \"생일\"\n        NUMBER AGE \"파생속성\"\n    }\n    </div>\n\n    <!-- 3가지 분류 기준 -->\n    <h2 class=\"reveal\">속성의 3가지 분류 기준</h2>\n\n    <div class=\"cls-row reveal\">\n      <div class=\"cls-card\">\n        <span class=\"badge\">① 특성</span>\n        <div class=\"name\">기본 / 설계 / 파생</div>\n        <div class=\"ex\">데이터가 어디서 왔는가</div>\n      </div>\n      <div class=\"cls-card\">\n        <span class=\"badge b-info\">② 분해</span>\n        <div class=\"name\">단순(원자) / 복합</div>\n        <div class=\"ex\">더 쪼갤 수 있는가</div>\n      </div>\n      <div class=\"cls-card\">\n        <span class=\"badge b-event\">③ 값 개수</span>\n        <div class=\"name\">단일값 / 다중값</div>\n        <div class=\"ex\">한 인스턴스에 몇 개?</div>\n      </div>\n    </div>\n\n    <h3 class=\"reveal\">특성에 따른 분류</h3>\n    <div class=\"cls-row reveal\">\n      <div class=\"cls-card\">\n        <span class=\"badge\">기본 속성</span>\n        <div class=\"name\">업무에서 직접 추출</div>\n        <div class=\"ex\">이름, 전화번호, 주소</div>\n      </div>\n      <div class=\"cls-card\">\n        <span class=\"badge b-info\">설계 속성</span>\n        <div class=\"name\">설계 과정에서 새로 만듦</div>\n        <div class=\"ex\">회원ID, 상품코드</div>\n      </div>\n      <div class=\"cls-card\">\n        <span class=\"badge b-event\">파생 속성</span>\n        <div class=\"name\">다른 속성에서 계산</div>\n        <div class=\"ex\">총주문금액 = 수량 × 단가</div>\n      </div>\n    </div>\n    <table class=\"reveal\">\n      <thead><tr><th>종류</th><th>의미</th><th>예시</th></tr></thead>\n      <tbody>\n        <tr><td>기본 속성</td><td>업무에서 직접 추출된 본래의 속성</td><td>이름, 전화번호, 주소</td></tr>\n        <tr><td>설계 속성</td><td>업무 설계 과정에서 새로 만든 속성</td><td>회원ID, 상품코드</td></tr>\n        <tr><td>파생 속성</td><td>다른 속성에서 계산되어 나온 속성</td><td>총주문금액(=수량×단가)</td></tr>\n      </tbody>\n    </table>\n    <blockquote class=\"reveal\">시험 단골 — \"주민번호로부터 구한 <strong>나이</strong>\"는 <strong>파생 속성</strong>이다.</blockquote>\n\n    <h3 class=\"reveal\">분해 가능 여부</h3>\n    <table class=\"reveal\">\n      <thead><tr><th>종류</th><th>의미</th><th>예시</th></tr></thead>\n      <tbody>\n        <tr><td>단순(원자) 속성</td><td>더 이상 분해 불가</td><td>이름, 나이</td></tr>\n        <tr><td>복합 속성</td><td>여러 의미가 합쳐진 형태 — 분해해서 저장하면 활용도 ↑</td><td>주소(시+구+동)</td></tr>\n      </tbody>\n    </table>\n    <blockquote class=\"reveal\">\n      <strong>주의</strong> — '복합 속성' (1-1-3) 과 '복합식별자' (<a href=\"#\" data-chapter=\"c115\">1-1-5</a>) 는 <strong>다른 개념</strong>.<br>\n      복합 속성 = 한 속성을 여러 의미로 쪼갤 수 있음. / 복합식별자 = 여러 속성을 묶어 PK로 씀.\n    </blockquote>\n\n    <h3 class=\"reveal\">속성값의 개수</h3>\n    <table class=\"reveal\">\n      <thead><tr><th>종류</th><th>의미</th><th>예시</th></tr></thead>\n      <tbody>\n        <tr><td>단일값 속성</td><td>하나만 가짐</td><td>주민번호</td></tr>\n        <tr><td>다중값 속성</td><td>여러 개 가능 → 별도 엔터티로 분리</td><td>전화번호(집, 휴대폰)</td></tr>\n      </tbody>\n    </table>\n\n    <!-- 명명 규칙 -->\n    <h2 class=\"reveal\">속성의 명명 규칙</h2>\n    <div class=\"name-rules reveal\">\n      <div class=\"nr-card\"><span class=\"num\">1</span><span class=\"nr-name\">현업 용어 사용</span><div class=\"nr-desc\">코드가 아닌 업무 용어로 명명</div></div>\n      <div class=\"nr-card\"><span class=\"num\">2</span><span class=\"nr-name\">명사형 (서술식 X)</span><div class=\"nr-desc\">'주문수량' O, '주문은얼마인가' X</div></div>\n      <div class=\"nr-card\"><span class=\"num\">3</span><span class=\"nr-name\">약어 자제</span><div class=\"nr-desc\">'qty' 보다 '수량'</div></div>\n      <div class=\"nr-card\"><span class=\"num\">4</span><span class=\"nr-name\">전체 모델에서 유일</span><div class=\"nr-desc\">같은 이름이 여러 엔터티에 흩어지지 않도록</div></div>\n    </div>\n    <table class=\"reveal\">\n      <thead><tr><th>좋은 예</th><th>나쁜 예</th></tr></thead>\n      <tbody>\n        <tr><td>회원_등록일</td><td>regdt (약어 남발)</td></tr>\n        <tr><td>상품_가격</td><td>상품의가격은얼마인가 (서술식)</td></tr>\n        <tr><td>주문_수량</td><td>qty (축약형 모호)</td></tr>\n      </tbody>\n    </table>\n\n    <!-- 도메인 -->\n    <h2 class=\"reveal\">도메인(Domain) — 속성의 값 범위</h2>\n    <p class=\"reveal\">도메인은 속성이 가질 수 있는 <strong>값의 종류·범위·제약</strong>을 정의한다. <strong>데이터 타입 + 크기 + 허용값(제약조건)</strong> 세 가지가 모두 도메인에 포함된다. 값이 비어있어도 되는지(NOT NULL 여부)도 도메인의 일부로, <a href=\"#\" data-chapter=\"c124\">NULL</a>을 허용할지는 속성마다 별도로 결정한다.</p>\n\n    <div class=\"trait-grid cols-3 reveal\">\n      <div class=\"trait-card\"><div class=\"glyph\">T</div><div class=\"label\">타입</div><div class=\"desc\">CHAR · NUMBER · DATE …</div></div>\n      <div class=\"trait-card\"><div class=\"glyph\">S</div><div class=\"label\">크기</div><div class=\"desc\">VARCHAR2(<strong>100</strong>)</div></div>\n      <div class=\"trait-card\"><div class=\"glyph\">C</div><div class=\"label\">제약</div><div class=\"desc\">NOT NULL · CHECK · UNIQUE</div></div>\n    </div>\n\n    <table class=\"reveal\">\n      <thead><tr><th>속성</th><th>도메인 (타입 · 크기 · 제약)</th></tr></thead>\n      <tbody>\n        <tr><td>성별</td><td>CHAR(1) / { 'M', 'F' } 만 허용</td></tr>\n        <tr><td>나이</td><td>NUMBER(3) / 0 ~ 150 사이 정수</td></tr>\n        <tr><td>이메일</td><td>VARCHAR2(100) / @ 포함 형식</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\">같은 도메인을 가진 속성은 여러 엔터티에 나와도 같은 의미로 다뤄야 한다(통합성).</p>\n\n    <!-- SQL 실전 -->\n    <h2 class=\"section-label sec-sql reveal\"><span class=\"label-tag\">SQL 실전</span><span class=\"label-rest\">속성 정의</span></h2>\n    <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — BIRTH(기본 속성) + AGE(파생 속성)</p>\n    <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n      <span class=\"ba-tag\">MEMBER</span>\n      <h4 class=\"ba-h\">파생 속성 자동 계산</h4>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">MEMBER_ID</div><div class=\"h\">NAME</div><div class=\"h\">BIRTH (입력)</div>\n        <div class=\"c\">M01</div><div class=\"c\">김철수</div><div class=\"c\">1995-03-12</div>\n        <div class=\"c\">M02</div><div class=\"c\">이영희</div><div class=\"c\">2000-08-21</div>\n      </div>\n    </div>\n    <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">CREATE TABLE</span> <span class=\"sql-name\">MEMBER</span> (\n    <span class=\"sql-type\">MEMBER_ID</span>    <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">10</span>),     <span class=\"sql-cm\">-- 설계 속성</span>\n    <span class=\"sql-type\">NAME</span>         <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">50</span>),      <span class=\"sql-cm\">-- 기본 속성</span>\n    <span class=\"sql-type\">BIRTH</span>        <span class=\"sql-type\">DATE</span>,              <span class=\"sql-cm\">-- 기본 속성</span>\n    <span class=\"sql-type\">AGE</span>          <span class=\"sql-type\">NUMBER</span> <span class=\"sql-kw\">GENERATED ALWAYS AS</span>  <span class=\"sql-cm\">-- 파생 속성</span>\n                 (<span class=\"sql-kw\">TRUNC</span>(<span class=\"sql-kw\">MONTHS_BETWEEN</span>(<span class=\"sql-kw\">SYSDATE</span>, <span class=\"sql-type\">BIRTH</span>)/<span class=\"sql-num\">12</span>)) <span class=\"sql-kw\">VIRTUAL</span>\n);\n\n<span class=\"sql-cm\">-- 도메인을 제약조건으로 표현 (CHECK)</span>\n<span class=\"sql-kw\">CREATE TABLE</span> <span class=\"sql-name\">SURVEY</span> (\n    <span class=\"sql-type\">RESP_ID</span>      <span class=\"sql-type\">NUMBER</span> <span class=\"sql-kw\">PRIMARY KEY</span>,\n    <span class=\"sql-type\">GENDER</span>       <span class=\"sql-type\">CHAR</span>(<span class=\"sql-num\">1</span>) <span class=\"sql-kw\">CHECK</span>(<span class=\"sql-type\">GENDER</span> <span class=\"sql-kw\">IN</span>(<span class=\"sql-str\">'M'</span>, <span class=\"sql-str\">'F'</span>)),  <span class=\"sql-cm\">-- 허용값 도메인</span>\n    <span class=\"sql-type\">AGE</span>          <span class=\"sql-type\">NUMBER</span>(<span class=\"sql-num\">3</span>) <span class=\"sql-kw\">CHECK</span>(<span class=\"sql-type\">AGE</span> <span class=\"sql-kw\">BETWEEN</span> <span class=\"sql-num\">0</span> <span class=\"sql-kw\">AND</span> <span class=\"sql-num\">150</span>) <span class=\"sql-kw\">NOT NULL</span>\n);\n\n<span class=\"sql-cm\">-- 데이터 입력 후 파생속성 조회</span>\n<span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">MEMBER</span>(<span class=\"sql-type\">MEMBER_ID</span>, <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">BIRTH</span>) <span class=\"sql-kw\">VALUES</span>(<span class=\"sql-str\">'M01'</span>, <span class=\"sql-str\">'김철수'</span>, <span class=\"sql-kw\">DATE</span> <span class=\"sql-str\">'1995-03-12'</span>);\n<span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">MEMBER</span>(<span class=\"sql-type\">MEMBER_ID</span>, <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">BIRTH</span>) <span class=\"sql-kw\">VALUES</span>(<span class=\"sql-str\">'M02'</span>, <span class=\"sql-str\">'이영희'</span>, <span class=\"sql-kw\">DATE</span> <span class=\"sql-str\">'2000-08-21'</span>);\n\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">BIRTH</span>, <span class=\"sql-type\">AGE</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">MEMBER</span>;</code></pre>\n\n    <p class=\"reveal\" style=\"font-size:13px;color:var(--fg-3);margin:8px 0 4px;\">↓ 결과 (오늘 기준 자동 계산)</p>\n    <table class=\"reveal\">\n      <thead><tr><th>NAME</th><th>BIRTH</th><th>AGE (파생)</th></tr></thead>\n      <tbody>\n        <tr><td>김철수</td><td>1995-03-12</td><td>31</td></tr>\n        <tr><td>이영희</td><td>2000-08-21</td><td>25</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\">파생 속성은 BIRTH가 바뀌지 않는 한 자동 계산되므로 별도 저장·갱신이 필요 없다. 다만 조회마다 계산 부담이 있어, 자주 쓰면 성능을 고려해 실제 컬럼으로 저장하는 선택도 가능하다 — 이는 데이터 일관성과 트레이드오프된다.</p>\n\n    <!-- Before & After -->\n    <h2 class=\"section-label sec-compare reveal\"><span class=\"label-tag\">Before &amp; After</span><span class=\"label-rest\">다중값 속성의 분리</span></h2>\n    <p class=\"reveal\">회원 한 명이 휴대폰·집 전화 두 개를 동시에 가진 상황. 한 칸에 \"010-1111, 02-333-4444\"처럼 쉼표로 이어 붙이는 방식과 별도 엔터티로 빼는 방식을 비교한다.</p>\n\n    <div class=\"ba-flow large-after reveal\">\n      <div class=\"ba-side before\">\n        <span class=\"ba-tag\">BEFORE</span>\n        <h4 class=\"ba-h\">다중값을 한 칸에</h4>\n        <div class=\"mini-table cols-3\">\n          <div class=\"h\">MEMBER_ID</div><div class=\"h\">NAME</div><div class=\"h\">PHONE</div>\n          <div class=\"c\">M01</div><div class=\"c\">김철수</div><div class=\"c is-null\">010-1111, 02-333-4444</div>\n        </div>\n        <p style=\"font-size:12px;color:var(--fg-3);margin:10px 0 0;\">검색·변경 어려움. 1NF 위반</p>\n      </div>\n      <div class=\"ba-arrow\">→</div>\n      <div class=\"ba-side after\">\n        <span class=\"ba-tag\">AFTER</span>\n        <h4 class=\"ba-h\">별도 엔터티 분리</h4>\n        <div class=\"ba-tables cols-2\">\n          <div class=\"ba-mini-table\">\n            <div class=\"h\">MEMBER</div>\n            <div class=\"row\">M01 / 김철수</div>\n          </div>\n          <div class=\"ba-mini-table\">\n            <div class=\"h\">MEMBER_PHONE</div>\n            <div class=\"row\">M01 / 휴대폰 / 010-1111</div>\n            <div class=\"row\">M01 / 집 / 02-333-4444</div>\n          </div>\n        </div>\n        <p style=\"font-size:12px;color:var(--fg-3);margin:10px 0 0;\">한 속성엔 한 값만</p>\n      </div>\n    </div>\n\n    <h4 class=\"reveal\">Before — 다중값 속성을 한 칸에</h4>\n    <table class=\"reveal\">\n      <thead><tr><th>MEMBER_ID</th><th>NAME</th><th>PHONE</th></tr></thead>\n      <tbody><tr><td>M01</td><td>김철수</td><td>010-1111, 02-333-4444</td></tr></tbody>\n    </table>\n    <p class=\"reveal\">검색이 어렵고 변경도 어렵다.</p>\n\n    <h4 class=\"reveal\">After — 별도 엔터티로 분리</h4>\n    <p class=\"reveal\" style=\"font-size:13.5px;color:var(--fg-3);\">MEMBER</p>\n    <table class=\"reveal\">\n      <thead><tr><th>MEMBER_ID</th><th>NAME</th></tr></thead>\n      <tbody><tr><td>M01</td><td>김철수</td></tr></tbody>\n    </table>\n    <p class=\"reveal\" style=\"font-size:13.5px;color:var(--fg-3);\">MEMBER_PHONE</p>\n    <table class=\"reveal\">\n      <thead><tr><th>MEMBER_ID</th><th>TYPE</th><th>PHONE</th></tr></thead>\n      <tbody>\n        <tr><td>M01</td><td>휴대폰</td><td>010-1111</td></tr>\n        <tr><td>M01</td><td>집</td><td>02-333-4444</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\">한 칸에 두 값이 들어가 있으면 \"휴대폰 번호만 검색\"이나 \"집 전화 변경\" 같은 단순한 작업도 문자열 파싱부터 해야 하고, 번호가 세 개로 늘어나면 컬럼 자체를 늘려야 한다. 한 속성에는 한 값만 — 한 인스턴스가 같은 속성에 여러 값을 갖는 순간, 그건 별도 엔터티 후보다. 1NF 의 원자값 원칙도 같은 이야기다.</p>\n\n    <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n      <div>\n        <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n        <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n      </div>\n      <a href=\"./exam-review.html#ch-1-1-3\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n    </div>",
  c114: "<!-- 핵심 요약 -->\n    <h2 class=\"section-label sec-summary reveal\"><span class=\"label-tag\">핵심 요약</span><span class=\"label-rest\">정의</span></h2>\n    <blockquote class=\"reveal\">\n      관계(Relationship)란 두 <a href=\"#\" data-chapter=\"c112\">엔터티</a>가 서로 어떻게 연결되어 있는지 표현한 것이다.\n    </blockquote>\n    <div class=\"ex-box reveal\">\n      가족에서 '부모 ─ 자식 : <strong>낳다/자식이다</strong>'처럼, 데이터 모델에서도 '회원 ─ 주문 : 주문하다/주문되다', '부서 ─ 사원 : 소속하다/소속되다'와 같이 양방향 동사로 표현한다.\n    </div>\n\n    <!-- 개념 도식화: 관계의 4요소 -->\n    <h2 class=\"section-label sec-diagram reveal\"><span class=\"label-tag\">개념 도식화</span><span class=\"label-rest\">관계의 4요소</span></h2>\n    <p class=\"reveal\">회원 1명 → 주문 여러 건 (1:N 관계). 양방향 관계명을 모두 명명한다.</p>\n\n    <div class=\"mermaid reveal\">\nerDiagram\n    MEMBER ||--o{ ORDER : \"주문하다 / 주문되다\"\n    MEMBER {\n        VARCHAR2 MEMBER_ID PK\n        VARCHAR2 NAME\n    }\n    ORDER {\n        NUMBER ORDER_ID PK\n        VARCHAR2 MEMBER_ID FK\n        DATE ORD_DATE\n    }\n    </div>\n    <p class=\"reveal\" style=\"font-size:13px;color:var(--fg-3);\">표기 — <code>||--o{</code>는 \"한 회원(필수, 1) ↔ 다 주문(선택 0..N)\"을 나타낸다.</p>\n\n    <div class=\"trait-grid cols-4 reveal\">\n      <div class=\"trait-card\"><div class=\"num\">1</div><div class=\"label\">관계명</div><div class=\"desc\">두 엔터티를 잇는 동사·역할명<br><strong>주문하다 / 주문되다</strong></div></div>\n      <div class=\"trait-card\"><div class=\"num\">2</div><div class=\"label\">관계차수</div><div class=\"desc\">Cardinality<br><strong>1:1, 1:N, M:N</strong></div></div>\n      <div class=\"trait-card\"><div class=\"num\">3</div><div class=\"label\">관계선택성</div><div class=\"desc\">Optionality<br><strong>필수 / 선택</strong></div></div>\n      <div class=\"trait-card\"><div class=\"num\">4</div><div class=\"label\">관계방향</div><div class=\"desc\">Direction<br><strong>양방향 표현</strong></div></div>\n    </div>\n    <table class=\"reveal\">\n      <thead><tr><th>요소</th><th>영문</th><th>설명</th><th>예</th></tr></thead>\n      <tbody>\n        <tr><td>관계명</td><td>Membership</td><td>두 엔터티를 잇는 동사·역할명</td><td>주문하다 / 주문되다</td></tr>\n        <tr><td>관계차수</td><td>Cardinality</td><td>1:1, 1:N, M:N</td><td>회원 1 : N 주문</td></tr>\n        <tr><td>관계선택성</td><td>Optionality</td><td>필수(Mandatory) / 선택(Optional)</td><td>주문엔 반드시 회원이 있어야 하는가</td></tr>\n        <tr><td>관계방향</td><td>Direction</td><td>양방향 표현 (양쪽 관계명 모두 명명)</td><td>회원→주문 / 주문→회원</td></tr>\n      </tbody>\n    </table>\n\n    <!-- 관계차수 3종 -->\n    <h2 class=\"reveal\">관계차수(Cardinality) 3가지</h2>\n\n    <div class=\"mermaid reveal\">\nerDiagram\n    EMPLOYEE ||--|| ID_CARD : \"1:1 발급\"\n    DEPT ||--o{ EMPLOYEE : \"1:N 소속\"\n    STUDENT }o--o{ COURSE : \"M:N 수강(분해 필요)\"\n    </div>\n\n    <div class=\"threeway reveal\">\n      <div class=\"threeway-card t-info\">\n        <div class=\"glyph\">1 : 1</div>\n        <div class=\"name\">1:1 관계</div>\n        <div class=\"desc\"><strong>사원 ─ 사원증</strong> · 사원 1명당 사원증 1개</div>\n      </div>\n      <div class=\"threeway-card t-correct\">\n        <div class=\"glyph\">1 : N</div>\n        <div class=\"name\">1:N 관계</div>\n        <div class=\"desc\"><strong>부서 ─ 사원</strong> · <strong>회원 ─ 주문</strong></div>\n      </div>\n      <div class=\"threeway-card t-warn\">\n        <div class=\"glyph\">M : N</div>\n        <div class=\"name\">M:N 관계</div>\n        <div class=\"desc\"><strong>학생 ─ 과목</strong> · 그대로 구현 불가 → 교차 엔터티</div>\n      </div>\n    </div>\n\n    <h3 class=\"reveal\">1:1 관계</h3>\n    <table class=\"reveal\">\n      <thead><tr><th>예시</th><th>설명</th></tr></thead>\n      <tbody><tr><td>사원 ─ 사원증</td><td>사원 1명당 사원증 1개</td></tr></tbody>\n    </table>\n\n    <h3 class=\"reveal\">1:N 관계</h3>\n    <table class=\"reveal\">\n      <thead><tr><th>예시</th><th>설명</th></tr></thead>\n      <tbody>\n        <tr><td>부서 ─ 사원</td><td>1개 부서에 N명 사원</td></tr>\n        <tr><td>회원 ─ 주문</td><td>회원 1명이 N건 주문</td></tr>\n      </tbody>\n    </table>\n\n    <h3 class=\"reveal\">M:N 관계</h3>\n    <table class=\"reveal\">\n      <thead><tr><th>예시</th><th>설명</th></tr></thead>\n      <tbody><tr><td>학생 ─ 과목</td><td>학생 M명, 과목 N개 (서로 여러 개)</td></tr></tbody>\n    </table>\n    <p class=\"reveal\">M:N 관계는 그대로 구현할 수 없다. 중간에 <strong>연결 엔터티(교차 엔터티)</strong>를 두어 1:N 두 개로 분해한다.</p>\n\n    <div class=\"mermaid reveal\">\nerDiagram\n    STUDENT ||--o{ ENROLL : \"수강신청\"\n    COURSE  ||--o{ ENROLL : \"개설\"\n    STUDENT { VARCHAR2 STU_ID PK\n              VARCHAR2 NAME }\n    COURSE  { VARCHAR2 SUB_ID PK\n              VARCHAR2 NAME }\n    ENROLL  { VARCHAR2 STU_ID PK\n              VARCHAR2 SUB_ID PK\n              NUMBER   SCORE }\n    </div>\n\n    <!-- 관계선택성 -->\n    <h2 class=\"reveal\">관계선택성(Optionality)</h2>\n    <table class=\"reveal\">\n      <thead><tr><th>종류</th><th>표기</th><th>의미</th></tr></thead>\n      <tbody>\n        <tr><td>필수(Mandatory)</td><td>─</td><td>반드시 있어야 함</td></tr>\n        <tr><td>선택(Optional)</td><td>○</td><td>있을 수도 있고 없을 수도 있음</td></tr>\n      </tbody>\n    </table>\n    <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code>[회원] ──── [주문]      :  주문은 반드시 회원이 있어야 함(<span class=\"sql-kw\">필수</span>)\n[회원] ──○─ [쿠폰]      :  회원이 쿠폰은 없을 수도 있음(<span class=\"sql-kw\">선택</span>)</code></pre>\n\n    <!-- 식별 vs 비식별 -->\n    <h2 class=\"reveal\">관계의 분류 — 식별 vs 비식별</h2>\n\n    <div class=\"ident-pair reveal\">\n      <div class=\"ident-card solid\">\n        <div class=\"nm\">━━ 식별 관계 (실선)</div>\n        <div class=\"ds\">자식의 PK에 부모 <a href=\"#\" data-chapter=\"c115\">식별자</a>가 <strong>포함</strong>됨 (강한 종속)</div>\n        <div class=\"ex\">자식이 부모 없이 존재 불가 (예: 주문 ↔ 주문상세)</div>\n      </div>\n      <div class=\"ident-card dashed\">\n        <div class=\"nm\">┄┄ 비식별 관계 (점선)</div>\n        <div class=\"ds\">부모 식별자가 자식의 일반 속성(FK)으로만 들어감 (약한 종속)</div>\n        <div class=\"ex\">자식이 부모 없이도 존재 가능 (예: 부서 ↔ 사원)</div>\n      </div>\n    </div>\n    <table class=\"reveal\">\n      <thead><tr><th>종류</th><th>자식의 PK에 부모 식별자가 포함?</th><th>표기</th><th>비유</th></tr></thead>\n      <tbody>\n        <tr><td>식별 관계</td><td>포함됨 (강한 종속)</td><td>실선</td><td>자식이 부모 없이 존재 불가 (예: 주문 ↔ 주문상세)</td></tr>\n        <tr><td>비식별 관계</td><td>포함 안 됨 (약한 종속)</td><td>점선</td><td>자식이 부모 없이도 존재 가능 (예: 부서 ↔ 사원)</td></tr>\n      </tbody>\n    </table>\n\n    <!-- SQL 실전 -->\n    <h2 class=\"section-label sec-sql reveal\"><span class=\"label-tag\">SQL 실전</span><span class=\"label-rest\">관계는 외래키(FK)로 구현된다</span></h2>\n    <p class=\"reveal\">설계 단계의 관계는 SQL 단계에서 <a href=\"#\" data-chapter=\"c217\">조인</a>으로 활용된다. 관계와 조인의 연결은 <a href=\"#\" data-chapter=\"c122\">관계와 조인의 이해</a>에서 자세히 본다.</p>\n    <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터</p>\n    <div class=\"ba-flow reveal\" style=\"grid-template-columns: 1fr 36px 1fr; align-items: stretch;\">\n      <div class=\"ba-side before\">\n        <span class=\"ba-tag\">MEMBER</span>\n        <h4 class=\"ba-h\">회원 테이블 (부모)</h4>\n        <div class=\"mini-table cols-2\">\n          <div class=\"h\">MEMBER_ID</div><div class=\"h\">NAME</div>\n          <div class=\"c\">M01</div><div class=\"c\">김철수</div>\n          <div class=\"c\">M02</div><div class=\"c\">이영희</div>\n        </div>\n      </div>\n      <div class=\"ba-arrow\" style=\"font-size: 22px; color: var(--point-500);\">+</div>\n      <div class=\"ba-side before\">\n        <span class=\"ba-tag\">ORDERS</span>\n        <h4 class=\"ba-h\">주문 테이블 (자식)</h4>\n        <div class=\"mini-table cols-3\">\n          <div class=\"h\">ORDER_ID</div><div class=\"h\">MEMBER_ID</div><div class=\"h\">ORD_DATE</div>\n          <div class=\"c\">1001</div><div class=\"c\">M01</div><div class=\"c\">2026-04-01</div>\n          <div class=\"c\">1002</div><div class=\"c\">M01</div><div class=\"c\">2026-04-05</div>\n          <div class=\"c\">1003</div><div class=\"c\">M02</div><div class=\"c\">2026-04-07</div>\n        </div>\n      </div>\n    </div>\n    <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 회원(부모) 1 : N 주문(자식)</span>\n<span class=\"sql-kw\">CREATE TABLE</span> <span class=\"sql-name\">MEMBER</span> (\n    <span class=\"sql-type\">MEMBER_ID</span>  <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">10</span>) <span class=\"sql-kw\">PRIMARY KEY</span>,\n    <span class=\"sql-type\">NAME</span>       <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">50</span>)\n);\n\n<span class=\"sql-kw\">CREATE TABLE</span> <span class=\"sql-name\">ORDERS</span> (\n    <span class=\"sql-type\">ORDER_ID</span>   <span class=\"sql-type\">NUMBER</span> <span class=\"sql-kw\">PRIMARY KEY</span>,\n    <span class=\"sql-type\">MEMBER_ID</span>  <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">10</span>),  <span class=\"sql-cm\">-- 외래키(관계의 구현)</span>\n    <span class=\"sql-type\">ORD_DATE</span>   <span class=\"sql-type\">DATE</span>,\n    <span class=\"sql-kw\">CONSTRAINT</span> <span class=\"sql-name\">FK_ORDER_MEMBER</span>\n        <span class=\"sql-kw\">FOREIGN KEY</span>(<span class=\"sql-type\">MEMBER_ID</span>) <span class=\"sql-kw\">REFERENCES</span> <span class=\"sql-name\">MEMBER</span>(<span class=\"sql-type\">MEMBER_ID</span>)\n);\n\n<span class=\"sql-cm\">-- 관계는 곧 조인이 된다</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">M</span>.<span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">O</span>.<span class=\"sql-type\">ORDER_ID</span>, <span class=\"sql-type\">O</span>.<span class=\"sql-type\">ORD_DATE</span>\n  <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">MEMBER</span> <span class=\"sql-type\">M</span>\n  <span class=\"sql-kw\">JOIN</span> <span class=\"sql-name\">ORDERS</span> <span class=\"sql-type\">O</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-type\">M</span>.<span class=\"sql-type\">MEMBER_ID</span> = <span class=\"sql-type\">O</span>.<span class=\"sql-type\">MEMBER_ID</span>;</code></pre>\n\n    <p class=\"reveal\" style=\"font-size:13px;color:var(--fg-3);margin:8px 0 4px;\">↓ 결과</p>\n    <table class=\"reveal\">\n      <thead><tr><th>NAME</th><th>ORDER_ID</th><th>ORD_DATE</th></tr></thead>\n      <tbody>\n        <tr><td>김철수</td><td>1001</td><td>2026-04-01</td></tr>\n        <tr><td>김철수</td><td>1002</td><td>2026-04-05</td></tr>\n        <tr><td>이영희</td><td>1003</td><td>2026-04-07</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ MEMBER_ID로 두 테이블이 연결되어 회원 1명의 여러 주문이 한 행씩 펼쳐진다(M01 → 1001/1002 두 행).</p>\n    <p class=\"reveal\">설계의 1:N 관계가 SQL 단계에서 <code>ON M.MEMBER_ID = O.MEMBER_ID</code> 한 줄로 구현된다 — 관계의 의미가 그대로 조인 조건이 된다.</p>\n\n    <!-- Before & After -->\n    <h2 class=\"section-label sec-compare reveal\"><span class=\"label-tag\">Before &amp; After</span><span class=\"label-rest\">M:N 관계의 분해</span></h2>\n    <p class=\"reveal\">학생은 여러 과목을 듣고 한 과목에는 여러 학생이 등록한다 — 양쪽 모두 다(多)인 M:N. 이 관계를 그대로 두려는 시도와, 가운데 '수강' 교차 엔터티를 끼워 1:N 두 개로 쪼갠 형태를 비교한다.</p>\n\n    <div class=\"ba-flow large-after reveal\">\n      <div class=\"ba-side before\">\n        <span class=\"ba-tag\">BEFORE</span>\n        <h4 class=\"ba-h\">M:N 그대로 → 다중값</h4>\n        <div class=\"sql\">[학생] M ────── N [과목]</div>\n        <div class=\"mini-table\">\n          <div class=\"h\">학생</div><div class=\"h\">듣는 과목들</div>\n          <div class=\"c\">김철수</div><div class=\"c is-null\">수학, 영어, 국어</div>\n          <div class=\"c\">이영희</div><div class=\"c is-null\">영어, 과학</div>\n        </div>\n      </div>\n      <div class=\"ba-arrow\">→</div>\n      <div class=\"ba-side after\">\n        <span class=\"ba-tag\">AFTER</span>\n        <h4 class=\"ba-h\">교차 엔터티로 1:N + 1:N</h4>\n        <div class=\"sql\">[학생] 1 ── N [수강] N ── 1 [과목]</div>\n        <div class=\"ba-tables cols-3\">\n          <div class=\"ba-mini-table\"><div class=\"h\">학생</div><div class=\"row\">S01 / 김철수</div><div class=\"row\">S02 / 이영희</div></div>\n          <div class=\"ba-mini-table\"><div class=\"h\">수강</div><div class=\"row\">S01 · K1</div><div class=\"row\">S01 · K2</div><div class=\"row\">S02 · K2</div></div>\n          <div class=\"ba-mini-table\"><div class=\"h\">과목</div><div class=\"row\">K1 / 수학</div><div class=\"row\">K2 / 영어</div></div>\n        </div>\n      </div>\n    </div>\n\n    <h4 class=\"reveal\">Before — M:N 관계는 그대로 구현 불가</h4>\n    <table class=\"reveal\">\n      <thead><tr><th>학생</th><th>듣는 과목들</th></tr></thead>\n      <tbody>\n        <tr><td>김철수</td><td>수학, 영어, 국어</td></tr>\n        <tr><td>이영희</td><td>영어, 과학</td></tr>\n      </tbody>\n    </table>\n\n    <h4 class=\"reveal\">After — 1:N + 1:N으로 분해</h4>\n    <p class=\"reveal\" style=\"font-size:13.5px;color:var(--fg-3);\">학생</p>\n    <table class=\"reveal\">\n      <thead><tr><th>STU_ID</th><th>NAME</th></tr></thead>\n      <tbody>\n        <tr><td>S01</td><td>김철수</td></tr>\n        <tr><td>S02</td><td>이영희</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\" style=\"font-size:13.5px;color:var(--fg-3);\">과목</p>\n    <table class=\"reveal\">\n      <thead><tr><th>SUB_ID</th><th>NAME</th></tr></thead>\n      <tbody>\n        <tr><td>K1</td><td>수학</td></tr>\n        <tr><td>K2</td><td>영어</td></tr>\n        <tr><td>K3</td><td>국어</td></tr>\n        <tr><td>K4</td><td>과학</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\" style=\"font-size:13.5px;color:var(--fg-3);\">수강(교차 엔터티)</p>\n    <table class=\"reveal\">\n      <thead><tr><th>STU_ID</th><th>SUB_ID</th></tr></thead>\n      <tbody>\n        <tr><td>S01</td><td>K1</td></tr>\n        <tr><td>S01</td><td>K2</td></tr>\n        <tr><td>S01</td><td>K3</td></tr>\n        <tr><td>S02</td><td>K2</td></tr>\n        <tr><td>S02</td><td>K4</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\">M:N 을 그대로 두면 학생 행에 \"수학, 영어, 국어\" 같은 다중값 컬럼을 넣을 수밖에 없는데, 이는 1NF 위반이고 성적·수강일 같은 관계 자체의 속성도 둘 곳이 없어진다. 가운데에 수강 같은 교차 엔터티를 두면 (S01, K1) 한 줄이 한 수강 사실을 표현하므로 관계 속성도 자연스럽게 거기에 붙는다. 양쪽이 다(多)인 관계를 만나면 반사적으로 교차 엔터티를 끼워 1:N + 1:N 으로 분해하는 것이 안전하다.</p>\n\n    <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n      <div>\n        <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n        <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n      </div>\n      <a href=\"./exam-review.html#ch-1-1-4\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n    </div>",
  c115: "<!-- 핵심 요약 -->\n    <h2 class=\"section-label sec-summary reveal\"><span class=\"label-tag\">핵심 요약</span><span class=\"label-rest\">정의</span></h2>\n    <blockquote class=\"reveal\">\n      식별자(Identifier)란 <a href=\"#\" data-chapter=\"c112\">엔터티</a> 안의 인스턴스를 서로 구분해 주는 <strong>유일한 표식</strong>이다. 테이블의 기본키(Primary Key)가 된다.\n    </blockquote>\n    <div class=\"ex-box reveal\">\n      같은 이름의 김철수가 100명 있어도 주민등록번호는 모두 다르다 — 이름은 일반 속성이지만 주민번호는 식별자(겹치지 않는 유일값)다.\n    </div>\n\n    <!-- 개념 도식화 -->\n    <h2 class=\"section-label sec-diagram reveal\"><span class=\"label-tag\">개념 도식화</span><span class=\"label-rest\">식별자의 위치</span></h2>\n    <p class=\"reveal\">회원(MEMBER) 테이블 — PK 가 모든 행을 유일하게 구분:</p>\n    <table class=\"reveal\">\n      <thead><tr><th>PK (주식별자)</th><th>이름</th><th>전화번호</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"pk-mark\">PK</span><strong>M01</strong></td><td>김철수</td><td>010-1111</td></tr>\n        <tr><td><span class=\"pk-mark\">PK</span><strong>M02</strong></td><td>이영희</td><td>010-2222</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\">같은 이름이어도 PK가 다르므로 <strong>100% 구분 가능</strong>.</p>\n\n    <p class=\"reveal\">PK는 자기 엔터티 안의 식별자, FK(외부식별자)는 다른 엔터티의 PK 를 참조한 식별자다 — ER로 같이 본다.</p>\n    <div class=\"mermaid reveal\">\nerDiagram\n    MEMBER ||--o{ ORDERS : \"주문하다\"\n    ORDERS ||--|{ ORDER_DETAIL : \"상세 (식별 관계)\"\n    PRODUCT ||--o{ ORDER_DETAIL : \"포함된다\"\n    MEMBER {\n        VARCHAR2 MEMBER_ID PK\n        VARCHAR2 EMAIL \"보조식별자(UNIQUE)\"\n        VARCHAR2 NAME\n    }\n    ORDERS {\n        NUMBER ORDER_ID PK\n        VARCHAR2 MEMBER_ID FK\n    }\n    ORDER_DETAIL {\n        NUMBER ORDER_ID PK \"복합식별자\"\n        VARCHAR2 PROD_ID PK\n        NUMBER QTY\n    }\n    PRODUCT {\n        VARCHAR2 PROD_ID PK\n        VARCHAR2 PROD_NAME\n    }\n    </div>\n\n    <!-- 4대 조건: 유최불존 -->\n    <h2 class=\"reveal\">주식별자의 4가지 조건</h2>\n    <div class=\"trait-grid cols-4 reveal\">\n      <div class=\"trait-card\"><div class=\"glyph\">유</div><div class=\"label\">유일성</div><div class=\"desc\">모든 인스턴스를 <strong>유일하게</strong> 구분</div></div>\n      <div class=\"trait-card\"><div class=\"glyph\">최</div><div class=\"label\">최소성</div><div class=\"desc\">꼭 필요한 속성만 — <a href=\"#\" data-chapter=\"c121\">정규화</a>와 직결</div></div>\n      <div class=\"trait-card\"><div class=\"glyph\">불</div><div class=\"label\">불변성</div><div class=\"desc\">한 번 정해지면 <strong>거의 변하지 않음</strong></div></div>\n      <div class=\"trait-card\"><div class=\"glyph\">존</div><div class=\"label\">존재성</div><div class=\"desc\">NULL이 될 수 없음 (<strong>NOT NULL</strong>)</div></div>\n    </div>\n    <div class=\"mnemonic reveal\">\n      <div class=\"label-side\">암기<br><small>주식별자 4대 조건</small></div>\n      <div class=\"glyphs\">\n        <div class=\"glyph-chip\">유</div>\n        <div class=\"glyph-chip\">최</div>\n        <div class=\"glyph-chip\">불</div>\n        <div class=\"glyph-chip\">존</div>\n      </div>\n    </div>\n    <table class=\"reveal\">\n      <thead><tr><th>조건</th><th>의미</th></tr></thead>\n      <tbody>\n        <tr><td>유일성</td><td>모든 인스턴스를 유일하게 구분</td></tr>\n        <tr><td>최소성</td><td>꼭 필요한 속성만으로 구성 (<a href=\"#\" data-chapter=\"c121\">정규화</a>와 직결)</td></tr>\n        <tr><td>불변성</td><td>한번 정해지면 거의 변하지 않음</td></tr>\n        <tr><td>존재성</td><td>NULL이 될 수 없음</td></tr>\n      </tbody>\n    </table>\n\n    <!-- 4대 분류 기준 -->\n    <h2 class=\"reveal\">식별자의 4가지 분류 기준</h2>\n\n    <div class=\"cls-row cols-4 reveal\">\n      <div class=\"cls-card\">\n        <span class=\"badge\">① 대표성</span>\n        <div class=\"name\">주 / 보조</div>\n        <div class=\"ex\">엔터티 대표 vs 보조용</div>\n      </div>\n      <div class=\"cls-card\">\n        <span class=\"badge b-info\">② 생성 여부</span>\n        <div class=\"name\">내부 / 외부</div>\n        <div class=\"ex\">내가 만듦 vs 가져옴(=FK)</div>\n      </div>\n      <div class=\"cls-card\">\n        <span class=\"badge b-warn\">③ 속성 수</span>\n        <div class=\"name\">단일 / 복합</div>\n        <div class=\"ex\">1개 vs 2개 이상 결합</div>\n      </div>\n      <div class=\"cls-card\">\n        <span class=\"badge b-event\">④ 대체 여부</span>\n        <div class=\"name\">본질 / 인조</div>\n        <div class=\"ex\">자연 도출 vs 인위 부여</div>\n      </div>\n    </div>\n    <table class=\"reveal\">\n      <thead><tr><th>기준</th><th>분류</th><th>핵심 차이</th></tr></thead>\n      <tbody>\n        <tr><td>① 대표성</td><td><strong>주식별자 / 보조식별자</strong></td><td>엔터티의 대표 식별자 vs 보조용</td></tr>\n        <tr><td>② 생성 여부</td><td><strong>내부식별자 / 외부식별자</strong></td><td>자기 엔터티에서 생성 vs 다른 엔터티에서 가져옴 (= FK)</td></tr>\n        <tr><td>③ 속성 수</td><td><strong>단일식별자 / 복합식별자</strong></td><td>1개 속성 vs 2개 이상 결합</td></tr>\n        <tr><td>④ 대체 여부</td><td><strong>본질식별자 / 인조식별자</strong></td><td>업무 자연 도출 vs 인위적 부여</td></tr>\n      </tbody>\n    </table>\n\n    <h3 class=\"reveal\">대표성</h3>\n    <table class=\"reveal\">\n      <thead><tr><th>종류</th><th>의미</th><th>예</th></tr></thead>\n      <tbody>\n        <tr><td>주식별자(Primary)</td><td>엔터티 대표 식별자</td><td>회원ID</td></tr>\n        <tr><td>보조식별자(Alternate)</td><td>보조적 식별자</td><td>이메일</td></tr>\n      </tbody>\n    </table>\n\n    <h3 class=\"reveal\">스스로 만든 vs 외부에서 받음</h3>\n    <table class=\"reveal\">\n      <thead><tr><th>종류</th><th>의미</th><th>예</th></tr></thead>\n      <tbody>\n        <tr><td>내부식별자</td><td>자기 엔터티 내에서 생성</td><td>MEMBER 테이블의 MEMBER_ID</td></tr>\n        <tr><td>외부식별자</td><td>다른 엔터티의 주식별자를 참조해 가져옴 = <strong>외래키(FK)</strong></td><td>주문 테이블의 MEMBER_ID (← 회원 PK 참조)</td></tr>\n      </tbody>\n    </table>\n\n    <h3 class=\"reveal\">속성의 개수</h3>\n    <table class=\"reveal\">\n      <thead><tr><th>종류</th><th>의미</th><th>예</th></tr></thead>\n      <tbody>\n        <tr><td>단일식별자</td><td>1개 속성</td><td>회원ID</td></tr>\n        <tr><td>복합식별자</td><td>2개 이상 속성 결합</td><td>(주문ID + 상품ID) → 주문상세 PK</td></tr>\n      </tbody>\n    </table>\n\n    <h3 class=\"reveal\">본질 vs 인조</h3>\n    <table class=\"reveal\">\n      <thead><tr><th>종류</th><th>의미</th><th>예</th></tr></thead>\n      <tbody>\n        <tr><td>본질식별자</td><td>업무에서 자연스럽게 도출</td><td>주민번호, 학번</td></tr>\n        <tr><td>인조식별자</td><td>인위적으로 만든 식별자</td><td>자동증가 ID, UUID</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\">본질·인조의 트레이드오프는 <a href=\"#\" data-chapter=\"c125\">본질식별자 vs 인조식별자</a>에서 자세히 다룬다.</p>\n\n    <!-- SQL 실전 -->\n    <h2 class=\"section-label sec-sql reveal\"><span class=\"label-tag\">SQL 실전</span><span class=\"label-rest\">PK / FK 정의</span></h2>\n    <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — 단일 PK(MEMBER) + 복합 PK(ORDER_DETAIL)</p>\n    <div class=\"ba-flow reveal\" style=\"grid-template-columns: 1fr 36px 1fr; align-items: stretch;\">\n      <div class=\"ba-side before\">\n        <span class=\"ba-tag\">MEMBER</span>\n        <h4 class=\"ba-h\">단일 식별자</h4>\n        <div class=\"mini-table cols-3\">\n          <div class=\"h\">MEMBER_ID (PK)</div><div class=\"h\">EMAIL (UK)</div><div class=\"h\">NAME</div>\n          <div class=\"c\">M01</div><div class=\"c\">a@a.com</div><div class=\"c\">김철수</div>\n        </div>\n      </div>\n      <div class=\"ba-arrow\" style=\"font-size: 22px; color: var(--point-500);\">+</div>\n      <div class=\"ba-side before\">\n        <span class=\"ba-tag\">ORDER_DETAIL</span>\n        <h4 class=\"ba-h\">복합 식별자 (ORDER_ID + PROD_ID)</h4>\n        <div class=\"mini-table cols-3\">\n          <div class=\"h\">ORDER_ID (PK)</div><div class=\"h\">PROD_ID (PK)</div><div class=\"h\">QTY</div>\n          <div class=\"c\">1001</div><div class=\"c\">P01</div><div class=\"c\">2</div>\n          <div class=\"c\">1001</div><div class=\"c\">P02</div><div class=\"c\">1</div>\n        </div>\n      </div>\n    </div>\n    <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 회원: 단일 PK</span>\n<span class=\"sql-kw\">CREATE TABLE</span> <span class=\"sql-name\">MEMBER</span> (\n    <span class=\"sql-type\">MEMBER_ID</span>  <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">10</span>) <span class=\"sql-kw\">PRIMARY KEY</span>,   <span class=\"sql-cm\">-- 주식별자</span>\n    <span class=\"sql-type\">EMAIL</span>      <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">100</span>) <span class=\"sql-kw\">UNIQUE</span>,       <span class=\"sql-cm\">-- 보조식별자</span>\n    <span class=\"sql-type\">NAME</span>       <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">50</span>) <span class=\"sql-kw\">NOT NULL</span>\n);\n\n<span class=\"sql-cm\">-- 주문상세: 복합 PK</span>\n<span class=\"sql-kw\">CREATE TABLE</span> <span class=\"sql-name\">ORDER_DETAIL</span> (\n    <span class=\"sql-type\">ORDER_ID</span>   <span class=\"sql-type\">NUMBER</span>,\n    <span class=\"sql-type\">PROD_ID</span>    <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">10</span>),\n    <span class=\"sql-type\">QTY</span>        <span class=\"sql-type\">NUMBER</span>,\n    <span class=\"sql-kw\">CONSTRAINT</span> <span class=\"sql-name\">PK_ORD_DTL</span> <span class=\"sql-kw\">PRIMARY KEY</span> (<span class=\"sql-type\">ORDER_ID</span>, <span class=\"sql-type\">PROD_ID</span>),  <span class=\"sql-cm\">-- 복합 식별자</span>\n    <span class=\"sql-kw\">CONSTRAINT</span> <span class=\"sql-name\">FK_OD_ORD</span>  <span class=\"sql-kw\">FOREIGN KEY</span> (<span class=\"sql-type\">ORDER_ID</span>) <span class=\"sql-kw\">REFERENCES</span> <span class=\"sql-name\">ORDERS</span>(<span class=\"sql-type\">ORDER_ID</span>),\n    <span class=\"sql-kw\">CONSTRAINT</span> <span class=\"sql-name\">FK_OD_PROD</span> <span class=\"sql-kw\">FOREIGN KEY</span> (<span class=\"sql-type\">PROD_ID</span>)  <span class=\"sql-kw\">REFERENCES</span> <span class=\"sql-name\">PRODUCT</span>(<span class=\"sql-type\">PROD_ID</span>)\n);\n\n<span class=\"sql-cm\">-- PK 위반 — 같은 회원ID 중복 입력</span>\n<span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">MEMBER</span> <span class=\"sql-kw\">VALUES</span>(<span class=\"sql-str\">'M01'</span>, <span class=\"sql-str\">'a@a.com'</span>, <span class=\"sql-str\">'김철수'</span>);\n<span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">MEMBER</span> <span class=\"sql-kw\">VALUES</span>(<span class=\"sql-str\">'M01'</span>, <span class=\"sql-str\">'b@b.com'</span>, <span class=\"sql-str\">'박민수'</span>);   <span class=\"sql-cm\">-- 에러!</span>\n\n<span class=\"sql-cm\">-- NULL 위반 — 주식별자에는 NULL 불가</span>\n<span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">MEMBER</span> <span class=\"sql-kw\">VALUES</span>(<span class=\"sql-kw\">NULL</span>, <span class=\"sql-str\">'c@c.com'</span>, <span class=\"sql-str\">'이영희'</span>);  <span class=\"sql-cm\">-- 에러!</span></code></pre>\n\n    <p class=\"reveal\" style=\"font-size:13px;color:var(--fg-3);margin:8px 0 4px;\">↓ 실행 결과 (DBMS 메시지)</p>\n    <table class=\"reveal\">\n      <thead><tr><th>SQL</th><th>결과</th></tr></thead>\n      <tbody>\n        <tr><td><code>INSERT … 'M01' … '김철수'</code></td><td><span style=\"color:var(--correct-fg);font-weight:700;\">1 row inserted.</span></td></tr>\n        <tr><td><code>INSERT … 'M01' … '박민수'</code></td><td><span style=\"color:var(--wrong-fg);font-weight:700;\">ORA-00001: unique constraint violated</span> (유일성 위반)</td></tr>\n        <tr><td><code>INSERT … NULL … '이영희'</code></td><td><span style=\"color:var(--wrong-fg);font-weight:700;\">ORA-01400: cannot insert NULL into PK</span> (존재성 위반)</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\">PRIMARY KEY 제약은 <strong>유일성 + NOT NULL</strong>을 한꺼번에 강제한다 — 식별자 4대 조건 중 두 가지가 DBMS 차원에서 자동 보장된다.</p>\n\n    <!-- Before & After -->\n    <h2 class=\"section-label sec-compare reveal\"><span class=\"label-tag\">Before &amp; After</span><span class=\"label-rest\">식별자를 잘못 잡으면</span></h2>\n    <p class=\"reveal\">이름이 똑같은 김철수가 두 명 가입한 상황. 이름을 PK로 잡은 경우와 회원ID 를 따로 부여한 경우를 비교한다.</p>\n\n    <div class=\"ba-flow reveal\">\n      <div class=\"ba-side before\">\n        <span class=\"ba-tag\">BEFORE</span>\n        <h4 class=\"ba-h\">식별자 = 이름</h4>\n        <div class=\"mini-table\">\n          <div class=\"h\">NAME (PK?)</div><div class=\"h\">PHONE</div>\n          <div class=\"c\">김철수</div><div class=\"c\">010-1111</div>\n          <div class=\"c is-null\">김철수</div><div class=\"c\">010-2222</div>\n        </div>\n        <p style=\"font-size:12px;color:var(--fg-3);margin:10px 0 0;\">동명이인 등록 불가 (유일성 위반)</p>\n      </div>\n      <div class=\"ba-arrow\">→</div>\n      <div class=\"ba-side after\">\n        <span class=\"ba-tag\">AFTER</span>\n        <h4 class=\"ba-h\">식별자 = 회원ID</h4>\n        <div class=\"mini-table cols-3\">\n          <div class=\"h\">ID (PK)</div><div class=\"h\">NAME</div><div class=\"h\">PHONE</div>\n          <div class=\"c\">M01</div><div class=\"c\">김철수</div><div class=\"c\">010-1111</div>\n          <div class=\"c\">M02</div><div class=\"c\">김철수</div><div class=\"c\">010-2222</div>\n        </div>\n        <p style=\"font-size:12px;color:var(--fg-3);margin:10px 0 0;\">동명이인이라도 ID로 구분</p>\n      </div>\n    </div>\n\n    <h4 class=\"reveal\">Before — 식별자가 '이름'</h4>\n    <table class=\"reveal\">\n      <thead><tr><th>NAME (PK?)</th><th>PHONE</th></tr></thead>\n      <tbody>\n        <tr><td>김철수</td><td>010-1111</td></tr>\n        <tr><td>김철수</td><td>010-2222</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\">동명이인을 등록할 수 없다(유일성 위반).</p>\n\n    <h4 class=\"reveal\">After — 식별자가 '회원ID'</h4>\n    <table class=\"reveal\">\n      <thead><tr><th>MEMBER_ID (PK)</th><th>NAME</th><th>PHONE</th></tr></thead>\n      <tbody>\n        <tr><td>M01</td><td>김철수</td><td>010-1111</td></tr>\n        <tr><td>M02</td><td>김철수</td><td>010-2222</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\">이름은 같은 값이 얼마든지 나올 수 있으므로 유일성을 보장하지 못한다. 식별자의 4대 조건(유·최·불·존) 중 가장 먼저 깨지는 게 유일성이고, 결혼·개명 등으로 변할 수도 있어 불변성도 위태롭다. 업무 속성 중 자연스러운 유일값이 마땅치 않으면 회원ID 처럼 인조식별자를 만들어 PK 로 두는 것이 안전하다.</p>\n\n    <!-- 식별자 표기 -->\n    <h2 class=\"reveal\">식별자 표기</h2>\n    <p class=\"reveal\">ERD 표기 — 회원 엔터티:</p>\n    <table class=\"reveal\">\n      <thead><tr><th>영역</th><th>속성</th><th>비고</th></tr></thead>\n      <tbody>\n        <tr><td><strong>PK 영역</strong></td><td>MEMBER_ID</td><td>주식별자 (Primary)</td></tr>\n        <tr><td>일반 속성</td><td>NAME</td><td></td></tr>\n        <tr><td>일반 속성</td><td>EMAIL</td><td>UNIQUE = 보조식별자</td></tr>\n        <tr><td>일반 속성</td><td>PHONE</td><td></td></tr>\n      </tbody>\n    </table>\n\n    <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n      <div>\n        <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n        <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n      </div>\n      <a href=\"./exam-review.html#ch-1-1-5\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n    </div>",
  c121: "<!-- 핵심 요약 -->\n    <h2 class=\"section-label sec-summary reveal\"><span class=\"label-tag\">핵심 요약</span><span class=\"label-rest\">정의</span></h2>\n    <blockquote class=\"reveal\">\n      정규화(Normalization)란 데이터의 <strong>중복을 없애고</strong> 깔끔하게 정리하는 작업이다. 테이블을 단계적으로 쪼개서 <strong>이상현상</strong>을 막는다.\n    </blockquote>\n    <div class=\"ex-box reveal\">\n      옷장 한 칸에 속옷·양말·셔츠·외투를 다 욱여넣으면 양말 찾기가 어렵고, 셔츠를 빼다가 다른 옷이 떨어진다. 칸을 나눠 종류별로 분리하는 것이 정규화다.\n    </div>\n\n    <!-- 개념 도식화 — 정규화 단계 -->\n    <h2 class=\"section-label sec-diagram reveal\"><span class=\"label-tag\">개념 도식화</span><span class=\"label-rest\">정규화 단계</span></h2>\n    <div class=\"step-flow cols-4 reveal\">\n      <div class=\"step-card\">\n        <div class=\"step\">STEP 1</div>\n        <div class=\"name\">1NF <small>원자값</small></div>\n        <div class=\"ex\">한 칸에 한 값만</div>\n        <div class=\"arrow-next\">›</div>\n      </div>\n      <div class=\"step-card\">\n        <div class=\"step\">STEP 2</div>\n        <div class=\"name\">2NF <small>부분종속 제거</small></div>\n        <div class=\"ex\">PK 일부에만 종속된 컬럼 분리</div>\n        <div class=\"arrow-next\">›</div>\n      </div>\n      <div class=\"step-card\">\n        <div class=\"step\">STEP 3</div>\n        <div class=\"name\">3NF <small>이행종속 제거</small></div>\n        <div class=\"ex\">A→B→C 형태 분리</div>\n        <div class=\"arrow-next\">›</div>\n      </div>\n      <div class=\"step-card\">\n        <div class=\"step\">STEP 4</div>\n        <div class=\"name\">BCNF <small>엄격 3NF</small></div>\n        <div class=\"ex\">모든 결정자 = 후보키</div>\n      </div>\n    </div>\n    <table class=\"reveal\">\n      <thead><tr><th>단계</th><th>핵심 규칙</th><th>한줄 의미</th></tr></thead>\n      <tbody>\n        <tr><td>1NF</td><td>모든 속성이 원자값</td><td>한 칸에 한 값만</td></tr>\n        <tr><td>2NF</td><td>부분 함수 종속 제거</td><td>PK 일부에만 종속된 컬럼 분리</td></tr>\n        <tr><td>3NF</td><td>이행 함수 종속 제거</td><td>A→B→C 형태 분리</td></tr>\n        <tr><td>BCNF</td><td>모든 결정자가 후보키</td><td>더 엄격한 3NF</td></tr>\n      </tbody>\n    </table>\n\n    <div class=\"mermaid reveal\">\nflowchart LR\n    NF0[\"비정규형<br/>(다중값·반복그룹)\"] -->|\"원자값으로\"| NF1[\"1NF<br/>한 칸에 한 값\"]\n    NF1 -->|\"부분종속 제거\"| NF2[\"2NF<br/>PK 전체에 종속\"]\n    NF2 -->|\"이행종속 제거\"| NF3[\"3NF<br/>비이행 종속만\"]\n    NF3 -->|\"결정자=후보키\"| BCNF[\"BCNF<br/>엄격한 3NF\"]\n    style NF0 fill:#FCEEE5,stroke:#A9562E\n    style BCNF fill:#E6F3E7,stroke:#256B29\n    </div>\n\n    <!-- 이상현상 -->\n    <h2 class=\"reveal\">이상현상(Anomaly) 3가지</h2>\n    <div class=\"anom-grid reveal\">\n      <div class=\"anom-card\">\n        <div class=\"icn\">＋</div>\n        <div class=\"nm\">삽입 이상</div>\n        <div class=\"ds\">데이터 넣으려는데 다른 정보가 없어 못 넣음</div>\n        <div class=\"ex\">학생 등록하려는데 수강과목 칸을 비울 수 없음</div>\n      </div>\n      <div class=\"anom-card\">\n        <div class=\"icn\">↻</div>\n        <div class=\"nm\">갱신 이상</div>\n        <div class=\"ds\">한 곳만 바꿨는데 다른 곳이 안 바뀜</div>\n        <div class=\"ex\">회원 주소 1곳만 수정해 데이터 불일치</div>\n      </div>\n      <div class=\"anom-card\">\n        <div class=\"icn\">−</div>\n        <div class=\"nm\">삭제 이상</div>\n        <div class=\"ds\">데이터 지우려다 필요한 정보까지 사라짐</div>\n        <div class=\"ex\">마지막 수강 취소했는데 학생 정보까지 삭제</div>\n      </div>\n    </div>\n    <table class=\"reveal\">\n      <thead><tr><th>종류</th><th>무슨 일인가</th><th>비유</th></tr></thead>\n      <tbody>\n        <tr><td>삽입 이상</td><td>데이터 넣으려는데 다른 정보가 없어 못 넣음</td><td>학생 등록하려는데 수강과목 칸을 비울 수 없음</td></tr>\n        <tr><td>갱신 이상</td><td>한 곳만 바꿨는데 다른 곳이 안 바뀜</td><td>회원 주소 1곳만 수정해 데이터 불일치</td></tr>\n        <tr><td>삭제 이상</td><td>데이터 지우려다 필요한 정보까지 사라짐</td><td>마지막 수강 취소했는데 학생 정보까지 삭제</td></tr>\n      </tbody>\n    </table>\n\n    <!-- 1NF -->\n    <h2 class=\"reveal\">1NF — 원자값 만들기</h2>\n    <div class=\"ba-flow reveal\">\n      <div class=\"ba-side before\">\n        <span class=\"ba-tag\">BEFORE</span>\n        <h4 class=\"ba-h\">비정규형 (다중값)</h4>\n        <div class=\"mini-table\">\n          <div class=\"h\">학생</div><div class=\"h\">수강과목</div>\n          <div class=\"c\">김철수</div><div class=\"c is-null\">수학, 영어, 국어</div>\n        </div>\n      </div>\n      <div class=\"ba-arrow\">→</div>\n      <div class=\"ba-side after\">\n        <span class=\"ba-tag\">AFTER (1NF)</span>\n        <h4 class=\"ba-h\">한 칸에 한 값</h4>\n        <div class=\"mini-table\">\n          <div class=\"h\">학생</div><div class=\"h\">수강과목</div>\n          <div class=\"c\">김철수</div><div class=\"c\">수학</div>\n          <div class=\"c\">김철수</div><div class=\"c\">영어</div>\n          <div class=\"c\">김철수</div><div class=\"c\">국어</div>\n        </div>\n      </div>\n    </div>\n\n    <h3 class=\"reveal\">Before(비정규형)</h3>\n    <table class=\"reveal\">\n      <thead><tr><th>학생</th><th>수강과목</th></tr></thead>\n      <tbody><tr><td>김철수</td><td>수학, 영어, 국어</td></tr></tbody>\n    </table>\n\n    <h3 class=\"reveal\">After(1NF)</h3>\n    <table class=\"reveal\">\n      <thead><tr><th>학생</th><th>수강과목</th></tr></thead>\n      <tbody>\n        <tr><td>김철수</td><td>수학</td></tr>\n        <tr><td>김철수</td><td>영어</td></tr>\n        <tr><td>김철수</td><td>국어</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\">모든 칸이 하나의 값을 가진다.</p>\n\n    <!-- 2NF -->\n    <h2 class=\"reveal\">2NF — 부분 함수 종속 제거</h2>\n    <p class=\"reveal\">부분 함수 종속이란 <a href=\"#\" data-chapter=\"c115\">복합 식별자</a>인 PK (A, B) 중 어떤 컬럼이 A에만 또는 B에만 의존하는 상태다.</p>\n\n    <div class=\"ba-flow large-after reveal\">\n      <div class=\"ba-side before\">\n        <span class=\"ba-tag\">BEFORE (1NF)</span>\n        <h4 class=\"ba-h\">PK = (학생ID, 과목ID) — 부분종속</h4>\n        <div class=\"mini-table cols-4\">\n          <div class=\"h\">학생ID</div><div class=\"h\">과목ID</div><div class=\"h\">학생이름</div><div class=\"h\">성적</div>\n          <div class=\"c\">S01</div><div class=\"c\">K1</div><div class=\"c is-null\">김철수</div><div class=\"c\">90</div>\n          <div class=\"c\">S01</div><div class=\"c\">K2</div><div class=\"c is-null\">김철수</div><div class=\"c\">85</div>\n        </div>\n        <p style=\"font-size:12px;color:var(--fg-3);margin:10px 0 0;\">학생이름은 학생ID에만, 과목명은 과목ID에만 종속</p>\n      </div>\n      <div class=\"ba-arrow\">→</div>\n      <div class=\"ba-side after\">\n        <span class=\"ba-tag\">AFTER (2NF)</span>\n        <h4 class=\"ba-h\">3개로 분리</h4>\n        <div class=\"ba-tables cols-3\">\n          <div class=\"ba-mini-table\"><div class=\"h\">학생</div><div class=\"row\">S01 / 김철수</div></div>\n          <div class=\"ba-mini-table\"><div class=\"h\">과목</div><div class=\"row\">K1 / 수학</div><div class=\"row\">K2 / 영어</div></div>\n          <div class=\"ba-mini-table\"><div class=\"h\">수강</div><div class=\"row\">S01·K1 / 90</div><div class=\"row\">S01·K2 / 85</div></div>\n        </div>\n      </div>\n    </div>\n\n    <h3 class=\"reveal\">Before(1NF, 부분종속 존재)</h3>\n    <p class=\"reveal\">PK = (학생ID, 과목ID)</p>\n    <table class=\"reveal\">\n      <thead><tr><th>학생ID</th><th>과목ID</th><th>학생이름</th><th>과목명</th><th>성적</th></tr></thead>\n      <tbody>\n        <tr><td>S01</td><td>K1</td><td>김철수</td><td>수학</td><td>90</td></tr>\n        <tr><td>S01</td><td>K2</td><td>김철수</td><td>영어</td><td>85</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\">학생이름은 학생ID에만, 과목명은 과목ID에만 종속된다.</p>\n\n    <h3 class=\"reveal\">After(2NF)</h3>\n    <p class=\"reveal\" style=\"font-size:13.5px;color:var(--fg-3);\">학생</p>\n    <table class=\"reveal\">\n      <thead><tr><th>학생ID</th><th>학생이름</th></tr></thead>\n      <tbody><tr><td>S01</td><td>김철수</td></tr></tbody>\n    </table>\n    <p class=\"reveal\" style=\"font-size:13.5px;color:var(--fg-3);\">과목</p>\n    <table class=\"reveal\">\n      <thead><tr><th>과목ID</th><th>과목명</th></tr></thead>\n      <tbody>\n        <tr><td>K1</td><td>수학</td></tr>\n        <tr><td>K2</td><td>영어</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\" style=\"font-size:13.5px;color:var(--fg-3);\">수강</p>\n    <table class=\"reveal\">\n      <thead><tr><th>학생ID</th><th>과목ID</th><th>성적</th></tr></thead>\n      <tbody>\n        <tr><td>S01</td><td>K1</td><td>90</td></tr>\n        <tr><td>S01</td><td>K2</td><td>85</td></tr>\n      </tbody>\n    </table>\n\n    <!-- 3NF -->\n    <h2 class=\"reveal\">3NF — 이행 함수 종속 제거</h2>\n    <p class=\"reveal\">이행 종속이란 <strong>A → B → C</strong> 형태로, PK가 아닌 B를 통해 C가 결정되는 상태다.</p>\n\n    <div class=\"ba-flow reveal\">\n      <div class=\"ba-side before\">\n        <span class=\"ba-tag\">BEFORE (2NF)</span>\n        <h4 class=\"ba-h\">사원ID → 부서ID → 부서명</h4>\n        <div class=\"mini-table cols-3\">\n          <div class=\"h\">사원ID</div><div class=\"h\">부서ID</div><div class=\"h\">부서명</div>\n          <div class=\"c\">E01</div><div class=\"c\">D1</div><div class=\"c is-null\">영업부</div>\n          <div class=\"c\">E02</div><div class=\"c\">D1</div><div class=\"c is-null\">영업부</div>\n        </div>\n      </div>\n      <div class=\"ba-arrow\">→</div>\n      <div class=\"ba-side after\">\n        <span class=\"ba-tag\">AFTER (3NF)</span>\n        <h4 class=\"ba-h\">사원·부서 분리</h4>\n        <div class=\"ba-tables cols-2\">\n          <div class=\"ba-mini-table\"><div class=\"h\">사원</div><div class=\"row\">E01 / D1</div><div class=\"row\">E02 / D1</div></div>\n          <div class=\"ba-mini-table\"><div class=\"h\">부서</div><div class=\"row\">D1 / 영업부</div></div>\n        </div>\n      </div>\n    </div>\n\n    <h3 class=\"reveal\">Before(2NF, 이행종속)</h3>\n    <table class=\"reveal\">\n      <thead><tr><th>사원ID(PK)</th><th>부서ID</th><th>부서명</th></tr></thead>\n      <tbody>\n        <tr><td>E01</td><td>D1</td><td>영업부</td></tr>\n        <tr><td>E02</td><td>D1</td><td>영업부</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\">사원ID → 부서ID → 부서명 (이행 종속)</p>\n\n    <h3 class=\"reveal\">After(3NF)</h3>\n    <p class=\"reveal\" style=\"font-size:13.5px;color:var(--fg-3);\">사원</p>\n    <table class=\"reveal\">\n      <thead><tr><th>사원ID</th><th>부서ID</th></tr></thead>\n      <tbody>\n        <tr><td>E01</td><td>D1</td></tr>\n        <tr><td>E02</td><td>D1</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\" style=\"font-size:13.5px;color:var(--fg-3);\">부서</p>\n    <table class=\"reveal\">\n      <thead><tr><th>부서ID</th><th>부서명</th></tr></thead>\n      <tbody><tr><td>D1</td><td>영업부</td></tr></tbody>\n    </table>\n\n    <!-- BCNF -->\n    <h2 class=\"reveal\">BCNF — 더 엄격한 3NF</h2>\n    <p class=\"reveal\">3NF 까지 정규화해도 일부 비정상 종속이 남는 경우가 있다. <strong>모든 결정자(determinant)가 후보키여야</strong> BCNF다.</p>\n    <blockquote class=\"reveal\">\n      <strong>결정자란?</strong> — A → B 일 때 B 를 결정하는 A. 이 A 가 후보키 (PK 또는 UNIQUE) 가 아니면 BCNF 위반.\n    </blockquote>\n\n    <h3 class=\"reveal\">예시 (3NF 만족, BCNF 위반)</h3>\n    <p class=\"reveal\">PK = (학생, 과목)</p>\n    <table class=\"reveal\">\n      <thead><tr><th>학생</th><th>과목</th><th>강사</th></tr></thead>\n      <tbody>\n        <tr><td>S01</td><td>수학</td><td>김교수</td></tr>\n        <tr><td>S02</td><td>수학</td><td>김교수</td></tr>\n        <tr><td>S03</td><td>영어</td><td>이교수</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\">규칙: 한 강사는 한 과목만 가르친다 → <strong>강사 → 과목</strong> 종속 존재.<br>문제: '강사' 는 후보키가 아닌데 '과목' 을 결정 → BCNF 위반.</p>\n\n    <h3 class=\"reveal\">After (BCNF)</h3>\n    <p class=\"reveal\"><strong>강사_과목</strong>: (강사, 과목) / <strong>학생_강사</strong>: (학생, 강사)</p>\n    <table class=\"reveal\">\n      <thead><tr><th>단계</th><th>차이</th></tr></thead>\n      <tbody>\n        <tr><td>3NF</td><td>PK가 아닌 컬럼이 PK에 직접 종속 (이행 종속 제거 완료)</td></tr>\n        <tr><td>BCNF</td><td>모든 함수 종속의 <strong>결정자가 후보키</strong> 여야 함</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\">비유하면 3NF 는 거의 깔끔, BCNF 는 완벽주의 정리다.</p>\n\n    <!-- SQL 실전 -->\n    <h2 class=\"section-label sec-sql reveal\"><span class=\"label-tag\">SQL 실전</span><span class=\"label-rest\">정규화로 분리</span></h2>\n    <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — 정규화 후 4개 테이블 (주문 1건: 김철수가 사과 2개)</p>\n    <div class=\"ba-flow reveal\" style=\"grid-template-columns: 1fr 28px 1fr 28px 1fr 28px 1fr; align-items: stretch;\">\n      <div class=\"ba-side before\">\n        <span class=\"ba-tag\">CUSTOMER</span>\n        <h4 class=\"ba-h\">고객</h4>\n        <div class=\"mini-table cols-2\">\n          <div class=\"h\">CUST_ID</div><div class=\"h\">CUST_NAME</div>\n          <div class=\"c\">C01</div><div class=\"c\">김철수</div>\n        </div>\n      </div>\n      <div class=\"ba-arrow\" style=\"font-size: 18px; color: var(--point-500);\">+</div>\n      <div class=\"ba-side before\">\n        <span class=\"ba-tag\">ORDERS</span>\n        <h4 class=\"ba-h\">주문</h4>\n        <div class=\"mini-table cols-2\">\n          <div class=\"h\">ORDER_ID</div><div class=\"h\">CUST_ID</div>\n          <div class=\"c\">1</div><div class=\"c\">C01</div>\n        </div>\n      </div>\n      <div class=\"ba-arrow\" style=\"font-size: 18px; color: var(--point-500);\">+</div>\n      <div class=\"ba-side before\">\n        <span class=\"ba-tag\">ORDER_DETAIL</span>\n        <h4 class=\"ba-h\">주문상세</h4>\n        <div class=\"mini-table cols-3\">\n          <div class=\"h\">ORDER_ID</div><div class=\"h\">PROD_ID</div><div class=\"h\">QTY</div>\n          <div class=\"c\">1</div><div class=\"c\">P01</div><div class=\"c\">2</div>\n        </div>\n      </div>\n      <div class=\"ba-arrow\" style=\"font-size: 18px; color: var(--point-500);\">+</div>\n      <div class=\"ba-side before\">\n        <span class=\"ba-tag\">PRODUCT</span>\n        <h4 class=\"ba-h\">상품</h4>\n        <div class=\"mini-table cols-2\">\n          <div class=\"h\">PROD_ID</div><div class=\"h\">PROD_NAME</div>\n          <div class=\"c\">P01</div><div class=\"c\">사과</div>\n        </div>\n      </div>\n    </div>\n    <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 정규화 전: 한 테이블에 모든 정보</span>\n<span class=\"sql-kw\">CREATE TABLE</span> <span class=\"sql-name\">BAD_ORDER</span> (\n    <span class=\"sql-type\">ORDER_ID</span> <span class=\"sql-type\">NUMBER</span>,\n    <span class=\"sql-type\">PROD_ID</span>  <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">10</span>),\n    <span class=\"sql-type\">PROD_NAME</span> <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">50</span>),  <span class=\"sql-cm\">-- 상품명이 함께</span>\n    <span class=\"sql-type\">QTY</span>      <span class=\"sql-type\">NUMBER</span>,\n    <span class=\"sql-type\">CUST_NAME</span> <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">50</span>)   <span class=\"sql-cm\">-- 고객명이 함께</span>\n);\n\n<span class=\"sql-cm\">-- 정규화 후: 책임에 따라 분리</span>\n<span class=\"sql-kw\">CREATE TABLE</span> <span class=\"sql-name\">PRODUCT</span> (<span class=\"sql-type\">PROD_ID</span> <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">10</span>) <span class=\"sql-kw\">PRIMARY KEY</span>, <span class=\"sql-type\">PROD_NAME</span> <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">50</span>));\n<span class=\"sql-kw\">CREATE TABLE</span> <span class=\"sql-name\">CUSTOMER</span>(<span class=\"sql-type\">CUST_ID</span> <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">10</span>) <span class=\"sql-kw\">PRIMARY KEY</span>, <span class=\"sql-type\">CUST_NAME</span> <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">50</span>));\n<span class=\"sql-kw\">CREATE TABLE</span> <span class=\"sql-name\">ORDERS</span>  (<span class=\"sql-type\">ORDER_ID</span> <span class=\"sql-type\">NUMBER</span> <span class=\"sql-kw\">PRIMARY KEY</span>, <span class=\"sql-type\">CUST_ID</span> <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">10</span>));\n<span class=\"sql-kw\">CREATE TABLE</span> <span class=\"sql-name\">ORDER_DETAIL</span>(<span class=\"sql-type\">ORDER_ID</span> <span class=\"sql-type\">NUMBER</span>, <span class=\"sql-type\">PROD_ID</span> <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">10</span>), <span class=\"sql-type\">QTY</span> <span class=\"sql-type\">NUMBER</span>);\n\n<span class=\"sql-cm\">-- 같은 주문(주문 1: 고객 C01의 사과 2개)을 INSERT 후 SELECT</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-name\">O</span>.<span class=\"sql-type\">ORDER_ID</span>, <span class=\"sql-name\">C</span>.<span class=\"sql-type\">CUST_NAME</span>, <span class=\"sql-name\">P</span>.<span class=\"sql-type\">PROD_NAME</span>, <span class=\"sql-name\">D</span>.<span class=\"sql-type\">QTY</span>\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">ORDERS</span> <span class=\"sql-name\">O</span>\n       <span class=\"sql-kw\">JOIN</span> <span class=\"sql-name\">CUSTOMER</span>     <span class=\"sql-name\">C</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-name\">O</span>.<span class=\"sql-type\">CUST_ID</span>  = <span class=\"sql-name\">C</span>.<span class=\"sql-type\">CUST_ID</span>\n       <span class=\"sql-kw\">JOIN</span> <span class=\"sql-name\">ORDER_DETAIL</span> <span class=\"sql-name\">D</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-name\">O</span>.<span class=\"sql-type\">ORDER_ID</span> = <span class=\"sql-name\">D</span>.<span class=\"sql-type\">ORDER_ID</span>\n       <span class=\"sql-kw\">JOIN</span> <span class=\"sql-name\">PRODUCT</span>      <span class=\"sql-name\">P</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-name\">D</span>.<span class=\"sql-type\">PROD_ID</span>  = <span class=\"sql-name\">P</span>.<span class=\"sql-type\">PROD_ID</span>;</code></pre>\n    <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과</p>\n    <table class=\"reveal\">\n      <thead><tr><th>ORDER_ID</th><th>CUST_NAME</th><th>PROD_NAME</th><th>QTY</th></tr></thead>\n      <tbody>\n        <tr><td>1</td><td>김철수</td><td>사과</td><td>2</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 4개 테이블에 흩어진 데이터가 3-way JOIN으로 합쳐져 비정규형과 같은 모양으로 조회된다. 저장은 분산, 조회는 통합 — 정규화의 본질.</p>\n    <p class=\"reveal\">정규화로 분리한 데이터도 <strong>JOIN으로 합쳐 보면</strong> 비정규형과 같은 결과를 낸다.</p>\n\n    <h3 class=\"reveal\">ER로 보는 정규화 후</h3>\n    <div class=\"mermaid reveal\">\nerDiagram\n    CUSTOMER ||--o{ ORDERS : \"주문한다\"\n    ORDERS   ||--|{ ORDER_DETAIL : \"포함한다\"\n    PRODUCT  ||--o{ ORDER_DETAIL : \"팔린다\"\n    CUSTOMER {\n        varchar CUST_ID PK\n        varchar CUST_NAME\n    }\n    ORDERS {\n        number  ORDER_ID PK\n        varchar CUST_ID  FK\n    }\n    PRODUCT {\n        varchar PROD_ID PK\n        varchar PROD_NAME\n    }\n    ORDER_DETAIL {\n        number  ORDER_ID PK,FK\n        varchar PROD_ID  PK,FK\n        number  QTY\n    }\n    </div>\n\n    <!-- Before & After -->\n    <h2 class=\"section-label sec-compare reveal\"><span class=\"label-tag\">Before &amp; After</span><span class=\"label-rest\">정규화 효과</span></h2>\n    <p class=\"reveal\">주문 한 건마다 고객 정보·상품 단가까지 한 줄에 다 적어두는 비정규형 테이블. 김철수가 두 번 주문하면 그의 전화번호가 두 번 똑같이 적히고, 사과의 단가는 주문될 때마다 반복된다. 정규화 전후의 차이를 본다.</p>\n\n    <div class=\"ba-flow large-after reveal\">\n      <div class=\"ba-side before\">\n        <span class=\"ba-tag\">BEFORE</span>\n        <h4 class=\"ba-h\">한 테이블에 모두</h4>\n        <div class=\"mini-table cols-4\">\n          <div class=\"h\">주문</div><div class=\"h\">고객</div><div class=\"h\">상품</div><div class=\"h\">단가</div>\n          <div class=\"c\">1</div><div class=\"c is-null\">김철수·010-1111</div><div class=\"c\">사과</div><div class=\"c is-null\">1000</div>\n          <div class=\"c\">2</div><div class=\"c is-null\">김철수·010-1111</div><div class=\"c\">배</div><div class=\"c\">2000</div>\n          <div class=\"c\">3</div><div class=\"c\">이영희·010-2222</div><div class=\"c\">사과</div><div class=\"c is-null\">1000</div>\n        </div>\n        <p style=\"font-size:12px;color:var(--fg-3);margin:10px 0 0;\">고객 정보 중복 + 상품 단가 중복</p>\n      </div>\n      <div class=\"ba-arrow\">→</div>\n      <div class=\"ba-side after\">\n        <span class=\"ba-tag\">AFTER (3NF)</span>\n        <h4 class=\"ba-h\">4개 테이블로 분리</h4>\n        <div class=\"ba-tables cols-2\">\n          <div class=\"ba-mini-table\"><div class=\"h\">고객</div><div class=\"row\">C01 / 김철수 / 010-1111</div><div class=\"row\">C02 / 이영희 / 010-2222</div></div>\n          <div class=\"ba-mini-table\"><div class=\"h\">상품</div><div class=\"row\">P01 / 사과 / 1000</div><div class=\"row\">P02 / 배 / 2000</div></div>\n          <div class=\"ba-mini-table\"><div class=\"h\">주문</div><div class=\"row\">1 / C01</div><div class=\"row\">2 / C01</div><div class=\"row\">3 / C02</div></div>\n          <div class=\"ba-mini-table\"><div class=\"h\">주문상세</div><div class=\"row\">1·P01·2</div><div class=\"row\">2·P02·1</div><div class=\"row\">3·P01·3</div></div>\n        </div>\n      </div>\n    </div>\n\n    <h4 class=\"reveal\">Before</h4>\n    <table class=\"reveal\">\n      <thead><tr><th>주문ID</th><th>고객명</th><th>고객전화</th><th>상품명</th><th>단가</th><th>수량</th></tr></thead>\n      <tbody>\n        <tr><td>1</td><td>김철수</td><td>010-1111</td><td>사과</td><td>1000</td><td>2</td></tr>\n        <tr><td>2</td><td>김철수</td><td>010-1111</td><td>배</td><td>2000</td><td>1</td></tr>\n        <tr><td>3</td><td>이영희</td><td>010-2222</td><td>사과</td><td>1000</td><td>3</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\">고객 정보 중복, 상품 단가 중복, 수정 시 일관성 깨짐.</p>\n\n    <h4 class=\"reveal\">After (3NF)</h4>\n    <p class=\"reveal\">고객·상품·주문·주문상세 4개로 분리되어 중복이 사라진다.</p>\n    <p class=\"reveal\">같은 고객 전화번호가 주문 행마다 반복되는 것은 함수 종속이 한 테이블 안에 섞여 있기 때문이다(고객명·고객전화는 고객ID 에, 상품명·단가는 상품ID 에 종속). 종속이 다른 데이터끼리 같은 테이블을 공유하면 갱신·삭제·삽입 이상이 모두 한 자리에서 발생한다. \"한 테이블엔 한 가지 의미만\"이라는 원칙으로 단계적으로 쪼개면, 김철수의 전화번호는 고객 테이블 한 줄에서만 관리하면 된다.</p>\n\n    <!-- 장단점 -->\n    <h2 class=\"reveal\">정규화의 장단점</h2>\n    <table class=\"reveal\">\n      <thead><tr><th>장점</th><th>단점</th></tr></thead>\n      <tbody>\n        <tr><td>데이터 중복 제거</td><td>테이블이 많아짐</td></tr>\n        <tr><td>이상현상 방지</td><td><a href=\"#\" data-chapter=\"c122\">조인</a>이 늘어남</td></tr>\n        <tr><td>데이터 무결성</td><td>조회 성능 일부 저하 가능</td></tr>\n        <tr><td>변경/유지보수 용이</td><td>—</td></tr>\n      </tbody>\n    </table>\n    <p class=\"reveal\">성능을 위해 의도적으로 <strong>반정규화(역정규화)</strong>를 하기도 한다.</p>\n\n    <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n      <div>\n        <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n        <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n      </div>\n      <a href=\"./exam-review.html#ch-1-2-1\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n    </div>",
  c122: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    모델에서의 <a href=\"#\" data-chapter=\"c114\">관계</a>는 외래키(FK)로 구현되고, 그 관계를 따라 여러 테이블을 합쳐 보는 작업이 <strong>조인(JOIN)</strong>이다.\n  </blockquote>\n  <div class=\"ex-box reveal\">\n    영수증에는 주문 정보만, 회원카드에는 회원 정보만 있다. 같은 사람의 영수증과 카드를 맞춰 보면 \"<strong>김철수가 사과 2개 샀구나</strong>\"가 보인다 — 흩어진 정보를 키로 맞춰 합치는 것이 조인이다.\n  </div>\n\n  <!-- 개념 도식화 — 3계층 흐름 -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">관계 → FK → JOIN</span>\n  </h2>\n  <div class=\"layer-stack reveal\">\n    <div class=\"layer-stack-track\">\n      <div class=\"layer-row\">\n        <div class=\"icon\">①</div>\n        <div class=\"body\">\n          <div class=\"name\">관계 <small>설계 단계 · 개념 모델</small></div>\n          <div class=\"desc\">두 엔터티 사이의 의미적 연결(\"회원이 주문을 한다\")을 ERD 선으로 표현</div>\n        </div>\n        <span class=\"arrow\">▼</span>\n      </div>\n      <div class=\"layer-row\">\n        <div class=\"icon\">②</div>\n        <div class=\"body\">\n          <div class=\"name\">외래키 (FK) <small>구현 단계 · 논리/물리 모델</small></div>\n          <div class=\"desc\">자식 테이블이 부모 테이블의 PK를 참조하는 컬럼. <strong>FK = 조인 키</strong></div>\n        </div>\n        <span class=\"arrow\">▼</span>\n      </div>\n      <div class=\"layer-row\">\n        <div class=\"icon\">③</div>\n        <div class=\"body\">\n          <div class=\"name\">조인 (JOIN) <small>조회 단계 · SQL 실행</small></div>\n          <div class=\"desc\">FK = PK 조건으로 두 테이블을 합쳐 한 결과로 보는 SQL 동작</div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <p class=\"reveal\">자식 테이블의 <strong>FK가 곧 조인 키</strong>다. 예: <code>MEMBER(MEMBER_ID PK)</code> ↔ <code>ORDERS(MEMBER_ID FK)</code>.</p>\n\n  <div class=\"mermaid reveal\">\nerDiagram\n    MEMBER ||--o{ ORDERS : \"필수1 - 선택N\"\n    MEMBER {\n        varchar MEMBER_ID PK\n        varchar NAME\n    }\n    ORDERS {\n        number  ORDER_ID PK\n        varchar MEMBER_ID FK\n        date    ORD_DATE\n    }\n  </div>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3);\">표기: <code>||--o{</code> = \"회원은 항상 1명, 주문은 0개 이상\" (회원에 필수, 주문은 선택). 식별 관계는 <code>||--|{</code>.</p>\n\n  <!-- 조인의 4가지 종류 -->\n  <h2 class=\"reveal\">조인의 4가지 종류 — 개념 미리보기</h2>\n  <table class=\"reveal\">\n    <thead><tr><th>종류</th><th>의미</th><th>비유</th></tr></thead>\n    <tbody>\n      <tr><td>INNER JOIN</td><td>양쪽에 다 있는 것만</td><td>양쪽 카드 모두 가진 사람</td></tr>\n      <tr><td>LEFT OUTER</td><td>왼쪽 다, 오른쪽은 매칭만</td><td>왼쪽 기준, 오른쪽 없으면 NULL</td></tr>\n      <tr><td>RIGHT OUTER</td><td>오른쪽 다</td><td>오른쪽 기준</td></tr>\n      <tr><td>FULL OUTER</td><td>양쪽 모두 다</td><td>한쪽만 있어도 표시</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\">자세한 구문은 <a href=\"#\" data-chapter=\"c217\">조인</a> / <a href=\"#\" data-chapter=\"c218\">표준 조인</a>에서 다룬다.</p>\n\n  <div class=\"venn-row cols-4 reveal\">\n    <div class=\"venn-card\">\n      <svg viewBox=\"0 0 220 130\">\n        <circle class=\"v-a\" cx=\"80\" cy=\"65\" r=\"50\"/>\n        <circle class=\"v-b\" cx=\"140\" cy=\"65\" r=\"50\"/>\n        <path class=\"v-hl\" d=\"M 110,30 A 50,50 0 0,1 110,100 A 50,50 0 0,1 110,30 Z\"/>\n        <text class=\"v-label\" x=\"110\" y=\"125\">A ∩ B</text>\n      </svg>\n      <div class=\"name\">INNER JOIN</div>\n      <div class=\"desc\">교집합 — 양쪽 매칭 행만</div>\n    </div>\n    <div class=\"venn-card\">\n      <svg viewBox=\"0 0 220 130\">\n        <circle class=\"v-hl\" cx=\"80\" cy=\"65\" r=\"50\"/>\n        <circle class=\"v-b\" cx=\"140\" cy=\"65\" r=\"50\"/>\n        <text class=\"v-label\" x=\"110\" y=\"125\">A (전부)</text>\n      </svg>\n      <div class=\"name\">LEFT OUTER</div>\n      <div class=\"desc\">왼쪽 다 + 매칭, 미매칭은 NULL</div>\n    </div>\n    <div class=\"venn-card\">\n      <svg viewBox=\"0 0 220 130\">\n        <circle class=\"v-a\" cx=\"80\" cy=\"65\" r=\"50\"/>\n        <circle class=\"v-hl\" cx=\"140\" cy=\"65\" r=\"50\"/>\n        <text class=\"v-label\" x=\"110\" y=\"125\">B (전부)</text>\n      </svg>\n      <div class=\"name\">RIGHT OUTER</div>\n      <div class=\"desc\">오른쪽 다 + 매칭, 미매칭은 NULL</div>\n    </div>\n    <div class=\"venn-card\">\n      <svg viewBox=\"0 0 220 130\">\n        <circle class=\"v-hl\" cx=\"80\" cy=\"65\" r=\"50\"/>\n        <circle class=\"v-hl\" cx=\"140\" cy=\"65\" r=\"50\"/>\n        <text class=\"v-label\" x=\"110\" y=\"125\">A ∪ B</text>\n      </svg>\n      <div class=\"name\">FULL OUTER</div>\n      <div class=\"desc\">합집합 — 한쪽만 있어도 모두</div>\n    </div>\n  </div>\n\n  <!-- 관계의 종류와 조인 시 주의점 -->\n  <h2 class=\"reveal\">관계의 종류와 조인 시 주의점</h2>\n  <div class=\"cls-row reveal\">\n    <div class=\"cls-card\">\n      <span class=\"badge\">1:1</span>\n      <div class=\"name\">단순 매칭</div>\n      <div class=\"ex\"><code>[사원] 1 ── 1 [사원증]</code><br>사원 한 명당 사원증 한 개 → 행 수 그대로</div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-info\">1:N</span>\n      <div class=\"name\">행이 늘어남</div>\n      <div class=\"ex\"><code>[회원] 1 ── N [주문]</code><br>회원 1명에 주문 3건이면 결과 3행</div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-event\">M:N</span>\n      <div class=\"name\">교차 엔터티 필요</div>\n      <div class=\"ex\"><code>학생 M─N 과목</code> → 수강 거쳐 두 번 조인</div>\n    </div>\n  </div>\n\n  <h3 class=\"reveal\">1:1 관계 — 단순 매칭</h3>\n  <p class=\"reveal\">INNER JOIN 결과: 사원 한 명당 사원증 한 개 → 사원 행 수 그대로 유지. (사원증이 없는 사원은 LEFT JOIN을 써야 결과에 남음)</p>\n\n  <h3 class=\"reveal\">1:N 관계 — 행이 늘어남</h3>\n  <p class=\"reveal\">회원 1명에게 주문이 3건이면 조인 후 3행으로 늘어난다.</p>\n\n  <h3 class=\"reveal\">M:N 관계 — 교차 엔터티 필요</h3>\n  <pre class=\"reveal\"><code>[학생] M ── N [과목]    →    [학생] 1─N [수강] N─1 [과목]</code></pre>\n  <p class=\"reveal\">조인은 반드시 수강(교차)을 거쳐 두 번 한다.</p>\n\n  <!-- SQL 실전 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">관계로 연결된 테이블 조인</span>\n  </h2>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — M:N (학생 ─ 수강 ─ 과목)</p>\n  <div class=\"ba-flow reveal\" style=\"grid-template-columns: 1fr 28px 1fr 28px 1fr; align-items: stretch;\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">STUDENT</span>\n      <h4 class=\"ba-h\">학생 테이블</h4>\n      <div class=\"mini-table cols-2\">\n        <div class=\"h\">STU_ID</div><div class=\"h\">NAME</div>\n        <div class=\"c\">S01</div><div class=\"c\">김철수</div>\n        <div class=\"c\">S02</div><div class=\"c\">이영희</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\" style=\"font-size: 18px; color: var(--point-500);\">+</div>\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">REGISTER</span>\n      <h4 class=\"ba-h\">수강 (교차 엔터티)</h4>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">STU_ID</div><div class=\"h\">SUB_ID</div><div class=\"h\">GRADE</div>\n        <div class=\"c\">S01</div><div class=\"c\">K1</div><div class=\"c\">A</div>\n        <div class=\"c\">S01</div><div class=\"c\">K2</div><div class=\"c\">B+</div>\n        <div class=\"c\">S02</div><div class=\"c\">K1</div><div class=\"c\">B</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\" style=\"font-size: 18px; color: var(--point-500);\">+</div>\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">SUBJECT</span>\n      <h4 class=\"ba-h\">과목 테이블</h4>\n      <div class=\"mini-table cols-2\">\n        <div class=\"h\">SUB_ID</div><div class=\"h\">NAME</div>\n        <div class=\"c\">K1</div><div class=\"c\">수학</div>\n        <div class=\"c\">K2</div><div class=\"c\">영어</div>\n      </div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 1:N 조인: 회원과 주문</span>\n<span class=\"sql-kw\">SELECT</span>  <span class=\"sql-name\">M</span>.<span class=\"sql-type\">NAME</span>, <span class=\"sql-name\">O</span>.<span class=\"sql-type\">ORDER_ID</span>, <span class=\"sql-name\">O</span>.<span class=\"sql-type\">ORD_DATE</span>\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">MEMBER</span> <span class=\"sql-name\">M</span>\n        <span class=\"sql-kw\">JOIN</span> <span class=\"sql-name\">ORDERS</span> <span class=\"sql-name\">O</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-name\">M</span>.<span class=\"sql-type\">MEMBER_ID</span> = <span class=\"sql-name\">O</span>.<span class=\"sql-type\">MEMBER_ID</span>;\n\n<span class=\"sql-cm\">-- M:N → 교차 테이블 거쳐 두 번 조인</span>\n<span class=\"sql-kw\">SELECT</span>  <span class=\"sql-name\">S</span>.<span class=\"sql-type\">NAME</span> <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">STUDENT</span>, <span class=\"sql-name\">K</span>.<span class=\"sql-type\">NAME</span> <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">SUBJECT</span>, <span class=\"sql-name\">R</span>.<span class=\"sql-type\">GRADE</span>\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">STUDENT</span>  <span class=\"sql-name\">S</span>\n        <span class=\"sql-kw\">JOIN</span> <span class=\"sql-name\">REGISTER</span> <span class=\"sql-name\">R</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-name\">S</span>.<span class=\"sql-type\">STU_ID</span> = <span class=\"sql-name\">R</span>.<span class=\"sql-type\">STU_ID</span>\n        <span class=\"sql-kw\">JOIN</span> <span class=\"sql-name\">SUBJECT</span>  <span class=\"sql-name\">K</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-name\">R</span>.<span class=\"sql-type\">SUB_ID</span> = <span class=\"sql-name\">K</span>.<span class=\"sql-type\">SUB_ID</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (M:N 조인)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>STUDENT</th><th>SUBJECT</th><th>GRADE</th></tr></thead>\n    <tbody>\n      <tr><td>김철수</td><td>수학</td><td>A</td></tr>\n      <tr><td>김철수</td><td>영어</td><td>B+</td></tr>\n      <tr><td>이영희</td><td>수학</td><td>B</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ STUDENT와 SUBJECT를 직접 못 잇기 때문에 REGISTER를 거쳐 두 번 조인. 수강 행 수만큼(3행) 결과가 만들어진다.</p>\n\n  <!-- Before & After -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">데이터가 합쳐지는 모습</span>\n  </h2>\n  <p class=\"reveal\">회원은 2명(김철수·이영희), 주문은 3건(김철수가 2건, 이영희가 1건)인 상황. <code>MEMBER</code>와 <code>ORDERS</code>가 <code>MEMBER_ID</code>로 1:N 관계일 때, INNER JOIN 결과의 행 수가 어떻게 결정되는지 본다.</p>\n\n  <h3 class=\"reveal\">입력 테이블</h3>\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3);\">MEMBER</p>\n  <table class=\"reveal\">\n    <thead><tr><th>MEMBER_ID</th><th>NAME</th></tr></thead>\n    <tbody>\n      <tr><td>M01</td><td>김철수</td></tr>\n      <tr><td>M02</td><td>이영희</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3);\">ORDERS</p>\n  <table class=\"reveal\">\n    <thead><tr><th>ORDER_ID</th><th>MEMBER_ID</th><th>ORD_DATE</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td>M01</td><td>2026-04-01</td></tr>\n      <tr><td>2</td><td>M01</td><td>2026-04-05</td></tr>\n      <tr><td>3</td><td>M02</td><td>2026-04-10</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">After — INNER JOIN 결과</h3>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>ORDER_ID</th><th>ORD_DATE</th></tr></thead>\n    <tbody>\n      <tr><td>김철수</td><td>1</td><td>2026-04-01</td></tr>\n      <tr><td>김철수</td><td>2</td><td>2026-04-05</td></tr>\n      <tr><td>이영희</td><td>3</td><td>2026-04-10</td></tr>\n    </tbody>\n  </table>\n\n  <div class=\"ba-flow large-after reveal\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">BEFORE</span>\n      <h4 class=\"ba-h\">두 테이블 분리</h4>\n      <div class=\"ba-tables cols-2\">\n        <div class=\"ba-mini-table\">\n          <div class=\"h\">MEMBER (2행)</div>\n          <div class=\"row\">M01 김철수</div>\n          <div class=\"row\">M02 이영희</div>\n        </div>\n        <div class=\"ba-mini-table\">\n          <div class=\"h\">ORDERS (3행)</div>\n          <div class=\"row\">1 · M01 · 04-01</div>\n          <div class=\"row\">2 · M01 · 04-05</div>\n          <div class=\"row\">3 · M02 · 04-10</div>\n        </div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\">→</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">AFTER · INNER JOIN</span>\n      <h4 class=\"ba-h\">M01은 2번 복제 → 3행</h4>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">NAME</div><div class=\"h\">ORDER</div><div class=\"h\">DATE</div>\n        <div class=\"c\">김철수</div><div class=\"c\">1</div><div class=\"c\">04-01</div>\n        <div class=\"c\">김철수</div><div class=\"c\">2</div><div class=\"c\">04-05</div>\n        <div class=\"c\">이영희</div><div class=\"c\">3</div><div class=\"c\">04-10</div>\n      </div>\n    </div>\n  </div>\n\n  <p class=\"reveal\">회원 2명이지만 주문이 3건이므로 결과는 <strong>3행</strong>이다. 1:N 조인의 결과 행 수는 부모(1쪽) 수가 아니라 <strong>자식(N쪽) 수에 맞춰</strong> 결정된다 — 부모 한 행이 매칭된 자식 수만큼 복제된다고 보면 된다. 이 사실을 잊고 부모 컬럼(예: 회원 등급별 포인트)을 그대로 SUM 하면 자식 수만큼 부풀려진 합계가 나온다. 1:N 조인 후 부모 쪽 집계가 필요하면 자식 합계를 서브쿼리로 먼저 구해 1:1로 만들어 붙이는 것이 안전하다.</p>\n\n  <!-- 조인 시 자주 하는 실수 -->\n  <h2 class=\"reveal\">조인 시 자주 하는 실수</h2>\n  <table class=\"reveal\">\n    <thead><tr><th>실수</th><th>결과</th><th>해결</th></tr></thead>\n    <tbody>\n      <tr><td>조인 조건 빠짐</td><td>카티션 곱(행 수 폭발)</td><td>ON 명시</td></tr>\n      <tr><td>1:N 관계인데 합계 계산</td><td>중복 합산</td><td>DISTINCT 또는 서브쿼리 분리</td></tr>\n      <tr><td>OUTER JOIN과 WHERE 혼동</td><td>NULL 행이 빠짐</td><td>OUTER JOIN 시 조건은 ON에 둠</td></tr>\n    </tbody>\n  </table>\n\n  <!-- 조인의 방향성 -->\n  <h2 class=\"reveal\">조인의 방향성</h2>\n  <p class=\"reveal\">일반적으로 <strong>PK(부모) ← FK(자식)</strong> 방향으로 조인한다.</p>\n  <pre class=\"reveal\"><code>[부서] PK ←─── FK [사원]\n   조인 키 = 부서.PK = 사원.FK</code></pre>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-1-2-2\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c123: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    트랜잭션(Transaction)이란 <strong>함께 성공하거나 함께 실패해야 하는 데이터 작업의 묶음</strong>이다. 모델은 이 묶음을 관계의 <strong>필수성</strong>과 <strong>식별성</strong>으로 표현한다.\n  </blockquote>\n  <div class=\"ex-box reveal\">\n    계좌 이체에서 A에서 1만원이 빠지고 B에 1만원이 들어와야 정상. A에서만 빠지고 멈추면 돈이 사라지므로, 둘 다 성공하거나 둘 다 취소되어야 한다.\n  </div>\n\n  <!-- 개념 도식화 — ACID 4특성 -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">트랜잭션의 ACID</span>\n  </h2>\n  <div class=\"trait-grid cols-4 reveal\">\n    <div class=\"trait-card\">\n      <div class=\"glyph\">A</div>\n      <div class=\"label\">원자성</div>\n      <div class=\"desc\"><strong>Atomicity</strong><br>전부 성공 또는 전부 실패</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"glyph\">C</div>\n      <div class=\"label\">일관성</div>\n      <div class=\"desc\"><strong>Consistency</strong><br>무결성 규칙 유지</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"glyph\">I</div>\n      <div class=\"label\">고립성</div>\n      <div class=\"desc\"><strong>Isolation</strong><br>다른 트랜잭션 간섭 없음</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"glyph\">D</div>\n      <div class=\"label\">지속성</div>\n      <div class=\"desc\"><strong>Durability</strong><br>커밋되면 영구 보존</div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead><tr><th>성질</th><th>의미</th><th>비유</th></tr></thead>\n    <tbody>\n      <tr><td>원자성 (Atomicity)</td><td>모두 성공하거나 모두 실패</td><td>이체는 출금+입금 한 묶음</td></tr>\n      <tr><td>일관성 (Consistency)</td><td>트랜잭션 전후 데이터 무결성 규칙 유지</td><td>잔고 합계는 변하지 않음</td></tr>\n      <tr><td>고립성 (Isolation)</td><td>동시 실행이라도 서로 간섭 없음</td><td>다른 사람 이체와 겹치지 않음</td></tr>\n      <tr><td>지속성 (Durability)</td><td>커밋되면 시스템이 죽어도 보존</td><td>영수증으로 기록됨</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">트랜잭션 상태 흐름</h3>\n  <div class=\"mermaid reveal\">\nstateDiagram-v2\n    [*] --> Active : BEGIN / 첫 DML\n    Active --> PartiallyCommitted : 마지막 SQL 성공\n    PartiallyCommitted --> Committed : COMMIT\n    Committed --> [*]\n    Active --> Failed : 오류 발생\n    PartiallyCommitted --> Failed : 디스크 쓰기 실패\n    Failed --> Aborted : ROLLBACK\n    Aborted --> [*]\n  </div>\n  <p class=\"reveal\">Active(활성) → 마지막 SQL까지 무사 통과하면 Partially Committed → COMMIT으로 영구 반영(Committed). 중간에 오류면 Failed → ROLLBACK으로 Aborted 종료.</p>\n\n  <!-- 모델에서 트랜잭션은 어떻게 보이는가 -->\n  <h2 class=\"reveal\">모델에서 트랜잭션은 어떻게 보이는가</h2>\n  <div class=\"cls-row reveal\">\n    <div class=\"cls-card\">\n      <span class=\"badge\">필수</span>\n      <div class=\"name\">관계의 필수성</div>\n      <div class=\"ex\">주문상세는 반드시 주문이 있어야 함 (Mandatory). 주문 INSERT 시 주문상세도 함께 INSERT</div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-warn\">식별</span>\n      <div class=\"name\">관계의 식별성</div>\n      <div class=\"ex\">주문상세는 주문 PK 일부를 자기 PK로 가짐 — 주문 없이 존재 불가. DELETE 시 함께 처리 또는 차단</div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-info\">선택</span>\n      <div class=\"name\">선택 관계 (Optional)</div>\n      <div class=\"ex\">고객은 주문이 없을 수 있음 — 트랜잭션으로 묶을 필요 없는 느슨한 연결</div>\n    </div>\n  </div>\n\n  <h3 class=\"reveal\">관계의 필수성</h3>\n  <p class=\"reveal\">주문을 INSERT할 때 주문상세도 함께 INSERT되어야 정상 트랜잭션이다.</p>\n\n  <h3 class=\"reveal\">관계의 식별성</h3>\n  <pre class=\"reveal\"><code>[주문]  ──── [주문상세]   :  식별 관계(실선), 주문 없이 주문상세 존재 불가</code></pre>\n  <p class=\"reveal\">주문을 DELETE할 때 주문상세도 함께 DELETE되거나 막아야 한다.</p>\n\n  <h3 class=\"reveal\">트랜잭션 표현 예시</h3>\n  <pre class=\"reveal\"><code>[고객]  ──○──── [주문]  ──────── [주문상세]\n              선택              식별(실선)</code></pre>\n  <table class=\"reveal\">\n    <thead><tr><th>표기</th><th>의미</th></tr></thead>\n    <tbody>\n      <tr><td>고객 ─○─ 주문</td><td>고객은 주문이 없을 수 있음 (선택, Optional)</td></tr>\n      <tr><td>주문 ──── 주문상세 (실선)</td><td><strong>식별 관계</strong> — 주문상세는 주문 PK 일부를 자기 PK로 가짐 (주문 없이 존재 불가)</td></tr>\n      <tr><td>주문 ─ ─ ─ 주문상세 (점선)</td><td><strong>비식별 관계</strong> — 주문 키는 일반 FK로만 (주문상세가 독자 PK 보유)</td></tr>\n    </tbody>\n  </table>\n\n  <!-- SQL 실전 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">트랜잭션 묶음</span>\n  </h2>\n  <p class=\"reveal\">INSERT/UPDATE/DELETE는 <a href=\"#\" data-chapter=\"c231\">DML</a>로 실행되고, COMMIT/ROLLBACK은 <a href=\"#\" data-chapter=\"c232\">TCL</a>로 트랜잭션을 마감한다.</p>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 — INSERT 대상 (주문 1001 + 주문상세 2건을 한 묶음으로)</p>\n  <div class=\"ba-flow reveal\" style=\"grid-template-columns: 1fr 36px 1fr; align-items: stretch;\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">ORDERS</span>\n      <h4 class=\"ba-h\">주문 (부모)</h4>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">ORDER_ID</div><div class=\"h\">CUST_ID</div><div class=\"h\">ORD_DATE</div>\n        <div class=\"c\">1001</div><div class=\"c\">C001</div><div class=\"c\">2026-04-27</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\" style=\"font-size: 22px; color: var(--point-500);\">+</div>\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">ORDER_DETAIL</span>\n      <h4 class=\"ba-h\">주문상세 (자식 · 식별)</h4>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">ORDER_ID</div><div class=\"h\">PROD_ID</div><div class=\"h\">QTY</div>\n        <div class=\"c\">1001</div><div class=\"c\">P01</div><div class=\"c\">2</div>\n        <div class=\"c\">1001</div><div class=\"c\">P02</div><div class=\"c\">1</div>\n      </div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 시작 (Oracle은 DML 실행 시 자동 시작)</span>\n<span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">ORDERS</span>(<span class=\"sql-type\">ORDER_ID</span>, <span class=\"sql-type\">CUST_ID</span>, <span class=\"sql-type\">ORD_DATE</span>)\n<span class=\"sql-kw\">VALUES</span> (<span class=\"sql-num\">1001</span>, <span class=\"sql-str\">'C001'</span>, <span class=\"sql-kw\">SYSDATE</span>);\n\n<span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">ORDER_DETAIL</span>(<span class=\"sql-type\">ORDER_ID</span>, <span class=\"sql-type\">PROD_ID</span>, <span class=\"sql-type\">QTY</span>)\n<span class=\"sql-kw\">VALUES</span> (<span class=\"sql-num\">1001</span>, <span class=\"sql-str\">'P01'</span>, <span class=\"sql-num\">2</span>);\n\n<span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">ORDER_DETAIL</span>(<span class=\"sql-type\">ORDER_ID</span>, <span class=\"sql-type\">PROD_ID</span>, <span class=\"sql-type\">QTY</span>)\n<span class=\"sql-kw\">VALUES</span> (<span class=\"sql-num\">1001</span>, <span class=\"sql-str\">'P02'</span>, <span class=\"sql-num\">1</span>);\n\n<span class=\"sql-kw\">COMMIT</span>;  <span class=\"sql-cm\">-- 한 묶음으로 영구 저장</span>\n\n<span class=\"sql-cm\">-- 중간에 오류 발생 시</span>\n<span class=\"sql-kw\">ROLLBACK</span>; <span class=\"sql-cm\">-- 모두 취소</span></code></pre>\n\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ COMMIT 후 ORDERS 조회 결과</p>\n  <table class=\"reveal\">\n    <thead><tr><th>ORDER_ID</th><th>CUST_ID</th><th>ORD_DATE</th></tr></thead>\n    <tbody>\n      <tr><td>1001</td><td>C001</td><td>2026-04-27</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">반대로 ROLLBACK 했다면</p>\n  <table class=\"reveal\">\n    <thead><tr><th>ORDER_ID</th><th>CUST_ID</th><th>ORD_DATE</th></tr></thead>\n    <tbody>\n      <tr><td colspan=\"3\" style=\"text-align:center;color:var(--fg-3);font-style:italic;\">(0건 — INSERT 모두 취소됨)</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ COMMIT 직전까지는 모두 같은 트랜잭션. 중간 어디서 깨져도 ROLLBACK 한 번에 3개 INSERT 가 통째로 사라진다(원자성).</p>\n\n  <!-- Before & After -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">트랜잭션이 깨지면</span>\n  </h2>\n  <p class=\"reveal\">A 계좌에서 B 계좌로 1만원 이체. 출금(A) → 입금(B) 두 작업 사이에서 시스템이 멈춘 상황과, 두 작업을 한 트랜잭션으로 묶어 ROLLBACK 한 상황의 잔고를 비교한다.</p>\n\n  <h3 class=\"reveal\">Before — 출금만 성공, 입금 실패</h3>\n  <table class=\"reveal\">\n    <thead><tr><th>계좌</th><th>잔고</th></tr></thead>\n    <tbody>\n      <tr><td>A</td><td>90,000 (10,000 빠짐)</td></tr>\n      <tr><td>B</td><td>50,000 (그대로)</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\">1만원이 사라진다.</p>\n\n  <h3 class=\"reveal\">After — 트랜잭션으로 묶었을 때</h3>\n  <p class=\"reveal\">ROLLBACK 후</p>\n  <table class=\"reveal\">\n    <thead><tr><th>계좌</th><th>잔고</th></tr></thead>\n    <tbody>\n      <tr><td>A</td><td>100,000 (원상복구)</td></tr>\n      <tr><td>B</td><td>50,000</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\">데이터가 보존된다.</p>\n\n  <div class=\"ba-flow reveal\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">BEFORE · 묶지 않음</span>\n      <h4 class=\"ba-h\">출금만 성공 → 1만원 증발</h4>\n      <div class=\"sql\">UPDATE A SET 잔고 = 잔고 - 10000;\n-- 시스템 다운 -- 입금 못함</div>\n      <div class=\"mini-table\">\n        <div class=\"h\">계좌</div><div class=\"h\">잔고</div>\n        <div class=\"c\">A</div><div class=\"c is-null\">90,000</div>\n        <div class=\"c\">B</div><div class=\"c\">50,000</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\">→</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">AFTER · 한 트랜잭션</span>\n      <h4 class=\"ba-h\">ROLLBACK으로 원상복구</h4>\n      <div class=\"sql\">BEGIN;\nUPDATE A …;  UPDATE B …;\nROLLBACK; -- 둘 다 취소</div>\n      <div class=\"mini-table\">\n        <div class=\"h\">계좌</div><div class=\"h\">잔고</div>\n        <div class=\"c\">A</div><div class=\"c\">100,000</div>\n        <div class=\"c\">B</div><div class=\"c\">50,000</div>\n      </div>\n    </div>\n  </div>\n\n  <p class=\"reveal\">출금과 입금은 업무적으로 한 사건(이체)이지만 SQL 입장에선 별개의 UPDATE 두 개다. 묶지 않으면 중간 실패가 곧 데이터 모순(원자성 깨짐)이 된다. 모델에서 두 엔터티가 식별 관계나 필수 관계로 묶여 있다는 것은 곧 \"이 INSERT/UPDATE/DELETE 들은 한 트랜잭션 안에서 함께 처리해야 한다\"는 신호다. 함께 변해야 하는 데이터는 코드에서도 <code>BEGIN ~ COMMIT</code>으로 한 묶음이 되도록 설계해야 한다.</p>\n\n  <!-- 트랜잭션 처리 패턴 -->\n  <h2 class=\"reveal\">트랜잭션 처리 패턴</h2>\n  <table class=\"reveal\">\n    <thead><tr><th>패턴</th><th>모델 단서</th><th>SQL</th></tr></thead>\n    <tbody>\n      <tr><td>묶어서 INSERT</td><td>식별 관계 / 필수 관계</td><td>INSERT ... INSERT ... COMMIT</td></tr>\n      <tr><td>묶어서 UPDATE</td><td>1:1 관계</td><td>UPDATE A ... UPDATE B ... COMMIT</td></tr>\n      <tr><td>묶어서 DELETE</td><td>식별 관계(CASCADE)</td><td>DELETE 부모 → 자식 자동/명시 삭제</td></tr>\n    </tbody>\n  </table>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-1-2-3\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c124: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    NULL이란 <strong>값이 없거나 아직 모름</strong>을 나타내는 특수한 표시다. 0이나 공백과는 전혀 다르다.\n  </blockquote>\n  <div class=\"ex-box reveal\">\n    설문지에서 \"월 소득: <strong>0원</strong>\"은 0이라는 값이 적힌 것, \"월 소득: <strong>␣</strong>\"(한 칸 띈 상태)은 공백 문자, \"월 소득: <strong>미작성</strong>\"이 NULL(값 자체가 없음)이다.\n  </div>\n\n  <!-- 개념 도식화 — 3-way 비교 인포그래픽 -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">NULL vs 0 vs 공백</span>\n  </h2>\n  <div class=\"threeway reveal\">\n    <div class=\"threeway-card zero\">\n      <div class=\"glyph\">0</div>\n      <div class=\"name\">숫자 0</div>\n      <div class=\"desc\"><strong>존재 O</strong> · 산술 가능 · 비교 가능</div>\n    </div>\n    <div class=\"threeway-card blank\">\n      <div class=\"glyph\">' '</div>\n      <div class=\"name\">공백 문자</div>\n      <div class=\"desc\"><strong>존재 O</strong> · 문자열 한 칸 · 비교 가능</div>\n    </div>\n    <div class=\"threeway-card null-card\">\n      <div class=\"glyph\">NULL</div>\n      <div class=\"name\">NULL</div>\n      <div class=\"desc\"><strong>존재 X</strong> · 값 자체가 없음 · <code>IS NULL</code>만 가능</div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead>\n      <tr><th>비교</th><th>0</th><th>공백</th><th>NULL</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>데이터 존재 여부</td><td>있음</td><td>있음</td><td>없음</td></tr>\n      <tr><td>비교 가능 여부</td><td>가능</td><td>가능</td><td>불가 (<code>= NULL</code> 안 됨)</td></tr>\n      <tr><td>산술연산</td><td>가능</td><td>—</td><td>불가 (결과는 모두 NULL)</td></tr>\n    </tbody>\n  </table>\n\n  <!-- NULL 4가지 규칙 — 인포그래픽 -->\n  <h2 class=\"reveal\">NULL의 4가지 규칙</h2>\n  <div class=\"rule-grid reveal\">\n    <div class=\"rule-card\">\n      <div class=\"num\">1</div>\n      <div class=\"label\">산술 연산</div>\n      <div class=\"desc\">결과는 <strong>NULL</strong><br><code>1000 + NULL = NULL</code></div>\n    </div>\n    <div class=\"rule-card\">\n      <div class=\"num\">2</div>\n      <div class=\"label\">비교 연산</div>\n      <div class=\"desc\">결과는 <strong>UNKNOWN</strong> (3-값 논리). <a href=\"#\" data-chapter=\"c214\">WHERE 절</a>에서 행 제외</div>\n    </div>\n    <div class=\"rule-card\">\n      <div class=\"num\">3</div>\n      <div class=\"label\"><code>IS NULL</code> / <code>IS NOT NULL</code></div>\n      <div class=\"desc\"><code>= NULL</code>, <code>!= NULL</code>은 <strong>항상 거짓</strong></div>\n    </div>\n    <div class=\"rule-card\">\n      <div class=\"num\">4</div>\n      <div class=\"label\">집계 함수</div>\n      <div class=\"desc\">NULL을 무시. <strong><code>COUNT(*)</code>만 NULL 포함</strong></div>\n    </div>\n  </div>\n  <blockquote class=\"reveal\">\n    <strong>SQL 3-값 논리</strong> — 일반 프로그래밍은 TRUE/FALSE 2값이지만 SQL은 NULL 때문에 <strong>TRUE / FALSE / UNKNOWN</strong> 3값. <code>NULL = NULL</code>도 결과가 UNKNOWN.\n  </blockquote>\n\n  <div class=\"mermaid reveal\">\nflowchart TD\n    Q[\"WHERE 조건 평가\"] --> V{\"피연산자에<br/>NULL 포함?\"}\n    V -->|\"NO\"| R[\"TRUE 또는 FALSE<br/>(2-값 논리)\"]\n    V -->|\"YES\"| U[\"UNKNOWN<br/>(3-값 논리)\"]\n    R -->|\"TRUE\"| KEEP[\"행 포함\"]\n    R -->|\"FALSE\"| DROP1[\"행 제외\"]\n    U --> DROP2[\"행 제외<br/>(UNKNOWN은 TRUE 아님)\"]\n    style U fill:#FCEEE5,stroke:#A9562E\n    style KEEP fill:#E6F3E7,stroke:#256B29\n  </div>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3);\">WHERE 절은 결과가 <strong>TRUE인 행만</strong> 남긴다. UNKNOWN은 TRUE가 아니므로 자동 제외 — 그래서 <code>= NULL</code>은 항상 0건.</p>\n\n  <!-- NULL 처리 함수 — 인포그래픽 -->\n  <h2 class=\"reveal\">NULL 처리 함수</h2>\n  <p class=\"reveal\">자세한 동작은 <a href=\"#\" data-chapter=\"c213\">함수</a> 챕터에서도 다룬다.</p>\n  <div class=\"fn-grid reveal\">\n    <div class=\"fn-card\">\n      <div class=\"name\">NVL(A, B)</div>\n      <div class=\"desc\">A가 NULL이면 <strong>B</strong>로 대체</div>\n      <div class=\"ex\">NVL(SAL, 0)</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">NVL2(A, B, C)</div>\n      <div class=\"desc\">A가 NULL <strong>아니면 B</strong>, NULL이면 <strong>C</strong></div>\n      <div class=\"ex\">NVL2(COMM, '있음', '없음')</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">NULLIF(A, B)</div>\n      <div class=\"desc\">A=B면 <strong>NULL</strong>, 아니면 A</div>\n      <div class=\"ex\">NULLIF(A, 0)</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">COALESCE(A, B, C, …)</div>\n      <div class=\"desc\">NULL이 <strong>아닌 첫 값</strong> 반환</div>\n      <div class=\"ex\">COALESCE(P1, P2, '없음')</div>\n    </div>\n  </div>\n\n  <!-- 집계 함수에서의 NULL -->\n  <h2 class=\"reveal\">집계 함수에서의 NULL</h2>\n  <table class=\"reveal\">\n    <thead>\n      <tr><th>함수</th><th>NULL 처리</th></tr>\n    </thead>\n    <tbody>\n      <tr><td><code>COUNT(*)</code></td><td>NULL 포함 모든 행 카운트</td></tr>\n      <tr><td><code>COUNT(컬럼)</code></td><td>NULL 제외</td></tr>\n      <tr><td><code>SUM/AVG/MAX/MIN</code></td><td>NULL 무시</td></tr>\n      <tr><td><code>AVG(컬럼)</code></td><td>(NULL 제외 합) / (NULL 제외 개수)</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">예시</h3>\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3);\">EMP 테이블</p>\n  <table class=\"reveal\">\n    <thead>\n      <tr><th>EMP</th><th>SAL</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>A</td><td>100</td></tr>\n      <tr><td>B</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td></tr>\n      <tr><td>C</td><td>200</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3);\">위 데이터에 집계 함수를 적용하면</p>\n  <table class=\"reveal\">\n    <thead>\n      <tr><th>쿼리</th><th>결과</th></tr>\n    </thead>\n    <tbody>\n      <tr><td><code>COUNT(*)</code></td><td>3</td></tr>\n      <tr><td><code>COUNT(SAL)</code></td><td>2</td></tr>\n      <tr><td><code>SUM(SAL)</code></td><td>300</td></tr>\n      <tr><td><code>AVG(SAL)</code></td><td>150 (300/2 — 0 포함이 아님에 주의)</td></tr>\n    </tbody>\n  </table>\n\n  <!-- SQL 실전 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">NULL 다루기</span>\n  </h2>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — EMP는 COMM이 NULL인 행이 섞여 있고, MEMBER는 PHONE/EMAIL 모두 비어 있을 수 있다</p>\n  <div class=\"null-flow reveal\" style=\"grid-template-columns: 1fr 36px 1fr;\">\n    <div class=\"null-side no-fix\">\n      <span class=\"tag\" style=\"background: var(--info-bg); color: var(--info-fg);\">EMP</span>\n      <h4 class=\"h\">사원 테이블</h4>\n      <div class=\"mini-table\" style=\"grid-template-columns: 1fr 1fr 1fr;\">\n        <div class=\"h\">NAME</div><div class=\"h\">SAL</div><div class=\"h\">COMM</div>\n        <div class=\"c\">A</div><div class=\"c\">100</div><div class=\"c\">10</div>\n        <div class=\"c\">B</div><div class=\"c\">200</div><div class=\"c is-null\">NULL</div>\n        <div class=\"c\">C</div><div class=\"c\">300</div><div class=\"c\">20</div>\n      </div>\n    </div>\n    <div class=\"null-arrow\">+</div>\n    <div class=\"null-side no-fix\">\n      <span class=\"tag\" style=\"background: var(--info-bg); color: var(--info-fg);\">MEMBER</span>\n      <h4 class=\"h\">회원 테이블</h4>\n      <div class=\"mini-table\" style=\"grid-template-columns: 1fr 1fr 1fr;\">\n        <div class=\"h\">NAME</div><div class=\"h\">PHONE</div><div class=\"h\">EMAIL</div>\n        <div class=\"c\">김</div><div class=\"c\">010-1234</div><div class=\"c\">k@x</div>\n        <div class=\"c\">이</div><div class=\"c is-null\">NULL</div><div class=\"c\">l@x</div>\n        <div class=\"c\">박</div><div class=\"c is-null\">NULL</div><div class=\"c is-null\">NULL</div>\n      </div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 잘못된 비교</span>\n<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">COMM</span> = <span class=\"sql-kw\">NULL</span>;     <span class=\"sql-cm\">-- 결과 0건</span>\n<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">COMM</span> != <span class=\"sql-kw\">NULL</span>;    <span class=\"sql-cm\">-- 결과 0건</span>\n\n<span class=\"sql-cm\">-- 올바른 비교</span>\n<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">COMM</span> <span class=\"sql-kw\">IS NULL</span>;\n<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">COMM</span> <span class=\"sql-kw\">IS NOT NULL</span>;\n\n<span class=\"sql-cm\">-- NULL 대체</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span>, <span class=\"sql-kw\">NVL</span>(<span class=\"sql-type\">COMM</span>, <span class=\"sql-num\">0</span>) <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">COMM_FIX</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span>;\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span>, <span class=\"sql-kw\">NVL2</span>(<span class=\"sql-type\">COMM</span>, <span class=\"sql-str\">'있음'</span>, <span class=\"sql-str\">'없음'</span>) <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">FLAG</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span>;\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span>, <span class=\"sql-kw\">COALESCE</span>(<span class=\"sql-type\">PHONE</span>, <span class=\"sql-type\">EMAIL</span>, <span class=\"sql-str\">'연락처 없음'</span>) <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">MEMBER</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ NVL2 결과 (EMP의 COMM이 NULL인 행은 '없음')</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>COMM</th><th>FLAG</th></tr></thead>\n    <tbody>\n      <tr><td>A</td><td>10</td><td>있음</td></tr>\n      <tr><td>B</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>없음</td></tr>\n      <tr><td>C</td><td>20</td><td>있음</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ NVL2(A, B, C): A가 NULL이 아니면 B('있음'), NULL이면 C('없음').</p>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ COALESCE 결과 (PHONE → EMAIL → '연락처 없음' 순으로 첫 비-NULL)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>PHONE</th><th>EMAIL</th><th>COALESCE</th></tr></thead>\n    <tbody>\n      <tr><td>김</td><td>010-1234</td><td>k@x</td><td>010-1234</td></tr>\n      <tr><td>이</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>l@x</td><td>l@x</td></tr>\n      <tr><td>박</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>연락처 없음</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 왼쪽부터 평가하다 처음으로 NULL이 아닌 값이 나오면 그 값을 반환. 모두 NULL이면 마지막 기본값(문자열).</p>\n\n  <!-- Before / After — 인포그래픽 -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">NULL이 끼면 결과가 달라진다</span>\n  </h2>\n  <p class=\"reveal\">기본급(<code>SAL</code>)에 커미션(<code>COMM</code>)을 더해 <strong>총급여</strong>를 구하는 상황. 아래 EMP에서 <strong>B</strong>는 커미션이 등록되지 않아 <code>COMM</code>이 NULL이다. 단순 합산과 <code>NVL</code> 처리의 결과를 비교한다.</p>\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3); margin-top: 0;\">EMP 테이블</p>\n  <table class=\"reveal\">\n    <thead>\n      <tr><th>NAME</th><th>SAL</th><th>COMM</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>A</td><td>100</td><td>10</td></tr>\n      <tr><td>B</td><td>200</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td></tr>\n      <tr><td>C</td><td>300</td><td>20</td></tr>\n    </tbody>\n  </table>\n  <div class=\"null-flow reveal\">\n    <div class=\"null-side no-fix\">\n      <span class=\"tag\">BEFORE</span>\n      <h4 class=\"h\">NULL을 그대로 더하면</h4>\n      <div class=\"sql\">SELECT NAME, SAL + COMM FROM EMP;</div>\n      <div class=\"mini-table\">\n        <div class=\"h\">NAME</div><div class=\"h\">SAL+COMM</div>\n        <div class=\"c\">A</div><div class=\"c\">110</div>\n        <div class=\"c\">B</div><div class=\"c is-null\">NULL</div>\n        <div class=\"c\">C</div><div class=\"c\">320</div>\n      </div>\n    </div>\n    <div class=\"null-arrow\">→</div>\n    <div class=\"null-side fixed\">\n      <span class=\"tag\">AFTER</span>\n      <h4 class=\"h\">NVL로 안전하게 처리</h4>\n      <div class=\"sql\">SELECT NAME, SAL + NVL(COMM, 0) FROM EMP;</div>\n      <div class=\"mini-table\">\n        <div class=\"h\">NAME</div><div class=\"h\">TOTAL</div>\n        <div class=\"c\">A</div><div class=\"c\">110</div>\n        <div class=\"c\">B</div><div class=\"c\">200</div>\n        <div class=\"c\">C</div><div class=\"c\">320</div>\n      </div>\n    </div>\n  </div>\n  <p class=\"reveal\">NULL은 산술 연산에 들어가면 결과 전체를 NULL로 만든다. B처럼 커미션이 비어 있을 뿐인 직원의 총급여까지 사라져버리는 셈이다. <code>NVL(COMM, 0)</code>으로 <strong>\"커미션 없음 = 0\"</strong>으로 안전하게 치환하면, NULL 행도 정상 합산되어 보고서에 누락이 생기지 않는다. 합계·평균 같은 집계 전에는 늘 NULL을 어떻게 다룰지 정해두는 것이 안전하다.</p>\n\n  <!-- NULL과 정렬 -->\n  <h2 class=\"reveal\">NULL과 정렬</h2>\n  <table class=\"reveal\">\n    <thead>\n      <tr><th>DBMS</th><th>기본 정렬 시 NULL 위치</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>Oracle</td><td>오름차순(ASC)에서 마지막, 내림차순(DESC)에서 처음</td></tr>\n      <tr><td>MS-SQL</td><td>오름차순에서 처음</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\">직접 지정: <code>ORDER BY COL NULLS FIRST</code> / <code>NULLS LAST</code> (자세히는 <a href=\"#\" data-chapter=\"c216\">ORDER BY 절</a>)</p>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-1-2-4\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c125: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    본질<a href=\"#\" data-chapter=\"c115\">식별자</a>는 <strong>업무에서 자연스럽게 도출된 식별자</strong>, 인조식별자는 <strong>인위적으로 만든 식별자</strong>다. 둘의 장단점을 알고 상황에 맞게 선택한다.\n  </blockquote>\n  <div class=\"ex-box reveal\">\n    도서관에서 ISBN(출판사 부여 = <strong>본질식별자</strong>)과 자체 분류번호 A-001(도서관 임의 부여 = <strong>인조식별자</strong>) 두 가지로 책을 구분할 수 있다. ISBN이 길고 형식이 들쑥날쑥해서 도서관은 자체 번호를 더 자주 쓴다.\n  </div>\n\n  <!-- 개념 도식화 — threeway 2-way -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">본질 vs 인조</span>\n  </h2>\n  <div class=\"threeway cols-2 reveal\">\n    <div class=\"threeway-card t-info\">\n      <div class=\"glyph\">本</div>\n      <div class=\"name\">본질식별자 (Natural)</div>\n      <div class=\"desc\"><strong>업무에서 자연 도출</strong> · 의미 있음 · 변경 위험 존재<br>예: 주민번호 · 사업자번호 · ISBN</div>\n    </div>\n    <div class=\"threeway-card t-correct\">\n      <div class=\"glyph\">人</div>\n      <div class=\"name\">인조식별자 (Surrogate)</div>\n      <div class=\"desc\"><strong>인위적으로 부여</strong> · 의미 없음 · 변경에 자유<br>예: 자동증가 ID · UUID · GUID</div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead><tr><th>구분</th><th>본질식별자</th><th>인조식별자</th></tr></thead>\n    <tbody>\n      <tr><td>출처</td><td>업무에서 자연 발생</td><td>인위적으로 부여</td></tr>\n      <tr><td>예시</td><td>주민번호 · 사업자번호 · ISBN</td><td>자동증가 ID · UUID · GUID</td></tr>\n      <tr><td>의미</td><td>업무적 의미 있음</td><td>의미 없음 (대체 키)</td></tr>\n      <tr><td>변경</td><td>변경되면 큰 영향</td><td>자유롭게 부여 가능</td></tr>\n    </tbody>\n  </table>\n  <div class=\"mermaid reveal\">\nflowchart TD\n    Start[\"식별자 후보 검토\"] --> Q1{\"업무에서<br/>자연 도출?\"}\n    Q1 -->|\"NO\"| SUR1[\"인조식별자<br/>(SEQ · UUID)\"]\n    Q1 -->|\"YES\"| Q2{\"길이가 길거나<br/>형식 들쑥날쑥?\"}\n    Q2 -->|\"YES\"| SUR2[\"인조식별자\"]\n    Q2 -->|\"NO\"| Q3{\"보안·개인정보<br/>이슈?\"}\n    Q3 -->|\"YES\"| SUR3[\"인조식별자<br/>(본질키는 UNIQUE)\"]\n    Q3 -->|\"NO\"| Q4{\"값이 자주<br/>변경되나?\"}\n    Q4 -->|\"YES\"| SUR4[\"인조식별자\"]\n    Q4 -->|\"NO\"| NAT[\"본질식별자<br/>OK\"]\n    style NAT fill:#E9F0F6,stroke:#2F5D80\n    style SUR1 fill:#E6F3E7,stroke:#256B29\n    style SUR2 fill:#E6F3E7,stroke:#256B29\n    style SUR3 fill:#E6F3E7,stroke:#256B29\n    style SUR4 fill:#E6F3E7,stroke:#256B29\n  </div>\n\n  <!-- 비교표 -->\n  <h2 class=\"reveal\">비교표</h2>\n  <table class=\"reveal\">\n    <thead><tr><th>항목</th><th>본질식별자</th><th>인조식별자</th></tr></thead>\n    <tbody>\n      <tr><td>정의</td><td>업무에서 자연스럽게 도출</td><td>인위적으로 부여</td></tr>\n      <tr><td>예시</td><td>주민번호, 사업자번호, ISBN</td><td>자동증가 ID, UUID, GUID</td></tr>\n      <tr><td>의미</td><td>업무적 의미 있음</td><td>의미 없음 (단순 키)</td></tr>\n      <tr><td>변경 위험</td><td><strong>존재</strong> — 업무 규칙 변동 시 변할 수 있음 (예: 주민번호 체계 개편)</td><td><strong>없음</strong> — 한 번 부여되면 영구 고정</td></tr>\n      <tr><td>길이</td><td>길 수 있음</td><td>짧고 일관</td></tr>\n      <tr><td>데이터 품질 검증</td><td>가능 (중복 자연 검출)</td><td>어려움 — 본질키에 별도 UNIQUE 필요</td></tr>\n      <tr><td>PK 사용 시 장점</td><td>의미 검증 용이</td><td>JOIN/인덱스/관리 효율</td></tr>\n    </tbody>\n  </table>\n\n  <!-- 장단점 — fn-grid 스타일 -->\n  <h2 class=\"reveal\">인조식별자의 장단점</h2>\n  <div class=\"fn-grid reveal\">\n    <div class=\"fn-card\">\n      <div class=\"name\">+ 장점</div>\n      <div class=\"desc\">짧고 일관된 형식 · 변경에 자유로움 · JOIN/인덱스 효율 · 보안(주민번호 노출 회피)</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">- 단점</div>\n      <div class=\"desc\">업무적 의미 없음 · 중복 데이터 식별 어려움 · 추가 UNIQUE 제약 필요 · 모델이 직관적이지 않음</div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead><tr><th>장점</th><th>단점</th></tr></thead>\n    <tbody>\n      <tr><td>짧고 일관된 형식</td><td>업무적 의미 없음</td></tr>\n      <tr><td>변경에 자유로움</td><td>중복 데이터 식별 어려움</td></tr>\n      <tr><td>JOIN/인덱스 효율</td><td>추가 UNIQUE 제약 필요</td></tr>\n      <tr><td>보안(주민번호 노출 회피)</td><td>모델이 직관적이지 않음</td></tr>\n    </tbody>\n  </table>\n\n  <h2 class=\"reveal\">본질식별자의 장단점</h2>\n  <div class=\"fn-grid reveal\">\n    <div class=\"fn-card\">\n      <div class=\"name\">+ 장점</div>\n      <div class=\"desc\">업무적 의미 명확 · 자연스러운 데이터 검증 · 모델 직관적</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">- 단점</div>\n      <div class=\"desc\">길거나 복잡 · 변경되면 큰 영향 · 보안 이슈(개인정보 등)</div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead><tr><th>장점</th><th>단점</th></tr></thead>\n    <tbody>\n      <tr><td>업무적 의미 명확</td><td>길거나 복잡</td></tr>\n      <tr><td>자연스러운 데이터 검증</td><td>변경되면 큰 영향</td></tr>\n      <tr><td>모델 직관적</td><td>보안 이슈(개인정보 등)</td></tr>\n    </tbody>\n  </table>\n\n  <!-- 언제 무엇을 쓸까 -->\n  <h2 class=\"reveal\">언제 무엇을 쓸까</h2>\n  <p class=\"reveal\"><strong>현업 권장 패턴</strong>: PK는 인조식별자, 본질키는 UNIQUE 제약으로 별도 보존 → 보안·성능·일관성 모두 만족. 본질키를 PK로 쓰면 <a href=\"#\" data-chapter=\"c121\">정규화</a> 단계의 종속성 분석이 자연스럽지만, 변경 위험이 따른다는 점을 고려한다.</p>\n\n  <!-- SQL 실전 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">두 식별자의 구현</span>\n  </h2>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — 같은 책을 두 가지 PK 설계로 만들어 본 BOOK 테이블 형태</p>\n  <div class=\"ba-flow reveal\" style=\"grid-template-columns: 1fr 36px 1fr; align-items: stretch;\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">본질 PK</span>\n      <h4 class=\"ba-h\">BOOK (PK = ISBN)</h4>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">ISBN (PK)</div><div class=\"h\">TITLE</div><div class=\"h\">AUTHOR</div>\n        <div class=\"c\">978-89-1234</div><div class=\"c\">SQL</div><div class=\"c is-null\">NULL</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\" style=\"font-size: 22px; color: var(--point-500);\">↔</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">인조 PK + UQ</span>\n      <h4 class=\"ba-h\">BOOK (PK = BOOK_ID, UQ = ISBN)</h4>\n      <div class=\"mini-table cols-4\">\n        <div class=\"h\">BOOK_ID (PK)</div><div class=\"h\">ISBN (UQ)</div><div class=\"h\">TITLE</div><div class=\"h\">AUTHOR</div>\n        <div class=\"c\">1</div><div class=\"c\">978-89-1234</div><div class=\"c\">SQL</div><div class=\"c is-null\">NULL</div>\n      </div>\n    </div>\n  </div>\n  <h3 class=\"reveal\">본질식별자 사용</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">CREATE TABLE</span> <span class=\"sql-name\">BOOK</span> (\n    <span class=\"sql-type\">ISBN</span>     <span class=\"sql-kw\">VARCHAR2</span>(<span class=\"sql-num\">20</span>) <span class=\"sql-kw\">PRIMARY KEY</span>,  <span class=\"sql-cm\">-- 본질식별자</span>\n    <span class=\"sql-type\">TITLE</span>    <span class=\"sql-kw\">VARCHAR2</span>(<span class=\"sql-num\">200</span>),\n    <span class=\"sql-type\">AUTHOR</span>   <span class=\"sql-kw\">VARCHAR2</span>(<span class=\"sql-num\">100</span>)\n);</code></pre>\n\n  <h3 class=\"reveal\">인조식별자 사용</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">CREATE TABLE</span> <span class=\"sql-name\">BOOK</span> (\n    <span class=\"sql-type\">BOOK_ID</span>  <span class=\"sql-kw\">NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY</span>,  <span class=\"sql-cm\">-- 인조식별자</span>\n    <span class=\"sql-type\">ISBN</span>     <span class=\"sql-kw\">VARCHAR2</span>(<span class=\"sql-num\">20</span>) <span class=\"sql-kw\">UNIQUE</span>,                              <span class=\"sql-cm\">-- 본질키는 UNIQUE로 유지</span>\n    <span class=\"sql-type\">TITLE</span>    <span class=\"sql-kw\">VARCHAR2</span>(<span class=\"sql-num\">200</span>),\n    <span class=\"sql-type\">AUTHOR</span>   <span class=\"sql-kw\">VARCHAR2</span>(<span class=\"sql-num\">100</span>)\n);\n\n<span class=\"sql-cm\">-- 같은 ISBN을 두 번 INSERT 시도</span>\n<span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">BOOK</span>(<span class=\"sql-type\">ISBN</span>, <span class=\"sql-type\">TITLE</span>) <span class=\"sql-kw\">VALUES</span>(<span class=\"sql-str\">'978-89-1234'</span>, <span class=\"sql-str\">'SQL'</span>);\n<span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">BOOK</span>(<span class=\"sql-type\">ISBN</span>, <span class=\"sql-type\">TITLE</span>) <span class=\"sql-kw\">VALUES</span>(<span class=\"sql-str\">'978-89-1234'</span>, <span class=\"sql-str\">'SQL'</span>);\n<span class=\"sql-cm\">-- ORA-00001: unique constraint violated</span>\n\n<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">BOOK</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과</p>\n  <table class=\"reveal\">\n    <thead><tr><th>BOOK_ID (PK)</th><th>ISBN (UQ)</th><th>TITLE</th><th>AUTHOR</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td>978-89-1234</td><td>SQL</td><td>(NULL)</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 두 번째 INSERT는 ISBN UNIQUE 제약 위반으로 거부 → 1행만 남는다. 인조 PK + 본질키 UNIQUE 조합이 무결성을 함께 지켜준다.</p>\n  <p class=\"reveal\">권장 패턴: 인조식별자를 <strong>PK</strong>로, 본질식별자를 <strong>UNIQUE 제약</strong>으로 함께 둔다. UNIQUE 제약 덕에 같은 ISBN 중복 입력은 차단되어 본질키의 무결성도 보존된다.</p>\n\n  <h3 class=\"reveal\">ER로 보는 인조식별자 패턴</h3>\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3);\">인조식별자 PK — 본질키는 UNIQUE로 보존, 자식엔 짧은 ID</p>\n  <div class=\"mermaid reveal\">\nerDiagram\n    MEMBER_SUR ||--o{ ORDER_SUR : \"주문\"\n    MEMBER_SUR {\n        varchar MEMBER_ID PK \"M01 같은 인조키\"\n        varchar RRN \"UNIQUE - 본질키 보존\"\n        varchar NAME\n    }\n    ORDER_SUR {\n        number  ORDER_ID PK\n        varchar MEMBER_ID FK \"짧은 ID만\"\n    }\n  </div>\n\n  <!-- Before & After -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">인조식별자 도입의 효과</span>\n  </h2>\n  <p class=\"reveal\">회원 김철수의 주민번호(800101-1234567)를 회원 PK로 쓰는 경우와, 인조식별자(M01)를 PK로 두고 주민번호는 UNIQUE로 보존하는 경우. 자식 테이블(주문)에 어떤 값이 흩뿌려지는지를 비교한다.</p>\n\n  <h3 class=\"reveal\">Before — 본질식별자(주민번호)를 PK로</h3>\n  <table class=\"reveal\">\n    <thead><tr><th>주문 (FK: 주민번호)</th></tr></thead>\n    <tbody>\n      <tr><td>800101-1234567 → 김철수 주문 1</td></tr>\n      <tr><td>800101-1234567 → 김철수 주문 2</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\">모든 자식 테이블에 주민번호가 흩뿌려져 개인정보 노출 위험이 커진다.</p>\n\n  <h3 class=\"reveal\">After — 인조식별자(MEMBER_ID) 도입</h3>\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3);\">MEMBER</p>\n  <table class=\"reveal\">\n    <thead><tr><th>MEMBER_ID(PK)</th><th>RRN(UQ)</th><th>NAME</th></tr></thead>\n    <tbody>\n      <tr><td>M01</td><td>800101-1234567</td><td>김철수</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3);\">ORDER (FK: MEMBER_ID)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>ORDER_ID</th><th>MEMBER_ID</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td>M01</td></tr>\n      <tr><td>2</td><td>M01</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\">자식 테이블엔 의미 없는 ID만 들어가 보안과 JOIN 효율이 모두 향상된다.</p>\n\n  <div class=\"ba-flow large-after reveal\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">BEFORE · 본질식별자 PK</span>\n      <h4 class=\"ba-h\">자식에도 주민번호 흩뿌려짐</h4>\n      <div class=\"ba-tables cols-2\">\n        <div class=\"ba-mini-table\">\n          <div class=\"h\">MEMBER (PK=주민번호)</div>\n          <div class=\"row\">800101-1234567 김철수</div>\n        </div>\n        <div class=\"ba-mini-table\">\n          <div class=\"h\">ORDER (FK)</div>\n          <div class=\"row\">1 · 800101-1234567</div>\n          <div class=\"row\">2 · 800101-1234567</div>\n        </div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\">→</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">AFTER · 인조식별자 PK</span>\n      <h4 class=\"ba-h\">자식엔 짧은 ID만, 본질키는 UNIQUE로 보존</h4>\n      <div class=\"ba-tables cols-2\">\n        <div class=\"ba-mini-table\">\n          <div class=\"h\">MEMBER (PK=M01, UQ=RRN)</div>\n          <div class=\"row\">M01 · 800101-1234567 · 김철수</div>\n        </div>\n        <div class=\"ba-mini-table\">\n          <div class=\"h\">ORDER (FK=MEMBER_ID)</div>\n          <div class=\"row\">1 · M01</div>\n          <div class=\"row\">2 · M01</div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <p class=\"reveal\">PK는 모든 자식 테이블에 FK로 흩어지므로, 본질식별자가 PK면 그 값(주민번호)도 함께 흩어진다 — 보안 사고의 표면적이 그대로 늘어나는 셈이다. 또 본질키는 길거나 형식이 들쑥날쑥해 인덱스·조인 비용도 커진다. 인조식별자(M01 같은 짧은 키)를 PK로 두고 본질키는 회원 테이블 한 곳에 UNIQUE로 가둬두면, 보안·성능·일관성이 한꺼번에 정리된다. 다만 본질키의 무결성 검증을 위해 <strong>UNIQUE 제약을 빼먹지 않는 것이 핵심</strong>이다.</p>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-1-2-5\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c211: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    관계형 데이터베이스(RDB, Relational Database)는 데이터를 <strong>행과 열로 된 표(테이블)</strong>로 저장하고, <strong>표들 사이의 관계</strong>로 데이터를 관리하는 시스템이다.\n  </blockquote>\n  <div class=\"ex-box reveal\">\n    엑셀 한 권에 여러 시트(=테이블)가 있고 VLOOKUP의 키(=외래키)로 시트끼리 연결되는 구조를, 더 안전하고 동시에 다룰 수 있도록 만든 것이 RDB다.\n  </div>\n\n  <!-- 개념 도식화 -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">데이터베이스의 구조</span>\n  </h2>\n  <div class=\"layer-stack reveal\">\n    <div class=\"layer-stack-track\">\n      <div class=\"layer-row\">\n        <div class=\"icon\">DB</div>\n        <div class=\"body\">\n          <div class=\"name\">DBMS <small>관리 SW</small></div>\n          <div class=\"desc\">Oracle, MySQL, PostgreSQL 등 — 데이터베이스를 관리하는 소프트웨어</div>\n        </div>\n        <span class=\"arrow\">▼</span>\n      </div>\n      <div class=\"layer-row\">\n        <div class=\"icon\">▤</div>\n        <div class=\"body\">\n          <div class=\"name\">Database <small>저장소</small></div>\n          <div class=\"desc\">여러 테이블을 담는 데이터의 저장소</div>\n        </div>\n        <span class=\"arrow\">▼</span>\n      </div>\n      <div class=\"layer-row\">\n        <div class=\"icon\">⌗</div>\n        <div class=\"body\">\n          <div class=\"name\">Table <small>행 + 열</small></div>\n          <div class=\"desc\">행(Row=Record=Tuple) × 열(Column=Attribute=Field). 테이블끼리 관계로 연결</div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead><tr><th>용어</th><th>의미</th></tr></thead>\n    <tbody>\n      <tr><td>DBMS</td><td>데이터베이스를 관리하는 SW (Oracle, MySQL 등)</td></tr>\n      <tr><td>Database</td><td>데이터의 저장소</td></tr>\n      <tr><td>Table</td><td>행과 열로 된 표</td></tr>\n      <tr><td>Row(Record)</td><td>한 줄(한 인스턴스)</td></tr>\n      <tr><td>Column(Attribute)</td><td>한 칸(속성)</td></tr>\n    </tbody>\n  </table>\n\n  <!-- SQL 명령어 분류 — cls-row.cols-4 -->\n  <h2 class=\"reveal\">SQL 명령어 분류</h2>\n  <div class=\"cls-row cols-4 reveal\">\n    <div class=\"cls-card\">\n      <span class=\"badge\">DDL</span>\n      <div class=\"name\">정의어</div>\n      <div class=\"ex\"><strong>CREATE · ALTER · DROP<br>TRUNCATE · RENAME</strong><br><span style=\"color:var(--fg-3)\">표(설계도) 만들기/바꾸기</span></div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-info\">DML</span>\n      <div class=\"name\">조작어</div>\n      <div class=\"ex\"><strong>SELECT · INSERT · UPDATE<br>DELETE · MERGE</strong><br><span style=\"color:var(--fg-3)\">표 안의 데이터 조작</span></div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-warn\">DCL</span>\n      <div class=\"name\">제어어</div>\n      <div class=\"ex\"><strong>GRANT · REVOKE</strong><br><span style=\"color:var(--fg-3)\">권한 부여/회수</span></div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-event\">TCL</span>\n      <div class=\"name\">트랜잭션</div>\n      <div class=\"ex\"><strong>COMMIT · ROLLBACK<br>SAVEPOINT</strong><br><span style=\"color:var(--fg-3)\">트랜잭션 묶음 처리</span></div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead><tr><th>분류</th><th>풀이</th><th>명령어</th><th>비유</th></tr></thead>\n    <tbody>\n      <tr><td><a href=\"#\" data-chapter=\"c233\">DDL</a></td><td>Data Definition</td><td>CREATE, ALTER, DROP, TRUNCATE, RENAME</td><td>표(설계도) 만들기/바꾸기</td></tr>\n      <tr><td><a href=\"#\" data-chapter=\"c231\">DML</a></td><td>Data Manipulation</td><td><a href=\"#\" data-chapter=\"c212\">SELECT</a>, INSERT, UPDATE, DELETE, MERGE</td><td>표 안의 데이터 조작</td></tr>\n      <tr><td><a href=\"#\" data-chapter=\"c234\">DCL</a></td><td>Data Control</td><td>GRANT, REVOKE</td><td>권한 부여/회수</td></tr>\n      <tr><td><a href=\"#\" data-chapter=\"c232\">TCL</a></td><td>Transaction Control</td><td>COMMIT, ROLLBACK, SAVEPOINT</td><td>트랜잭션 묶음 처리</td></tr>\n    </tbody>\n  </table>\n  <blockquote class=\"reveal\">\n    <strong>헷갈리기 쉬운 점</strong> — <code>TRUNCATE</code>는 DDL, <code>DELETE</code>는 DML이다.\n  </blockquote>\n\n  <!-- ER 다이어그램 — 정규화된 관계형 DB 예시 -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">정규화된 관계형 DB의 ER 예시</span>\n  </h2>\n  <p class=\"reveal\">회원이 주문을 여러 건 가질 수 있는 1:N 관계. 외래키(FK)로 두 테이블이 연결된다.</p>\n  <div class=\"mermaid reveal\">\nerDiagram\n    MEMBER ||--o{ ORDERS : \"places\"\n    MEMBER {\n      int    member_id PK\n      string name\n      string email\n    }\n    ORDERS {\n      int    order_id PK\n      int    member_id FK\n      date   order_date\n      number total_amount\n    }\n  </div>\n  <div class=\"er-row reveal\">\n    <div class=\"er-entity\">\n      <div class=\"ent-name\">MEMBER</div>\n      <div class=\"attr pk\">member_id</div>\n      <div class=\"attr\">name</div>\n      <div class=\"attr\">email</div>\n    </div>\n    <div class=\"er-relation\">\n      <div class=\"card\">1 : N</div>\n      <span class=\"label\">places</span>\n    </div>\n    <div class=\"er-entity\">\n      <div class=\"ent-name\">ORDERS</div>\n      <div class=\"attr pk\">order_id</div>\n      <div class=\"attr fk\">member_id</div>\n      <div class=\"attr\">order_date</div>\n      <div class=\"attr\">total_amount</div>\n    </div>\n  </div>\n\n  <!-- 주요 데이터 타입 -->\n  <h2 class=\"reveal\">주요 데이터 타입</h2>\n  <div class=\"fn-grid cols-3 reveal\">\n    <div class=\"fn-card\">\n      <div class=\"name\">CHAR(n)</div>\n      <div class=\"desc\"><strong>고정</strong> 길이 문자열 — 모자라면 공백으로 채움</div>\n      <div class=\"ex\">CHAR(5) ← 'AB' → 'AB&nbsp;&nbsp;&nbsp;'</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">VARCHAR2(n)</div>\n      <div class=\"desc\"><strong>가변</strong> 길이 문자열 — 입력한 만큼만 저장</div>\n      <div class=\"ex\">VARCHAR2(5) ← 'AB' → 'AB'</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">NUMBER(p, s)</div>\n      <div class=\"desc\">숫자 (전체 p자리, 소수 s자리)</div>\n      <div class=\"ex\">NUMBER(7, 2) → 12345.67</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">DATE</div>\n      <div class=\"desc\">날짜 + 시간</div>\n      <div class=\"ex\">2026-04-26 13:24:00</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">TIMESTAMP</div>\n      <div class=\"desc\">정밀 시간 (소수초까지)</div>\n      <div class=\"ex\">2026-04-26 13:24:00.123456</div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead><tr><th>타입</th><th>의미</th><th>예</th></tr></thead>\n    <tbody>\n      <tr><td>CHAR(n)</td><td><strong>고정</strong> 길이 문자열 — 모자라면 공백으로 채움</td><td>CHAR(5)에 'AB' 저장 → 'AB&nbsp;&nbsp;&nbsp;' (공백 3칸)</td></tr>\n      <tr><td>VARCHAR2(n)</td><td><strong>가변</strong> 길이 문자열 — 입력한 만큼만 저장</td><td>VARCHAR2(5)에 'AB' 저장 → 'AB'</td></tr>\n      <tr><td>NUMBER(p, s)</td><td>숫자 (전체 p자리, 소수 s자리)</td><td>NUMBER(7, 2) → 12345.67</td></tr>\n      <tr><td>DATE</td><td>날짜+시간</td><td>2026-04-26 13:24:00</td></tr>\n      <tr><td>TIMESTAMP</td><td>정밀 시간 (소수초까지)</td><td>2026-04-26 13:24:00.123456</td></tr>\n    </tbody>\n  </table>\n\n  <!-- ACID -->\n  <h2 class=\"reveal\">트랜잭션의 핵심 약속 — ACID</h2>\n  <div class=\"trait-grid cols-4 reveal\">\n    <div class=\"trait-card\">\n      <div class=\"glyph\">A</div>\n      <div class=\"label\">Atomicity</div>\n      <div class=\"desc\">전부 성공 또는 전부 실패</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"glyph\">C</div>\n      <div class=\"label\">Consistency</div>\n      <div class=\"desc\">규칙 유지</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"glyph\">I</div>\n      <div class=\"label\">Isolation</div>\n      <div class=\"desc\">동시 처리 시 격리</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"glyph\">D</div>\n      <div class=\"label\">Durability</div>\n      <div class=\"desc\">커밋 후 영구 저장</div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead><tr><th>성질</th><th>의미</th></tr></thead>\n    <tbody>\n      <tr><td>Atomicity</td><td>전부 성공 또는 전부 실패</td></tr>\n      <tr><td>Consistency</td><td>규칙 유지</td></tr>\n      <tr><td>Isolation</td><td>동시 처리 시 격리</td></tr>\n      <tr><td>Durability</td><td>커밋 후 영구 저장</td></tr>\n    </tbody>\n  </table>\n\n  <!-- SQL 실전 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">DDL → DML → TCL → DCL 흐름</span>\n  </h2>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — 테이블 생성 직후 빈 상태</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">EMP</span>\n    <h4 class=\"ba-h\">사원 테이블 (생성 직후 0행)</h4>\n    <div class=\"mini-table cols-3\">\n      <div class=\"h\">EMP_ID</div><div class=\"h\">NAME</div><div class=\"h\">SAL</div>\n      <div class=\"c\" style=\"grid-column: 1 / -1; color: var(--fg-4);\">(데이터 없음)</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- DDL: 테이블 생성</span>\n<span class=\"sql-kw\">CREATE TABLE</span> <span class=\"sql-name\">EMP</span> (\n    <span class=\"sql-type\">EMP_ID</span> <span class=\"sql-kw\">NUMBER PRIMARY KEY</span>,\n    <span class=\"sql-type\">NAME</span>   <span class=\"sql-kw\">VARCHAR2</span>(<span class=\"sql-num\">50</span>),\n    <span class=\"sql-type\">SAL</span>    <span class=\"sql-kw\">NUMBER</span>\n);\n\n<span class=\"sql-cm\">-- DML: 데이터 입력/조회</span>\n<span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">VALUES</span> (<span class=\"sql-num\">1</span>, <span class=\"sql-str\">'김철수'</span>, <span class=\"sql-num\">3000</span>);\n<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span>;\n\n<span class=\"sql-cm\">-- TCL: 영구 저장</span>\n<span class=\"sql-kw\">COMMIT</span>;\n\n<span class=\"sql-cm\">-- DCL: 권한 부여</span>\n<span class=\"sql-kw\">GRANT SELECT ON</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">TO</span> <span class=\"sql-name\">USER1</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (<code>SELECT * FROM EMP;</code>)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>EMP_ID</th><th>NAME</th><th>SAL</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td>김철수</td><td>3000</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ DDL로 표 만들기 → DML로 행 넣고 조회 → TCL로 영구 반영 → DCL로 권한 부여. 4가지 분류가 한 흐름에서 모두 등장한다.</p>\n\n  <!-- Before & After -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">파일 시스템 vs RDB</span>\n  </h2>\n  <p class=\"reveal\">직원 데이터(EMP_ID, NAME, SAL) 2건을 보관하고 \"급여 2000 초과인 사람\"을 찾는 상황. 텍스트 파일에 그대로 저장한 경우와 RDB의 EMP 테이블에 넣은 경우를 비교한다.</p>\n\n  <h3 class=\"reveal\">Before — 일반 파일에 저장</h3>\n  <pre class=\"reveal\"><code>emp.txt\n1, 김철수, 3000\n2, 이영희, 4000</code></pre>\n  <p class=\"reveal\">동시 수정 불가, 검색 느림, 무결성 보장 어려움.</p>\n\n  <h3 class=\"reveal\">After — RDB 사용</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">SAL</span> &gt; <span class=\"sql-num\">2000</span>;</code></pre>\n  <p class=\"reveal\">빠른 검색(인덱스), 동시 처리(트랜잭션), 무결성 제약이 보장된다.</p>\n\n  <div class=\"ba-flow reveal\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">BEFORE · emp.txt</span>\n      <h4 class=\"ba-h\">단순 파일</h4>\n      <div class=\"sql\">1, 김철수, 3000\n2, 이영희, 4000</div>\n      <div class=\"ba-row\">동시 수정 불가</div>\n      <div class=\"ba-row\">검색 시 매번 파싱</div>\n      <div class=\"ba-row\">무결성 보장 어려움</div>\n    </div>\n    <div class=\"ba-arrow\">→</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">AFTER · RDB</span>\n      <h4 class=\"ba-h\">스키마·인덱스·트랜잭션</h4>\n      <div class=\"sql\">SELECT * FROM EMP\nWHERE SAL &gt; 2000;</div>\n      <div class=\"ba-row\">인덱스로 빠른 검색</div>\n      <div class=\"ba-row\">트랜잭션으로 동시 처리</div>\n      <div class=\"ba-row\">제약조건으로 무결성 보장</div>\n    </div>\n  </div>\n\n  <p class=\"reveal\">파일에는 데이터의 의미·타입·관계 정보가 없어 매번 읽어 직접 파싱해야 하고, 두 사람이 동시에 수정하면 한쪽 변경이 사라진다. RDB는 스키마(타입·제약)·인덱스·트랜잭션을 엔진이 보장하므로 데이터가 많거나 여러 사용자가 함께 쓰는 환경에서는 단순 파일이 아니라 RDB로 관리해야 한다.</p>\n\n  <!-- RDB 5대 장점 -->\n  <h2 class=\"reveal\">RDB의 5대 장점</h2>\n  <div class=\"trait-grid reveal\">\n    <div class=\"trait-card\">\n      <div class=\"num\">1</div>\n      <div class=\"label\">데이터 독립성</div>\n      <div class=\"desc\">DB 변경이 응용 프로그램에 영향을 덜 줌</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"num\">2</div>\n      <div class=\"label\">중복 최소화</div>\n      <div class=\"desc\">정규화로 일관성 유지</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"num\">3</div>\n      <div class=\"label\">무결성</div>\n      <div class=\"desc\">제약조건으로 잘못된 데이터 차단</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"num\">4</div>\n      <div class=\"label\">보안</div>\n      <div class=\"desc\">DCL로 권한 관리</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"num\">5</div>\n      <div class=\"label\">동시성</div>\n      <div class=\"desc\">트랜잭션 격리로 충돌 방지</div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead><tr><th>장점</th><th>설명</th></tr></thead>\n    <tbody>\n      <tr><td>데이터 독립성</td><td>DB 변경이 응용 프로그램에 영향을 덜 줌</td></tr>\n      <tr><td>데이터 중복 최소화</td><td>정규화로 일관성 유지</td></tr>\n      <tr><td>무결성</td><td>제약조건으로 잘못된 데이터 차단</td></tr>\n      <tr><td>보안</td><td>DCL로 권한 관리</td></tr>\n      <tr><td>동시성</td><td>트랜잭션 격리로 충돌 방지</td></tr>\n    </tbody>\n  </table>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-2-1-1\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c212: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    SELECT 문은 데이터베이스에서 <strong>원하는 데이터를 골라서 뽑아내는</strong> 명령어다.\n  </blockquote>\n  <div class=\"ex-box reveal\">\n    식당 주문처럼 \"어느 식당(<strong>FROM</strong>) · 어떤 음식(<strong>SELECT</strong>) · 조건(<strong>WHERE</strong>) · 그룹별(<strong>GROUP BY</strong>) · 정렬(<strong>ORDER BY</strong>)\"을 차례로 지정한다.\n  </div>\n\n  <!-- 개념 도식화 — 6대 절 -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">SELECT 문의 6대 절</span>\n  </h2>\n  <pre class=\"reveal\"><code><span class=\"sql-kw\">SELECT</span>    컬럼1, 컬럼2, ...      <span class=\"sql-cm\">← ② 어떤 컬럼? (함수 활용)</span>\n<span class=\"sql-kw\">FROM</span>      테이블                   <span class=\"sql-cm\">← ① 어디서? (조인 가능)</span>\n<span class=\"sql-kw\">WHERE</span>     조건                     <span class=\"sql-cm\">← ③ 어떤 행?</span>\n<span class=\"sql-kw\">GROUP BY</span>  그룹기준                 <span class=\"sql-cm\">← ④ 어떻게 묶을지?</span>\n<span class=\"sql-kw\">HAVING</span>    그룹조건                 <span class=\"sql-cm\">← ⑤ 묶은 후 조건?</span>\n<span class=\"sql-kw\">ORDER BY</span>  정렬기준;                <span class=\"sql-cm\">← ⑥ 어떻게 정렬?</span></code></pre>\n  <p class=\"reveal\">각 절의 자세한 사용은 <a href=\"#\" data-chapter=\"c214\">WHERE</a>, <a href=\"#\" data-chapter=\"c215\">GROUP BY/HAVING</a>, <a href=\"#\" data-chapter=\"c216\">ORDER BY</a>, <a href=\"#\" data-chapter=\"c213\">함수</a>, <a href=\"#\" data-chapter=\"c217\">조인</a> 챕터에서 다룬다.</p>\n\n  <!-- 작성 순서 vs 실행 순서 -->\n  <h3 class=\"reveal\">작성 순서 vs 실행 순서</h3>\n  <div class=\"mermaid reveal\">\nflowchart LR\n    subgraph WRITE[\"작성 순서 (사람이 쓰는 순서)\"]\n      direction LR\n      W1[SELECT] --> W2[FROM] --> W3[WHERE] --> W4[GROUP BY] --> W5[HAVING] --> W6[ORDER BY]\n    end\n    subgraph RUN[\"실행 순서 (DB가 처리하는 순서) — FWGHSO\"]\n      direction LR\n      R1[FROM] --> R2[WHERE] --> R3[GROUP BY] --> R4[HAVING] --> R5[SELECT] --> R6[ORDER BY]\n    end\n    WRITE -.->|순서가 다름| RUN\n  </div>\n\n  <table class=\"reveal\">\n    <thead><tr><th>작성 순서</th><th>실행 순서</th></tr></thead>\n    <tbody>\n      <tr><td>1. SELECT</td><td>5. SELECT</td></tr>\n      <tr><td>2. FROM</td><td>1. FROM</td></tr>\n      <tr><td>3. WHERE</td><td>2. WHERE</td></tr>\n      <tr><td>4. GROUP BY</td><td>3. GROUP BY</td></tr>\n      <tr><td>5. HAVING</td><td>4. HAVING</td></tr>\n      <tr><td>6. ORDER BY</td><td>6. ORDER BY</td></tr>\n    </tbody>\n  </table>\n\n  <div class=\"mnemonic reveal\">\n    <div class=\"label-side\">암기 키<small>실행 순서</small></div>\n    <div class=\"glyphs\">\n      <div class=\"glyph-chip\">F</div>\n      <div class=\"glyph-chip\">W</div>\n      <div class=\"glyph-chip\">G</div>\n      <div class=\"glyph-chip\">H</div>\n      <div class=\"glyph-chip\">S</div>\n      <div class=\"glyph-chip\">O</div>\n    </div>\n  </div>\n  <p class=\"reveal\">암기: <strong>FROM → WHERE → GROUP → HAVING → SELECT → ORDER (FWGHSO)</strong></p>\n\n  <!-- SELECT 절의 다양한 표현 -->\n  <h2 class=\"reveal\">SELECT 절의 다양한 표현</h2>\n  <table class=\"reveal\">\n    <thead><tr><th>형태</th><th>의미</th></tr></thead>\n    <tbody>\n      <tr><td><code>SELECT *</code></td><td>모든 컬럼</td></tr>\n      <tr><td><code>SELECT col1, col2</code></td><td>특정 컬럼</td></tr>\n      <tr><td><code>SELECT DISTINCT col</code></td><td>중복 제거</td></tr>\n      <tr><td><code>SELECT col AS 별명</code></td><td>별칭 부여</td></tr>\n      <tr><td><code>SELECT col || '문자'</code></td><td>문자열 연결(Oracle)</td></tr>\n      <tr><td><code>SELECT 1+1 FROM DUAL</code></td><td>계산식</td></tr>\n    </tbody>\n  </table>\n\n  <!-- SQL 실전 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">SELECT 패턴들</span>\n  </h2>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">EMP</span>\n    <h4 class=\"ba-h\">사원 테이블</h4>\n    <div class=\"mini-table cols-4\">\n      <div class=\"h\">EMP_ID</div><div class=\"h\">NAME</div><div class=\"h\">DEPT_ID</div><div class=\"h\">SAL</div>\n      <div class=\"c\">1</div><div class=\"c\">김철수</div><div class=\"c\">D1</div><div class=\"c\">3000</div>\n      <div class=\"c\">2</div><div class=\"c\">이영희</div><div class=\"c\">D2</div><div class=\"c\">4000</div>\n      <div class=\"c\">3</div><div class=\"c\">박민수</div><div class=\"c\">D2</div><div class=\"c\">3500</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 1. 모든 컬럼</span>\n<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span>;\n\n<span class=\"sql-cm\">-- 2. 특정 컬럼</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">EMP_ID</span>, <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span>;\n\n<span class=\"sql-cm\">-- 3. 별칭(AS 생략 가능, 한글 별칭은 \"\")</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span> <span class=\"sql-kw\">AS</span> 사원명, <span class=\"sql-type\">SAL</span>*<span class=\"sql-num\">12</span> <span class=\"sql-str\">\"연봉\"</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span>;\n\n<span class=\"sql-cm\">-- 4. 중복 제거</span>\n<span class=\"sql-kw\">SELECT DISTINCT</span> <span class=\"sql-type\">DEPT_ID</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span>;\n\n<span class=\"sql-cm\">-- 5. 문자열 연결</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span> || <span class=\"sql-str\">'님'</span> <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">GREETING</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (5. 문자열 연결 — <code>NAME || '님'</code>)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>GREETING</th></tr></thead>\n    <tbody>\n      <tr><td>김철수님</td></tr>\n      <tr><td>이영희님</td></tr>\n      <tr><td>박민수님</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ <code>||</code>(Oracle 연결 연산자)로 컬럼값 뒤에 문자열을 이어 붙인다.</p>\n\n  <!-- Before & After -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">같은 데이터, 다른 SELECT</span>\n  </h2>\n  <p class=\"reveal\">EMP 테이블 4명 중 동명이인 김철수가 D1·D2 부서에 한 명씩 있는 상황. 같은 데이터에 SELECT 컬럼 지정·DISTINCT·연봉 계산 별칭을 각각 적용했을 때 결과가 어떻게 달라지는지 비교한다.</p>\n\n  <h3 class=\"reveal\">EMP</h3>\n  <table class=\"reveal\">\n    <thead><tr><th>EMP_ID</th><th>NAME</th><th>DEPT_ID</th><th>SAL</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td>김철수</td><td>D1</td><td>3000</td></tr>\n      <tr><td>2</td><td>이영희</td><td>D1</td><td>4000</td></tr>\n      <tr><td>3</td><td>박민수</td><td>D2</td><td>3500</td></tr>\n      <tr><td>4</td><td>김철수</td><td>D2</td><td>3200</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\"><code>SELECT NAME, SAL FROM EMP;</code></h3>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>SAL</th></tr></thead>\n    <tbody>\n      <tr><td>김철수</td><td>3000</td></tr>\n      <tr><td>이영희</td><td>4000</td></tr>\n      <tr><td>박민수</td><td>3500</td></tr>\n      <tr><td>김철수</td><td>3200</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\"><code>SELECT DISTINCT NAME FROM EMP;</code></h3>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th></tr></thead>\n    <tbody>\n      <tr><td>김철수</td></tr>\n      <tr><td>이영희</td></tr>\n      <tr><td>박민수</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\"><code>SELECT NAME, SAL*12 AS \"연봉\" FROM EMP;</code></h3>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>연봉</th></tr></thead>\n    <tbody>\n      <tr><td>김철수</td><td>36000</td></tr>\n      <tr><td>이영희</td><td>48000</td></tr>\n      <tr><td>박민수</td><td>42000</td></tr>\n      <tr><td>김철수</td><td>38400</td></tr>\n    </tbody>\n  </table>\n\n  <div class=\"ba-flow large-after reveal\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">BEFORE · 원본 4행</span>\n      <h4 class=\"ba-h\">EMP</h4>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">NAME</div><div class=\"h\">DEPT</div><div class=\"h\">SAL</div>\n        <div class=\"c\">김철수</div><div class=\"c\">D1</div><div class=\"c\">3000</div>\n        <div class=\"c\">이영희</div><div class=\"c\">D1</div><div class=\"c\">4000</div>\n        <div class=\"c\">박민수</div><div class=\"c\">D2</div><div class=\"c\">3500</div>\n        <div class=\"c\">김철수</div><div class=\"c\">D2</div><div class=\"c\">3200</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\">→</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">AFTER · 3가지 SELECT</span>\n      <h4 class=\"ba-h\">컬럼/DISTINCT/별칭에 따라 결과가 달라진다</h4>\n      <div class=\"ba-tables cols-3\">\n        <div class=\"ba-mini-table\">\n          <div class=\"h\">NAME, SAL</div>\n          <div class=\"row\">김철수 3000</div>\n          <div class=\"row\">이영희 4000</div>\n          <div class=\"row\">박민수 3500</div>\n          <div class=\"row\">김철수 3200</div>\n        </div>\n        <div class=\"ba-mini-table\">\n          <div class=\"h\">DISTINCT NAME</div>\n          <div class=\"row\">김철수</div>\n          <div class=\"row\">이영희</div>\n          <div class=\"row\">박민수</div>\n        </div>\n        <div class=\"ba-mini-table\">\n          <div class=\"h\">SAL*12 AS 연봉</div>\n          <div class=\"row\">김철수 36000</div>\n          <div class=\"row\">이영희 48000</div>\n          <div class=\"row\">박민수 42000</div>\n          <div class=\"row\">김철수 38400</div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <p class=\"reveal\"><code>DISTINCT</code>는 SELECT 절 전체(여러 컬럼이면 컬럼 조합) 단위로 중복을 제거하므로, NAME만 골라보면 동명이인 김철수도 한 줄로 합쳐진다. 반면 <code>SAL*12</code> 같은 표현은 행 단위로 매번 계산되므로 같은 이름이라도 별개 행으로 남는다. \"원본 데이터를 그대로 보고 싶다\"면 컬럼 나열, \"값 종류만 보고 싶다\"면 DISTINCT, \"가공된 값을 의미있는 이름으로 보고 싶다\"면 별칭을 선택하면 된다.</p>\n\n  <!-- 별칭 규칙 -->\n  <h2 class=\"reveal\">별칭(Alias) 규칙</h2>\n  <table class=\"reveal\">\n    <thead><tr><th>규칙</th><th>예</th></tr></thead>\n    <tbody>\n      <tr><td>AS 생략 가능</td><td><code>SELECT NAME 사원명</code></td></tr>\n      <tr><td>공백/한글/특수문자 포함 시 <code>\"\"</code> 사용</td><td><code>\"사원 이름\"</code></td></tr>\n      <tr><td>테이블 별칭은 AS 사용 불가(Oracle)</td><td><code>FROM EMP E</code></td></tr>\n      <tr><td>WHERE/GROUP/HAVING에서 SELECT의 별칭 사용</td><td>불가(실행 순서 때문)</td></tr>\n      <tr><td>ORDER BY에서 별칭 사용</td><td>가능</td></tr>\n    </tbody>\n  </table>\n\n  <!-- DUAL 테이블 -->\n  <h2 class=\"reveal\">DUAL 테이블 (Oracle)</h2>\n  <p class=\"reveal\">시스템 내장 가짜 테이블이다. 한 행, 한 컬럼만 있고, 계산이나 함수 결과를 확인할 때 쓴다.</p>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span> <span class=\"sql-num\">1</span>+<span class=\"sql-num\">1</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">DUAL</span>;        <span class=\"sql-cm\">-- 2</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-kw\">SYSDATE</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">DUAL</span>;    <span class=\"sql-cm\">-- 현재 시각</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-kw\">USER</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">DUAL</span>;       <span class=\"sql-cm\">-- 접속 계정</span></code></pre>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-2-1-2\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c213: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    함수는 데이터를 입력받아 <strong>가공된 결과</strong>를 돌려주는 도구다. 문자, 숫자, 날짜, <a href=\"#\" data-chapter=\"c124\">NULL</a>을 가공할 수 있다.\n  </blockquote>\n\n  <!-- 개념 도식화 — 함수 카테고리 -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">함수의 분류 — 단일행(1행→1결과) / 다중행(N행→1결과)</span>\n  </h2>\n  <div class=\"fn-grid cols-3 reveal\">\n    <div class=\"fn-card\">\n      <div class=\"name\">문자</div>\n      <div class=\"desc\">대소문자 변환·자르기·붙이기·찾기·치환</div>\n      <div class=\"ex\">UPPER · SUBSTR · INSTR · LENGTH</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">숫자</div>\n      <div class=\"desc\">반올림·버림·나머지·부호·거듭제곱</div>\n      <div class=\"ex\">ROUND · TRUNC · MOD · ABS</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">날짜</div>\n      <div class=\"desc\">현재시각·개월 가감·요일 추출·자르기</div>\n      <div class=\"ex\">SYSDATE · ADD_MONTHS · MONTHS_BETWEEN</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">변환</div>\n      <div class=\"desc\">문자·숫자·날짜 사이의 명시적 형변환</div>\n      <div class=\"ex\">TO_CHAR · TO_NUMBER · TO_DATE</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">일반 / NULL</div>\n      <div class=\"desc\">NULL 대체·조건 분기</div>\n      <div class=\"ex\">NVL · NVL2 · COALESCE · CASE · DECODE</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">집계 (다중행)</div>\n      <div class=\"desc\">여러 행 → 하나의 요약값</div>\n      <div class=\"ex\">SUM · AVG · COUNT · MAX · MIN</div>\n    </div>\n  </div>\n\n  <!-- 문자 함수 -->\n  <h2 class=\"reveal\">문자 함수</h2>\n  <table class=\"reveal\">\n    <thead><tr><th>함수</th><th>설명</th><th>예</th><th>결과</th></tr></thead>\n    <tbody>\n      <tr><td>UPPER(s)</td><td>대문자</td><td>UPPER('abc')</td><td>ABC</td></tr>\n      <tr><td>LOWER(s)</td><td>소문자</td><td>LOWER('ABC')</td><td>abc</td></tr>\n      <tr><td>INITCAP(s)</td><td>첫글자만 대문자</td><td>INITCAP('hi sql')</td><td>Hi Sql</td></tr>\n      <tr><td>LENGTH(s)</td><td>문자열 길이</td><td>LENGTH('한글')</td><td>2</td></tr>\n      <tr><td>SUBSTR(s, m, n)</td><td>n글자 추출</td><td>SUBSTR('ABCDE', 2, 3)</td><td>BCD</td></tr>\n      <tr><td>INSTR(s, sub)</td><td>위치 찾기</td><td>INSTR('ABCDE', 'C')</td><td>3</td></tr>\n      <tr><td>LPAD/RPAD</td><td>자리 채우기</td><td>LPAD('1', 3, '0')</td><td>001</td></tr>\n      <tr><td>LTRIM/RTRIM/TRIM</td><td>공백 제거</td><td>TRIM(' ABC ')</td><td>ABC</td></tr>\n      <tr><td>REPLACE(s, a, b)</td><td>문자열 교체</td><td>REPLACE('A-B', '-', '+')</td><td>A+B</td></tr>\n      <tr><td>CONCAT(a,b) 또는 <code>||</code></td><td>문자열 연결</td><td>'A' || 'B'</td><td>AB</td></tr>\n    </tbody>\n  </table>\n\n  <!-- 숫자 함수 -->\n  <h2 class=\"reveal\">숫자 함수</h2>\n  <table class=\"reveal\">\n    <thead><tr><th>함수</th><th>설명</th><th>예</th><th>결과</th></tr></thead>\n    <tbody>\n      <tr><td>ABS(n)</td><td>절댓값</td><td>ABS(-5)</td><td>5</td></tr>\n      <tr><td>ROUND(n, m)</td><td>반올림</td><td>ROUND(3.456, 1)</td><td>3.5</td></tr>\n      <tr><td>TRUNC(n, m)</td><td>버림</td><td>TRUNC(3.456, 1)</td><td>3.4</td></tr>\n      <tr><td>MOD(a, b)</td><td>나머지</td><td>MOD(10, 3)</td><td>1</td></tr>\n      <tr><td>CEIL(n)</td><td>올림</td><td>CEIL(3.1)</td><td>4</td></tr>\n      <tr><td>FLOOR(n)</td><td>내림</td><td>FLOOR(3.9)</td><td>3</td></tr>\n      <tr><td>POWER(a, b)</td><td>거듭제곱</td><td>POWER(2, 3)</td><td>8</td></tr>\n      <tr><td>SIGN(n)</td><td>부호(-1/0/1)</td><td>SIGN(-5)</td><td>-1</td></tr>\n    </tbody>\n  </table>\n\n  <!-- 날짜 함수 -->\n  <h2 class=\"reveal\">날짜 함수</h2>\n  <table class=\"reveal\">\n    <thead><tr><th>함수</th><th>설명</th></tr></thead>\n    <tbody>\n      <tr><td>SYSDATE</td><td>현재 날짜+시간</td></tr>\n      <tr><td>CURRENT_DATE</td><td>세션 기준 현재</td></tr>\n      <tr><td>ADD_MONTHS(d, n)</td><td>개월 더하기</td></tr>\n      <tr><td>MONTHS_BETWEEN(d1, d2)</td><td>개월 차이</td></tr>\n      <tr><td>LAST_DAY(d)</td><td>그 달의 마지막 날</td></tr>\n      <tr><td>NEXT_DAY(d, '월')</td><td>다음 월요일</td></tr>\n      <tr><td>EXTRACT(YEAR FROM d)</td><td>연도 추출</td></tr>\n      <tr><td>TRUNC(d, 'MM')</td><td>월 단위 자름</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\"><strong>날짜 - 날짜 = 일수(숫자)</strong>, <strong>날짜 + 숫자 = 날짜</strong>.</p>\n\n  <!-- 변환 함수 -->\n  <h2 class=\"reveal\">변환 함수</h2>\n  <table class=\"reveal\">\n    <thead><tr><th>함수</th><th>변환</th><th>예</th></tr></thead>\n    <tbody>\n      <tr><td>TO_CHAR(d, 'YYYY-MM-DD')</td><td>날짜 → 문자</td><td>2026-04-26</td></tr>\n      <tr><td>TO_CHAR(n, '999,999')</td><td>숫자 → 문자</td><td>1,000</td></tr>\n      <tr><td>TO_NUMBER('1234')</td><td>문자 → 숫자</td><td>1234</td></tr>\n      <tr><td>TO_DATE('20260426', 'YYYYMMDD')</td><td>문자 → 날짜</td><td>2026-04-26</td></tr>\n    </tbody>\n  </table>\n  <table class=\"reveal\">\n    <thead><tr><th>종류</th><th>의미</th></tr></thead>\n    <tbody>\n      <tr><td>명시적 형변환</td><td>TO_CHAR, TO_NUMBER, TO_DATE 직접 호출</td></tr>\n      <tr><td>암시적 형변환</td><td>DBMS가 자동 변환(의도치 않은 결과 위험)</td></tr>\n    </tbody>\n  </table>\n\n  <!-- NULL 관련 함수 -->\n  <h2 class=\"reveal\">NULL 관련 함수</h2>\n  <div class=\"fn-grid cols-4 reveal\">\n    <div class=\"fn-card\">\n      <div class=\"name\">NVL(A, B)</div>\n      <div class=\"desc\">A가 NULL이면 <strong>B</strong>로 대체</div>\n      <div class=\"ex\">NVL(SAL, 0)</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">NVL2(A, B, C)</div>\n      <div class=\"desc\">A가 NULL <strong>아니면 B</strong>, NULL이면 <strong>C</strong></div>\n      <div class=\"ex\">NVL2(COMM, '있음', '없음')</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">NULLIF(A, B)</div>\n      <div class=\"desc\">A=B면 <strong>NULL</strong>, 아니면 A</div>\n      <div class=\"ex\">NULLIF(A, 0)</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">COALESCE(A, B, …)</div>\n      <div class=\"desc\">NULL이 <strong>아닌 첫 값</strong> 반환</div>\n      <div class=\"ex\">COALESCE(P1, P2, '없음')</div>\n    </div>\n  </div>\n\n  <!-- 함수별 SQL + 결과 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">함수별 미니 예시</span>\n  </h2>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — NVL 예시에 사용할 EMP 테이블</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">EMP</span>\n    <h4 class=\"ba-h\">사원 테이블</h4>\n    <div class=\"mini-table cols-2\">\n      <div class=\"h\">NAME</div><div class=\"h\">COMM</div>\n      <div class=\"c\">A</div><div class=\"c\">10</div>\n      <div class=\"c\">B</div><div class=\"c is-null\">NULL</div>\n      <div class=\"c\">C</div><div class=\"c\">20</div>\n    </div>\n  </div>\n  <h3 class=\"reveal\">UPPER — 대문자 변환 (문자)</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span> <span class=\"sql-kw\">UPPER</span>(<span class=\"sql-str\">'sqld'</span>) <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">RESULT</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">DUAL</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과</p>\n  <table class=\"reveal\">\n    <thead><tr><th>RESULT</th></tr></thead>\n    <tbody><tr><td>SQLD</td></tr></tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 입력 문자열의 모든 알파벳이 대문자로 변환된다.</p>\n\n  <h3 class=\"reveal\">ROUND — 반올림 (숫자)</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span> <span class=\"sql-kw\">ROUND</span>(<span class=\"sql-num\">3.456</span>, <span class=\"sql-num\">1</span>) <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">RESULT</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">DUAL</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과</p>\n  <table class=\"reveal\">\n    <thead><tr><th>RESULT</th></tr></thead>\n    <tbody><tr><td>3.5</td></tr></tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 두 번째 인자 <code>1</code>은 소수 1자리까지 남기겠다는 뜻. 3.456 → 3.5.</p>\n\n  <h3 class=\"reveal\">TO_CHAR — 날짜→문자 변환</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span> <span class=\"sql-kw\">TO_CHAR</span>(<span class=\"sql-kw\">SYSDATE</span>, <span class=\"sql-str\">'YYYY-MM-DD'</span>) <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">TODAY</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">DUAL</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과</p>\n  <table class=\"reveal\">\n    <thead><tr><th>TODAY</th></tr></thead>\n    <tbody><tr><td>2026-04-27</td></tr></tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 날짜 타입을 <code>'YYYY-MM-DD'</code> 포맷에 맞춰 문자열로 변환한다.</p>\n\n  <h3 class=\"reveal\">NVL — NULL 대체</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span>, <span class=\"sql-kw\">NVL</span>(<span class=\"sql-type\">COMM</span>, <span class=\"sql-num\">0</span>) <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">COMM_FIX</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (B는 COMM이 NULL)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>COMM_FIX</th></tr></thead>\n    <tbody>\n      <tr><td>A</td><td>10</td></tr>\n      <tr><td>B</td><td>0</td></tr>\n      <tr><td>C</td><td>20</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ B의 COMM이 NULL이어서 <code>NVL(COMM, 0)</code>이 0으로 대체했다.</p>\n\n  <!-- SQL 실전 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">조건 함수 — CASE / DECODE</span>\n  </h2>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- DECODE (Oracle 전용, 동등비교만 가능)</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span>,\n       <span class=\"sql-kw\">DECODE</span>(<span class=\"sql-type\">GENDER</span>, <span class=\"sql-str\">'M'</span>, <span class=\"sql-str\">'남자'</span>, <span class=\"sql-str\">'F'</span>, <span class=\"sql-str\">'여자'</span>, <span class=\"sql-str\">'기타'</span>) <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">GENDER_KOR</span>\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">MEMBER</span>;\n\n<span class=\"sql-cm\">-- CASE (표준, 모든 비교 가능)</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span>,\n       <span class=\"sql-kw\">CASE WHEN</span> <span class=\"sql-type\">SAL</span> &gt;= <span class=\"sql-num\">5000</span> <span class=\"sql-kw\">THEN</span> <span class=\"sql-str\">'고급'</span>\n            <span class=\"sql-kw\">WHEN</span> <span class=\"sql-type\">SAL</span> &gt;= <span class=\"sql-num\">3000</span> <span class=\"sql-kw\">THEN</span> <span class=\"sql-str\">'중급'</span>\n            <span class=\"sql-kw\">ELSE</span> <span class=\"sql-str\">'초급'</span>\n       <span class=\"sql-kw\">END</span> <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">GRADE</span>\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span>;</code></pre>\n\n  <table class=\"reveal\">\n    <thead><tr><th>함수</th><th>동등비교</th><th>범위비교</th></tr></thead>\n    <tbody>\n      <tr><td>DECODE</td><td>가능</td><td>불가</td></tr>\n      <tr><td>CASE</td><td>가능</td><td>가능</td></tr>\n    </tbody>\n  </table>\n\n  <!-- 다중행 집계 -->\n  <h2 class=\"reveal\">다중행(집계) 함수</h2>\n  <p class=\"reveal\">여러 행을 묶어 하나의 결과로 요약한다. 자세한 분석은 <a href=\"#\" data-chapter=\"c223\">그룹함수</a> 챕터 참고. 보통 <a href=\"#\" data-chapter=\"c214\">WHERE</a> 이후의 GROUP BY와 함께 쓰인다.</p>\n  <table class=\"reveal\">\n    <thead><tr><th>함수</th><th>의미</th><th>NULL 처리</th></tr></thead>\n    <tbody>\n      <tr><td>COUNT(*)</td><td>모든 행 수</td><td>NULL 포함</td></tr>\n      <tr><td>COUNT(col)</td><td>컬럼 NULL 제외</td><td>NULL 제외</td></tr>\n      <tr><td>SUM(col)</td><td>합</td><td>NULL 무시</td></tr>\n      <tr><td>AVG(col)</td><td>평균</td><td>NULL 무시</td></tr>\n      <tr><td>MAX(col)</td><td>최대</td><td>NULL 무시</td></tr>\n      <tr><td>MIN(col)</td><td>최소</td><td>NULL 무시</td></tr>\n    </tbody>\n  </table>\n\n  <!-- Before & After -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">함수 활용</span>\n  </h2>\n  <p class=\"reveal\">EMP의 NAME(소문자), HIRE_DATE(날짜형), SAL+COMM(NULL 가능)을 한 번에 가공해야 하는 상황. 김철수는 COMM이 NULL이고 이영희는 200인데, 문자·날짜·NULL 함수를 결합해 \"대문자 이름 / 입사연도 / 총급여\"를 동시에 뽑는다.</p>\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3);\">EMP 테이블</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>HIRE_DATE</th><th>SAL</th><th>COMM</th></tr></thead>\n    <tbody>\n      <tr><td>김철수</td><td>2020-03-15</td><td>3000</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td></tr>\n      <tr><td>이영희</td><td>2022-08-20</td><td>4000</td><td>200</td></tr>\n    </tbody>\n  </table>\n  <div class=\"ba-flow large-after reveal\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">BEFORE</span>\n      <h4 class=\"ba-h\">함수 미사용</h4>\n      <div class=\"sql\">SELECT NAME, HIRE_DATE, SAL+COMM FROM EMP;</div>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">NAME</div><div class=\"h\">HIRE_DATE</div><div class=\"h\">SAL+COMM</div>\n        <div class=\"c\">김철수</div><div class=\"c\">2020-03-15</div><div class=\"c is-null\">NULL</div>\n        <div class=\"c\">이영희</div><div class=\"c\">2022-08-20</div><div class=\"c\">4200</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\">→</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">AFTER</span>\n      <h4 class=\"ba-h\">함수로 정돈된 결과</h4>\n      <div class=\"sql\">SELECT UPPER(NAME), TO_CHAR(HIRE_DATE,'YYYY'), SAL+NVL(COMM,0) FROM EMP;</div>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">UPPER_NAME</div><div class=\"h\">HIRE_YEAR</div><div class=\"h\">TOTAL</div>\n        <div class=\"c\">김철수</div><div class=\"c\">2020</div><div class=\"c\">3000</div>\n        <div class=\"c\">이영희</div><div class=\"c\">2022</div><div class=\"c\">4200</div>\n      </div>\n    </div>\n  </div>\n  <p class=\"reveal\">UPPER는 문자형, TO_CHAR(HIRE_DATE,'YYYY')는 날짜→문자, NVL(COMM,0)은 NULL 안전 산술처럼 함수마다 다루는 도메인이 다르다. NVL을 빼면 김철수의 TOTAL이 NULL로 사라지는 사고가 그대로 발생하므로, 출력 형식·표시 단위·NULL 처리를 모두 함수 단계에서 정리하고 SELECT 결과는 화면에 바로 쓸 수 있는 형태로 만드는 것이 안전하다.</p>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-2-1-3\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c214: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    WHERE 절은 <strong>어떤 행만 가져올지</strong> 조건을 거는 필터다. 테이블 전체에서 원하는 행만 골라낸다.\n  </blockquote>\n  <div class=\"ex-box reveal\">\n    옷가게에서 \"검은색(<code>= '검정'</code>)·5만원 이하(<code>&lt;= 50000</code>)·M 또는 L 사이즈(<code>IN ('M','L')</code>)\"라고 조건을 거는 것과 같다.\n  </div>\n\n  <!-- 연산자 그리드 -->\n  <h2 class=\"reveal\">WHERE 절의 연산자</h2>\n  <div class=\"trait-grid cols-3 reveal\">\n    <div class=\"trait-card\">\n      <div class=\"glyph\">=</div>\n      <div class=\"label\">비교 연산자</div>\n      <div class=\"desc\"><code>=</code> · <code>!=</code>·<code>&lt;&gt;</code>·<code>^=</code> · <code>&gt;</code>·<code>&gt;=</code>·<code>&lt;</code>·<code>&lt;=</code></div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"glyph\">∧</div>\n      <div class=\"label\">논리 연산자</div>\n      <div class=\"desc\"><strong>AND</strong> 둘 다 / <strong>OR</strong> 둘 중 하나 / <strong>NOT</strong> 부정</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"glyph\">⌖</div>\n      <div class=\"label\">SQL 연산자</div>\n      <div class=\"desc\"><code>BETWEEN</code> · <code>IN</code> · <code>LIKE</code> · <code>IS NULL</code></div>\n    </div>\n  </div>\n\n  <h3 class=\"reveal\">비교 연산자</h3>\n  <table class=\"reveal\">\n    <thead><tr><th>연산자</th><th>의미</th></tr></thead>\n    <tbody>\n      <tr><td><code>=</code></td><td>같다</td></tr>\n      <tr><td><code>!=</code>, <code>&lt;&gt;</code>, <code>^=</code></td><td>다르다</td></tr>\n      <tr><td><code>&gt;</code>, <code>&gt;=</code>, <code>&lt;</code>, <code>&lt;=</code></td><td>크다/작다</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">논리 연산자</h3>\n  <table class=\"reveal\">\n    <thead><tr><th>연산자</th><th>의미</th><th>비유</th></tr></thead>\n    <tbody>\n      <tr><td>AND</td><td>둘 다</td><td>검정색 그리고 5만원 이하</td></tr>\n      <tr><td>OR</td><td>둘 중 하나</td><td>검정색 또는 흰색</td></tr>\n      <tr><td>NOT</td><td>부정</td><td>검정색이 아닌</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">SQL 연산자 4종</h3>\n  <div class=\"trait-grid cols-4 reveal\">\n    <div class=\"trait-card\">\n      <div class=\"glyph\">↔</div>\n      <div class=\"label\">BETWEEN A AND B</div>\n      <div class=\"desc\">A ≤ x ≤ B (양 끝 <strong>포함</strong>)</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"glyph\">∈</div>\n      <div class=\"label\">IN (a, b, c)</div>\n      <div class=\"desc\">값 목록 또는 <a href=\"#\" data-chapter=\"c221\">서브쿼리</a> 가능 (OR 단축형)</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"glyph\">~</div>\n      <div class=\"label\">LIKE '패턴'</div>\n      <div class=\"desc\"><code>%</code> 0개 이상 / <code>_</code> 정확히 1개</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"glyph\">∅</div>\n      <div class=\"label\">IS NULL</div>\n      <div class=\"desc\">NULL 비교 전용. <code>= NULL</code> 안 됨</div>\n    </div>\n  </div>\n  <p class=\"reveal\"><strong>부정형</strong>: NOT BETWEEN, NOT IN, NOT LIKE, IS NOT NULL.</p>\n\n  <!-- 벤 다이어그램 — AND/OR/NOT -->\n  <h2 class=\"reveal\">AND · OR · NOT 의 집합 의미</h2>\n  <p class=\"reveal\">두 조건 A, B를 두 원으로 그렸을 때 각 논리 연산자가 가리키는 영역.</p>\n  <div class=\"venn-row cols-3 reveal\">\n    <div class=\"venn-card\">\n      <svg viewBox=\"0 0 220 140\" xmlns=\"http://www.w3.org/2000/svg\">\n        <defs>\n          <clipPath id=\"ca-and\"><circle cx=\"80\" cy=\"70\" r=\"45\"/></clipPath>\n        </defs>\n        <circle class=\"v-a\" cx=\"80\" cy=\"70\" r=\"45\"/>\n        <circle class=\"v-b\" cx=\"140\" cy=\"70\" r=\"45\"/>\n        <circle class=\"v-hl\" cx=\"140\" cy=\"70\" r=\"45\" clip-path=\"url(#ca-and)\"/>\n        <text class=\"v-label\" x=\"55\" y=\"35\">A</text>\n        <text class=\"v-label\" x=\"165\" y=\"35\">B</text>\n      </svg>\n      <div class=\"name\">A AND B</div>\n      <div class=\"desc\">교집합 — A와 B <strong>둘 다 참</strong></div>\n    </div>\n    <div class=\"venn-card\">\n      <svg viewBox=\"0 0 220 140\" xmlns=\"http://www.w3.org/2000/svg\">\n        <circle class=\"v-hl\" cx=\"80\" cy=\"70\" r=\"45\"/>\n        <circle class=\"v-hl\" cx=\"140\" cy=\"70\" r=\"45\"/>\n        <text class=\"v-label\" x=\"55\" y=\"35\">A</text>\n        <text class=\"v-label\" x=\"165\" y=\"35\">B</text>\n      </svg>\n      <div class=\"name\">A OR B</div>\n      <div class=\"desc\">합집합 — <strong>둘 중 하나</strong> 이상 참</div>\n    </div>\n    <div class=\"venn-card\">\n      <svg viewBox=\"0 0 220 140\" xmlns=\"http://www.w3.org/2000/svg\">\n        <defs>\n          <mask id=\"m-not\">\n            <rect x=\"0\" y=\"0\" width=\"220\" height=\"140\" fill=\"white\"/>\n            <circle cx=\"100\" cy=\"70\" r=\"45\" fill=\"black\"/>\n          </mask>\n        </defs>\n        <rect x=\"10\" y=\"15\" width=\"200\" height=\"110\" class=\"v-hl\" mask=\"url(#m-not)\"/>\n        <circle class=\"v-a\" cx=\"100\" cy=\"70\" r=\"45\"/>\n        <text class=\"v-label\" x=\"100\" y=\"78\">A</text>\n      </svg>\n      <div class=\"name\">NOT A</div>\n      <div class=\"desc\">여집합 — A가 <strong>아닌</strong> 영역</div>\n    </div>\n  </div>\n\n  <!-- LIKE 와일드카드 -->\n  <h2 class=\"reveal\">LIKE 연산자의 와일드카드</h2>\n  <table class=\"reveal\">\n    <thead><tr><th>기호</th><th>의미</th><th>예</th></tr></thead>\n    <tbody>\n      <tr><td><code>%</code></td><td>0개 이상의 문자</td><td><code>'김%'</code> → '김', '김철수', '김OO'</td></tr>\n      <tr><td><code>_</code></td><td>정확히 1개 문자</td><td><code>'김_수'</code> → '김철수', '김영수'</td></tr>\n    </tbody>\n  </table>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 김으로 시작</span>\n<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">NAME</span> <span class=\"sql-kw\">LIKE</span> <span class=\"sql-str\">'김%'</span>;\n\n<span class=\"sql-cm\">-- 정확히 3글자, 가운데가 '철'</span>\n<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">NAME</span> <span class=\"sql-kw\">LIKE</span> <span class=\"sql-str\">'_철_'</span>;\n\n<span class=\"sql-cm\">-- 와일드카드 자체를 검색하려면 ESCAPE</span>\n<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">ITEM</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">NAME</span> <span class=\"sql-kw\">LIKE</span> <span class=\"sql-str\">'%50\\%%'</span> <span class=\"sql-kw\">ESCAPE</span> <span class=\"sql-str\">'\\'</span>;</code></pre>\n\n  <!-- NULL 비교 -->\n  <h2 class=\"reveal\">NULL 비교</h2>\n  <table class=\"reveal\">\n    <thead><tr><th>잘못된 표현</th><th>올바른 표현</th></tr></thead>\n    <tbody>\n      <tr><td><code>WHERE COL = NULL</code></td><td><code>WHERE COL IS NULL</code></td></tr>\n      <tr><td><code>WHERE COL != NULL</code></td><td><code>WHERE COL IS NOT NULL</code></td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\">NULL과의 비교는 항상 <strong>UNKNOWN</strong>이 되어 결과가 비어버린다. 자세한 배경은 <a href=\"#\" data-chapter=\"c124\">NULL 속성의 이해</a> 참고.</p>\n\n  <!-- 연산자 우선순위 -->\n  <h2 class=\"reveal\">연산자 우선순위</h2>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code>1. 산술 ( *, /, +, - )\n2. 연결 ( || )\n3. 비교 ( =, &lt;, &gt; 등)\n4. NOT\n5. AND\n6. OR</code></pre>\n  <p class=\"reveal\"><strong>AND가 OR보다 먼저</strong> 처리된다. <code>A OR B AND C</code> = <code>A OR (B AND C)</code>.</p>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 의도: 부서가 D1이거나 D2 이면서 급여 3000 이상</span>\n<span class=\"sql-cm\">-- 잘못된 예</span>\n<span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">DEPT</span> = <span class=\"sql-str\">'D1'</span> <span class=\"sql-kw\">OR</span> <span class=\"sql-type\">DEPT</span> = <span class=\"sql-str\">'D2'</span> <span class=\"sql-kw\">AND</span> <span class=\"sql-type\">SAL</span> &gt;= <span class=\"sql-num\">3000</span>\n<span class=\"sql-cm\">-- AND 먼저 해석되어 D1 또는 (D2 AND SAL&gt;=3000)이 됨</span>\n\n<span class=\"sql-cm\">-- 올바른 예</span>\n<span class=\"sql-kw\">WHERE</span> (<span class=\"sql-type\">DEPT</span> = <span class=\"sql-str\">'D1'</span> <span class=\"sql-kw\">OR</span> <span class=\"sql-type\">DEPT</span> = <span class=\"sql-str\">'D2'</span>) <span class=\"sql-kw\">AND</span> <span class=\"sql-type\">SAL</span> &gt;= <span class=\"sql-num\">3000</span></code></pre>\n\n  <!-- SQL 실전 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">연산자별 사용 예</span>\n  </h2>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 비교</span>\n<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">SAL</span> &gt;= <span class=\"sql-num\">3000</span>;\n\n<span class=\"sql-cm\">-- BETWEEN</span>\n<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">BETWEEN</span> <span class=\"sql-num\">3000</span> <span class=\"sql-kw\">AND</span> <span class=\"sql-num\">5000</span>;\n\n<span class=\"sql-cm\">-- IN</span>\n<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">DEPT_ID</span> <span class=\"sql-kw\">IN</span> (<span class=\"sql-str\">'D1'</span>, <span class=\"sql-str\">'D2'</span>, <span class=\"sql-str\">'D3'</span>);\n\n<span class=\"sql-cm\">-- LIKE</span>\n<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">NAME</span> <span class=\"sql-kw\">LIKE</span> <span class=\"sql-str\">'김%'</span>;\n\n<span class=\"sql-cm\">-- IS NULL</span>\n<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">COMM</span> <span class=\"sql-kw\">IS NULL</span>;\n\n<span class=\"sql-cm\">-- AND/OR</span>\n<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">DEPT_ID</span> = <span class=\"sql-str\">'D1'</span> <span class=\"sql-kw\">AND</span> <span class=\"sql-type\">SAL</span> &gt;= <span class=\"sql-num\">3000</span>;</code></pre>\n\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">EMP</span>\n    <h4 class=\"ba-h\">사원 테이블 (4명)</h4>\n    <div class=\"mini-table cols-5\">\n      <div class=\"h\">EMP_ID</div><div class=\"h\">NAME</div><div class=\"h\">DEPT_ID</div><div class=\"h\">SAL</div><div class=\"h\">COMM</div>\n      <div class=\"c\">1</div><div class=\"c\">김철수</div><div class=\"c\">D1</div><div class=\"c\">3000</div><div class=\"c is-null\">NULL</div>\n      <div class=\"c\">2</div><div class=\"c\">이영희</div><div class=\"c\">D1</div><div class=\"c\">4500</div><div class=\"c\">200</div>\n      <div class=\"c\">3</div><div class=\"c\">박민수</div><div class=\"c\">D2</div><div class=\"c\">2500</div><div class=\"c is-null\">NULL</div>\n      <div class=\"c\">4</div><div class=\"c\">김영수</div><div class=\"c\">D3</div><div class=\"c\">5000</div><div class=\"c\">500</div>\n    </div>\n  </div>\n\n  <h3 class=\"reveal\">BETWEEN — <code>SAL BETWEEN 3000 AND 5000</code></h3>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과</p>\n  <table class=\"reveal\">\n    <thead><tr><th>EMP_ID</th><th>NAME</th><th>SAL</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td>김철수</td><td>3000</td></tr>\n      <tr><td>2</td><td>이영희</td><td>4500</td></tr>\n      <tr><td>4</td><td>김영수</td><td>5000</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 양 끝 3000·5000을 모두 포함. 박민수(2500)만 빠진다.</p>\n\n  <h3 class=\"reveal\">IN — <code>DEPT_ID IN ('D1','D2')</code></h3>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과</p>\n  <table class=\"reveal\">\n    <thead><tr><th>EMP_ID</th><th>NAME</th><th>DEPT_ID</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td>김철수</td><td>D1</td></tr>\n      <tr><td>2</td><td>이영희</td><td>D1</td></tr>\n      <tr><td>3</td><td>박민수</td><td>D2</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ <code>DEPT_ID = 'D1' OR DEPT_ID = 'D2'</code>의 단축형. D3 부서인 김영수는 제외.</p>\n\n  <h3 class=\"reveal\">LIKE — <code>NAME LIKE '김%'</code></h3>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과</p>\n  <table class=\"reveal\">\n    <thead><tr><th>EMP_ID</th><th>NAME</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td>김철수</td></tr>\n      <tr><td>4</td><td>김영수</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ <code>%</code>는 0개 이상의 임의 문자. '김'으로 시작하는 모든 이름이 매칭된다.</p>\n\n  <h3 class=\"reveal\">IS NULL — <code>COMM IS NULL</code></h3>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과</p>\n  <table class=\"reveal\">\n    <thead><tr><th>EMP_ID</th><th>NAME</th><th>COMM</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td>김철수</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td></tr>\n      <tr><td>3</td><td>박민수</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ NULL은 <code>= NULL</code>로 잡히지 않으므로 반드시 <code>IS NULL</code>을 써야 한다.</p>\n\n  <!-- Before & After -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">조건 조합으로 결과 행 추리기</span>\n  </h2>\n  <p class=\"reveal\">EMP 4명에서 부서·급여·이름·커미션 조건을 조합해 행을 골라내는 상황. IN과 LIKE, IS NULL 같은 SQL 연산자를 어떻게 결합하느냐에 따라 결과 행이 달라지는지 비교한다.</p>\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3);\">EMP 테이블</p>\n  <table class=\"reveal\">\n    <thead><tr><th>EMP_ID</th><th>NAME</th><th>DEPT_ID</th><th>SAL</th><th>COMM</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td>김철수</td><td>D1</td><td>3000</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td></tr>\n      <tr><td>2</td><td>이영희</td><td>D1</td><td>4500</td><td>200</td></tr>\n      <tr><td>3</td><td>박민수</td><td>D2</td><td>2500</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td></tr>\n      <tr><td>4</td><td>김영수</td><td>D3</td><td>5000</td><td>500</td></tr>\n    </tbody>\n  </table>\n  <div class=\"ba-flow reveal\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">CASE A</span>\n      <h4 class=\"ba-h\">DEPT IN ('D1','D3') AND SAL ≥ 3000</h4>\n      <div class=\"sql\">WHERE DEPT_ID IN ('D1','D3') AND SAL &gt;= 3000</div>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">EMP_ID</div><div class=\"h\">NAME</div><div class=\"h\">SAL</div>\n        <div class=\"c\">1</div><div class=\"c\">김철수</div><div class=\"c\">3000</div>\n        <div class=\"c\">2</div><div class=\"c\">이영희</div><div class=\"c\">4500</div>\n        <div class=\"c\">4</div><div class=\"c\">김영수</div><div class=\"c\">5000</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\">⇌</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">CASE B</span>\n      <h4 class=\"ba-h\">NAME LIKE '김%' AND COMM IS NULL</h4>\n      <div class=\"sql\">WHERE NAME LIKE '김%' AND COMM IS NULL</div>\n      <div class=\"mini-table\">\n        <div class=\"h\">EMP_ID</div><div class=\"h\">NAME</div>\n        <div class=\"c\">1</div><div class=\"c\">김철수</div>\n      </div>\n    </div>\n  </div>\n  <p class=\"reveal\">WHERE는 행을 하나씩 검사해 조건이 TRUE인 행만 통과시키므로, 조건 표현이 곧 결과 집합이 된다. NULL 비교는 항상 UNKNOWN이 되어 <code>=</code>·<code>!=</code>로는 잡히지 않으니 IS NULL을 써야 하고, IN으로 부서 다중 선택과 비교 연산자를 AND로 묶는 식으로 조건을 세분화하면 된다. \"정확히 어떤 행이 필요한가\"를 먼저 말로 풀어쓴 뒤 그것을 그대로 연산자로 옮기면 실수가 줄어든다.</p>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-2-1-4\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c215: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    <strong>GROUP BY</strong>는 데이터를 그룹별로 묶는 절, <strong>HAVING</strong>은 묶인 그룹에 조건을 거는 절이다.\n  </blockquote>\n  <div class=\"ex-box reveal\">\n    영수증 50장을 \"분류별로 묶어 합계(<code>GROUP BY 분류</code>)\" → \"합계 10만원 넘는 분류만(<code>HAVING 합계 &gt; 10만</code>)\"으로 거르는 것과 같다.\n  </div>\n\n  <!-- 개념 도식화 — 실행 흐름 -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">WHERE vs HAVING의 위치</span>\n  </h2>\n  <div class=\"mermaid reveal\">\nflowchart LR\n    A[FROM<br/>테이블] --> B[WHERE<br/>행 필터]\n    B --> C[GROUP BY<br/>그룹화]\n    C --> D[HAVING<br/>그룹 필터]\n    D --> E[SELECT<br/>컬럼 추출]\n  </div>\n  <p class=\"reveal\">실행 순서: <strong>FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY</strong></p>\n\n  <!-- GROUP BY 핵심 규칙 -->\n  <h2 class=\"reveal\">GROUP BY의 핵심 규칙</h2>\n  <p class=\"reveal\">GROUP BY에 명시되지 않은 컬럼은 SELECT 절에 그대로 쓸 수 없다. 집계함수로만 사용 가능하다.</p>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 잘못된 쿼리</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-type\">NAME</span>, <span class=\"sql-kw\">AVG</span>(<span class=\"sql-type\">SAL</span>)   <span class=\"sql-cm\">-- NAME이 GROUP BY에 없음</span>\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">GROUP BY</span> <span class=\"sql-type\">DEPT_ID</span>;\n\n<span class=\"sql-cm\">-- 옳은 쿼리</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-kw\">AVG</span>(<span class=\"sql-type\">SAL</span>)\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">GROUP BY</span> <span class=\"sql-type\">DEPT_ID</span>;</code></pre>\n\n  <!-- 집계 함수 복습 -->\n  <h2 class=\"reveal\">집계 함수 복습</h2>\n  <p class=\"reveal\">GROUP BY와 함께 쓰이는 <a href=\"#\" data-chapter=\"c223\">그룹함수</a>의 기본형. 행 단위 분석이 필요하면 <a href=\"#\" data-chapter=\"c224\">윈도우함수</a>로 확장한다.</p>\n  <table class=\"reveal\">\n    <thead><tr><th>함수</th><th>설명</th></tr></thead>\n    <tbody>\n      <tr><td>COUNT(*)</td><td>행 수(NULL 포함)</td></tr>\n      <tr><td>COUNT(컬럼)</td><td>NULL 제외 행 수</td></tr>\n      <tr><td>SUM(컬럼)</td><td>합</td></tr>\n      <tr><td>AVG(컬럼)</td><td>평균</td></tr>\n      <tr><td>MAX/MIN(컬럼)</td><td>최대/최소</td></tr>\n    </tbody>\n  </table>\n\n  <!-- WHERE vs HAVING — 인포그래픽 -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">비교</span>\n    <span class=\"label-rest\">WHERE vs HAVING</span>\n  </h2>\n  <p class=\"reveal\"><a href=\"#\" data-chapter=\"c214\">WHERE 절</a>이 행 단위 필터라면, HAVING은 그룹 단위 필터다.</p>\n  <div class=\"threeway cols-2 reveal\">\n    <div class=\"threeway-card t-info\">\n      <div class=\"glyph\">WHERE</div>\n      <div class=\"name\">행 단위 필터</div>\n      <div class=\"desc\">적용 시점: <strong>그룹화 전</strong> · 집계함수 <strong>불가</strong><br>예) <code>WHERE SAL &gt; 3000</code></div>\n    </div>\n    <div class=\"threeway-card t-correct\">\n      <div class=\"glyph\">HAVING</div>\n      <div class=\"name\">그룹 단위 필터</div>\n      <div class=\"desc\">적용 시점: <strong>그룹화 후</strong> · 집계함수 <strong>가능</strong><br>예) <code>HAVING AVG(SAL) &gt; 3000</code></div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 잘못된 예: WHERE에 집계함수</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-kw\">AVG</span>(<span class=\"sql-type\">SAL</span>)\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">WHERE</span>  <span class=\"sql-kw\">AVG</span>(<span class=\"sql-type\">SAL</span>) &gt; <span class=\"sql-num\">3000</span>;     <span class=\"sql-cm\">-- 에러</span>\n\n<span class=\"sql-cm\">-- 옳은 예: HAVING에 집계함수</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-kw\">AVG</span>(<span class=\"sql-type\">SAL</span>)\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">GROUP BY</span> <span class=\"sql-type\">DEPT_ID</span>\n<span class=\"sql-kw\">HAVING</span> <span class=\"sql-kw\">AVG</span>(<span class=\"sql-type\">SAL</span>) &gt; <span class=\"sql-num\">3000</span>;</code></pre>\n\n  <!-- SQL 실전 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">집계와 필터의 결합</span>\n  </h2>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">EMP</span>\n    <h4 class=\"ba-h\">사원 테이블 (5명 / 3개 부서)</h4>\n    <div class=\"mini-table cols-3\">\n      <div class=\"h\">NAME</div><div class=\"h\">DEPT_ID</div><div class=\"h\">SAL</div>\n      <div class=\"c\">김</div><div class=\"c\">D1</div><div class=\"c\">3000</div>\n      <div class=\"c\">이</div><div class=\"c\">D1</div><div class=\"c\">4000</div>\n      <div class=\"c\">박</div><div class=\"c\">D2</div><div class=\"c\">2500</div>\n      <div class=\"c\">최</div><div class=\"c\">D2</div><div class=\"c\">3500</div>\n      <div class=\"c\">홍</div><div class=\"c\">D3</div><div class=\"c\">5000</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 부서별 인원수와 평균급여</span>\n<span class=\"sql-kw\">SELECT</span>  <span class=\"sql-type\">DEPT_ID</span>,\n        <span class=\"sql-kw\">COUNT</span>(*)    <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">CNT</span>,\n        <span class=\"sql-kw\">AVG</span>(<span class=\"sql-type\">SAL</span>)    <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">AVG_SAL</span>\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">GROUP BY</span> <span class=\"sql-type\">DEPT_ID</span>;\n\n<span class=\"sql-cm\">-- 부서별 평균급여가 3500 이상인 부서만</span>\n<span class=\"sql-kw\">SELECT</span>  <span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-kw\">AVG</span>(<span class=\"sql-type\">SAL</span>)\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">GROUP BY</span> <span class=\"sql-type\">DEPT_ID</span>\n<span class=\"sql-kw\">HAVING</span>  <span class=\"sql-kw\">AVG</span>(<span class=\"sql-type\">SAL</span>) &gt;= <span class=\"sql-num\">3500</span>;\n\n<span class=\"sql-cm\">-- WHERE + GROUP BY + HAVING 조합</span>\n<span class=\"sql-kw\">SELECT</span>  <span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-kw\">AVG</span>(<span class=\"sql-type\">SAL</span>)\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">WHERE</span>   <span class=\"sql-type\">HIRE_DATE</span> &gt;= <span class=\"sql-kw\">DATE</span> <span class=\"sql-str\">'2020-01-01'</span>   <span class=\"sql-cm\">-- 2020년 이후 입사자만</span>\n<span class=\"sql-kw\">GROUP BY</span> <span class=\"sql-type\">DEPT_ID</span>\n<span class=\"sql-kw\">HAVING</span>  <span class=\"sql-kw\">COUNT</span>(*) &gt;= <span class=\"sql-num\">3</span>;                   <span class=\"sql-cm\">-- 3명 이상인 부서</span></code></pre>\n\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (GROUP BY 후 — 부서별 인원수와 평균급여)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>DEPT_ID</th><th>CNT</th><th>AVG_SAL</th></tr></thead>\n    <tbody>\n      <tr><td>D1</td><td>2</td><td>3500</td></tr>\n      <tr><td>D2</td><td>2</td><td>3000</td></tr>\n      <tr><td>D3</td><td>1</td><td>5000</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ DEPT_ID 값별로 5명의 행이 3개 그룹으로 접히고, 각 그룹마다 COUNT·AVG가 한 번씩 계산된다.</p>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (HAVING 적용 후 — 평균급여 3500 이상 그룹만)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>DEPT_ID</th><th>AVG(SAL)</th></tr></thead>\n    <tbody>\n      <tr><td>D1</td><td>3500</td></tr>\n      <tr><td>D3</td><td>5000</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 그룹 단위 결과 3행 중 AVG(SAL) &lt; 3500인 D2(3000)가 빠진다. HAVING은 그룹 결과를 거르는 필터.</p>\n\n  <!-- Before & After -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">그룹화 전 → 후</span>\n  </h2>\n  <p class=\"reveal\">EMP 5명을 D1·D2·D3 세 부서로 묶어 부서별 인원수와 평균급여를 구하고, 그중 평균급여 3500 이상 부서만 남기는 상황. GROUP BY로 그룹을 만든 단계와 HAVING으로 그룹을 거른 단계의 결과를 단계별로 비교한다.</p>\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3);\">EMP 테이블</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>DEPT_ID</th><th>SAL</th></tr></thead>\n    <tbody>\n      <tr><td>김</td><td>D1</td><td>3000</td></tr>\n      <tr><td>이</td><td>D1</td><td>4000</td></tr>\n      <tr><td>박</td><td>D2</td><td>2500</td></tr>\n      <tr><td>최</td><td>D2</td><td>3500</td></tr>\n      <tr><td>홍</td><td>D3</td><td>5000</td></tr>\n    </tbody>\n  </table>\n  <div class=\"ba-flow reveal\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">GROUP BY</span>\n      <h4 class=\"ba-h\">DEPT_ID로 묶음</h4>\n      <div class=\"sql\">SELECT DEPT_ID, COUNT(*), AVG(SAL) FROM EMP GROUP BY DEPT_ID;</div>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">DEPT_ID</div><div class=\"h\">COUNT</div><div class=\"h\">AVG(SAL)</div>\n        <div class=\"c\">D1</div><div class=\"c\">2</div><div class=\"c\">3500</div>\n        <div class=\"c\">D2</div><div class=\"c\">2</div><div class=\"c\">3000</div>\n        <div class=\"c\">D3</div><div class=\"c\">1</div><div class=\"c\">5000</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\">→</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">HAVING</span>\n      <h4 class=\"ba-h\">AVG(SAL) ≥ 3500 그룹만</h4>\n      <div class=\"sql\">… GROUP BY DEPT_ID HAVING AVG(SAL) &gt;= 3500;</div>\n      <div class=\"mini-table\">\n        <div class=\"h\">DEPT_ID</div><div class=\"h\">AVG(SAL)</div>\n        <div class=\"c\">D1</div><div class=\"c\">3500</div>\n        <div class=\"c\">D3</div><div class=\"c\">5000</div>\n      </div>\n    </div>\n  </div>\n  <p class=\"reveal\">GROUP BY는 행을 키 단위로 접어 한 그룹당 한 행으로 만들고, 그 위에서 집계 함수가 동작한다. 따라서 평균급여 같은 집계 결과를 조건으로 걸려면 행 단위인 WHERE가 아니라 그룹 단위인 HAVING을 써야 한다. \"어떤 행을 걸러야 하나\"는 WHERE, \"묶은 결과 중 어떤 그룹을 남기나\"는 HAVING — 필터를 어느 단계에 둘지를 먼저 정한 뒤 쿼리를 짜는 것이 안전하다.</p>\n\n  <!-- 다중 컬럼 그룹화 -->\n  <h2 class=\"reveal\">다중 컬럼 그룹화</h2>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  <span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-type\">JOB</span>, <span class=\"sql-kw\">COUNT</span>(*)\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">GROUP BY</span> <span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-type\">JOB</span>;</code></pre>\n  <table class=\"reveal\">\n    <thead><tr><th>DEPT_ID</th><th>JOB</th><th>COUNT(*)</th></tr></thead>\n    <tbody>\n      <tr><td>D1</td><td>MGR</td><td>1</td></tr>\n      <tr><td>D1</td><td>CLERK</td><td>1</td></tr>\n      <tr><td>D2</td><td>CLERK</td><td>2</td></tr>\n    </tbody>\n  </table>\n\n  <!-- SELECT - GROUP BY 매칭 규칙 -->\n  <h2 class=\"reveal\">SELECT — GROUP BY 매칭 규칙</h2>\n  <table class=\"reveal\">\n    <thead><tr><th>SELECT 절에 쓸 수 있는 것</th><th>가능 여부</th></tr></thead>\n    <tbody>\n      <tr><td>GROUP BY 컬럼</td><td>가능</td></tr>\n      <tr><td>집계 함수(SUM, AVG 등)</td><td>가능</td></tr>\n      <tr><td>상수, 함수, 표현식</td><td>가능</td></tr>\n      <tr><td>그 외 일반 컬럼</td><td>불가</td></tr>\n    </tbody>\n  </table>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-2-1-5\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c216: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    ORDER BY는 결과를 <strong>어떤 순서로 보여줄지</strong> 정렬하는 절이다. SELECT 문에서 <strong>가장 마지막에 실행</strong>된다.\n  </blockquote>\n  <div class=\"ex-box reveal\">\n    책장 정리처럼 \"가나다순(<code>ASC</code>)·최신순(<code>DESC</code>)·분야별 → 분야 내 가나다순(<code>ORDER BY 분야, 책이름</code>)\" 식으로 1차·2차 정렬이 가능하다.\n  </div>\n\n  <!-- 개념 도식화 — 위치 -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">ORDER BY의 위치</span>\n  </h2>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  ...\n<span class=\"sql-kw\">FROM</span>    ...\n<span class=\"sql-kw\">WHERE</span>   ...\n<span class=\"sql-kw\">GROUP BY</span> ...\n<span class=\"sql-kw\">HAVING</span>  ...\n<span class=\"sql-kw\">ORDER BY</span> ...   <span class=\"sql-cm\">← 항상 맨 마지막</span></code></pre>\n\n  <p class=\"reveal\">ORDER BY는 SELECT 다음에 실행되는 <strong>가장 마지막 단계</strong>다. 그래서 SELECT에서 만든 별칭과 컬럼 번호를 사용할 수 있다.</p>\n\n  <!-- ASC vs DESC — 인포그래픽 -->\n  <h2 class=\"reveal\">ASC vs DESC</h2>\n  <div class=\"cls-row cols-2 reveal\">\n    <div class=\"cls-card\">\n      <span class=\"badge\">ASC (기본)</span>\n      <div class=\"name\">오름차순</div>\n      <div class=\"ex\">작 → 큰, ㄱ → ㅎ, 1 → 9 · 생략 시 ASC</div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-event\">DESC</span>\n      <div class=\"name\">내림차순</div>\n      <div class=\"ex\">큰 → 작 · 명시 필수</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">SAL</span>          <span class=\"sql-cm\">-- ASC(기본)</span>\n<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">ASC</span>      <span class=\"sql-cm\">-- 명시</span>\n<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">DESC</span>     <span class=\"sql-cm\">-- 내림차순</span></code></pre>\n\n  <!-- 정렬 기준 작성 방법 3가지 — 인포그래픽 -->\n  <h2 class=\"reveal\">정렬 기준 작성 방법 3가지</h2>\n  <div class=\"trait-grid cols-3 reveal\">\n    <div class=\"trait-card\">\n      <div class=\"num\">1</div>\n      <div class=\"label\">컬럼명</div>\n      <div class=\"desc\"><code>ORDER BY SAL DESC</code></div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"num\">2</div>\n      <div class=\"label\">별칭(Alias)</div>\n      <div class=\"desc\"><code>ORDER BY ANNUAL_SAL DESC</code></div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"num\">3</div>\n      <div class=\"label\">N번째 컬럼(정수)</div>\n      <div class=\"desc\"><code>ORDER BY 2 DESC</code></div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span>\n<span class=\"sql-cm\">-- 방법 1: 컬럼명</span>\n<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">DESC</span>;\n\n<span class=\"sql-cm\">-- 방법 2: SELECT 별칭(Alias)</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">SAL</span>*<span class=\"sql-num\">12</span> <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">ANNUAL_SAL</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">ANNUAL_SAL</span> <span class=\"sql-kw\">DESC</span>;\n\n<span class=\"sql-cm\">-- 방법 3: SELECT의 N번째 컬럼(정수)</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-num\">2</span> <span class=\"sql-kw\">DESC</span>;        <span class=\"sql-cm\">-- 2번째 컬럼 = SAL</span></code></pre>\n  <p class=\"reveal\">ORDER BY는 SELECT 다음에 실행되므로 <strong>별칭 사용이 가능</strong>하다(WHERE, GROUP BY는 불가).</p>\n\n  <!-- 다중 정렬 -->\n  <h2 class=\"reveal\">다중 정렬</h2>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">EMP</span>\n    <h4 class=\"ba-h\">사원 테이블</h4>\n    <div class=\"mini-table cols-3\">\n      <div class=\"h\">NAME</div><div class=\"h\">DEPT_ID</div><div class=\"h\">SAL</div>\n      <div class=\"c\">김</div><div class=\"c\">D1</div><div class=\"c\">3000</div>\n      <div class=\"c\">이</div><div class=\"c\">D2</div><div class=\"c\">4000</div>\n      <div class=\"c\">박</div><div class=\"c\">D1</div><div class=\"c\">2500</div>\n      <div class=\"c\">최</div><div class=\"c\">D2</div><div class=\"c\">4500</div>\n      <div class=\"c\">홍</div><div class=\"c\">D1</div><div class=\"c\">4000</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 부서별로 묶고, 같은 부서 안에서는 급여 높은 순</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-type\">SAL</span>\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">DEPT_ID</span> <span class=\"sql-kw\">ASC</span>, <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">DESC</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>DEPT_ID</th><th>SAL</th></tr></thead>\n    <tbody>\n      <tr><td>홍</td><td>D1</td><td>4000</td></tr>\n      <tr><td>김</td><td>D1</td><td>3000</td></tr>\n      <tr><td>박</td><td>D1</td><td>2500</td></tr>\n      <tr><td>최</td><td>D2</td><td>4500</td></tr>\n      <tr><td>이</td><td>D2</td><td>4000</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ DEPT_ID 오름차순으로 묶고, 같은 부서 안에서는 SAL 내림차순으로 2차 정렬된다.</p>\n\n  <!-- NULL 정렬 — 인포그래픽 -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">비교</span>\n    <span class=\"label-rest\">NULL의 정렬 순서 — DBMS별</span>\n  </h2>\n  <p class=\"reveal\"><a href=\"#\" data-chapter=\"c124\">NULL</a>은 비교 불가 값이므로 정렬에서도 DBMS마다 다르게 처리된다.</p>\n  <div class=\"threeway cols-2 reveal\">\n    <div class=\"threeway-card t-info\">\n      <div class=\"glyph\">Oracle</div>\n      <div class=\"name\">ASC = NULL <strong>마지막</strong></div>\n      <div class=\"desc\">DESC = NULL <strong>처음</strong><br>\"비어있는 값은 뒤로\"</div>\n    </div>\n    <div class=\"threeway-card t-warn\">\n      <div class=\"glyph\">MS-SQL</div>\n      <div class=\"name\">ASC = NULL <strong>처음</strong></div>\n      <div class=\"desc\">DESC = NULL <strong>마지막</strong><br>Oracle과 정반대</div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead><tr><th>DBMS</th><th>ASC 기본</th><th>DESC 기본</th></tr></thead>\n    <tbody>\n      <tr><td>Oracle</td><td>NULL이 마지막</td><td>NULL이 처음</td></tr>\n      <tr><td>MS-SQL Server</td><td>NULL이 처음</td><td>NULL이 마지막</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\">명시적 지정:</p>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">COMM</span> <span class=\"sql-kw\">ASC NULLS FIRST</span>   <span class=\"sql-cm\">-- NULL 먼저</span>\n<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">COMM</span> <span class=\"sql-kw\">ASC NULLS LAST</span>    <span class=\"sql-cm\">-- NULL 마지막</span></code></pre>\n\n  <!-- NULL 위치 SQL + 결과 -->\n  <h3 class=\"reveal\">NULL 위치 — SQL 예시 + 결과</h3>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 (Oracle 기준)</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">EMP</span>\n    <h4 class=\"ba-h\">사원 테이블</h4>\n    <div class=\"mini-table cols-2\">\n      <div class=\"h\">NAME</div><div class=\"h\">COMM</div>\n      <div class=\"c\">김</div><div class=\"c\">100</div>\n      <div class=\"c\">이</div><div class=\"c is-null\">NULL</div>\n      <div class=\"c\">박</div><div class=\"c\">300</div>\n      <div class=\"c\">최</div><div class=\"c is-null\">NULL</div>\n      <div class=\"c\">홍</div><div class=\"c\">200</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">COMM</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">COMM</span> <span class=\"sql-kw\">ASC NULLS FIRST</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (NULL이 먼저)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>COMM</th></tr></thead>\n    <tbody>\n      <tr><td>이</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td></tr>\n      <tr><td>최</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td></tr>\n      <tr><td>김</td><td>100</td></tr>\n      <tr><td>홍</td><td>200</td></tr>\n      <tr><td>박</td><td>300</td></tr>\n    </tbody>\n  </table>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">COMM</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">COMM</span> <span class=\"sql-kw\">ASC</span>;   <span class=\"sql-cm\">-- Oracle 기본</span></code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (Oracle 기본 = NULLS LAST)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>COMM</th></tr></thead>\n    <tbody>\n      <tr><td>김</td><td>100</td></tr>\n      <tr><td>홍</td><td>200</td></tr>\n      <tr><td>박</td><td>300</td></tr>\n      <tr><td>이</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td></tr>\n      <tr><td>최</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td></tr>\n    </tbody>\n  </table>\n\n  <!-- SQL 실전 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">정렬 패턴</span>\n  </h2>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 단일 컬럼</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">DESC</span>;\n\n<span class=\"sql-cm\">-- 다중 컬럼</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">DESC</span>;\n\n<span class=\"sql-cm\">-- 별칭으로</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">SAL</span>*<span class=\"sql-num\">12</span> <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">YEAR_SAL</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">YEAR_SAL</span> <span class=\"sql-kw\">DESC</span>;\n\n<span class=\"sql-cm\">-- 컬럼 번호로</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-num\">3</span> <span class=\"sql-kw\">DESC</span>, <span class=\"sql-num\">2</span> <span class=\"sql-kw\">ASC</span>;</code></pre>\n\n  <!-- Before & After -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">다중 정렬의 우선순위</span>\n  </h2>\n  <p class=\"reveal\">EMP 5명을 부서별로 묶어 보여주되, 같은 부서 안에서는 급여가 높은 사람이 먼저 보이도록 정렬하는 상황. DEPT_ID(오름차순)와 SAL(내림차순)을 하나의 ORDER BY 절에 섞었을 때 결과 순서가 어떻게 결정되는지 확인한다.</p>\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3);\">EMP 테이블</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>DEPT_ID</th><th>SAL</th></tr></thead>\n    <tbody>\n      <tr><td>김</td><td>D1</td><td>3000</td></tr>\n      <tr><td>이</td><td>D2</td><td>4000</td></tr>\n      <tr><td>박</td><td>D1</td><td>2500</td></tr>\n      <tr><td>최</td><td>D2</td><td>4500</td></tr>\n      <tr><td>홍</td><td>D1</td><td>4000</td></tr>\n    </tbody>\n  </table>\n  <div class=\"ba-flow reveal\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">BEFORE</span>\n      <h4 class=\"ba-h\">정렬 안 된 원본</h4>\n      <div class=\"sql\">SELECT NAME, DEPT_ID, SAL FROM EMP;</div>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">NAME</div><div class=\"h\">DEPT</div><div class=\"h\">SAL</div>\n        <div class=\"c\">김</div><div class=\"c\">D1</div><div class=\"c\">3000</div>\n        <div class=\"c\">이</div><div class=\"c\">D2</div><div class=\"c\">4000</div>\n        <div class=\"c\">박</div><div class=\"c\">D1</div><div class=\"c\">2500</div>\n        <div class=\"c\">최</div><div class=\"c\">D2</div><div class=\"c\">4500</div>\n        <div class=\"c\">홍</div><div class=\"c\">D1</div><div class=\"c\">4000</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\">→</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">AFTER</span>\n      <h4 class=\"ba-h\">DEPT_ID ASC, SAL DESC</h4>\n      <div class=\"sql\">ORDER BY DEPT_ID ASC, SAL DESC;</div>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">NAME</div><div class=\"h\">DEPT</div><div class=\"h\">SAL</div>\n        <div class=\"c\">홍</div><div class=\"c\">D1</div><div class=\"c\">4000</div>\n        <div class=\"c\">김</div><div class=\"c\">D1</div><div class=\"c\">3000</div>\n        <div class=\"c\">박</div><div class=\"c\">D1</div><div class=\"c\">2500</div>\n        <div class=\"c\">최</div><div class=\"c\">D2</div><div class=\"c\">4500</div>\n        <div class=\"c\">이</div><div class=\"c\">D2</div><div class=\"c\">4000</div>\n      </div>\n    </div>\n  </div>\n  <p class=\"reveal\">부서 오름차순 → 부서 내 급여 내림차순으로 정렬되었다. ORDER BY는 나열된 컬럼 순서대로 1차·2차·3차 정렬을 적용하고, ASC/DESC는 컬럼별로 따로 지정된다. 따라서 \"DEPT_ID는 오름차순, SAL은 내림차순\"처럼 키마다 방향이 달라도 한 줄에 함께 쓸 수 있다. 결과 순서를 사람 눈에 보일 형태로 확정해야 하는 보고서·페이지네이션·TopN 쿼리에서는 정렬 키를 의도대로 명시해두는 것이 안전하다.</p>\n\n  <!-- 주의사항 -->\n  <h2 class=\"reveal\">ORDER BY 주의사항</h2>\n  <p class=\"reveal\">ORDER BY는 정렬된 상위 N개만 추출하는 <a href=\"#\" data-chapter=\"c225\">TopN 쿼리</a>의 기반이 된다.</p>\n  <table class=\"reveal\">\n    <thead><tr><th>주의</th><th>설명</th></tr></thead>\n    <tbody>\n      <tr><td>항상 맨 끝</td><td>UNION 등 집합연산자 사용 시도 마지막에 한 번만</td></tr>\n      <tr><td>숫자 정렬</td><td>1, 2, 10... 숫자 그대로</td></tr>\n      <tr><td>문자 정렬</td><td>'1', '10', '2'... <strong>사전순</strong> → 1, 10, 2</td></tr>\n      <tr><td>NULL 위치</td><td>DBMS별로 다름. 명시 권장</td></tr>\n      <tr><td>인덱스 활용</td><td>정렬 작업에 인덱스가 활용될 수 있음</td></tr>\n    </tbody>\n  </table>\n\n  <!-- SELECT 실행 순서 -->\n  <h2 class=\"reveal\">SELECT 실행 순서</h2>\n  <table class=\"reveal\">\n    <thead><tr><th>순서</th><th>절</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td>FROM</td></tr>\n      <tr><td>2</td><td>WHERE</td></tr>\n      <tr><td>3</td><td>GROUP BY</td></tr>\n      <tr><td>4</td><td>HAVING</td></tr>\n      <tr><td>5</td><td>SELECT</td></tr>\n      <tr><td>6</td><td>ORDER BY</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\">ORDER BY가 마지막이라 <strong>별칭과 컬럼번호 사용이 가능</strong>하다.</p>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-2-1-6\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c217: "<!-- 핵심 요약 -->\r\n  <h2 class=\"section-label sec-summary reveal\">\r\n    <span class=\"label-tag\">핵심 요약</span>\r\n    <span class=\"label-rest\">정의</span>\r\n  </h2>\r\n  <blockquote class=\"reveal\">\r\n    조인은 <strong>두 개 이상의 테이블을 키로 연결</strong>해 한 결과로 합치는 작업이다.\r\n  </blockquote>\r\n  <div class=\"ex-box reveal\">\r\n    영화관 티켓(영화 정보)과 회원증(회원 정보)을 회원번호라는 공통 키로 매칭해 \"누가 어떤 영화를 봤는지\" 알아내는 것과 같다.\r\n  </div>\r\n\r\n  <!-- 개념 도식화 — 키 매칭 -->\r\n  <h2 class=\"section-label sec-diagram reveal\">\r\n    <span class=\"label-tag\">개념 도식화</span>\r\n    <span class=\"label-rest\">조인의 기본 원리</span>\r\n  </h2>\r\n  <p class=\"reveal\">조인은 모델링 단계의 <a href=\"#\" data-chapter=\"c114\">관계</a>가 SQL 단에서 실제로 사용되는 방식이다. 두 테이블은 공통 키(외래키 FK)를 따라가며 행을 짝짓는다. 이론적 배경은 <a href=\"#\" data-chapter=\"c122\">관계와 조인의 이해</a> 참고.</p>\r\n\r\n  <!-- 조인의 종류 — 핵심 인포그래픽 -->\r\n  <h2 class=\"reveal\">조인의 종류 — 5가지</h2>\r\n  <div class=\"cls-row cols-4 reveal\" style=\"grid-template-columns: repeat(5, 1fr);\">\r\n    <div class=\"cls-card\">\r\n      <span class=\"badge\">EQUI</span>\r\n      <div class=\"name\">동등 조인</div>\r\n      <div class=\"ex\"><code>=</code> 연산자로 연결<br><code>A.ID = B.ID</code></div>\r\n    </div>\r\n    <div class=\"cls-card\">\r\n      <span class=\"badge b-info\">Non-EQUI</span>\r\n      <div class=\"name\">비동등 조인</div>\r\n      <div class=\"ex\"><code>=</code> 외 연산자(BETWEEN, &gt;, &lt;)<br>등급표 매칭</div>\r\n    </div>\r\n    <div class=\"cls-card\">\r\n      <span class=\"badge b-warn\">SELF</span>\r\n      <div class=\"name\">셀프 조인</div>\r\n      <div class=\"ex\">같은 테이블끼리<br>사원-매니저(별칭 필수)</div>\r\n    </div>\r\n    <div class=\"cls-card\">\r\n      <span class=\"badge b-event\">OUTER</span>\r\n      <div class=\"name\">외부 조인</div>\r\n      <div class=\"ex\">LEFT / RIGHT / FULL<br>없는 쪽은 NULL</div>\r\n    </div>\r\n    <div class=\"cls-card\">\r\n      <span class=\"badge b-event\">CROSS</span>\r\n      <div class=\"name\">교차 조인</div>\r\n      <div class=\"ex\">카티션 곱<br>A행 × B행</div>\r\n    </div>\r\n  </div>\r\n  <table class=\"reveal\">\r\n    <thead><tr><th>종류</th><th>의미</th><th>예</th></tr></thead>\r\n    <tbody>\r\n      <tr><td>동등 조인</td><td><code>=</code>으로 연결</td><td><code>A.ID = B.ID</code></td></tr>\r\n      <tr><td>비동등 조인</td><td><code>=</code> 외(BETWEEN 등)</td><td><code>SAL BETWEEN LO AND HI</code></td></tr>\r\n      <tr><td>셀프 조인 (SELF JOIN)</td><td>같은 테이블끼리</td><td>사원-매니저(같은 EMP)</td></tr>\r\n      <tr><td>외부 조인 (OUTER JOIN)</td><td>매칭 안 돼도 한쪽 다 포함</td><td>LEFT/RIGHT/FULL</td></tr>\r\n      <tr><td>교차 조인 (CROSS JOIN)</td><td>모든 조합(카티션 곱)</td><td>두 테이블의 곱</td></tr>\r\n    </tbody>\r\n  </table>\r\n\r\n  <!-- EQUI -->\r\n  <h2 class=\"reveal\">동등 조인</h2>\r\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터</p>\r\n  <div class=\"ba-flow reveal\" style=\"grid-template-columns: 1fr 36px 1fr; align-items: stretch;\">\r\n    <div class=\"ba-side before\">\r\n      <span class=\"ba-tag\">EMP</span>\r\n      <h4 class=\"ba-h\">사원 테이블</h4>\r\n      <div class=\"mini-table cols-3\">\r\n        <div class=\"h\">EMP_ID</div><div class=\"h\">NAME</div><div class=\"h\">DEPT_ID</div>\r\n        <div class=\"c\">1</div><div class=\"c\">김</div><div class=\"c\">D1</div>\r\n        <div class=\"c\">2</div><div class=\"c\">이</div><div class=\"c\">D2</div>\r\n        <div class=\"c\">3</div><div class=\"c\">박</div><div class=\"c is-null\">NULL</div>\r\n      </div>\r\n    </div>\r\n    <div class=\"ba-arrow\" style=\"font-size: 22px; color: var(--point-500);\">+</div>\r\n    <div class=\"ba-side before\">\r\n      <span class=\"ba-tag\">DEPT</span>\r\n      <h4 class=\"ba-h\">부서 테이블</h4>\r\n      <div class=\"mini-table cols-2\">\r\n        <div class=\"h\">DEPT_ID</div><div class=\"h\">DEPT_NAME</div>\r\n        <div class=\"c\">D1</div><div class=\"c\">영업부</div>\r\n        <div class=\"c\">D2</div><div class=\"c\">인사부</div>\r\n        <div class=\"c\">D3</div><div class=\"c\">개발부</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <h3 class=\"reveal\">전통적 방식 (Oracle)</h3>\r\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  <span class=\"sql-type\">E</span>.<span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">D</span>.<span class=\"sql-type\">DEPT_NAME</span>\r\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span> <span class=\"sql-type\">E</span>, <span class=\"sql-name\">DEPT</span> <span class=\"sql-type\">D</span>\r\n<span class=\"sql-kw\">WHERE</span>   <span class=\"sql-type\">E</span>.<span class=\"sql-type\">DEPT_ID</span> = <span class=\"sql-type\">D</span>.<span class=\"sql-type\">DEPT_ID</span>;     <span class=\"sql-cm\">-- 조인 조건</span></code></pre>\r\n  <h3 class=\"reveal\">표준 ANSI 방식</h3>\r\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  <span class=\"sql-type\">E</span>.<span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">D</span>.<span class=\"sql-type\">DEPT_NAME</span>\r\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span>  <span class=\"sql-type\">E</span>\r\n        <span class=\"sql-kw\">JOIN</span> <span class=\"sql-name\">DEPT</span> <span class=\"sql-type\">D</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-type\">E</span>.<span class=\"sql-type\">DEPT_ID</span> = <span class=\"sql-type\">D</span>.<span class=\"sql-type\">DEPT_ID</span>;</code></pre>\r\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (두 SQL 동일)</p>\r\n  <table class=\"reveal\">\r\n    <thead><tr><th>NAME</th><th>DEPT_NAME</th></tr></thead>\r\n    <tbody>\r\n      <tr><td>김</td><td>영업부</td></tr>\r\n      <tr><td>이</td><td>인사부</td></tr>\r\n    </tbody>\r\n  </table>\r\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ <code>DEPT_ID</code>가 일치하는 행만 결합된다. 박(부서 없음)·D3(사람 없음)은 매칭 안 돼서 결과에서 제외.</p>\r\n  <p class=\"reveal\">자세한 <a href=\"#\" data-chapter=\"c218\">표준 조인</a>은 다음 챕터에서 다룬다.</p>\r\n\r\n  <!-- Non-EQUI -->\r\n  <h2 class=\"reveal\">비동등 조인</h2>\r\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터</p>\r\n  <div class=\"ba-flow reveal\" style=\"grid-template-columns: 1fr 36px 1fr; align-items: stretch;\">\r\n    <div class=\"ba-side before\">\r\n      <span class=\"ba-tag\">EMP</span>\r\n      <h4 class=\"ba-h\">사원 테이블</h4>\r\n      <div class=\"mini-table cols-2\">\r\n        <div class=\"h\">NAME</div><div class=\"h\">SAL</div>\r\n        <div class=\"c\">김</div><div class=\"c\">1500</div>\r\n        <div class=\"c\">이</div><div class=\"c\">2500</div>\r\n        <div class=\"c\">박</div><div class=\"c\">3500</div>\r\n      </div>\r\n    </div>\r\n    <div class=\"ba-arrow\" style=\"font-size: 22px; color: var(--point-500);\">+</div>\r\n    <div class=\"ba-side before\">\r\n      <span class=\"ba-tag\">SALGRADE</span>\r\n      <h4 class=\"ba-h\">급여 등급표</h4>\r\n      <div class=\"mini-table cols-3\">\r\n        <div class=\"h\">GRADE</div><div class=\"h\">LOSAL</div><div class=\"h\">HISAL</div>\r\n        <div class=\"c\">A</div><div class=\"c\">1000</div><div class=\"c\">2000</div>\r\n        <div class=\"c\">B</div><div class=\"c\">2001</div><div class=\"c\">3000</div>\r\n        <div class=\"c\">C</div><div class=\"c\">3001</div><div class=\"c\">5000</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 급여 등급표를 조인</span>\r\n<span class=\"sql-kw\">SELECT</span>  <span class=\"sql-type\">E</span>.<span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">E</span>.<span class=\"sql-type\">SAL</span>, <span class=\"sql-type\">S</span>.<span class=\"sql-type\">GRADE</span>\r\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span> <span class=\"sql-type\">E</span>, <span class=\"sql-name\">SALGRADE</span> <span class=\"sql-type\">S</span>\r\n<span class=\"sql-kw\">WHERE</span>   <span class=\"sql-type\">E</span>.<span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">BETWEEN</span> <span class=\"sql-type\">S</span>.<span class=\"sql-type\">LOSAL</span> <span class=\"sql-kw\">AND</span> <span class=\"sql-type\">S</span>.<span class=\"sql-type\">HISAL</span>;</code></pre>\r\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 — EMP{김 1500, 이 2500, 박 3500} ⨝ SALGRADE{A 1000~2000, B 2001~3000, C 3001~5000}</p>\r\n  <table class=\"reveal\">\r\n    <thead><tr><th>NAME</th><th>SAL</th><th>GRADE</th></tr></thead>\r\n    <tbody>\r\n      <tr><td>김</td><td>1500</td><td>A</td></tr>\r\n      <tr><td>이</td><td>2500</td><td>B</td></tr>\r\n      <tr><td>박</td><td>3500</td><td>C</td></tr>\r\n    </tbody>\r\n  </table>\r\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 등호(<code>=</code>) 대신 <code>BETWEEN</code>으로 범위 매칭. 각 사원의 급여가 어느 등급 구간에 속하는지로 짝짓는다.</p>\r\n\r\n  <!-- SELF -->\r\n  <h2 class=\"reveal\">셀프 조인 (SELF JOIN)</h2>\r\n  <p class=\"reveal\">한 테이블에 부모-자식 관계가 들어있을 때 사용한다(예: 사원-매니저). 계층 구조 조회와 함께 <a href=\"#\" data-chapter=\"c226\">계층형 질의와 셀프조인</a> 챕터에서 더 깊이 다룬다.</p>\r\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — EMP 한 테이블만 (자기 자신과 조인)</p>\r\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\r\n    <span class=\"ba-tag\">EMP</span>\r\n    <h4 class=\"ba-h\">사원 테이블</h4>\r\n    <div class=\"mini-table cols-3\">\r\n      <div class=\"h\">EMP_ID</div><div class=\"h\">NAME</div><div class=\"h\">MGR_ID</div>\r\n      <div class=\"c\">E1</div><div class=\"c\">김</div><div class=\"c\">E2</div>\r\n      <div class=\"c\">E2</div><div class=\"c\">이</div><div class=\"c\">E3</div>\r\n      <div class=\"c\">E3</div><div class=\"c\">박</div><div class=\"c is-null\">NULL</div>\r\n    </div>\r\n  </div>\r\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  <span class=\"sql-type\">E</span>.<span class=\"sql-type\">NAME</span>    <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">사원</span>,\r\n        <span class=\"sql-type\">M</span>.<span class=\"sql-type\">NAME</span>    <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">매니저</span>\r\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span> <span class=\"sql-type\">E</span>, <span class=\"sql-name\">EMP</span> <span class=\"sql-type\">M</span>\r\n<span class=\"sql-kw\">WHERE</span>   <span class=\"sql-type\">E</span>.<span class=\"sql-type\">MGR_ID</span> = <span class=\"sql-type\">M</span>.<span class=\"sql-type\">EMP_ID</span>;</code></pre>\r\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과</p>\r\n  <table class=\"reveal\">\r\n    <thead><tr><th>사원</th><th>매니저</th></tr></thead>\r\n    <tbody>\r\n      <tr><td>김</td><td>이</td></tr>\r\n      <tr><td>이</td><td>박</td></tr>\r\n    </tbody>\r\n  </table>\r\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 박은 매니저가 NULL이므로 매칭되는 행이 없어 제외된다(이는 INNER 조인의 동작).</p>\r\n\r\n  <!-- OUTER -->\r\n  <h2 class=\"section-label sec-compare reveal\">\r\n    <span class=\"label-tag\">비교</span>\r\n    <span class=\"label-rest\">외부 조인 (OUTER JOIN) — INNER vs LEFT vs RIGHT vs FULL</span>\r\n  </h2>\r\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터</p>\r\n  <div class=\"ba-flow reveal\" style=\"grid-template-columns: 1fr 36px 1fr; align-items: stretch;\">\r\n    <div class=\"ba-side before\">\r\n      <span class=\"ba-tag\">MEMBER</span>\r\n      <h4 class=\"ba-h\">회원 테이블</h4>\r\n      <div class=\"mini-table cols-2\">\r\n        <div class=\"h\">MEMBER_ID</div><div class=\"h\">NAME</div>\r\n        <div class=\"c\">M01</div><div class=\"c\">김</div>\r\n        <div class=\"c\">M02</div><div class=\"c\">이</div>\r\n        <div class=\"c\">M03</div><div class=\"c\">박</div>\r\n      </div>\r\n    </div>\r\n    <div class=\"ba-arrow\" style=\"font-size: 22px; color: var(--point-500);\">+</div>\r\n    <div class=\"ba-side before\">\r\n      <span class=\"ba-tag\">ORDERS</span>\r\n      <h4 class=\"ba-h\">주문 테이블</h4>\r\n      <div class=\"mini-table cols-2\">\r\n        <div class=\"h\">ORDER_ID</div><div class=\"h\">MEMBER_ID</div>\r\n        <div class=\"c\">O1</div><div class=\"c\">M01</div>\r\n        <div class=\"c\">O2</div><div class=\"c\">M02</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- LEFT OUTER (왼쪽 다)</span>\r\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">M</span>.<span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">O</span>.<span class=\"sql-type\">ORDER_ID</span>\r\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">MEMBER</span> <span class=\"sql-type\">M</span> <span class=\"sql-kw\">LEFT OUTER JOIN</span> <span class=\"sql-name\">ORDERS</span> <span class=\"sql-type\">O</span>\r\n       <span class=\"sql-kw\">ON</span> <span class=\"sql-type\">M</span>.<span class=\"sql-type\">MEMBER_ID</span> = <span class=\"sql-type\">O</span>.<span class=\"sql-type\">MEMBER_ID</span>;\r\n\r\n<span class=\"sql-cm\">-- Oracle 전통 방식 (+) 기호</span>\r\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">M</span>.<span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">O</span>.<span class=\"sql-type\">ORDER_ID</span>\r\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">MEMBER</span> <span class=\"sql-type\">M</span>, <span class=\"sql-name\">ORDERS</span> <span class=\"sql-type\">O</span>\r\n<span class=\"sql-kw\">WHERE</span>  <span class=\"sql-type\">M</span>.<span class=\"sql-type\">MEMBER_ID</span> = <span class=\"sql-type\">O</span>.<span class=\"sql-type\">MEMBER_ID</span>(+);   <span class=\"sql-cm\">-- (+)는 매칭 안 될 때 NULL로 보충될 쪽(없을 수 있는 쪽)에 붙임</span></code></pre>\r\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 — MEMBER{M01 김, M02 이, M03 박(주문 없음)} ⟕ ORDERS{O1 M01, O2 M02}</p>\r\n  <table class=\"reveal\">\r\n    <thead><tr><th>NAME</th><th>ORDER_ID</th></tr></thead>\r\n    <tbody>\r\n      <tr><td>김</td><td>O1</td></tr>\r\n      <tr><td>이</td><td>O2</td></tr>\r\n      <tr><td>박</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td></tr>\r\n    </tbody>\r\n  </table>\r\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 두 SQL은 같은 결과. 매칭 안 된 박도 결과에 남고 ORDER_ID는 NULL로 채워진다.</p>\r\n\r\n  <!-- 벤 다이어그램 5종 -->\r\n  <h3 class=\"reveal\">조인 종류 — 벤 다이어그램</h3>\r\n  <div class=\"venn-row cols-3 reveal\">\r\n    <div class=\"venn-card\">\r\n      <svg viewBox=\"0 0 220 140\">\r\n        <defs>\r\n          <clipPath id=\"ven-inner-clip\"><circle cx=\"85\" cy=\"70\" r=\"50\"/></clipPath>\r\n        </defs>\r\n        <circle class=\"v-a\" cx=\"85\" cy=\"70\" r=\"50\"/>\r\n        <circle class=\"v-b\" cx=\"135\" cy=\"70\" r=\"50\"/>\r\n        <circle class=\"v-hl\" cx=\"135\" cy=\"70\" r=\"50\" clip-path=\"url(#ven-inner-clip)\"/>\r\n        <text class=\"v-label\" x=\"55\" y=\"75\">A</text>\r\n        <text class=\"v-label\" x=\"165\" y=\"75\">B</text>\r\n      </svg>\r\n      <div class=\"name\">INNER JOIN</div>\r\n      <div class=\"desc\">A ∩ B<br/>양쪽에 모두 매칭되는 행만</div>\r\n    </div>\r\n    <div class=\"venn-card\">\r\n      <svg viewBox=\"0 0 220 140\">\r\n        <circle class=\"v-hl\" cx=\"85\" cy=\"70\" r=\"50\"/>\r\n        <circle class=\"v-b\" cx=\"135\" cy=\"70\" r=\"50\"/>\r\n        <text class=\"v-label\" x=\"55\" y=\"75\">A</text>\r\n        <text class=\"v-label\" x=\"165\" y=\"75\">B</text>\r\n      </svg>\r\n      <div class=\"name\">LEFT OUTER</div>\r\n      <div class=\"desc\">A 모두 + 매칭되는 B<br/>매칭 안 되면 NULL</div>\r\n    </div>\r\n    <div class=\"venn-card\">\r\n      <svg viewBox=\"0 0 220 140\">\r\n        <circle class=\"v-a\" cx=\"85\" cy=\"70\" r=\"50\"/>\r\n        <circle class=\"v-hl\" cx=\"135\" cy=\"70\" r=\"50\"/>\r\n        <text class=\"v-label\" x=\"55\" y=\"75\">A</text>\r\n        <text class=\"v-label\" x=\"165\" y=\"75\">B</text>\r\n      </svg>\r\n      <div class=\"name\">RIGHT OUTER</div>\r\n      <div class=\"desc\">B 모두 + 매칭되는 A<br/>매칭 안 되면 NULL</div>\r\n    </div>\r\n    <div class=\"venn-card\">\r\n      <svg viewBox=\"0 0 220 140\">\r\n        <circle class=\"v-hl\" cx=\"85\" cy=\"70\" r=\"50\"/>\r\n        <circle class=\"v-hl\" cx=\"135\" cy=\"70\" r=\"50\"/>\r\n        <text class=\"v-label\" x=\"55\" y=\"75\">A</text>\r\n        <text class=\"v-label\" x=\"165\" y=\"75\">B</text>\r\n      </svg>\r\n      <div class=\"name\">FULL OUTER</div>\r\n      <div class=\"desc\">A ∪ B 모두<br/>없는 쪽은 NULL</div>\r\n    </div>\r\n    <div class=\"venn-card\">\r\n      <svg viewBox=\"0 0 220 140\">\r\n        <rect class=\"v-hl\" x=\"20\" y=\"20\" width=\"180\" height=\"100\" rx=\"8\"/>\r\n        <text class=\"v-label\" x=\"110\" y=\"75\" style=\"fill: var(--fg-1);\">A × B</text>\r\n      </svg>\r\n      <div class=\"name\">CROSS JOIN</div>\r\n      <div class=\"desc\">A의 모든 행 × B의 모든 행<br/>카티션 곱</div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- 4종 OUTER SQL + 결과 (입력은 위 EMP/DEPT 사용) -->\r\n  <h3 class=\"reveal\">SQL 4종 + 결과 비교</h3>\r\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3);\">EMP(3행, 박은 DEPT_ID NULL) · DEPT(D1 영업 / D2 인사 / D3 개발) 기준</p>\r\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- INNER</span>\r\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">E</span>.<span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">D</span>.<span class=\"sql-type\">DEPT_NAME</span>\r\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span> <span class=\"sql-type\">E</span> <span class=\"sql-kw\">JOIN</span> <span class=\"sql-name\">DEPT</span> <span class=\"sql-type\">D</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-type\">E</span>.<span class=\"sql-type\">DEPT_ID</span> = <span class=\"sql-type\">D</span>.<span class=\"sql-type\">DEPT_ID</span>;</code></pre>\r\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (2행)</p>\r\n  <table class=\"reveal\">\r\n    <thead><tr><th>NAME</th><th>DEPT_NAME</th></tr></thead>\r\n    <tbody>\r\n      <tr><td>김</td><td>영업부</td></tr>\r\n      <tr><td>이</td><td>인사부</td></tr>\r\n    </tbody>\r\n  </table>\r\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- LEFT OUTER</span>\r\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">E</span>.<span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">D</span>.<span class=\"sql-type\">DEPT_NAME</span>\r\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span> <span class=\"sql-type\">E</span> <span class=\"sql-kw\">LEFT JOIN</span> <span class=\"sql-name\">DEPT</span> <span class=\"sql-type\">D</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-type\">E</span>.<span class=\"sql-type\">DEPT_ID</span> = <span class=\"sql-type\">D</span>.<span class=\"sql-type\">DEPT_ID</span>;</code></pre>\r\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (3행)</p>\r\n  <table class=\"reveal\">\r\n    <thead><tr><th>NAME</th><th>DEPT_NAME</th></tr></thead>\r\n    <tbody>\r\n      <tr><td>김</td><td>영업부</td></tr>\r\n      <tr><td>이</td><td>인사부</td></tr>\r\n      <tr><td>박</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td></tr>\r\n    </tbody>\r\n  </table>\r\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- FULL OUTER</span>\r\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">E</span>.<span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">D</span>.<span class=\"sql-type\">DEPT_NAME</span>\r\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span> <span class=\"sql-type\">E</span> <span class=\"sql-kw\">FULL OUTER JOIN</span> <span class=\"sql-name\">DEPT</span> <span class=\"sql-type\">D</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-type\">E</span>.<span class=\"sql-type\">DEPT_ID</span> = <span class=\"sql-type\">D</span>.<span class=\"sql-type\">DEPT_ID</span>;</code></pre>\r\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (4행)</p>\r\n  <table class=\"reveal\">\r\n    <thead><tr><th>NAME</th><th>DEPT_NAME</th></tr></thead>\r\n    <tbody>\r\n      <tr><td>김</td><td>영업부</td></tr>\r\n      <tr><td>이</td><td>인사부</td></tr>\r\n      <tr><td>박</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td></tr>\r\n      <tr><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>개발부</td></tr>\r\n    </tbody>\r\n  </table>\r\n\r\n  <!-- CROSS -->\r\n  <h2 class=\"reveal\">교차 조인 (CROSS JOIN, 카티션 곱)</h2>\r\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터</p>\r\n  <div class=\"ba-flow reveal\" style=\"grid-template-columns: 1fr 36px 1fr; align-items: stretch;\">\r\n    <div class=\"ba-side before\">\r\n      <span class=\"ba-tag\">A</span>\r\n      <h4 class=\"ba-h\">테이블 A</h4>\r\n      <div class=\"mini-table\" style=\"grid-template-columns: 1fr;\">\r\n        <div class=\"h\">A</div>\r\n        <div class=\"c\">a1</div>\r\n        <div class=\"c\">a2</div>\r\n        <div class=\"c\">a3</div>\r\n      </div>\r\n    </div>\r\n    <div class=\"ba-arrow\" style=\"font-size: 22px; color: var(--point-500);\">×</div>\r\n    <div class=\"ba-side before\">\r\n      <span class=\"ba-tag\">B</span>\r\n      <h4 class=\"ba-h\">테이블 B</h4>\r\n      <div class=\"mini-table\" style=\"grid-template-columns: 1fr;\">\r\n        <div class=\"h\">B</div>\r\n        <div class=\"c\">b1</div>\r\n        <div class=\"c\">b2</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">A</span> <span class=\"sql-kw\">CROSS JOIN</span> <span class=\"sql-name\">B</span>;\r\n<span class=\"sql-cm\">-- A 3행, B 2행 → 6행 (3×2)</span></code></pre>\r\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 — A{a1, a2, a3} × B{b1, b2}</p>\r\n  <table class=\"reveal\">\r\n    <thead><tr><th>A</th><th>B</th></tr></thead>\r\n    <tbody>\r\n      <tr><td>a1</td><td>b1</td></tr>\r\n      <tr><td>a1</td><td>b2</td></tr>\r\n      <tr><td>a2</td><td>b1</td></tr>\r\n      <tr><td>a2</td><td>b2</td></tr>\r\n      <tr><td>a3</td><td>b1</td></tr>\r\n      <tr><td>a3</td><td>b2</td></tr>\r\n    </tbody>\r\n  </table>\r\n  <p class=\"reveal\"><strong>조인 조건을 빼먹어도</strong> 발생하므로 의도치 않으면 위험하다.</p>\r\n\r\n  <!-- SQL 실전 -->\r\n  <h2 class=\"section-label sec-sql reveal\">\r\n    <span class=\"label-tag\">SQL 실전</span>\r\n    <span class=\"label-rest\">다양한 조인</span>\r\n  </h2>\r\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- INNER JOIN</span>\r\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">E</span>.<span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">D</span>.<span class=\"sql-type\">DEPT_NAME</span>\r\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span> <span class=\"sql-type\">E</span> <span class=\"sql-kw\">JOIN</span> <span class=\"sql-name\">DEPT</span> <span class=\"sql-type\">D</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-type\">E</span>.<span class=\"sql-type\">DEPT_ID</span> = <span class=\"sql-type\">D</span>.<span class=\"sql-type\">DEPT_ID</span>;\r\n\r\n<span class=\"sql-cm\">-- 3개 테이블 조인</span>\r\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">E</span>.<span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">D</span>.<span class=\"sql-type\">DEPT_NAME</span>, <span class=\"sql-type\">L</span>.<span class=\"sql-type\">CITY</span>\r\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span> <span class=\"sql-type\">E</span>\r\n       <span class=\"sql-kw\">JOIN</span> <span class=\"sql-name\">DEPT</span> <span class=\"sql-type\">D</span>     <span class=\"sql-kw\">ON</span> <span class=\"sql-type\">E</span>.<span class=\"sql-type\">DEPT_ID</span> = <span class=\"sql-type\">D</span>.<span class=\"sql-type\">DEPT_ID</span>\r\n       <span class=\"sql-kw\">JOIN</span> <span class=\"sql-name\">LOCATION</span> <span class=\"sql-type\">L</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-type\">D</span>.<span class=\"sql-type\">LOC_ID</span>  = <span class=\"sql-type\">L</span>.<span class=\"sql-type\">LOC_ID</span>;\r\n\r\n<span class=\"sql-cm\">-- LEFT OUTER JOIN</span>\r\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">M</span>.<span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">O</span>.<span class=\"sql-type\">ORDER_ID</span>\r\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">MEMBER</span> <span class=\"sql-type\">M</span> <span class=\"sql-kw\">LEFT JOIN</span> <span class=\"sql-name\">ORDERS</span> <span class=\"sql-type\">O</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-type\">M</span>.<span class=\"sql-type\">MEMBER_ID</span> = <span class=\"sql-type\">O</span>.<span class=\"sql-type\">MEMBER_ID</span>;</code></pre>\r\n\r\n  <!-- Before & After — 4 결과 테이블 -->\r\n  <h2 class=\"section-label sec-compare reveal\">\r\n    <span class=\"label-tag\">Before &amp; After</span>\r\n    <span class=\"label-rest\">조인 종류별 결과 행 차이</span>\r\n  </h2>\r\n  <p class=\"reveal\">EMP에는 부서가 없는 박이 있고, DEPT에는 아무도 속하지 않은 D3(개발부)가 있다. 같은 두 테이블에 INNER / LEFT / RIGHT / FULL OUTER 조인을 차례로 적용해 결과 행이 어떻게 늘었다 줄었다 하는지 비교한다.</p>\r\n  <div class=\"ba-flow reveal\">\r\n    <div class=\"ba-side before\">\r\n      <span class=\"ba-tag\">EMP</span>\r\n      <h4 class=\"ba-h\">사원 테이블</h4>\r\n      <div class=\"mini-table cols-3\">\r\n        <div class=\"h\">EMP_ID</div><div class=\"h\">NAME</div><div class=\"h\">DEPT_ID</div>\r\n        <div class=\"c\">1</div><div class=\"c\">김</div><div class=\"c\">D1</div>\r\n        <div class=\"c\">2</div><div class=\"c\">이</div><div class=\"c\">D2</div>\r\n        <div class=\"c\">3</div><div class=\"c\">박</div><div class=\"c is-null\">NULL</div>\r\n      </div>\r\n    </div>\r\n    <div class=\"ba-arrow\">+</div>\r\n    <div class=\"ba-side after\">\r\n      <span class=\"ba-tag\">DEPT</span>\r\n      <h4 class=\"ba-h\">부서 테이블</h4>\r\n      <div class=\"mini-table\">\r\n        <div class=\"h\">DEPT_ID</div><div class=\"h\">DEPT_NAME</div>\r\n        <div class=\"c\">D1</div><div class=\"c\">영업부</div>\r\n        <div class=\"c\">D2</div><div class=\"c\">인사부</div>\r\n        <div class=\"c\">D3</div><div class=\"c\">개발부</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div class=\"ba-tables cols-4 reveal\">\r\n    <div class=\"ba-mini-table\">\r\n      <div class=\"h\">INNER JOIN</div>\r\n      <div class=\"row\">김 · 영업부</div>\r\n      <div class=\"row\">이 · 인사부</div>\r\n      <div class=\"row\" style=\"color: var(--fg-4);\">(박, D3 제외)</div>\r\n    </div>\r\n    <div class=\"ba-mini-table\">\r\n      <div class=\"h\">LEFT OUTER (EMP 기준)</div>\r\n      <div class=\"row\">김 · 영업부</div>\r\n      <div class=\"row\">이 · 인사부</div>\r\n      <div class=\"row\">박 · NULL</div>\r\n    </div>\r\n    <div class=\"ba-mini-table\">\r\n      <div class=\"h\">RIGHT OUTER (DEPT 기준)</div>\r\n      <div class=\"row\">김 · 영업부</div>\r\n      <div class=\"row\">이 · 인사부</div>\r\n      <div class=\"row\">NULL · 개발부</div>\r\n    </div>\r\n    <div class=\"ba-mini-table\">\r\n      <div class=\"h\">FULL OUTER</div>\r\n      <div class=\"row\">김 · 영업부</div>\r\n      <div class=\"row\">이 · 인사부</div>\r\n      <div class=\"row\">박 · NULL</div>\r\n      <div class=\"row\">NULL · 개발부</div>\r\n    </div>\r\n  </div>\r\n  <p class=\"reveal\">INNER 조인은 양쪽 모두에 매칭되는 행만 남기므로 박과 개발부가 동시에 사라진다. LEFT/RIGHT OUTER는 기준이 되는 쪽을 다 살리고 반대쪽이 비면 NULL을 채우며, FULL OUTER는 양쪽 모두를 살린다. \"어느 쪽에 매칭이 없는 데이터까지 보고 싶은가\"가 INNER vs OUTER 선택 기준이며, OUTER 조인 후 WHERE에 비기준 컬럼 조건을 걸면 NULL 행이 도로 빠지므로 추가 조건은 ON 절에 두는 것이 안전하다.</p>\r\n\r\n  <!-- 주의사항 -->\r\n  <h2 class=\"reveal\">조인 시 주의사항</h2>\r\n  <table class=\"reveal\">\r\n    <thead><tr><th>함정</th><th>결과</th><th>해결</th></tr></thead>\r\n    <tbody>\r\n      <tr><td>조인 조건 누락</td><td>카티션 곱(행수 폭발)</td><td>ON 또는 WHERE 명시</td></tr>\r\n      <tr><td>OUTER JOIN과 WHERE 혼용</td><td>NULL 행 사라짐</td><td>조건은 ON에</td></tr>\r\n      <tr><td>N+1 테이블 조인</td><td>N개 조인 조건 필요</td><td>잘 매핑</td></tr>\r\n    </tbody>\r\n  </table>\r\n\r\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\r\n    <div>\r\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\r\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\r\n    </div>\r\n    <a href=\"./exam-review.html#ch-2-1-7\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\r\n  </div>",
  c218: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    표준 조인은 ANSI/ISO에서 정의한, <strong>모든 DBMS에서 통하는 조인 문법</strong>이다. <code>JOIN ... ON</code> 키워드를 사용한다. 앞 챕터의 <a href=\"#\" data-chapter=\"c217\">조인</a> 종류를 표준 문법으로 다시 정리한다.\n  </blockquote>\n\n  <!-- 개념 도식화 -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">표준 조인의 종류</span>\n  </h2>\n\n  <div class=\"cls-row cols-4 reveal\">\n    <div class=\"cls-card\"><span class=\"badge\">INNER</span><div class=\"name\">INNER JOIN (내부 조인)</div><div class=\"ex\">양쪽 매칭만. <code>INNER</code> 키워드 생략 가능 (<code>JOIN ... ON</code>)</div></div>\n    <div class=\"cls-card\"><span class=\"badge b-info\">LEFT</span><div class=\"name\">LEFT OUTER JOIN (왼쪽 외부 조인)</div><div class=\"ex\">왼쪽 모두 + 매칭된 오른쪽. <code>OUTER</code> 생략 가능</div></div>\n    <div class=\"cls-card\"><span class=\"badge b-info\">RIGHT</span><div class=\"name\">RIGHT OUTER JOIN (오른쪽 외부 조인)</div><div class=\"ex\">오른쪽 모두 + 매칭된 왼쪽</div></div>\n    <div class=\"cls-card\"><span class=\"badge b-warn\">FULL</span><div class=\"name\">FULL OUTER JOIN (전체 외부 조인)</div><div class=\"ex\">양쪽 모두(매칭 안 되면 NULL 채움)</div></div>\n  </div>\n\n  <!-- 벤다이어그램 4종 -->\n  <h3 class=\"reveal\">표준 OUTER 조인 — 벤 다이어그램</h3>\n  <div class=\"venn-row cols-4 reveal\">\n    <div class=\"venn-card\">\n      <svg viewBox=\"0 0 220 140\">\n        <defs>\n          <clipPath id=\"std-inner-clip\"><circle cx=\"85\" cy=\"70\" r=\"50\"/></clipPath>\n        </defs>\n        <circle class=\"v-a\" cx=\"85\" cy=\"70\" r=\"50\"/>\n        <circle class=\"v-b\" cx=\"135\" cy=\"70\" r=\"50\"/>\n        <circle class=\"v-hl\" cx=\"135\" cy=\"70\" r=\"50\" clip-path=\"url(#std-inner-clip)\"/>\n        <text class=\"v-label\" x=\"55\" y=\"75\">A</text>\n        <text class=\"v-label\" x=\"165\" y=\"75\">B</text>\n      </svg>\n      <div class=\"name\">INNER</div>\n      <div class=\"desc\">A ∩ B</div>\n    </div>\n    <div class=\"venn-card\">\n      <svg viewBox=\"0 0 220 140\">\n        <circle class=\"v-hl\" cx=\"85\" cy=\"70\" r=\"50\"/>\n        <circle class=\"v-b\" cx=\"135\" cy=\"70\" r=\"50\"/>\n        <text class=\"v-label\" x=\"55\" y=\"75\">A</text>\n        <text class=\"v-label\" x=\"165\" y=\"75\">B</text>\n      </svg>\n      <div class=\"name\">LEFT</div>\n      <div class=\"desc\">A 모두 + 매칭 B</div>\n    </div>\n    <div class=\"venn-card\">\n      <svg viewBox=\"0 0 220 140\">\n        <circle class=\"v-a\" cx=\"85\" cy=\"70\" r=\"50\"/>\n        <circle class=\"v-hl\" cx=\"135\" cy=\"70\" r=\"50\"/>\n        <text class=\"v-label\" x=\"55\" y=\"75\">A</text>\n        <text class=\"v-label\" x=\"165\" y=\"75\">B</text>\n      </svg>\n      <div class=\"name\">RIGHT</div>\n      <div class=\"desc\">B 모두 + 매칭 A</div>\n    </div>\n    <div class=\"venn-card\">\n      <svg viewBox=\"0 0 220 140\">\n        <circle class=\"v-hl\" cx=\"85\" cy=\"70\" r=\"50\"/>\n        <circle class=\"v-hl\" cx=\"135\" cy=\"70\" r=\"50\"/>\n        <text class=\"v-label\" x=\"55\" y=\"75\">A</text>\n        <text class=\"v-label\" x=\"165\" y=\"75\">B</text>\n      </svg>\n      <div class=\"name\">FULL OUTER</div>\n      <div class=\"desc\">A ∪ B 모두</div>\n    </div>\n  </div>\n  <div class=\"cls-row reveal\">\n    <div class=\"cls-card\"><span class=\"badge b-event\">CROSS</span><div class=\"name\">CROSS JOIN (교차 조인)</div><div class=\"ex\">조인 조건 없이 모든 조합. 결과 행수 = A × B</div></div>\n    <div class=\"cls-card\"><span class=\"badge b-event\">NATURAL</span><div class=\"name\">NATURAL JOIN (자연 조인)</div><div class=\"ex\">같은 이름 컬럼으로 자동 매칭. 별칭 사용 불가</div></div>\n    <div class=\"cls-card\"><span class=\"badge\">USING</span><div class=\"name\">USING (컬럼)</div><div class=\"ex\">지정한 컬럼만 매칭. USING 컬럼에 테이블 별칭 불가</div></div>\n  </div>\n\n  <!-- SQL 실전 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">조인 종류별 표준 문법</span>\n  </h2>\n\n  <h3 class=\"reveal\">INNER JOIN (내부 조인) — 양쪽 매칭만</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  E.<span class=\"sql-type\">NAME</span>, D.<span class=\"sql-type\">DEPT_NAME</span>\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span> E\n        <span class=\"sql-kw\">INNER JOIN</span> <span class=\"sql-name\">DEPT</span> D <span class=\"sql-kw\">ON</span> E.<span class=\"sql-type\">DEPT_ID</span> = D.<span class=\"sql-type\">DEPT_ID</span>;\n        <span class=\"sql-cm\">-- INNER 생략 가능: JOIN ... ON</span></code></pre>\n\n  <h3 class=\"reveal\">LEFT OUTER JOIN (왼쪽 외부 조인) — 왼쪽 다, 오른쪽 매칭</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  E.<span class=\"sql-type\">NAME</span>, D.<span class=\"sql-type\">DEPT_NAME</span>\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span> E\n        <span class=\"sql-kw\">LEFT OUTER JOIN</span> <span class=\"sql-name\">DEPT</span> D <span class=\"sql-kw\">ON</span> E.<span class=\"sql-type\">DEPT_ID</span> = D.<span class=\"sql-type\">DEPT_ID</span>;\n        <span class=\"sql-cm\">-- OUTER 생략 가능: LEFT JOIN</span></code></pre>\n\n  <h3 class=\"reveal\">RIGHT OUTER JOIN (오른쪽 외부 조인) — 오른쪽 다, 왼쪽 매칭</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  E.<span class=\"sql-type\">NAME</span>, D.<span class=\"sql-type\">DEPT_NAME</span>\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span> E\n        <span class=\"sql-kw\">RIGHT OUTER JOIN</span> <span class=\"sql-name\">DEPT</span> D <span class=\"sql-kw\">ON</span> E.<span class=\"sql-type\">DEPT_ID</span> = D.<span class=\"sql-type\">DEPT_ID</span>;</code></pre>\n\n  <h3 class=\"reveal\">FULL OUTER JOIN (전체 외부 조인) — 양쪽 다</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  E.<span class=\"sql-type\">NAME</span>, D.<span class=\"sql-type\">DEPT_NAME</span>\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span> E\n        <span class=\"sql-kw\">FULL OUTER JOIN</span> <span class=\"sql-name\">DEPT</span> D <span class=\"sql-kw\">ON</span> E.<span class=\"sql-type\">DEPT_ID</span> = D.<span class=\"sql-type\">DEPT_ID</span>;</code></pre>\n\n  <h3 class=\"reveal\">CROSS JOIN (교차 조인) — 모든 조합</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  *\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span> E <span class=\"sql-kw\">CROSS JOIN</span> <span class=\"sql-name\">DEPT</span> D;</code></pre>\n  <p class=\"reveal\">조인 조건 없음. 결과는 A행수 × B행수.</p>\n\n  <h3 class=\"reveal\">NATURAL JOIN (자연 조인) — 같은 이름 컬럼 자동 조인</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  *\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">NATURAL JOIN</span> <span class=\"sql-name\">DEPT</span>;     <span class=\"sql-cm\">-- DEPT_ID로 자동 조인</span></code></pre>\n  <table class=\"reveal\">\n    <thead><tr><th>특징</th><th>설명</th></tr></thead>\n    <tbody>\n      <tr><td>자동 매칭</td><td>이름이 같은 컬럼으로 매칭</td></tr>\n      <tr><td>별칭 사용 X</td><td>같은 이름 컬럼에 별칭 사용 불가</td></tr>\n      <tr><td>같은 이름 컬럼은 한 번만 등장</td><td>중복 제거</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\">의도치 않은 컬럼이 매칭될 수 있어 실무에서는 잘 쓰지 않는다.</p>\n\n  <h3 class=\"reveal\">USING 절 — 명시적 컬럼 매칭</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">DEPT_NAME</span>, <span class=\"sql-type\">DEPT_ID</span>\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">JOIN</span> <span class=\"sql-name\">DEPT</span> <span class=\"sql-kw\">USING</span> (<span class=\"sql-type\">DEPT_ID</span>);</code></pre>\n\n  <!-- NATURAL vs USING vs ON -->\n  <h2 class=\"reveal\">NATURAL vs USING vs ON</h2>\n  <div class=\"threeway reveal\">\n    <div class=\"threeway-card t-info\">\n      <div class=\"glyph\">NATURAL</div>\n      <div class=\"name\">자동 매칭</div>\n      <div class=\"desc\"><strong>이름이 같은 모든 컬럼</strong>으로 자동 조인. 별칭 불가, 의도치 않은 매칭 위험</div>\n    </div>\n    <div class=\"threeway-card t-warn\">\n      <div class=\"glyph\">USING</div>\n      <div class=\"name\">지정 컬럼만</div>\n      <div class=\"desc\">괄호 안 <strong>지정한 컬럼만</strong> 매칭. USING 컬럼에 테이블 별칭 사용 불가 (<code>E.DEPT_ID</code> ✗)</div>\n    </div>\n    <div class=\"threeway-card t-correct\">\n      <div class=\"glyph\">ON</div>\n      <div class=\"name\">명시적 조건</div>\n      <div class=\"desc\">조인 조건을 <strong>직접 지정</strong>. 다른 이름 컬럼끼리도 조인 가능, 별칭 자유</div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead><tr><th>NATURAL vs USING</th><th>차이</th></tr></thead>\n    <tbody>\n      <tr><td>NATURAL</td><td>자동(모든 같은 이름)</td></tr>\n      <tr><td>USING</td><td>지정한 컬럼만</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\">USING으로 조인된 컬럼은 테이블 별칭을 붙일 수 없다(예: <code>E.DEPT_ID</code> 불가).</p>\n\n  <h3 class=\"reveal\">ON 절 vs WHERE 절 (OUTER JOIN 핵심)</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 잘못된 예: OUTER JOIN인데 WHERE로 필터하면 NULL 행이 빠짐</span>\n<span class=\"sql-kw\">SELECT</span> M.<span class=\"sql-type\">NAME</span>, O.<span class=\"sql-type\">ORDER_ID</span>\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">MEMBER</span> M <span class=\"sql-kw\">LEFT JOIN</span> <span class=\"sql-name\">ORDERS</span> O <span class=\"sql-kw\">ON</span> M.<span class=\"sql-type\">MEMBER_ID</span> = O.<span class=\"sql-type\">MEMBER_ID</span>\n<span class=\"sql-kw\">WHERE</span>  O.<span class=\"sql-type\">AMOUNT</span> &gt; <span class=\"sql-num\">1000</span>;     <span class=\"sql-cm\">-- 주문 없는 회원이 사라짐</span>\n\n<span class=\"sql-cm\">-- 올바른 예: 조인 조건에 함께</span>\n<span class=\"sql-kw\">SELECT</span> M.<span class=\"sql-type\">NAME</span>, O.<span class=\"sql-type\">ORDER_ID</span>\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">MEMBER</span> M <span class=\"sql-kw\">LEFT JOIN</span> <span class=\"sql-name\">ORDERS</span> O\n       <span class=\"sql-kw\">ON</span> M.<span class=\"sql-type\">MEMBER_ID</span> = O.<span class=\"sql-type\">MEMBER_ID</span>\n       <span class=\"sql-kw\">AND</span> O.<span class=\"sql-type\">AMOUNT</span> &gt; <span class=\"sql-num\">1000</span>;</code></pre>\n\n  <!-- Before & After -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">표준 조인 결과 비교</span>\n  </h2>\n  <p class=\"reveal\">EMP 3행(박은 부서 미지정)과 DEPT 3행(D3 개발은 소속 사원 없음)을 같은 키 <code>DEPT_ID</code>로 조인하는 상황. 동일한 두 테이블에 INNER / LEFT / RIGHT / FULL / CROSS를 차례로 적용하면서 ANSI 표준 문법별 결과 행 수가 어떻게 달라지는지 비교한다.</p>\n\n  <h3 class=\"reveal\">입력</h3>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터</p>\n  <div class=\"ba-flow reveal\" style=\"grid-template-columns: 1fr 36px 1fr; align-items: stretch;\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">EMP</span>\n      <h4 class=\"ba-h\">사원 테이블</h4>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">EMP_ID</div><div class=\"h\">NAME</div><div class=\"h\">DEPT_ID</div>\n        <div class=\"c\">1</div><div class=\"c\">김</div><div class=\"c\">D1</div>\n        <div class=\"c\">2</div><div class=\"c\">이</div><div class=\"c\">D2</div>\n        <div class=\"c\">3</div><div class=\"c\">박</div><div class=\"c is-null\">NULL</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\" style=\"font-size: 22px; color: var(--point-500);\">+</div>\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">DEPT</span>\n      <h4 class=\"ba-h\">부서 테이블</h4>\n      <div class=\"mini-table cols-2\">\n        <div class=\"h\">DEPT_ID</div><div class=\"h\">DEPT_NAME</div>\n        <div class=\"c\">D1</div><div class=\"c\">영업</div>\n        <div class=\"c\">D2</div><div class=\"c\">인사</div>\n        <div class=\"c\">D3</div><div class=\"c\">개발</div>\n      </div>\n    </div>\n  </div>\n\n  <h3 class=\"reveal\">INNER JOIN (내부 조인) 결과</h3>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>DEPT_NAME</th></tr></thead>\n    <tbody>\n      <tr><td>김</td><td>영업</td></tr>\n      <tr><td>이</td><td>인사</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">LEFT JOIN (왼쪽 외부 조인) 결과</h3>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>DEPT_NAME</th></tr></thead>\n    <tbody>\n      <tr><td>김</td><td>영업</td></tr>\n      <tr><td>이</td><td>인사</td></tr>\n      <tr><td>박</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">RIGHT JOIN (오른쪽 외부 조인) 결과</h3>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>DEPT_NAME</th></tr></thead>\n    <tbody>\n      <tr><td>김</td><td>영업</td></tr>\n      <tr><td>이</td><td>인사</td></tr>\n      <tr><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>개발</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">FULL JOIN (전체 외부 조인) 결과</h3>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>DEPT_NAME</th></tr></thead>\n    <tbody>\n      <tr><td>김</td><td>영업</td></tr>\n      <tr><td>이</td><td>인사</td></tr>\n      <tr><td>박</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td></tr>\n      <tr><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>개발</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">CROSS JOIN (교차 조인) 결과</h3>\n  <p class=\"reveal\">3 × 3 = 9행.</p>\n\n  <!-- Oracle 사투리 vs ANSI 표준 SQL 비교 -->\n  <h3 class=\"reveal\">Oracle 사투리 vs ANSI 표준</h3>\n  <p class=\"reveal\">같은 LEFT OUTER 조인을 두 문법으로 작성한 비교다. Oracle 전용 <code>(+)</code> 표기와 ANSI 표준 <code>LEFT JOIN ... ON</code> 결과는 동일하지만, 표준 문법은 어느 DBMS에서나 통한다.</p>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- Oracle 사투리: (+) 기호</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">E</span>.<span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">D</span>.<span class=\"sql-type\">DEPT_NAME</span>\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span> <span class=\"sql-type\">E</span>, <span class=\"sql-name\">DEPT</span> <span class=\"sql-type\">D</span>\n<span class=\"sql-kw\">WHERE</span>  <span class=\"sql-type\">E</span>.<span class=\"sql-type\">DEPT_ID</span> = <span class=\"sql-type\">D</span>.<span class=\"sql-type\">DEPT_ID</span>(+);\n\n<span class=\"sql-cm\">-- ANSI 표준: LEFT JOIN ... ON</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">E</span>.<span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">D</span>.<span class=\"sql-type\">DEPT_NAME</span>\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span> <span class=\"sql-type\">E</span> <span class=\"sql-kw\">LEFT JOIN</span> <span class=\"sql-name\">DEPT</span> <span class=\"sql-type\">D</span>\n       <span class=\"sql-kw\">ON</span> <span class=\"sql-type\">E</span>.<span class=\"sql-type\">DEPT_ID</span> = <span class=\"sql-type\">D</span>.<span class=\"sql-type\">DEPT_ID</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 두 쿼리의 결과 (동일)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>DEPT_NAME</th></tr></thead>\n    <tbody>\n      <tr><td>김</td><td>영업</td></tr>\n      <tr><td>이</td><td>인사</td></tr>\n      <tr><td>박</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td></tr>\n    </tbody>\n  </table>\n\n  <p class=\"reveal\">ANSI 표준은 결과 집합을 키워드 한 단어로 명확히 구분한다 — INNER는 매칭만, LEFT/RIGHT는 한쪽 기준 모두, FULL은 양쪽 모두, CROSS는 카티션 곱이다. <strong>\"어느 쪽에 매칭이 없는 데이터까지 살릴 것인가\"</strong>를 먼저 정한 다음 그에 맞는 키워드를 고르고, OUTER 조인의 추가 조건은 반드시 <code>ON</code> 절에 두어야 매칭 안 되는 NULL 행이 그대로 살아남는다.</p>\n\n  <!-- 정리표 -->\n  <h2 class=\"reveal\">정리표</h2>\n  <table class=\"reveal\">\n    <thead><tr><th>종류</th><th>매칭 안 되는 왼쪽</th><th>매칭 안 되는 오른쪽</th></tr></thead>\n    <tbody>\n      <tr><td>INNER</td><td>제외</td><td>제외</td></tr>\n      <tr><td>LEFT</td><td>포함(NULL)</td><td>제외</td></tr>\n      <tr><td>RIGHT</td><td>제외</td><td>포함(NULL)</td></tr>\n      <tr><td>FULL</td><td>포함</td><td>포함</td></tr>\n      <tr><td>CROSS</td><td>모든 조합</td><td>모든 조합</td></tr>\n    </tbody>\n  </table>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-2-1-8\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c221: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    서브쿼리는 <strong>쿼리 안에 들어 있는 또 다른 쿼리</strong>다. 메인쿼리가 사용할 값을 미리 계산해 알려주는 보조 쿼리다.\n  </blockquote>\n  <div class=\"ex-box reveal\">\n    \"평균 가격보다 비싼 상품\"을 찾을 때, 평균을 먼저 계산(<strong>서브쿼리</strong>)한 뒤 그 값보다 큰 상품을 찾는(<strong>메인쿼리</strong>) 두 단계 작업.\n  </div>\n\n  <!-- 개념 도식화 -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">서브쿼리의 위치</span>\n  </h2>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  컬럼들                    <span class=\"sql-cm\">← SELECT 서브쿼리(스칼라)</span>\n<span class=\"sql-kw\">FROM</span>    (서브쿼리)                 <span class=\"sql-cm\">← FROM 서브쿼리(인라인 뷰)</span>\n<span class=\"sql-kw\">WHERE</span>   컬럼 = (서브쿼리);         <span class=\"sql-cm\">← WHERE 서브쿼리(대표적)</span></code></pre>\n\n  <div class=\"step-flow reveal\">\n    <div class=\"step-card\">\n      <div class=\"step\">STEP 1</div>\n      <div class=\"name\">메인 쿼리 시작</div>\n      <div class=\"ex\">실행 중 서브쿼리 결과가 필요한 자리에 도달</div>\n      <div class=\"arrow-next\">→</div>\n    </div>\n    <div class=\"step-card\">\n      <div class=\"step\">STEP 2</div>\n      <div class=\"name\">서브쿼리 실행</div>\n      <div class=\"ex\">메인이 필요로 하는 값을 계산해 반환</div>\n      <div class=\"arrow-next\">→</div>\n    </div>\n    <div class=\"step-card\">\n      <div class=\"step\">STEP 3</div>\n      <div class=\"name\">메인 쿼리 계속</div>\n      <div class=\"ex\">반환된 값으로 비교/필터/투영을 마무리</div>\n    </div>\n  </div>\n\n  <!-- 분류 트리 (mermaid) -->\n  <h2 class=\"reveal\">서브쿼리 분류</h2>\n  <div class=\"mermaid reveal\">flowchart TD\n    A[서브쿼리] --> B[결과 행수]\n    A --> C[위치]\n    A --> D[메인쿼리 관계]\n    B --> B1[단일행<br/>=, &gt;, &lt;]\n    B --> B2[다중행<br/>IN, ANY, ALL, EXISTS]\n    B --> B3[다중컬럼<br/>A,B IN ...]\n    C --> C1[SELECT 절<br/>스칼라]\n    C --> C2[FROM 절<br/>인라인 뷰]\n    C --> C3[WHERE 절<br/>중첩]\n    D --> D1[비연관<br/>한 번 실행]\n    D --> D2[연관<br/>행마다 반복]\n  </div>\n\n  <h2 class=\"reveal\">서브쿼리의 분류</h2>\n\n  <h3 class=\"reveal\">결과 행수에 따른 분류</h3>\n  <div class=\"cls-row reveal\">\n    <div class=\"cls-card\"><span class=\"badge\">단일행</span><div class=\"name\">Single-row</div><div class=\"ex\">1행 반환. <code>=</code>, <code>&gt;</code>, <code>&lt;</code>, <code>&gt;=</code>, <code>&lt;=</code>, <code>&lt;&gt;</code></div></div>\n    <div class=\"cls-card\"><span class=\"badge b-info\">다중행</span><div class=\"name\">Multi-row</div><div class=\"ex\">여러 행 반환. <code>IN</code>, <code>ANY</code>, <code>ALL</code>, <code>EXISTS</code></div></div>\n    <div class=\"cls-card\"><span class=\"badge b-warn\">다중컬럼</span><div class=\"name\">Multi-column</div><div class=\"ex\"><code>(A, B) IN (...)</code></div></div>\n  </div>\n  <table class=\"reveal\">\n    <thead><tr><th>종류</th><th>결과 행수</th><th>사용 연산자</th></tr></thead>\n    <tbody>\n      <tr><td>단일행 서브쿼리</td><td>1행</td><td><code>=</code>, <code>&gt;</code>, <code>&lt;</code>, <code>&gt;=</code>, <code>&lt;=</code>, <code>&lt;&gt;</code></td></tr>\n      <tr><td>다중행 서브쿼리</td><td>여러 행</td><td>IN, ANY, ALL, EXISTS</td></tr>\n      <tr><td>다중컬럼 서브쿼리</td><td>여러 컬럼</td><td><code>(A, B) IN (...)</code></td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">위치에 따른 분류</h3>\n  <div class=\"cls-row reveal\">\n    <div class=\"cls-card\"><span class=\"badge\">SELECT 절</span><div class=\"name\">스칼라 서브쿼리</div><div class=\"ex\"><code>SELECT (SELECT MAX(SAL) FROM EMP) FROM ...</code></div></div>\n    <div class=\"cls-card\"><span class=\"badge b-info\">FROM 절</span><div class=\"name\">인라인 뷰</div><div class=\"ex\"><code>FROM (SELECT ...) X</code> · 별칭 필수</div></div>\n    <div class=\"cls-card\"><span class=\"badge b-warn\">WHERE 절</span><div class=\"name\">중첩 서브쿼리</div><div class=\"ex\"><code>WHERE SAL &gt; (SELECT AVG(SAL)...)</code> — <a href=\"#\" data-chapter=\"c214\">WHERE 절</a></div></div>\n  </div>\n\n  <h3 class=\"reveal\">메인쿼리와의 관계</h3>\n  <table class=\"reveal\">\n    <thead><tr><th>종류</th><th>의미</th><th>특징</th></tr></thead>\n    <tbody>\n      <tr><td>비연관 서브쿼리</td><td>메인쿼리 컬럼 사용 안 함</td><td>한 번만 실행</td></tr>\n      <tr><td>연관 서브쿼리</td><td>메인쿼리 컬럼 참조</td><td>메인의 각 행마다 반복 실행</td></tr>\n    </tbody>\n  </table>\n\n  <!-- 서브쿼리 vs 조인 vs 집합 -->\n  <h2 class=\"reveal\">서브쿼리 vs 조인 vs 집합 연산자</h2>\n  <div class=\"threeway reveal\">\n    <div class=\"threeway-card t-info\">\n      <div class=\"glyph\">SUB</div>\n      <div class=\"name\">서브쿼리</div>\n      <div class=\"desc\">메인쿼리에 <strong>값 하나(또는 집합)을 공급</strong>. 보조 쿼리</div>\n    </div>\n    <div class=\"threeway-card t-correct\">\n      <div class=\"glyph\">JOIN</div>\n      <div class=\"name\"><a href=\"#\" data-chapter=\"c217\">조인</a></div>\n      <div class=\"desc\">컬럼을 <strong>옆으로 붙임</strong>. 두 테이블의 행 결합</div>\n    </div>\n    <div class=\"threeway-card t-warn\">\n      <div class=\"glyph\">SET</div>\n      <div class=\"name\"><a href=\"#\" data-chapter=\"c222\">집합 연산자</a></div>\n      <div class=\"desc\">행을 <strong>위·아래로 이어붙임</strong>. UNION/INTERSECT/MINUS</div>\n    </div>\n  </div>\n\n  <!-- SQL 실전 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">서브쿼리 패턴별 예제</span>\n  </h2>\n\n  <h3 class=\"reveal\">단일행 서브쿼리</h3>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">EMP</span>\n    <h4 class=\"ba-h\">사원 테이블</h4>\n    <div class=\"mini-table cols-2\">\n      <div class=\"h\">NAME</div><div class=\"h\">SAL</div>\n      <div class=\"c\">김</div><div class=\"c\">3000</div>\n      <div class=\"c\">이</div><div class=\"c\">5000</div>\n      <div class=\"c\">박</div><div class=\"c\">4000</div>\n      <div class=\"c\">최</div><div class=\"c\">4500</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 평균 급여보다 많이 받는 사원</span>\n<span class=\"sql-kw\">SELECT</span>  <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">SAL</span>\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">WHERE</span>   <span class=\"sql-type\">SAL</span> &gt; (<span class=\"sql-kw\">SELECT</span> <span class=\"sql-kw\">AVG</span>(<span class=\"sql-type\">SAL</span>) <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span>);</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (전체 평균 = 4125)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>SAL</th></tr></thead>\n    <tbody>\n      <tr><td>이</td><td>5000</td></tr>\n      <tr><td>최</td><td>4500</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 서브쿼리 결과가 1행 1값이므로 <code>&gt;</code> 같은 단순 연산자 사용이 가능하다.</p>\n\n  <h3 class=\"reveal\">다중행 서브쿼리 — IN / ANY / ALL</h3>\n  <table class=\"reveal\">\n    <thead><tr><th>연산자</th><th>의미</th></tr></thead>\n    <tbody>\n      <tr><td><code>IN (...)</code></td><td>값 중 하나와 같으면</td></tr>\n      <tr><td><code>&gt; ANY(...)</code></td><td>하나 이상보다 크면 → <strong>최솟값보다 크면</strong> 됨</td></tr>\n      <tr><td><code>&gt; ALL(...)</code></td><td>모두보다 크면 → <strong>최댓값보다 커야</strong> 함</td></tr>\n      <tr><td><code>EXISTS (...)</code></td><td>존재하면 참</td></tr>\n    </tbody>\n  </table>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- IN</span>\n<span class=\"sql-kw\">SELECT</span>  *\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">WHERE</span>   <span class=\"sql-type\">DEPT_ID</span> <span class=\"sql-kw\">IN</span> (<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">DEPT_ID</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">DEPT</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">LOC</span> = <span class=\"sql-str\">'SEOUL'</span>);\n\n<span class=\"sql-cm\">-- &gt; ANY: 어느 한 값보다 크면 → 최솟값보다만 크면 됨</span>\n<span class=\"sql-kw\">SELECT</span>  *\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">WHERE</span>   <span class=\"sql-type\">SAL</span> &gt; <span class=\"sql-kw\">ANY</span> (<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">DEPT_ID</span> = <span class=\"sql-str\">'D1'</span>);\n\n<span class=\"sql-cm\">-- &gt; ALL: 모든 값보다 커야 함 → 최댓값보다 커야 함</span>\n<span class=\"sql-kw\">SELECT</span>  *\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">WHERE</span>   <span class=\"sql-type\">SAL</span> &gt; <span class=\"sql-kw\">ALL</span> (<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">DEPT_ID</span> = <span class=\"sql-str\">'D1'</span>);</code></pre>\n\n  <h3 class=\"reveal\">EXISTS 서브쿼리</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 주문 내역이 있는 회원만</span>\n<span class=\"sql-kw\">SELECT</span>  *\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">MEMBER</span> M\n<span class=\"sql-kw\">WHERE</span>   <span class=\"sql-kw\">EXISTS</span> (<span class=\"sql-kw\">SELECT</span> <span class=\"sql-num\">1</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">ORDERS</span> O <span class=\"sql-kw\">WHERE</span> O.<span class=\"sql-type\">MEMBER_ID</span> = M.<span class=\"sql-type\">MEMBER_ID</span>);</code></pre>\n  <table class=\"reveal\">\n    <thead><tr><th>특징</th><th>설명</th></tr></thead>\n    <tbody>\n      <tr><td>결과가 존재하기만 하면 TRUE</td><td>1건이라도 있으면 통과</td></tr>\n      <tr><td>IN보다 효율적일 수 있음</td><td>존재 확인만 하면 됨</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">스칼라 서브쿼리 (SELECT 절)</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  E.<span class=\"sql-type\">NAME</span>,\n        E.<span class=\"sql-type\">SAL</span>,\n        (<span class=\"sql-kw\">SELECT</span> <span class=\"sql-kw\">AVG</span>(<span class=\"sql-type\">SAL</span>) <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span>) <span class=\"sql-kw\">AS</span> 전체평균\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span> E;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (전체평균 = 4125, 모든 행에 같은 값)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>SAL</th><th>전체평균</th></tr></thead>\n    <tbody>\n      <tr><td>김</td><td>3000</td><td>4125</td></tr>\n      <tr><td>이</td><td>5000</td><td>4125</td></tr>\n      <tr><td>박</td><td>4000</td><td>4125</td></tr>\n      <tr><td>최</td><td>4500</td><td>4125</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\">반드시 1행 1값을 반환해야 하며, 여러 행 반환 시 에러가 난다.</p>\n\n  <h3 class=\"reveal\">인라인 뷰 (FROM 절)</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 부서별 평균 중 평균 4000 이상인 부서</span>\n<span class=\"sql-kw\">SELECT</span>  *\n<span class=\"sql-kw\">FROM</span>    (<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-kw\">AVG</span>(<span class=\"sql-type\">SAL</span>) <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">AVG_SAL</span>\n         <span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span>\n         <span class=\"sql-kw\">GROUP BY</span> <span class=\"sql-type\">DEPT_ID</span>) X\n<span class=\"sql-kw\">WHERE</span>   X.<span class=\"sql-type\">AVG_SAL</span> &gt;= <span class=\"sql-num\">4000</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (D1=4000 통과, D2=4250 통과)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>DEPT_ID</th><th>AVG_SAL</th></tr></thead>\n    <tbody>\n      <tr><td>D1</td><td>4000</td></tr>\n      <tr><td>D2</td><td>4250</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\">임시 테이블처럼 사용한다. <strong>별칭 필수</strong>.</p>\n\n  <h4 class=\"reveal\">EXISTS SQL + 결과</h4>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터</p>\n  <div class=\"ba-flow reveal\" style=\"grid-template-columns: 1fr 36px 1fr; align-items: stretch;\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">MEMBER</span>\n      <h4 class=\"ba-h\">회원 테이블</h4>\n      <div class=\"mini-table cols-2\">\n        <div class=\"h\">MEMBER</div><div class=\"h\">NAME</div>\n        <div class=\"c\">M01</div><div class=\"c\">김</div>\n        <div class=\"c\">M02</div><div class=\"c\">이</div>\n        <div class=\"c\">M03</div><div class=\"c\">박</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\" style=\"font-size: 22px; color: var(--point-500);\">+</div>\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">ORDERS</span>\n      <h4 class=\"ba-h\">주문 테이블</h4>\n      <div class=\"mini-table cols-2\">\n        <div class=\"h\">ORDER_ID</div><div class=\"h\">MEMBER_ID</div>\n        <div class=\"c\">#1</div><div class=\"c\">M01</div>\n        <div class=\"c\">#2</div><div class=\"c\">M01</div>\n        <div class=\"c\">#3</div><div class=\"c\">M03</div>\n      </div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">MEMBER</span> M\n<span class=\"sql-kw\">WHERE</span>  <span class=\"sql-kw\">EXISTS</span> (<span class=\"sql-kw\">SELECT</span> <span class=\"sql-num\">1</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">ORDERS</span> O <span class=\"sql-kw\">WHERE</span> O.<span class=\"sql-type\">MEMBER_ID</span> = M.<span class=\"sql-type\">MEMBER_ID</span>);</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (주문 있는 회원만)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th></tr></thead>\n    <tbody>\n      <tr><td>김</td></tr>\n      <tr><td>박</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\">이(M02)는 주문 없으므로 EXISTS가 거짓이 되어 결과에서 빠진다.</p>\n\n  <h3 class=\"reveal\">연관 서브쿼리</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 자기 부서 평균보다 많이 받는 사원</span>\n<span class=\"sql-kw\">SELECT</span>  E.<span class=\"sql-type\">NAME</span>, E.<span class=\"sql-type\">SAL</span>, E.<span class=\"sql-type\">DEPT_ID</span>\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span> E\n<span class=\"sql-kw\">WHERE</span>   E.<span class=\"sql-type\">SAL</span> &gt; (<span class=\"sql-kw\">SELECT</span> <span class=\"sql-kw\">AVG</span>(<span class=\"sql-type\">SAL</span>)\n                 <span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span>\n                 <span class=\"sql-kw\">WHERE</span>  <span class=\"sql-type\">DEPT_ID</span> = E.<span class=\"sql-type\">DEPT_ID</span>);   <span class=\"sql-cm\">-- E.DEPT_ID는 메인쿼리 참조</span></code></pre>\n  <table class=\"reveal\">\n    <thead><tr><th>특징</th><th>설명</th></tr></thead>\n    <tbody>\n      <tr><td>메인쿼리의 각 행마다 서브쿼리 실행</td><td>행 수만큼 반복</td></tr>\n      <tr><td>성능 영향</td><td>큼. 필요시 <a href=\"#\" data-chapter=\"c217\">조인</a>으로 변환</td></tr>\n    </tbody>\n  </table>\n\n  <!-- Before & After -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">단일행(전체 평균) vs 연관(부서 평균)</span>\n  </h2>\n  <p class=\"reveal\">같은 EMP 4명 데이터에 같은 비교(자기보다 평균이 큰 사람)를 적용해도, 비교 기준이 <strong>\"회사 전체 평균\"</strong>이냐 <strong>\"자기 부서 평균\"</strong>이냐에 따라 결과가 달라지는 상황. 단일행 서브쿼리(전체 평균 1개)와 연관 서브쿼리(부서별 평균 2개)가 어떻게 다른 행을 골라내는지 비교한다.</p>\n\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3);\">EMP 테이블</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>DEPT_ID</th><th>SAL</th></tr></thead>\n    <tbody>\n      <tr><td>김</td><td>D1</td><td>3000</td></tr>\n      <tr><td>이</td><td>D1</td><td>5000</td></tr>\n      <tr><td>박</td><td>D2</td><td>4000</td></tr>\n      <tr><td>최</td><td>D2</td><td>4500</td></tr>\n    </tbody>\n  </table>\n\n  <div class=\"ba-flow reveal\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">단일행 서브쿼리</span>\n      <h4 class=\"ba-h\">전체 평균 1개와 비교</h4>\n      <div class=\"sql\">SELECT NAME, SAL FROM EMP\nWHERE SAL &gt; (SELECT AVG(SAL) FROM EMP);\n\n전체 평균 = 4125</div>\n      <div class=\"mini-table\">\n        <div class=\"h\">NAME</div><div class=\"h\">SAL</div>\n        <div class=\"c\">이</div><div class=\"c\">5000</div>\n        <div class=\"c\">최</div><div class=\"c\">4500</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\">→</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">연관 서브쿼리</span>\n      <h4 class=\"ba-h\">부서별 평균과 행마다 비교</h4>\n      <div class=\"sql\">SELECT NAME, SAL FROM EMP E\nWHERE SAL &gt; (SELECT AVG(SAL) FROM EMP\n             WHERE DEPT_ID = E.DEPT_ID);\n\nD1=4000 · D2=4250</div>\n      <div class=\"mini-table\">\n        <div class=\"h\">NAME</div><div class=\"h\">SAL</div>\n        <div class=\"c\">이</div><div class=\"c\">5000</div>\n        <div class=\"c\">최</div><div class=\"c\">4500</div>\n      </div>\n    </div>\n  </div>\n\n  <p class=\"reveal\">비연관(단일행) 서브쿼리는 메인쿼리와 무관하게 한 번만 실행되어 4125라는 한 값을 만들고 모든 행이 그 값과 비교된다. 반면 연관 서브쿼리는 바깥의 <code>E.DEPT_ID</code>를 참조하므로 <strong>행마다 평균이 다시 계산</strong>된다(D1행은 4000, D2행은 4250 기준). 결과 행 집합은 우연히 같아 보여도 비교 기준은 행마다 달라지는 셈이다. <strong>\"전체 기준\"인지 \"그룹 기준\"인지</strong>에 따라 단일행이냐 연관이냐를 선택해야 한다.</p>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-2-2-1\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c222: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    집합 연산자는 <strong>두 개 이상의 SELECT 결과를 합치거나 비교하는 도구</strong>다. 합집합(UNION), 교집합(INTERSECT), 차집합(MINUS).\n  </blockquote>\n  <div class=\"ex-box reveal\">\n    도시락 A={김밥,사과,우유}와 B={사과,빵,우유} → <strong>UNION</strong>={김밥,사과,우유,빵}, <strong>INTERSECT</strong>={사과,우유}, <strong>MINUS(A-B)</strong>={김밥}.\n  </div>\n\n  <!-- 개념 도식화 -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">4가지 집합 연산자</span>\n  </h2>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code>A = { 김, 이, 박 }      B = { 이, 박, 최 }\n\nUNION       (A ∪ B, 중복 제거)  →  { 김, 이, 박, 최 }\nUNION ALL   (A + B, 중복 유지)  →  { 김, 이, 박, 이, 박, 최 }\nINTERSECT   (A ∩ B, 교집합)     →  { 이, 박 }\nMINUS       (A − B, 차집합)     →  { 김 }       (A 에만 있는 것)</code></pre>\n\n  <!-- 벤 다이어그램 4종 (집합 연산자 챕터의 핵심 시각화) -->\n  <h3 class=\"reveal\">벤 다이어그램으로 보는 4가지 집합 연산자</h3>\n  <div class=\"venn-row cols-4 reveal\">\n    <div class=\"venn-card\">\n      <svg viewBox=\"0 0 220 140\">\n        <circle class=\"v-hl\" cx=\"85\" cy=\"70\" r=\"50\"/>\n        <circle class=\"v-hl\" cx=\"135\" cy=\"70\" r=\"50\"/>\n        <text class=\"v-label\" x=\"55\" y=\"75\">A</text>\n        <text class=\"v-label\" x=\"165\" y=\"75\">B</text>\n      </svg>\n      <div class=\"name\">UNION</div>\n      <div class=\"desc\">A ∪ B<br/>중복 제거 (정렬 발생)</div>\n    </div>\n    <div class=\"venn-card\">\n      <svg viewBox=\"0 0 220 140\">\n        <circle class=\"v-hl\" cx=\"85\" cy=\"70\" r=\"50\"/>\n        <circle class=\"v-hl\" cx=\"135\" cy=\"70\" r=\"50\"/>\n        <text class=\"v-label\" x=\"55\" y=\"75\">A</text>\n        <text class=\"v-label\" x=\"165\" y=\"75\">B</text>\n        <text x=\"110\" y=\"125\" style=\"font-size:11px; fill: var(--wrong-fg); font-weight:700; text-anchor:middle; font-family: var(--font-mono);\">+ 중복 그대로</text>\n      </svg>\n      <div class=\"name\">UNION ALL</div>\n      <div class=\"desc\">A + B<br/>중복 유지 (가장 빠름)</div>\n    </div>\n    <div class=\"venn-card\">\n      <svg viewBox=\"0 0 220 140\">\n        <defs>\n          <clipPath id=\"set-inter-clip\"><circle cx=\"85\" cy=\"70\" r=\"50\"/></clipPath>\n        </defs>\n        <circle class=\"v-a\" cx=\"85\" cy=\"70\" r=\"50\"/>\n        <circle class=\"v-b\" cx=\"135\" cy=\"70\" r=\"50\"/>\n        <circle class=\"v-hl\" cx=\"135\" cy=\"70\" r=\"50\" clip-path=\"url(#set-inter-clip)\"/>\n        <text class=\"v-label\" x=\"55\" y=\"75\">A</text>\n        <text class=\"v-label\" x=\"165\" y=\"75\">B</text>\n      </svg>\n      <div class=\"name\">INTERSECT</div>\n      <div class=\"desc\">A ∩ B<br/>양쪽 공통만</div>\n    </div>\n    <div class=\"venn-card\">\n      <svg viewBox=\"0 0 220 140\">\n        <defs>\n          <mask id=\"set-minus-mask\">\n            <rect width=\"220\" height=\"140\" fill=\"white\"/>\n            <circle cx=\"135\" cy=\"70\" r=\"50\" fill=\"black\"/>\n          </mask>\n        </defs>\n        <circle class=\"v-b\" cx=\"135\" cy=\"70\" r=\"50\"/>\n        <circle class=\"v-hl\" cx=\"85\" cy=\"70\" r=\"50\" mask=\"url(#set-minus-mask)\"/>\n        <text class=\"v-label\" x=\"55\" y=\"75\">A</text>\n        <text class=\"v-label\" x=\"165\" y=\"75\">B</text>\n      </svg>\n      <div class=\"name\">MINUS / EXCEPT</div>\n      <div class=\"desc\">A − B<br/>A에만 있는 것</div>\n    </div>\n  </div>\n\n  <!-- 4가지 집합 연산자 표 -->\n  <h2 class=\"reveal\">4가지 집합 연산자</h2>\n  <table class=\"reveal\">\n    <thead><tr><th>연산자</th><th>의미</th><th>중복 처리</th></tr></thead>\n    <tbody>\n      <tr><td>UNION</td><td>합집합</td><td>중복 제거</td></tr>\n      <tr><td>UNION ALL</td><td>합집합</td><td>중복 유지(가장 빠름)</td></tr>\n      <tr><td>INTERSECT</td><td>교집합</td><td>중복 제거</td></tr>\n      <tr><td>MINUS(Oracle) / EXCEPT(표준)</td><td>차집합</td><td>중복 제거</td></tr>\n    </tbody>\n  </table>\n\n  <!-- 사용 조건 -->\n  <h2 class=\"reveal\">사용 조건</h2>\n  <div class=\"trait-grid cols-4 reveal\">\n    <div class=\"trait-card\">\n      <div class=\"num\">1</div>\n      <div class=\"label\">컬럼 개수 동일</div>\n      <div class=\"desc\">두 SELECT의 컬럼 수가 같아야 함</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"num\">2</div>\n      <div class=\"label\">데이터 타입 호환</div>\n      <div class=\"desc\">같은 자리 컬럼은 호환되는 타입</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"num\">3</div>\n      <div class=\"label\">컬럼명은 첫 SELECT</div>\n      <div class=\"desc\">결과의 컬럼명은 첫 SELECT 기준</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"num\">4</div>\n      <div class=\"label\">ORDER BY 마지막 한 번</div>\n      <div class=\"desc\">맨 마지막에 한 번만 사용</div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead><tr><th>조건</th><th>설명</th></tr></thead>\n    <tbody>\n      <tr><td>컬럼 개수</td><td>두 SELECT의 컬럼 수가 같아야 함</td></tr>\n      <tr><td>데이터 타입</td><td>같은 자리의 컬럼은 호환되는 타입</td></tr>\n      <tr><td>컬럼명</td><td>결과의 컬럼명은 첫 SELECT 기준</td></tr>\n      <tr><td>ORDER BY</td><td>맨 마지막에 한 번만</td></tr>\n    </tbody>\n  </table>\n\n  <!-- SQL 실전 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">집합 연산자 사용</span>\n  </h2>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터</p>\n  <div class=\"ba-flow reveal\" style=\"grid-template-columns: 1fr 36px 1fr; align-items: stretch;\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">EMP_A</span>\n      <h4 class=\"ba-h\">본사 명단</h4>\n      <div class=\"mini-table\" style=\"grid-template-columns: 1fr;\">\n        <div class=\"h\">NAME</div>\n        <div class=\"c\">김</div>\n        <div class=\"c\">이</div>\n        <div class=\"c\">박</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\" style=\"font-size: 22px; color: var(--point-500);\">+</div>\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">EMP_B</span>\n      <h4 class=\"ba-h\">지사 명단</h4>\n      <div class=\"mini-table\" style=\"grid-template-columns: 1fr;\">\n        <div class=\"h\">NAME</div>\n        <div class=\"c\">이</div>\n        <div class=\"c\">박</div>\n        <div class=\"c\">최</div>\n      </div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- UNION (합집합 · 중복 제거)</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP_A</span>\n<span class=\"sql-kw\">UNION</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP_B</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (4행)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th></tr></thead>\n    <tbody>\n      <tr><td>김</td></tr><tr><td>이</td></tr><tr><td>박</td></tr><tr><td>최</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 양쪽에 모두 있는 \"이\", \"박\"은 한 번씩만 등장.</p>\n\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- UNION ALL (합집합 · 중복 유지)</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP_A</span>\n<span class=\"sql-kw\">UNION ALL</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP_B</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (6행 · 중복 그대로)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th></tr></thead>\n    <tbody>\n      <tr><td>김</td></tr><tr><td>이</td></tr><tr><td>박</td></tr>\n      <tr><td>이</td></tr><tr><td>박</td></tr><tr><td>최</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 중복 제거 단계가 없어 양쪽 행이 그대로 이어붙는다.</p>\n\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- INTERSECT (교집합)</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP_A</span>\n<span class=\"sql-kw\">INTERSECT</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP_B</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th></tr></thead>\n    <tbody>\n      <tr><td>이</td></tr><tr><td>박</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 양쪽에 모두 있는 행만 남는다.</p>\n\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- MINUS (차집합, A에만 있는 것)</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP_A</span>\n<span class=\"sql-kw\">MINUS</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP_B</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th></tr></thead>\n    <tbody>\n      <tr><td>김</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ A(EMP_A)에만 있는 행만 남는다. \"이\", \"박\"은 B에도 있어서 제외.</p>\n\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- ORDER BY는 마지막에</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP_A</span>\n<span class=\"sql-kw\">UNION</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP_B</span>\n<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">NAME</span>;</code></pre>\n\n  <!-- Before & After -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">UNION / UNION ALL / INTERSECT / MINUS</span>\n  </h2>\n  <p class=\"reveal\">본사(EMP_A)와 지사(EMP_B) 두 명단을 합치거나 비교하는 상황. 두 표에는 <strong>\"이\"와 \"박\"이 양쪽 모두</strong>에 들어 있고, \"김\"은 A에만, \"최\"는 B에만 있다. 같은 데이터를 네 가지 집합 연산자(UNION/UNION ALL/INTERSECT/MINUS)에 넣었을 때 결과가 어떻게 갈라지는지 비교한다.</p>\n\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3);\">EMP_A</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th></tr></thead>\n    <tbody>\n      <tr><td>김</td></tr>\n      <tr><td>이</td></tr>\n      <tr><td>박</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3);\">EMP_B</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th></tr></thead>\n    <tbody>\n      <tr><td>이</td></tr>\n      <tr><td>박</td></tr>\n      <tr><td>최</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">UNION (중복 제거, 4행)</h3>\n  <table class=\"reveal\"><thead><tr><th>NAME</th></tr></thead><tbody>\n    <tr><td>김</td></tr><tr><td>이</td></tr><tr><td>박</td></tr><tr><td>최</td></tr>\n  </tbody></table>\n\n  <h3 class=\"reveal\">UNION ALL (중복 그대로, 6행)</h3>\n  <table class=\"reveal\"><thead><tr><th>NAME</th></tr></thead><tbody>\n    <tr><td>김</td></tr><tr><td>이</td></tr><tr><td>박</td></tr>\n    <tr><td>이</td></tr><tr><td>박</td></tr><tr><td>최</td></tr>\n  </tbody></table>\n\n  <h3 class=\"reveal\">INTERSECT</h3>\n  <table class=\"reveal\"><thead><tr><th>NAME</th></tr></thead><tbody>\n    <tr><td>이</td></tr><tr><td>박</td></tr>\n  </tbody></table>\n\n  <h3 class=\"reveal\">MINUS</h3>\n  <table class=\"reveal\"><thead><tr><th>NAME</th></tr></thead><tbody>\n    <tr><td>김</td></tr>\n  </tbody></table>\n\n  <p class=\"reveal\">같은 두 입력에서 4가지 결과가 갈라지는 이유는 <strong>\"중복을 어떻게 다루느냐\"와 \"어느 쪽 기준으로 비교하느냐\"</strong>가 연산마다 다르기 때문이다. UNION은 중복을 제거하기 위해 정렬을 한 번 더 거치므로 행 수가 줄고, UNION ALL은 그 단계를 건너뛰어 그대로 이어붙인다. INTERSECT는 양쪽 모두에 있는 값만, MINUS는 A에만 있는 값만 남긴다. 따라서 \"합칠 때 중복이 의미가 있는가\" \"두 집합의 공통 부분만 보고 싶은가\" \"한쪽에만 있는 것을 추리는가\"를 먼저 묻고 연산자를 고르는 것이 핵심이다.</p>\n\n  <!-- UNION vs UNION ALL 성능 -->\n  <h2 class=\"reveal\">UNION vs UNION ALL 성능 차이</h2>\n  <table class=\"reveal\">\n    <thead><tr><th>비교</th><th>UNION</th><th>UNION ALL</th></tr></thead>\n    <tbody>\n      <tr><td>중복 제거</td><td>함</td><td>안 함</td></tr>\n      <tr><td>정렬 작업</td><td>일어남(중복 제거 위해)</td><td>안 일어남</td></tr>\n      <tr><td>성능</td><td>느림</td><td>빠름</td></tr>\n      <tr><td>권장</td><td>중복 가능성이 있을 때</td><td>중복 없거나 그대로 둬도 될 때</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\">중복이 절대 없다고 확신하면 <strong>UNION ALL</strong>을 사용해 성능을 높인다. 두 결과를 \"행 단위로 이어붙이는\" 집합 연산자와 달리 <a href=\"#\" data-chapter=\"c217\">조인</a>은 컬럼을 옆으로 붙이고, <a href=\"#\" data-chapter=\"c221\">서브쿼리</a>는 메인쿼리에 값 하나를 공급한다는 점에서 역할이 다르다.</p>\n\n  <!-- 다중 컬럼 -->\n  <h2 class=\"reveal\">다중 컬럼 집합 연산</h2>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP_A</span>\n<span class=\"sql-kw\">UNION</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP_B</span>;</code></pre>\n  <p class=\"reveal\">모든 컬럼 값이 일치할 때만 중복으로 간주된다.</p>\n\n  <!-- NULL과 집합 연산 -->\n  <h2 class=\"reveal\">NULL과 집합 연산</h2>\n  <p class=\"reveal\">집합 연산에서 NULL은 NULL과 같은 값으로 취급되어 <strong>중복으로 처리</strong>된다(일반 비교 <code>=</code>와 다름).</p>\n  <table class=\"reveal\">\n    <thead><tr><th>EMP_A.COL</th><th>EMP_B.COL</th></tr></thead>\n    <tbody>\n      <tr><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\">UNION 시 1행만 남는다.</p>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-2-2-2\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c223: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    그룹 함수는 <strong>다양한 단위의 소계와 합계를 한 쿼리로 한꺼번에</strong> 뽑아주는 확장 <a href=\"#\" data-chapter=\"c215\">GROUP BY</a> 도구다(ROLLUP, CUBE, GROUPING SETS).\n  </blockquote>\n  <div class=\"ex-box reveal\">\n    매장 매출 보고서에서 <strong>\"부서별 / 부서+상품별 / 전체 합계\"</strong>를 따로따로 SELECT하지 않고 한 번에 뽑는 도구.\n  </div>\n\n  <!-- 개념 도식화 -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">그룹 함수의 종류</span>\n  </h2>\n  <div class=\"threeway reveal\">\n    <div class=\"threeway-card t-info\">\n      <div class=\"glyph\">ROLLUP</div>\n      <div class=\"name\">계층적 소계</div>\n      <div class=\"desc\">A,B → A → ⌀ — <strong>N+1 단계</strong>. 왼쪽부터 한 칸씩 떼며 소계</div>\n    </div>\n    <div class=\"threeway-card t-warn\">\n      <div class=\"glyph\">CUBE</div>\n      <div class=\"name\">모든 조합</div>\n      <div class=\"desc\">A,B → A → B → ⌀ — <strong>2^N 단계</strong>. 큐브의 모든 면</div>\n    </div>\n    <div class=\"threeway-card t-correct\">\n      <div class=\"glyph\">SETS</div>\n      <div class=\"name\">GROUPING SETS</div>\n      <div class=\"desc\">지정한 조합만 — <strong>가장 유연</strong>. 골라서 보기</div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead><tr><th>함수</th><th>의미</th><th>비유</th></tr></thead>\n    <tbody>\n      <tr><td>ROLLUP(A, B)</td><td>A별, A+B별, 전체 합계</td><td>단계적 소계</td></tr>\n      <tr><td>CUBE(A, B)</td><td>모든 조합(A별, B별, A+B별, 전체)</td><td>큐브의 모든 면</td></tr>\n      <tr><td>GROUPING SETS((A), (B))</td><td>특정 조합만</td><td>골라서 보기</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">ROLLUP의 누적 그룹 — (DEPT, JOB) 기준</h3>\n  <div class=\"tree-diagram reveal\">\n    <ul>\n      <li><span class=\"node root\">ROLLUP(DEPT, JOB)</span>\n        <ul>\n          <li><span class=\"node\">(DEPT, JOB) <span class=\"meta\">상세 그룹</span></span></li>\n          <li><span class=\"node\">(DEPT) <span class=\"meta\">부서 소계</span></span></li>\n          <li><span class=\"node\">() <span class=\"meta\">전체 합계</span></span></li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n  <p class=\"reveal\">왼쪽부터 한 칸씩 떼어내며 누적되는 구조다. <code>ROLLUP(A, B, C)</code>라면 (A,B,C) → (A,B) → (A) → () 총 4단계가 만들어진다.</p>\n\n  <!-- SQL 실전 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">함수별 사용 예제</span>\n  </h2>\n\n  <h3 class=\"reveal\">ROLLUP — 계층적 소계</h3>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">EMP</span>\n    <h4 class=\"ba-h\">사원 테이블</h4>\n    <div class=\"mini-table cols-3\">\n      <div class=\"h\">DEPT_ID</div><div class=\"h\">JOB</div><div class=\"h\">SAL</div>\n      <div class=\"c\">D1</div><div class=\"c\">MGR</div><div class=\"c\">5000</div>\n      <div class=\"c\">D1</div><div class=\"c\">CLERK</div><div class=\"c\">2000</div>\n      <div class=\"c\">D2</div><div class=\"c\">MGR</div><div class=\"c\">4500</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  <span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-type\">JOB</span>, <span class=\"sql-kw\">SUM</span>(<span class=\"sql-type\">SAL</span>)\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">GROUP BY</span> <span class=\"sql-kw\">ROLLUP</span>(<span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-type\">JOB</span>);</code></pre>\n\n  <h4 class=\"reveal\">결과 — 3단계(부서+직무, 부서, 전체)</h4>\n  <table class=\"reveal\">\n    <thead><tr><th>DEPT_ID</th><th>JOB</th><th>SUM(SAL)</th></tr></thead>\n    <tbody>\n      <tr><td>D1</td><td>MGR</td><td>5000</td></tr>\n      <tr><td>D1</td><td>CLERK</td><td>2000</td></tr>\n      <tr><td>D1</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>7000 (D1 소계)</td></tr>\n      <tr><td>D2</td><td>MGR</td><td>4500</td></tr>\n      <tr><td>D2</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>4500 (D2 소계)</td></tr>\n      <tr><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>11500 (전체 합계)</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\">ROLLUP(A, B): A → A+B로 갈수록 세분화되고, 위로 갈수록 소계가 된다.</p>\n\n  <h3 class=\"reveal\">CUBE — 모든 조합</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  <span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-type\">JOB</span>, <span class=\"sql-kw\">SUM</span>(<span class=\"sql-type\">SAL</span>)\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">GROUP BY</span> <span class=\"sql-kw\">CUBE</span>(<span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-type\">JOB</span>);</code></pre>\n\n  <h4 class=\"reveal\">결과 — ROLLUP 결과 + JOB별 합계까지</h4>\n  <table class=\"reveal\">\n    <thead><tr><th>DEPT_ID</th><th>JOB</th><th>SUM(SAL)</th></tr></thead>\n    <tbody>\n      <tr><td>D1</td><td>MGR</td><td>5000</td></tr>\n      <tr><td>D1</td><td>CLERK</td><td>2000</td></tr>\n      <tr><td>D1</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>7000</td></tr>\n      <tr><td>D2</td><td>MGR</td><td>4500</td></tr>\n      <tr><td>D2</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>4500</td></tr>\n      <tr><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>MGR</td><td>9500 (MGR 합계, CUBE만 추가)</td></tr>\n      <tr><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>CLERK</td><td>2000 (CLERK 합계)</td></tr>\n      <tr><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>11500</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\">N개 컬럼 CUBE는 <strong>2^N가지 조합</strong>을 만든다.</p>\n\n  <h3 class=\"reveal\">GROUPING SETS — 골라 보기</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  <span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-type\">JOB</span>, <span class=\"sql-kw\">SUM</span>(<span class=\"sql-type\">SAL</span>)\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">GROUP BY</span> <span class=\"sql-kw\">GROUPING SETS</span>((<span class=\"sql-type\">DEPT_ID</span>), (<span class=\"sql-type\">JOB</span>), ());</code></pre>\n\n  <h4 class=\"reveal\">결과 — 부서별, 직무별, 전체</h4>\n  <table class=\"reveal\">\n    <thead><tr><th>DEPT_ID</th><th>JOB</th><th>SUM(SAL)</th></tr></thead>\n    <tbody>\n      <tr><td>D1</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>7000</td></tr>\n      <tr><td>D2</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>4500</td></tr>\n      <tr><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>MGR</td><td>9500</td></tr>\n      <tr><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>CLERK</td><td>2000</td></tr>\n      <tr><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>11500</td></tr>\n    </tbody>\n  </table>\n\n  <!-- 정리표 -->\n  <h2 class=\"reveal\">정리표</h2>\n  <table class=\"reveal\">\n    <thead><tr><th>함수</th><th>결과</th></tr></thead>\n    <tbody>\n      <tr><td>GROUP BY (A, B)</td><td>A, B 조합</td></tr>\n      <tr><td>GROUP BY ROLLUP(A, B)</td><td>(A, B), (A), ()</td></tr>\n      <tr><td>GROUP BY CUBE(A, B)</td><td>(A, B), (A), (B), ()</td></tr>\n      <tr><td>GROUP BY GROUPING SETS((A, B), (A))</td><td>지정한 조합만</td></tr>\n    </tbody>\n  </table>\n\n  <!-- GROUPING 함수 -->\n  <h2 class=\"reveal\">GROUPING 함수 — 소계 행 구분</h2>\n  <p class=\"reveal\">결과에 NULL이 보일 때, <strong>원래 NULL</strong>인지 <strong>소계로 인한 NULL</strong>인지 구분하는 함수다.</p>\n  <div class=\"fn-grid reveal\">\n    <div class=\"fn-card\">\n      <div class=\"name\">GROUPING(컬럼) = 0</div>\n      <div class=\"desc\">일반 행 (실제 그룹의 데이터 NULL)</div>\n      <div class=\"ex\">D1, MGR, 5000 → 0, 0</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">GROUPING(컬럼) = 1</div>\n      <div class=\"desc\"><strong>소계 행</strong>의 NULL (집계로 생긴 NULL)</div>\n      <div class=\"ex\">D1, NULL(소계) → 0, 1</div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead><tr><th>결과</th><th>의미</th></tr></thead>\n    <tbody>\n      <tr><td>GROUPING(컬럼) = 0</td><td>일반 행(실제 그룹)</td></tr>\n      <tr><td>GROUPING(컬럼) = 1</td><td>소계 행</td></tr>\n    </tbody>\n  </table>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  <span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-type\">JOB</span>, <span class=\"sql-kw\">SUM</span>(<span class=\"sql-type\">SAL</span>),\n        <span class=\"sql-kw\">GROUPING</span>(<span class=\"sql-type\">DEPT_ID</span>) <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">G_DEPT</span>,\n        <span class=\"sql-kw\">GROUPING</span>(<span class=\"sql-type\">JOB</span>)     <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">G_JOB</span>\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">GROUP BY</span> <span class=\"sql-kw\">ROLLUP</span>(<span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-type\">JOB</span>);</code></pre>\n  <table class=\"reveal\">\n    <thead><tr><th>DEPT_ID</th><th>JOB</th><th>SUM</th><th>G_DEPT</th><th>G_JOB</th></tr></thead>\n    <tbody>\n      <tr><td>D1</td><td>MGR</td><td>5000</td><td>0</td><td>0</td></tr>\n      <tr><td>D1</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>7000</td><td>0</td><td>1 (소계)</td></tr>\n      <tr><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>11500</td><td>1</td><td>1 (전체 합계)</td></tr>\n    </tbody>\n  </table>\n\n  <!-- Before & After -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">ROLLUP vs CUBE 비교</span>\n  </h2>\n  <p class=\"reveal\">EMP 3행(D1·D2 부서, A·B 직무)을 부서/직무로 집계하는 상황. 같은 데이터를 일반 GROUP BY, ROLLUP, CUBE에 차례로 넣어 어디까지 소계가 추가되는지 비교한다. 핵심은 <strong>\"부서 소계만 필요한가, 직무 소계까지 필요한가\"</strong>이다.</p>\n\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3);\">EMP</p>\n  <table class=\"reveal\">\n    <thead><tr><th>DEPT_ID</th><th>JOB</th><th>SAL</th></tr></thead>\n    <tbody>\n      <tr><td>D1</td><td>A</td><td>1000</td></tr>\n      <tr><td>D1</td><td>B</td><td>2000</td></tr>\n      <tr><td>D2</td><td>A</td><td>3000</td></tr>\n    </tbody>\n  </table>\n\n  <div class=\"ba-flow large-after reveal\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">BEFORE</span>\n      <h4 class=\"ba-h\">기본 GROUP BY (DEPT, JOB)</h4>\n      <div class=\"sql\">SELECT DEPT_ID, JOB, SUM(SAL)\nFROM EMP\nGROUP BY DEPT_ID, JOB;</div>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">D</div><div class=\"h\">J</div><div class=\"h\">SUM</div>\n        <div class=\"c\">D1</div><div class=\"c\">A</div><div class=\"c\">1000</div>\n        <div class=\"c\">D1</div><div class=\"c\">B</div><div class=\"c\">2000</div>\n        <div class=\"c\">D2</div><div class=\"c\">A</div><div class=\"c\">3000</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\">→</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">AFTER</span>\n      <h4 class=\"ba-h\">ROLLUP / CUBE</h4>\n      <div class=\"ba-tables cols-2\">\n        <div class=\"ba-mini-table\">\n          <div class=\"h\">ROLLUP(D, J)</div>\n          <div class=\"row\">D1·A · 1000</div>\n          <div class=\"row\">D1·B · 2000</div>\n          <div class=\"row\">D1·NULL · 3000</div>\n          <div class=\"row\">D2·A · 3000</div>\n          <div class=\"row\">D2·NULL · 3000</div>\n          <div class=\"row\">NULL·NULL · 6000</div>\n        </div>\n        <div class=\"ba-mini-table\">\n          <div class=\"h\">CUBE 추가 행</div>\n          <div class=\"row\">NULL · A · 4000</div>\n          <div class=\"row\">NULL · B · 2000</div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <h3 class=\"reveal\"><code>GROUP BY (DEPT, JOB)</code> — 기본</h3>\n  <table class=\"reveal\">\n    <thead><tr><th>D</th><th>J</th><th>SUM</th></tr></thead>\n    <tbody>\n      <tr><td>D1</td><td>A</td><td>1000</td></tr>\n      <tr><td>D1</td><td>B</td><td>2000</td></tr>\n      <tr><td>D2</td><td>A</td><td>3000</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\"><code>ROLLUP(DEPT, JOB)</code></h3>\n  <table class=\"reveal\">\n    <thead><tr><th>D</th><th>J</th><th>SUM</th></tr></thead>\n    <tbody>\n      <tr><td>D1</td><td>A</td><td>1000</td></tr>\n      <tr><td>D1</td><td>B</td><td>2000</td></tr>\n      <tr><td>D1</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>3000</td></tr>\n      <tr><td>D2</td><td>A</td><td>3000</td></tr>\n      <tr><td>D2</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>3000</td></tr>\n      <tr><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>6000</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\"><code>CUBE(DEPT, JOB)</code> 추가 행</h3>\n  <table class=\"reveal\">\n    <thead><tr><th>D</th><th>J</th><th>SUM</th></tr></thead>\n    <tbody>\n      <tr><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>A</td><td>4000</td></tr>\n      <tr><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>B</td><td>2000</td></tr>\n    </tbody>\n  </table>\n\n  <p class=\"reveal\">기본 GROUP BY는 (DEPT, JOB) 조합 1단계만, ROLLUP(DEPT, JOB)은 (DEPT, JOB) → (DEPT) → ()로 <strong>왼쪽부터 한 칸씩 떼어내며 소계를 쌓는다(N+1단계)</strong>. CUBE(DEPT, JOB)는 거기에 더해 (JOB) 단독 소계까지 만들어 모든 조합 2^N단계를 채운다. 부서 단위 소계만 필요하면 ROLLUP으로 충분하지만, 직무별 가로 합계까지 한 번에 보고 싶다면 CUBE가 정답이다. 더 정밀하게 특정 조합만 골라 뽑고 싶다면 GROUPING SETS를 쓴다.</p>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-2-2-3\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c224: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    윈도우 함수는 <strong>행을 합치지 않으면서</strong>, 행마다 <a href=\"#\" data-chapter=\"c223\">그룹</a>별 통계나 순위를 옆에 붙여주는 함수다(분석 함수라고도 한다).\n  </blockquote>\n  <div class=\"ex-box reveal\">\n    학생 명단을 GROUP BY로 묶으면 학년 평균만 남아 개별 정보가 사라지지만, 윈도우 함수는 <strong>학생 행은 그대로 두고 옆에 학년 평균/등수를 추가</strong>한다.\n  </div>\n\n  <!-- 개념 도식화 -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">일반 집계 vs 윈도우 함수</span>\n  </h2>\n  <div class=\"ba-flow reveal\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">GROUP BY</span>\n      <h4 class=\"ba-h\">행이 합쳐짐 (1행 결과)</h4>\n      <div class=\"sql\">SELECT AVG(SAL) FROM EMP;</div>\n      <div class=\"mini-table\">\n        <div class=\"h\">AVG</div><div class=\"h\">—</div>\n        <div class=\"c\">4000</div><div class=\"c\">—</div>\n      </div>\n      <div class=\"ba-row\">개별 데이터 사라짐</div>\n    </div>\n    <div class=\"ba-arrow\">→</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">OVER</span>\n      <h4 class=\"ba-h\">행 유지 + 옆에 분석값</h4>\n      <div class=\"sql\">AVG(SAL) OVER () + RANK()</div>\n      <div class=\"mini-table cols-4\">\n        <div class=\"h\">NAME</div><div class=\"h\">SAL</div><div class=\"h\">RANK</div><div class=\"h\">AVG</div>\n        <div class=\"c\">김</div><div class=\"c\">3000</div><div class=\"c\">3</div><div class=\"c\">4000</div>\n        <div class=\"c\">이</div><div class=\"c\">5000</div><div class=\"c\">1</div><div class=\"c\">4000</div>\n        <div class=\"c\">박</div><div class=\"c\">4000</div><div class=\"c\">2</div><div class=\"c\">4000</div>\n      </div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead><tr><th>일반 집계 (GROUP BY)</th><th>윈도우 함수 (OVER)</th></tr></thead>\n    <tbody>\n      <tr><td>행이 그룹별로 <strong>합쳐짐</strong></td><td>행은 <strong>그대로 유지</strong> + 옆에 분석값</td></tr>\n      <tr><td>결과 1행</td><td>결과 N행 (원본과 같음)</td></tr>\n      <tr><td>AVG = 4000</td><td>NAME · SAL · RANK · AVG 모두 보임</td></tr>\n    </tbody>\n  </table>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code>[원본 행]  ──OVER 절로 윈도우 정의──→  [행 그대로 유지 + 옆에 분석값 추가]</code></pre>\n\n  <!-- 기본 문법 -->\n  <h2 class=\"reveal\">기본 문법</h2>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code>함수명(컬럼) <span class=\"sql-kw\">OVER</span> (\n    <span class=\"sql-kw\">PARTITION BY</span> 그룹기준        <span class=\"sql-cm\">-- 어떻게 묶을지</span>\n    <span class=\"sql-kw\">ORDER BY</span> 정렬기준              <span class=\"sql-cm\">-- 어떻게 정렬할지</span>\n    <span class=\"sql-kw\">ROWS BETWEEN</span> ... <span class=\"sql-kw\">AND</span> ...       <span class=\"sql-cm\">-- 어디부터 어디까지(윈도우)</span>\n)</code></pre>\n\n  <div class=\"mermaid reveal\">\nflowchart TD\n    A[\"원본 행\"] --> B[\"PARTITION BY<br/>그룹 분할\"]\n    B --> C[\"ORDER BY<br/>그룹 내 정렬\"]\n    C --> D[\"ROWS / RANGE<br/>윈도우 프레임 결정\"]\n    D --> E[\"함수 적용<br/>(RANK · SUM · LAG …)\"]\n    E --> F[\"행 유지 + 옆에 분석값\"]\n  </div>\n\n  <div class=\"cls-row reveal\">\n    <div class=\"cls-card\"><span class=\"badge\">PARTITION BY</span><div class=\"name\">그룹 기준</div><div class=\"ex\">생략 시 전체. 부서별·지점별 등 윈도우 분리</div></div>\n    <div class=\"cls-card\"><span class=\"badge b-info\">ORDER BY</span><div class=\"name\">그룹 내 정렬</div><div class=\"ex\">순위·LAG/LEAD에 필수. <a href=\"#\" data-chapter=\"c216\">ORDER BY 절</a></div></div>\n    <div class=\"cls-card\"><span class=\"badge b-warn\">ROWS / RANGE</span><div class=\"name\">윈도우 프레임</div><div class=\"ex\">어디부터 어디까지 (PRECEDING/FOLLOWING)</div></div>\n  </div>\n\n  <!-- 윈도우 함수 분류 -->\n  <h2 class=\"reveal\">윈도우 함수의 분류</h2>\n  <div class=\"fn-grid cols-4 reveal\">\n    <div class=\"fn-card\">\n      <div class=\"name\">RANK</div>\n      <div class=\"desc\">동점 같은 등수, 다음 <strong>건너뜀</strong> (1, 1, 3)</div>\n      <div class=\"ex\">RANK() OVER (ORDER BY SAL DESC)</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">DENSE_RANK</div>\n      <div class=\"desc\">동점 같은 등수, 다음 <strong>연속</strong> (1, 1, 2)</div>\n      <div class=\"ex\">DENSE_RANK() OVER (...)</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">ROW_NUMBER</div>\n      <div class=\"desc\">동점 무시, <strong>모두 다른 등수</strong> (1, 2, 3)</div>\n      <div class=\"ex\">ROW_NUMBER() OVER (...)</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">NTILE(N)</div>\n      <div class=\"desc\">N등분 그룹 번호 부여</div>\n      <div class=\"ex\">NTILE(4) OVER (ORDER BY SAL DESC)</div>\n    </div>\n  </div>\n  <div class=\"fn-grid cols-4 reveal\">\n    <div class=\"fn-card\">\n      <div class=\"name\">LAG(col, n)</div>\n      <div class=\"desc\">n행 전(앞) 값. 기본 오프셋 1</div>\n      <div class=\"ex\">LAG(NAME) OVER (ORDER BY HIRE_DATE)</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">LEAD(col, n)</div>\n      <div class=\"desc\">n행 후(뒷) 값. 기본 오프셋 1</div>\n      <div class=\"ex\">LEAD(NAME) OVER (ORDER BY HIRE_DATE)</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">FIRST_VALUE / LAST_VALUE</div>\n      <div class=\"desc\">윈도우의 첫 / 마지막 값</div>\n      <div class=\"ex\">FIRST_VALUE(SAL) OVER (...)</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">SUM/AVG/COUNT/MAX/MIN</div>\n      <div class=\"desc\">행 옆에 그룹 통계</div>\n      <div class=\"ex\">AVG(SAL) OVER (PARTITION BY DEPT_ID)</div>\n    </div>\n  </div>\n\n  <!-- SQL 실전 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">함수별 사용 예제</span>\n  </h2>\n\n  <h3 class=\"reveal\">순위 함수 — RANK vs DENSE_RANK vs ROW_NUMBER</h3>\n  <div class=\"threeway reveal\">\n    <div class=\"threeway-card t-info\">\n      <div class=\"glyph\">1,1,3</div>\n      <div class=\"name\">RANK()</div>\n      <div class=\"desc\">동점 같은 등수 → 다음 등수 <strong>건너뜀</strong></div>\n    </div>\n    <div class=\"threeway-card t-warn\">\n      <div class=\"glyph\">1,1,2</div>\n      <div class=\"name\">DENSE_RANK()</div>\n      <div class=\"desc\">동점 같은 등수 → 다음 등수 <strong>연속</strong></div>\n    </div>\n    <div class=\"threeway-card t-correct\">\n      <div class=\"glyph\">1,2,3</div>\n      <div class=\"name\">ROW_NUMBER()</div>\n      <div class=\"desc\">동점 무시 → <strong>무조건 다른 등수</strong></div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead><tr><th>함수</th><th>동점 처리</th><th>다음 순위</th></tr></thead>\n    <tbody>\n      <tr><td>RANK()</td><td>같은 등수</td><td>건너뜀 (1, 1, 3)</td></tr>\n      <tr><td>DENSE_RANK()</td><td>같은 등수</td><td>연속 (1, 1, 2)</td></tr>\n      <tr><td>ROW_NUMBER()</td><td>무조건 다른 등수</td><td>(1, 2, 3)</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">EMP</span>\n    <h4 class=\"ba-h\">사원 테이블</h4>\n    <div class=\"mini-table cols-2\">\n      <div class=\"h\">NAME</div><div class=\"h\">SAL</div>\n      <div class=\"c\">이</div><div class=\"c\">5000</div>\n      <div class=\"c\">박</div><div class=\"c\">5000</div>\n      <div class=\"c\">최</div><div class=\"c\">4500</div>\n      <div class=\"c\">김</div><div class=\"c\">3000</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">SAL</span>,\n        <span class=\"sql-kw\">RANK</span>()       <span class=\"sql-kw\">OVER</span> (<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">DESC</span>) <span class=\"sql-kw\">AS</span> R,\n        <span class=\"sql-kw\">DENSE_RANK</span>() <span class=\"sql-kw\">OVER</span> (<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">DESC</span>) <span class=\"sql-kw\">AS</span> DR,\n        <span class=\"sql-kw\">ROW_NUMBER</span>() <span class=\"sql-kw\">OVER</span> (<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">DESC</span>) <span class=\"sql-kw\">AS</span> RN\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>SAL</th><th>R</th><th>DR</th><th>RN</th></tr></thead>\n    <tbody>\n      <tr><td>이</td><td>5000</td><td>1</td><td>1</td><td>1</td></tr>\n      <tr><td>박</td><td>5000</td><td>1</td><td>1</td><td>2</td></tr>\n      <tr><td>최</td><td>4500</td><td>3</td><td>2</td><td>3</td></tr>\n      <tr><td>김</td><td>3000</td><td>4</td><td>3</td><td>4</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 이·박이 5000으로 동률. RANK는 다음을 3으로 건너뛰고, DENSE_RANK는 2로 연속, ROW_NUMBER는 동률 무시하고 1·2를 다르게 매긴다.</p>\n\n  <h3 class=\"reveal\">집계 윈도우 함수</h3>\n  <table class=\"reveal\">\n    <thead><tr><th>함수</th><th>의미</th></tr></thead>\n    <tbody>\n      <tr><td>SUM/AVG/MAX/MIN/COUNT</td><td>행 옆에 그룹 통계</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">EMP</span>\n    <h4 class=\"ba-h\">사원 테이블 (부서·급여)</h4>\n    <div class=\"mini-table cols-3\">\n      <div class=\"h\">NAME</div><div class=\"h\">DEPT_ID</div><div class=\"h\">SAL</div>\n      <div class=\"c\">김</div><div class=\"c\">D1</div><div class=\"c\">3000</div>\n      <div class=\"c\">이</div><div class=\"c\">D1</div><div class=\"c\">5000</div>\n      <div class=\"c\">박</div><div class=\"c\">D2</div><div class=\"c\">4000</div>\n      <div class=\"c\">최</div><div class=\"c\">D2</div><div class=\"c\">4000</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 부서별 평균 급여를 옆에 붙임</span>\n<span class=\"sql-kw\">SELECT</span>  <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-type\">SAL</span>,\n        <span class=\"sql-kw\">AVG</span>(<span class=\"sql-type\">SAL</span>) <span class=\"sql-kw\">OVER</span> (<span class=\"sql-kw\">PARTITION BY</span> <span class=\"sql-type\">DEPT_ID</span>) <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">DEPT_AVG</span>\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>DEPT_ID</th><th>SAL</th><th>DEPT_AVG</th></tr></thead>\n    <tbody>\n      <tr><td>김</td><td>D1</td><td>3000</td><td>4000</td></tr>\n      <tr><td>이</td><td>D1</td><td>5000</td><td>4000</td></tr>\n      <tr><td>박</td><td>D2</td><td>4000</td><td>4000</td></tr>\n      <tr><td>최</td><td>D2</td><td>4000</td><td>4000</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ <code>PARTITION BY DEPT_ID</code>로 D1·D2를 나눠 각 부서 평균을 행마다 붙인다. 행은 합쳐지지 않고 4행 그대로.</p>\n\n  <h3 class=\"reveal\">행 순서 함수</h3>\n  <table class=\"reveal\">\n    <thead><tr><th>함수</th><th>의미</th></tr></thead>\n    <tbody>\n      <tr><td>LAG(col, n)</td><td>n행 전 값(앞 행)</td></tr>\n      <tr><td>LEAD(col, n)</td><td>n행 후 값(뒷 행)</td></tr>\n      <tr><td>FIRST_VALUE(col)</td><td>윈도우의 첫 값</td></tr>\n      <tr><td>LAST_VALUE(col)</td><td>윈도우의 마지막 값</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">EMP</span>\n    <h4 class=\"ba-h\">입사일 순 사원</h4>\n    <div class=\"mini-table cols-2\">\n      <div class=\"h\">NAME</div><div class=\"h\">HIRE_DATE</div>\n      <div class=\"c\">김</div><div class=\"c\">2020-01</div>\n      <div class=\"c\">이</div><div class=\"c\">2021-03</div>\n      <div class=\"c\">박</div><div class=\"c\">2022-07</div>\n      <div class=\"c\">최</div><div class=\"c\">2023-09</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">HIRE_DATE</span>,\n        <span class=\"sql-kw\">LAG</span>(<span class=\"sql-type\">NAME</span>)  <span class=\"sql-kw\">OVER</span> (<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">HIRE_DATE</span>) <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">PREV_EMP</span>,\n        <span class=\"sql-kw\">LEAD</span>(<span class=\"sql-type\">NAME</span>) <span class=\"sql-kw\">OVER</span> (<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">HIRE_DATE</span>) <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">NEXT_EMP</span>\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>HIRE_DATE</th><th>PREV_EMP</th><th>NEXT_EMP</th></tr></thead>\n    <tbody>\n      <tr><td>김</td><td>2020-01</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td><td>이</td></tr>\n      <tr><td>이</td><td>2021-03</td><td>김</td><td>박</td></tr>\n      <tr><td>박</td><td>2022-07</td><td>이</td><td>최</td></tr>\n      <tr><td>최</td><td>2023-09</td><td>박</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\">첫 행에는 LAG가 NULL, 마지막 행에는 LEAD가 NULL이다(기본 오프셋 1).</p>\n\n  <h3 class=\"reveal\">비율 함수</h3>\n  <table class=\"reveal\">\n    <thead><tr><th>함수</th><th>의미</th></tr></thead>\n    <tbody>\n      <tr><td>CUME_DIST()</td><td>누적 비율</td></tr>\n      <tr><td>PERCENT_RANK()</td><td>백분위 순위</td></tr>\n      <tr><td>NTILE(N)</td><td>N등분 그룹</td></tr>\n      <tr><td>RATIO_TO_REPORT(col)</td><td>전체 합 대비 비율(Oracle)</td></tr>\n    </tbody>\n  </table>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 4등분으로 나눠서 그룹 번호 부여</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">SAL</span>, <span class=\"sql-kw\">NTILE</span>(<span class=\"sql-num\">4</span>) <span class=\"sql-kw\">OVER</span> (<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">DESC</span>) <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">QUARTILE</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span>;</code></pre>\n\n  <h3 class=\"reveal\">윈도우 프레임 — ROWS / RANGE</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW</span>   <span class=\"sql-cm\">-- 처음~현재</span>\n<span class=\"sql-kw\">ROWS BETWEEN</span> <span class=\"sql-num\">1</span> <span class=\"sql-kw\">PRECEDING AND</span> <span class=\"sql-num\">1</span> <span class=\"sql-kw\">FOLLOWING</span>           <span class=\"sql-cm\">-- 앞1, 자신, 뒤1</span>\n<span class=\"sql-kw\">RANGE BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING</span>  <span class=\"sql-cm\">-- 전체</span></code></pre>\n  <table class=\"reveal\">\n    <thead><tr><th>키워드</th><th>의미</th></tr></thead>\n    <tbody>\n      <tr><td>UNBOUNDED PRECEDING</td><td>그룹의 처음부터</td></tr>\n      <tr><td>n PRECEDING</td><td>앞 n번째부터</td></tr>\n      <tr><td>CURRENT ROW</td><td>현재 행</td></tr>\n      <tr><td>n FOLLOWING</td><td>뒤 n번째까지</td></tr>\n      <tr><td>UNBOUNDED FOLLOWING</td><td>그룹의 끝까지</td></tr>\n    </tbody>\n  </table>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 누적 합(running total)</span>\n<span class=\"sql-kw\">SELECT</span>  <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">HIRE_DATE</span>, <span class=\"sql-type\">SAL</span>,\n        <span class=\"sql-kw\">SUM</span>(<span class=\"sql-type\">SAL</span>) <span class=\"sql-kw\">OVER</span> (<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">HIRE_DATE</span>\n                       <span class=\"sql-kw\">ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW</span>) <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">RUN_TOT</span>\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>HIRE_DATE</th><th>SAL</th><th>RUN_TOT</th></tr></thead>\n    <tbody>\n      <tr><td>김</td><td>2020-01</td><td>3000</td><td>3000</td></tr>\n      <tr><td>이</td><td>2021-03</td><td>5000</td><td>8000</td></tr>\n      <tr><td>박</td><td>2022-07</td><td>4000</td><td>12000</td></tr>\n      <tr><td>최</td><td>2023-09</td><td>4000</td><td>16000</td></tr>\n    </tbody>\n  </table>\n\n  <!-- Before & After -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">PARTITION BY로 부서별 RANK + AVG</span>\n  </h2>\n  <p class=\"reveal\">D1·D2 두 부서 4명에 대해 <strong>\"부서 안에서의 등수\"와 \"부서 평균\"</strong>을 동시에 한 표에 보여줘야 하는 상황. GROUP BY로 묶으면 4행이 2행으로 줄어 개별 이름이 사라지지만, 윈도우 함수는 4행을 그대로 유지하면서 옆에 부서별 RANK와 부서 AVG를 붙인다. D2의 박·최가 4500으로 동률일 때 RANK가 어떻게 매겨지는지도 함께 본다.</p>\n\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3);\">EMP</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>DEPT_ID</th><th>SAL</th></tr></thead>\n    <tbody>\n      <tr><td>김</td><td>D1</td><td>3000</td></tr>\n      <tr><td>이</td><td>D1</td><td>5000</td></tr>\n      <tr><td>박</td><td>D2</td><td>4500</td></tr>\n      <tr><td>최</td><td>D2</td><td>4500</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">쿼리</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-type\">SAL</span>,\n        <span class=\"sql-kw\">RANK</span>() <span class=\"sql-kw\">OVER</span> (<span class=\"sql-kw\">PARTITION BY</span> <span class=\"sql-type\">DEPT_ID</span> <span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">DESC</span>) <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">DEPT_RANK</span>,\n        <span class=\"sql-kw\">AVG</span>(<span class=\"sql-type\">SAL</span>) <span class=\"sql-kw\">OVER</span> (<span class=\"sql-kw\">PARTITION BY</span> <span class=\"sql-type\">DEPT_ID</span>) <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">DEPT_AVG</span>\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span>;</code></pre>\n\n  <div class=\"ba-flow large-after reveal\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">BEFORE</span>\n      <h4 class=\"ba-h\">GROUP BY DEPT_ID로 묶으면</h4>\n      <div class=\"sql\">SELECT DEPT_ID, AVG(SAL)\nFROM EMP\nGROUP BY DEPT_ID;</div>\n      <div class=\"mini-table\">\n        <div class=\"h\">DEPT_ID</div><div class=\"h\">AVG</div>\n        <div class=\"c\">D1</div><div class=\"c\">4000</div>\n        <div class=\"c\">D2</div><div class=\"c\">4500</div>\n      </div>\n      <div class=\"ba-row\">개별 이름 사라짐 (4행 → 2행)</div>\n    </div>\n    <div class=\"ba-arrow\">→</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">AFTER</span>\n      <h4 class=\"ba-h\">윈도우 함수: 4행 유지 + 옆에 RANK·AVG</h4>\n      <div class=\"mini-table cols-4\">\n        <div class=\"h\">NAME</div><div class=\"h\">SAL</div><div class=\"h\">DEPT_RANK</div><div class=\"h\">DEPT_AVG</div>\n        <div class=\"c\">이</div><div class=\"c\">5000</div><div class=\"c\">1</div><div class=\"c\">4000</div>\n        <div class=\"c\">김</div><div class=\"c\">3000</div><div class=\"c\">2</div><div class=\"c\">4000</div>\n        <div class=\"c\">박</div><div class=\"c\">4500</div><div class=\"c\">1</div><div class=\"c\">4500</div>\n        <div class=\"c\">최</div><div class=\"c\">4500</div><div class=\"c\">1</div><div class=\"c\">4500</div>\n      </div>\n    </div>\n  </div>\n\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>DEPT_ID</th><th>SAL</th><th>DEPT_RANK</th><th>DEPT_AVG</th></tr></thead>\n    <tbody>\n      <tr><td>이</td><td>D1</td><td>5000</td><td>1</td><td>4000</td></tr>\n      <tr><td>김</td><td>D1</td><td>3000</td><td>2</td><td>4000</td></tr>\n      <tr><td>박</td><td>D2</td><td>4500</td><td>1</td><td>4500</td></tr>\n      <tr><td>최</td><td>D2</td><td>4500</td><td>1</td><td>4500</td></tr>\n    </tbody>\n  </table>\n\n  <p class=\"reveal\"><code>PARTITION BY DEPT_ID</code>가 D1·D2를 각각 독립된 윈도우로 나누기 때문에 RANK와 AVG가 부서별로 따로 계산된다. D2의 박·최가 둘 다 RANK 1을 받는 이유는 <strong>RANK()가 동률을 같은 등수</strong>로 처리하기 때문이고(다음 등수는 3으로 건너뜀), AVG도 부서 안 두 명만으로 계산해 4500이 된다. <strong>행을 합치지 않고 옆에 통계를 붙이는 윈도우 함수의 본질</strong>이 같은 부서 두 명의 SAL이 그대로 보이면서 평균·등수가 함께 따라붙는 결과로 드러난다.</p>\n\n  <!-- 윈도우 함수 vs GROUP BY -->\n  <h2 class=\"reveal\">윈도우 함수 vs GROUP BY</h2>\n  <table class=\"reveal\">\n    <thead><tr><th>항목</th><th>GROUP BY</th><th>윈도우 함수</th></tr></thead>\n    <tbody>\n      <tr><td>결과 행수</td><td>줄어듦(그룹별 1행)</td><td>유지(원본 그대로)</td></tr>\n      <tr><td>개별 데이터</td><td>사라짐</td><td>남음</td></tr>\n      <tr><td>사용 목적</td><td>집계 결과만</td><td>개별 + 집계</td></tr>\n    </tbody>\n  </table>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-2-2-4\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c225: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    Top N 쿼리는 <strong>상위 N개 행</strong>만 뽑는 쿼리다(예: 매출 상위 10개 상품, 최신 5건의 주문).\n  </blockquote>\n\n  <!-- 개념 도식화 -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">Top N의 4가지 방법</span>\n  </h2>\n  <div class=\"threeway cols-4 reveal\">\n    <div class=\"threeway-card t-warn\">\n      <div class=\"glyph\">ROWNUM</div>\n      <div class=\"name\">Oracle ROWNUM</div>\n      <div class=\"desc\">의사 컬럼 · <strong>정렬 전</strong> 매겨짐 · 인라인뷰 필수</div>\n    </div>\n    <div class=\"threeway-card t-correct\">\n      <div class=\"glyph\">FETCH</div>\n      <div class=\"name\">표준 FETCH FIRST</div>\n      <div class=\"desc\">Oracle 12c+ · OFFSET · WITH TIES · PERCENT</div>\n    </div>\n    <div class=\"threeway-card t-info\">\n      <div class=\"glyph\">TOP</div>\n      <div class=\"name\">MS-SQL TOP</div>\n      <div class=\"desc\"><code>SELECT TOP n</code> · <code>TOP n WITH TIES</code></div>\n    </div>\n    <div class=\"threeway-card t-danger\">\n      <div class=\"glyph\">ROW#</div>\n      <div class=\"name\">윈도우 함수</div>\n      <div class=\"desc\"><code>ROW_NUMBER() OVER</code> · <strong>PARTITION BY</strong>로 그룹별 가능</div>\n    </div>\n  </div>\n\n  <h3 class=\"reveal\">실행 순서 — 정렬 → Top N 적용</h3>\n  <div class=\"timeline reveal\">\n    <div class=\"timeline-track\">\n      <div class=\"tl-step\">\n        <div class=\"label\">STEP 1</div>\n        <div class=\"dot\"></div>\n        <div class=\"body\">원본 테이블 <code>EMP</code> 스캔</div>\n      </div>\n      <div class=\"tl-step\">\n        <div class=\"label\">STEP 2</div>\n        <div class=\"dot\"></div>\n        <div class=\"body\"><code>ORDER BY SAL DESC</code><br/>정렬 먼저</div>\n      </div>\n      <div class=\"tl-step\">\n        <div class=\"label\">STEP 3</div>\n        <div class=\"dot\"></div>\n        <div class=\"body\">번호 매김<br/><code>ROWNUM</code> · <code>ROW_NUMBER()</code></div>\n      </div>\n      <div class=\"tl-step\">\n        <div class=\"label\">STEP 4</div>\n        <div class=\"dot\"></div>\n        <div class=\"body\">상위 N개 자르기<br/><code>WHERE RN &lt;= N</code></div>\n      </div>\n    </div>\n  </div>\n  <p class=\"reveal\">ROWNUM 함정의 본질이 여기 있다 — STEP 2(정렬) 전에 STEP 3(번호)이 먼저 매겨지면 의도와 다른 5명이 잘려 나온다. 그래서 인라인뷰로 정렬을 먼저 끝내야 한다.</p>\n\n  <!-- SQL 실전 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">방식별 구현</span>\n  </h2>\n\n  <h3 class=\"reveal\">Oracle ROWNUM</h3>\n  <p class=\"reveal\">ROWNUM은 행이 만들어진 순서대로 1, 2, 3...이 매겨지는 의사 컬럼이다.</p>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — 아래 모든 SQL은 이 EMP를 사용</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">EMP</span>\n    <h4 class=\"ba-h\">사원 테이블 (5명)</h4>\n    <div class=\"mini-table cols-2\">\n      <div class=\"h\">NAME</div><div class=\"h\">SAL</div>\n      <div class=\"c\">김</div><div class=\"c\">3000</div>\n      <div class=\"c\">이</div><div class=\"c\">5000</div>\n      <div class=\"c\">박</div><div class=\"c\">4500</div>\n      <div class=\"c\">최</div><div class=\"c\">4500</div>\n      <div class=\"c\">홍</div><div class=\"c\">2000</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  *\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">WHERE</span>   <span class=\"sql-kw\">ROWNUM</span> &lt;= <span class=\"sql-num\">3</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 — 정렬 없이 저장 순서 앞 3행</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>SAL</th></tr></thead>\n    <tbody>\n      <tr><td>김</td><td>3000</td></tr>\n      <tr><td>이</td><td>5000</td></tr>\n      <tr><td>박</td><td>4500</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ \"급여 상위 3명\"이 의도였다면 이 결과는 틀렸다. ROWNUM이 정렬 전 매겨지기 때문.</p>\n\n  <h4 class=\"reveal\">ROWNUM의 함정</h4>\n  <p class=\"reveal\">ROWNUM은 <a href=\"#\" data-chapter=\"c216\">ORDER BY</a> 적용 전에 매겨지므로 정렬을 먼저 한 인라인 뷰를 감싸야 한다.</p>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 잘못된 예: 정렬 전에 ROWNUM이 매겨짐</span>\n<span class=\"sql-kw\">SELECT</span> *\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">WHERE</span>  <span class=\"sql-kw\">ROWNUM</span> &lt;= <span class=\"sql-num\">5</span>\n<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">DESC</span>;     <span class=\"sql-cm\">-- 5개 추출 후 정렬되어 의도와 다름</span>\n\n<span class=\"sql-cm\">-- 올바른 예: 인라인 뷰로 정렬 먼저</span>\n<span class=\"sql-kw\">SELECT</span> *\n<span class=\"sql-kw\">FROM</span>   (<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">DESC</span>)\n<span class=\"sql-kw\">WHERE</span>  <span class=\"sql-kw\">ROWNUM</span> &lt;= <span class=\"sql-num\">5</span>;</code></pre>\n  <table class=\"reveal\">\n    <thead><tr><th>조건</th><th>결과</th></tr></thead>\n    <tbody>\n      <tr><td><code>ROWNUM = 1</code></td><td>가능</td></tr>\n      <tr><td><code>ROWNUM &lt;= 5</code></td><td>가능</td></tr>\n      <tr><td><code>ROWNUM = 5</code></td><td>결과 없음</td></tr>\n      <tr><td><code>ROWNUM &gt; 5</code></td><td>결과 없음</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\">ROWNUM은 1부터 시작하므로 \"5번째만\"을 ROWNUM = 5로 표현할 수 없다.</p>\n\n  <h3 class=\"reveal\">표준 FETCH FIRST (Oracle 12c+)</h3>\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3);\">EMP — 이 5000 / 박 4500 / 최 4500 (박·최 SAL 동률) 기준. <code>ROWS ONLY</code>와 <code>WITH TIES</code> 차이를 명확히 보려면 상위 2개로 비교.</p>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 상위 2개 (정확히 N행)</span>\n<span class=\"sql-kw\">SELECT</span> *\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">DESC</span>\n<span class=\"sql-kw\">FETCH FIRST</span> <span class=\"sql-num\">2</span> <span class=\"sql-kw\">ROWS ONLY</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (2행) — 4500 동률 중 한 명만 임의로 포함(비결정적)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>SAL</th></tr></thead>\n    <tbody>\n      <tr><td>이</td><td>5000</td></tr>\n      <tr><td>박 또는 최</td><td>4500</td></tr>\n    </tbody>\n  </table>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 상위 2개 (동률 포함)</span>\n<span class=\"sql-kw\">SELECT</span> *\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">DESC</span>\n<span class=\"sql-kw\">FETCH FIRST</span> <span class=\"sql-num\">2</span> <span class=\"sql-kw\">ROWS WITH TIES</span>;     <span class=\"sql-cm\">-- 마지막 행 동률은 모두 포함</span>\n\n<span class=\"sql-cm\">-- 상위 10%(백분율)</span>\n<span class=\"sql-kw\">SELECT</span> *\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">DESC</span>\n<span class=\"sql-kw\">FETCH FIRST</span> <span class=\"sql-num\">10</span> <span class=\"sql-kw\">PERCENT ROWS ONLY</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ WITH TIES 결과 — 4500 동률 두 명 모두 포함되어 3행</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>SAL</th></tr></thead>\n    <tbody>\n      <tr><td>이</td><td>5000</td></tr>\n      <tr><td>박</td><td>4500</td></tr>\n      <tr><td>최</td><td>4500</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ <code>ROWS ONLY</code>는 정확히 N행(동률은 잘림), <code>WITH TIES</code>는 마지막 N등과 동률인 행을 모두 포함해 N+α행이 될 수 있다.</p>\n  <table class=\"reveal\">\n    <thead><tr><th>옵션</th><th>의미</th></tr></thead>\n    <tbody>\n      <tr><td><code>FETCH FIRST n ROWS ONLY</code></td><td>정확히 n개</td></tr>\n      <tr><td><code>FETCH FIRST n ROWS WITH TIES</code></td><td>n등 동률은 모두 포함</td></tr>\n      <tr><td><code>OFFSET n ROWS</code></td><td>n개 건너뛰고</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">MS-SQL TOP</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT TOP</span> <span class=\"sql-num\">5</span> *\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">DESC</span>;\n\n<span class=\"sql-cm\">-- 동률 포함</span>\n<span class=\"sql-kw\">SELECT TOP</span> <span class=\"sql-num\">5</span> <span class=\"sql-kw\">WITH TIES</span> *\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">DESC</span>;</code></pre>\n\n  <h3 class=\"reveal\"><a href=\"#\" data-chapter=\"c224\">윈도우 함수</a> — 부서별 Top N</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 부서별 급여 상위 3명</span>\n<span class=\"sql-kw\">SELECT</span> *\n<span class=\"sql-kw\">FROM</span>   (<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">DEPT_ID</span>, <span class=\"sql-type\">SAL</span>,\n               <span class=\"sql-kw\">ROW_NUMBER</span>() <span class=\"sql-kw\">OVER</span> (<span class=\"sql-kw\">PARTITION BY</span> <span class=\"sql-type\">DEPT_ID</span> <span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">DESC</span>) <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">RN</span>\n        <span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span>)\n<span class=\"sql-kw\">WHERE</span>  <span class=\"sql-type\">RN</span> &lt;= <span class=\"sql-num\">3</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (D1·D2 부서 각각 Top 2 — RN 매김 결과)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>DEPT_ID</th><th>SAL</th><th>RN</th></tr></thead>\n    <tbody>\n      <tr><td>이</td><td>D1</td><td>5000</td><td>1</td></tr>\n      <tr><td>김</td><td>D1</td><td>3000</td><td>2</td></tr>\n      <tr><td>박</td><td>D2</td><td>4500</td><td>1</td></tr>\n      <tr><td>최</td><td>D2</td><td>4500</td><td>2</td></tr>\n    </tbody>\n  </table>\n  <table class=\"reveal\">\n    <thead><tr><th>함수</th><th>동률 처리</th></tr></thead>\n    <tbody>\n      <tr><td><code>ROW_NUMBER()</code></td><td>무조건 다른 번호 → 정확히 N개</td></tr>\n      <tr><td><code>RANK()</code></td><td>동률 같은 등수, 건너뜀</td></tr>\n      <tr><td><code>DENSE_RANK()</code></td><td>동률 같은 등수, 연속</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">페이징(Pagination)</h3>\n  <p class=\"reveal\">\"1페이지: 1-10번째, 2페이지: 11-20번째...\"</p>\n  <h4 class=\"reveal\">Oracle</h4>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 11~20번째</span>\n<span class=\"sql-kw\">SELECT</span> *\n<span class=\"sql-kw\">FROM</span>   (<span class=\"sql-kw\">SELECT</span> <span class=\"sql-kw\">ROWNUM</span> <span class=\"sql-type\">RN</span>, <span class=\"sql-type\">X</span>.*\n        <span class=\"sql-kw\">FROM</span>   (<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">DESC</span>) <span class=\"sql-type\">X</span>\n        <span class=\"sql-kw\">WHERE</span>  <span class=\"sql-kw\">ROWNUM</span> &lt;= <span class=\"sql-num\">20</span>)\n<span class=\"sql-kw\">WHERE</span>  <span class=\"sql-type\">RN</span> &gt;= <span class=\"sql-num\">11</span>;</code></pre>\n  <h4 class=\"reveal\">표준 (Oracle 12c+)</h4>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span> *\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">ORDER BY</span> <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">DESC</span>\n<span class=\"sql-kw\">OFFSET</span> <span class=\"sql-num\">10</span> <span class=\"sql-kw\">ROWS FETCH NEXT</span> <span class=\"sql-num\">10</span> <span class=\"sql-kw\">ROWS ONLY</span>;</code></pre>\n\n  <!-- Before & After -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">동률이 들어오면 갈라진다</span>\n  </h2>\n  <p class=\"reveal\">EMP 5명에서 급여 상위 3명을 뽑는 상황. 박·최가 4500으로 동률이라는 점이 핵심 차이를 만든다. 같은 \"Top 3\" 요구라도 ROWNUM 기반(정확히 3명)과 WITH TIES(동률 모두 포함)가 어떻게 갈라지는지 비교한다.</p>\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3); margin-top: 0;\">EMP 테이블</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>SAL</th></tr></thead>\n    <tbody>\n      <tr><td>김</td><td>3000</td></tr>\n      <tr><td>이</td><td>5000</td></tr>\n      <tr><td>박</td><td>4500</td></tr>\n      <tr><td>최</td><td>4500</td></tr>\n      <tr><td>홍</td><td>2000</td></tr>\n    </tbody>\n  </table>\n  <div class=\"ba-flow reveal\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">ROWNUM</span>\n      <h4 class=\"ba-h\">정확히 N개 (인라인뷰 + ROWNUM)</h4>\n      <div class=\"sql\">SELECT * FROM (SELECT * FROM EMP ORDER BY SAL DESC) WHERE ROWNUM &lt;= 3;</div>\n      <div class=\"mini-table\">\n        <div class=\"h\">NAME</div><div class=\"h\">SAL</div>\n        <div class=\"c\">이</div><div class=\"c\">5000</div>\n        <div class=\"c\">박</div><div class=\"c\">4500</div>\n        <div class=\"c\">최</div><div class=\"c\">4500</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\">↔</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">WITH TIES</span>\n      <h4 class=\"ba-h\">동률 모두 포함 (4명 이상 가능)</h4>\n      <div class=\"sql\">SELECT * FROM EMP ORDER BY SAL DESC FETCH FIRST 3 ROWS WITH TIES;</div>\n      <div class=\"mini-table\">\n        <div class=\"h\">NAME</div><div class=\"h\">SAL</div>\n        <div class=\"c\">이</div><div class=\"c\">5000</div>\n        <div class=\"c\">박</div><div class=\"c\">4500</div>\n        <div class=\"c\">최</div><div class=\"c\">4500</div>\n      </div>\n    </div>\n  </div>\n  <p class=\"reveal\">이 예에서는 박·최 두 명이 4500이라 마침 정확히 3명이 떨어졌지만, 만약 4500이 한 명 더 있었다면 ROWNUM 방식은 그중 임의의 3명만, WITH TIES는 동률 전원을 포함해 4명 이상을 반환한다. 즉 \"정확한 N개\"가 필요하면 <code>ROW_NUMBER()</code>/ROWNUM, \"공평하게 동률 포함\"이 원칙이면 WITH TIES나 RANK()를 써야 한다. 결과 행 수가 입력 데이터에 따라 달라질 수 있다는 점이 Top N 쿼리에서 가장 흔히 놓치는 함정이다.</p>\n\n  <!-- ROWNUM vs ROW_NUMBER() -->\n  <h2 class=\"reveal\">ROWNUM vs ROW_NUMBER()</h2>\n  <table class=\"reveal\">\n    <thead><tr><th>항목</th><th>ROWNUM</th><th>ROW_NUMBER()</th></tr></thead>\n    <tbody>\n      <tr><td>정렬 적용 시점</td><td>WHERE보다 먼저(정렬 전)</td><td>OVER에 ORDER BY 명시</td></tr>\n      <tr><td>그룹별 번호</td><td>불가</td><td>가능(PARTITION BY)</td></tr>\n      <tr><td><code>=N</code> 사용</td><td>안 됨(1만 가능)</td><td>가능</td></tr>\n    </tbody>\n  </table>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-2-2-5\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c226: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    계층형 질의는 <strong>트리 구조 데이터(예: 조직도)</strong>를 위에서 아래로 펼치는 쿼리다. 셀프 조인은 같은 테이블을 자기 자신과 조인하는 것이다.\n  </blockquote>\n  <div class=\"ex-box reveal\">\n    가족 족보를 \"사람ID, 부모ID\" 한 테이블에 저장한 뒤 <code>CONNECT BY</code>로 할아버지 → 아버지 → 나 순으로 펼쳐 보는 쿼리.\n  </div>\n\n  <!-- 개념 도식화 -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">계층형 데이터의 모양</span>\n  </h2>\n  <div class=\"layer-stack reveal\">\n    <div class=\"layer-stack-track\">\n      <div class=\"layer-row\">\n        <div class=\"icon\">L1</div>\n        <div class=\"body\">\n          <div class=\"name\">사장 <small>E1 · MGR_ID = NULL</small></div>\n          <div class=\"desc\">루트(최상위) — START WITH의 시작점</div>\n        </div>\n        <div class=\"arrow\">↓</div>\n      </div>\n      <div class=\"layer-row\">\n        <div class=\"icon\">L2</div>\n        <div class=\"body\">\n          <div class=\"name\">매니저A · 매니저B <small>E2, E3 · MGR_ID = E1</small></div>\n          <div class=\"desc\">사장의 직속 자식 두 명 (형제 관계)</div>\n        </div>\n        <div class=\"arrow\">↓</div>\n      </div>\n      <div class=\"layer-row\">\n        <div class=\"icon\">L3</div>\n        <div class=\"body\">\n          <div class=\"name\">사원 <small>E4 · MGR_ID = E2</small></div>\n          <div class=\"desc\">매니저A의 자식 — 리프(잎)</div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead><tr><th>EMP_ID</th><th>NAME</th><th>MGR_ID</th></tr></thead>\n    <tbody>\n      <tr><td>E1</td><td>사장</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td></tr>\n      <tr><td>E2</td><td>매니저A</td><td>E1</td></tr>\n      <tr><td>E3</td><td>매니저B</td><td>E1</td></tr>\n      <tr><td>E4</td><td>사원</td><td>E2</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">조직도 트리</h3>\n  <div class=\"tree-diagram reveal\">\n    <ul>\n      <li><span class=\"node root\">사장 <span class=\"meta\">E1 · LEVEL 1</span></span>\n        <ul>\n          <li><span class=\"node\">매니저A <span class=\"meta\">E2 · LEVEL 2</span></span>\n            <ul>\n              <li><span class=\"node\">사원 <span class=\"meta\">E4 · LEVEL 3 · LEAF</span></span></li>\n            </ul>\n          </li>\n          <li><span class=\"node\">매니저B <span class=\"meta\">E3 · LEVEL 2 · LEAF</span></span></li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n  <p class=\"reveal\">평면 4행이 트리로 펼쳐지면 LEVEL이 1·2·3으로 자연스레 매겨지고, 자식이 없는 매니저B와 사원이 LEAF가 된다.</p>\n\n  <!-- CONNECT BY -->\n  <h2 class=\"reveal\">CONNECT BY (Oracle 계층형 질의)</h2>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — 아래 모든 SQL은 이 EMP를 사용</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">EMP</span>\n    <h4 class=\"ba-h\">사원 테이블 (자기 참조)</h4>\n    <div class=\"mini-table cols-3\">\n      <div class=\"h\">EMP_ID</div><div class=\"h\">NAME</div><div class=\"h\">MGR_ID</div>\n      <div class=\"c\">E1</div><div class=\"c\">사장</div><div class=\"c is-null\">NULL</div>\n      <div class=\"c\">E2</div><div class=\"c\">매니저A</div><div class=\"c\">E1</div>\n      <div class=\"c\">E3</div><div class=\"c\">매니저B</div><div class=\"c\">E1</div>\n      <div class=\"c\">E4</div><div class=\"c\">사원</div><div class=\"c\">E2</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  <span class=\"sql-kw\">LEVEL</span>,\n        <span class=\"sql-type\">EMP_ID</span>, <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">MGR_ID</span>\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">START WITH</span> <span class=\"sql-type\">MGR_ID</span> <span class=\"sql-kw\">IS NULL</span>          <span class=\"sql-cm\">-- 시작점(루트)</span>\n<span class=\"sql-kw\">CONNECT BY PRIOR</span> <span class=\"sql-type\">EMP_ID</span> = <span class=\"sql-type\">MGR_ID</span>;  <span class=\"sql-cm\">-- 부모-자식 관계</span></code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 — 깊이 우선으로 트리 펼침, LEVEL이 1·2·3 매겨짐</p>\n  <table class=\"reveal\">\n    <thead><tr><th>LEVEL</th><th>EMP_ID</th><th>NAME</th><th>MGR_ID</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td>E1</td><td>사장</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td></tr>\n      <tr><td>2</td><td>E2</td><td>매니저A</td><td>E1</td></tr>\n      <tr><td>3</td><td>E4</td><td>사원</td><td>E2</td></tr>\n      <tr><td>2</td><td>E3</td><td>매니저B</td><td>E1</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 매니저A의 자식(사원)이 먼저 따라붙은 뒤 매니저B가 출력된다(깊이 우선).</p>\n\n  <div class=\"fn-grid cols-3 reveal\">\n    <div class=\"fn-card\">\n      <div class=\"name\">START WITH</div>\n      <div class=\"desc\">루트 행 조건</div>\n      <div class=\"ex\">START WITH MGR_ID IS NULL</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">CONNECT BY PRIOR</div>\n      <div class=\"desc\">부모-자식 연결</div>\n      <div class=\"ex\">PRIOR EMP_ID = MGR_ID</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">LEVEL</div>\n      <div class=\"desc\">깊이(1=루트)</div>\n      <div class=\"ex\">SELECT LEVEL ...</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">CONNECT_BY_ROOT</div>\n      <div class=\"desc\">루트의 컬럼값</div>\n      <div class=\"ex\">CONNECT_BY_ROOT NAME</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">CONNECT_BY_ISLEAF</div>\n      <div class=\"desc\">리프(잎)이면 1</div>\n      <div class=\"ex\">CONNECT_BY_ISLEAF</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">SYS_CONNECT_BY_PATH</div>\n      <div class=\"desc\">경로 표시</div>\n      <div class=\"ex\">SYS_CONNECT_BY_PATH(NAME, '/')</div>\n    </div>\n  </div>\n\n  <h3 class=\"reveal\">PRIOR 위치</h3>\n  <table class=\"reveal\">\n    <thead><tr><th>표현</th><th>의미</th></tr></thead>\n    <tbody>\n      <tr><td><code>PRIOR EMP_ID = MGR_ID</code></td><td>순방향: 부모→자식</td></tr>\n      <tr><td><code>PRIOR MGR_ID = EMP_ID</code></td><td>역방향: 자식→부모</td></tr>\n    </tbody>\n  </table>\n\n  <!-- SQL 실전 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">계층형 질의</span>\n  </h2>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  <span class=\"sql-kw\">LEVEL</span>,\n        <span class=\"sql-kw\">LPAD</span>(<span class=\"sql-str\">' '</span>, (<span class=\"sql-kw\">LEVEL</span>-<span class=\"sql-num\">1</span>)*<span class=\"sql-num\">4</span>) || <span class=\"sql-type\">NAME</span> <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">TREE</span>,\n        <span class=\"sql-kw\">SYS_CONNECT_BY_PATH</span>(<span class=\"sql-type\">NAME</span>, <span class=\"sql-str\">'/'</span>) <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">PATH</span>\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">START WITH</span> <span class=\"sql-type\">MGR_ID</span> <span class=\"sql-kw\">IS NULL</span>\n<span class=\"sql-kw\">CONNECT BY PRIOR</span> <span class=\"sql-type\">EMP_ID</span> = <span class=\"sql-type\">MGR_ID</span>;</code></pre>\n  <h4 class=\"reveal\">결과</h4>\n  <table class=\"reveal\">\n    <thead><tr><th>LEVEL</th><th>TREE</th><th>PATH</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td>사장</td><td>/사장</td></tr>\n      <tr><td>2</td><td>&nbsp;&nbsp;&nbsp;&nbsp;매니저A</td><td>/사장/매니저A</td></tr>\n      <tr><td>3</td><td>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;사원</td><td>/사장/매니저A/사원</td></tr>\n      <tr><td>2</td><td>&nbsp;&nbsp;&nbsp;&nbsp;매니저B</td><td>/사장/매니저B</td></tr>\n    </tbody>\n  </table>\n\n  <!-- ORDER SIBLINGS BY -->\n  <h2 class=\"reveal\">ORDER SIBLINGS BY — 형제 정렬</h2>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  <span class=\"sql-kw\">LEVEL</span>, <span class=\"sql-type\">NAME</span>\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">START WITH</span> <span class=\"sql-type\">MGR_ID</span> <span class=\"sql-kw\">IS NULL</span>\n<span class=\"sql-kw\">CONNECT BY PRIOR</span> <span class=\"sql-type\">EMP_ID</span> = <span class=\"sql-type\">MGR_ID</span>\n<span class=\"sql-kw\">ORDER SIBLINGS BY</span> <span class=\"sql-type\">NAME</span>;     <span class=\"sql-cm\">-- 형제(같은 LEVEL)끼리만 정렬</span></code></pre>\n  <p class=\"reveal\">일반 <code>ORDER BY</code>는 계층 구조를 망가뜨리므로 <code>ORDER SIBLINGS BY</code>를 사용한다.</p>\n\n  <!-- SELF JOIN -->\n  <h2 class=\"reveal\">SELF JOIN</h2>\n  <p class=\"reveal\">같은 테이블을 두 번 사용해서 <a href=\"#\" data-chapter=\"c217\">조인</a>한다. 별칭으로 구분한다.</p>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  <span class=\"sql-type\">E</span>.<span class=\"sql-type\">NAME</span>    <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">사원</span>,\n        <span class=\"sql-type\">M</span>.<span class=\"sql-type\">NAME</span>    <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">매니저</span>\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span> <span class=\"sql-type\">E</span>,  <span class=\"sql-name\">EMP</span> <span class=\"sql-type\">M</span>\n<span class=\"sql-kw\">WHERE</span>   <span class=\"sql-type\">E</span>.<span class=\"sql-type\">MGR_ID</span> = <span class=\"sql-type\">M</span>.<span class=\"sql-type\">EMP_ID</span>;</code></pre>\n  <p class=\"reveal\">표준 방식:</p>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  <span class=\"sql-type\">E</span>.<span class=\"sql-type\">NAME</span>    <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">사원</span>,\n        <span class=\"sql-type\">M</span>.<span class=\"sql-type\">NAME</span>    <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">매니저</span>\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">EMP</span> <span class=\"sql-type\">E</span> <span class=\"sql-kw\">LEFT JOIN</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-type\">M</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-type\">E</span>.<span class=\"sql-type\">MGR_ID</span> = <span class=\"sql-type\">M</span>.<span class=\"sql-type\">EMP_ID</span>;</code></pre>\n  <table class=\"reveal\">\n    <thead><tr><th>사원</th><th>매니저</th></tr></thead>\n    <tbody>\n      <tr><td>사장</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">NULL</td></tr>\n      <tr><td>매니저A</td><td>사장</td></tr>\n      <tr><td>매니저B</td><td>사장</td></tr>\n      <tr><td>사원</td><td>매니저A</td></tr>\n    </tbody>\n  </table>\n\n  <!-- 비교 -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">비교</span>\n    <span class=\"label-rest\">계층형 질의 vs 셀프 조인</span>\n  </h2>\n  <table class=\"reveal\">\n    <thead><tr><th>비교</th><th>계층형 질의</th><th>셀프 조인</th></tr></thead>\n    <tbody>\n      <tr><td>구조</td><td>여러 단계 트리</td><td>보통 1단계(직속만)</td></tr>\n      <tr><td>사용 함수</td><td>LEVEL, PATH 등</td><td>일반 SQL</td></tr>\n      <tr><td>표준 여부</td><td>Oracle 전용(CONNECT BY)</td><td>표준</td></tr>\n      <tr><td>깊이 제한</td><td>무제한</td><td>1단계</td></tr>\n    </tbody>\n  </table>\n\n  <!-- 표준 재귀 쿼리 -->\n  <h2 class=\"reveal\">표준 재귀 쿼리 (참고)</h2>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- ANSI 표준: 재귀 CTE(Common Table Expression)</span>\n<span class=\"sql-kw\">WITH RECURSIVE</span> <span class=\"sql-type\">EMP_TREE</span>(<span class=\"sql-type\">EMP_ID</span>, <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">MGR_ID</span>, <span class=\"sql-type\">LV</span>) <span class=\"sql-kw\">AS</span> (\n    <span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">EMP_ID</span>, <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">MGR_ID</span>, <span class=\"sql-num\">1</span>\n    <span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span>\n    <span class=\"sql-kw\">WHERE</span>  <span class=\"sql-type\">MGR_ID</span> <span class=\"sql-kw\">IS NULL</span>\n    <span class=\"sql-kw\">UNION ALL</span>\n    <span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">E</span>.<span class=\"sql-type\">EMP_ID</span>, <span class=\"sql-type\">E</span>.<span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">E</span>.<span class=\"sql-type\">MGR_ID</span>, <span class=\"sql-type\">T</span>.<span class=\"sql-type\">LV</span> + <span class=\"sql-num\">1</span>\n    <span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span> <span class=\"sql-type\">E</span> <span class=\"sql-kw\">JOIN</span> <span class=\"sql-type\">EMP_TREE</span> <span class=\"sql-type\">T</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-type\">E</span>.<span class=\"sql-type\">MGR_ID</span> = <span class=\"sql-type\">T</span>.<span class=\"sql-type\">EMP_ID</span>\n)\n<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-type\">EMP_TREE</span>;</code></pre>\n  <p class=\"reveal\">Oracle 12c 이상 및 다른 DBMS도 지원한다.</p>\n\n  <!-- Before & After -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">평면 → 트리</span>\n  </h2>\n  <p class=\"reveal\">평면 테이블 EMP는 4행이 단순히 나열돼 있을 뿐, 사장-매니저-사원의 위계가 보이지 않는다. CONNECT BY로 MGR_ID 컬럼을 따라 부모-자식 관계를 펼치면 같은 4행이 트리 순서로 재배열되고 LEVEL이 1·2·3으로 매겨지는 상황을 비교한다.</p>\n  <div class=\"ba-flow large-after reveal\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">BEFORE</span>\n      <h4 class=\"ba-h\">평면 EMP — 위계 없음</h4>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">EMP_ID</div><div class=\"h\">NAME</div><div class=\"h\">MGR_ID</div>\n        <div class=\"c\">E1</div><div class=\"c\">사장</div><div class=\"c is-null\">NULL</div>\n        <div class=\"c\">E2</div><div class=\"c\">매니저A</div><div class=\"c\">E1</div>\n        <div class=\"c\">E3</div><div class=\"c\">매니저B</div><div class=\"c\">E1</div>\n        <div class=\"c\">E4</div><div class=\"c\">사원</div><div class=\"c\">E2</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\">→</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">AFTER (CONNECT BY)</span>\n      <h4 class=\"ba-h\">트리 순서로 재배열 + LEVEL</h4>\n      <div class=\"sql\">START WITH MGR_ID IS NULL CONNECT BY PRIOR EMP_ID = MGR_ID</div>\n      <div class=\"mini-table cols-4\">\n        <div class=\"h\">LEVEL</div><div class=\"h\">NAME</div><div class=\"h\">EMP_ID</div><div class=\"h\">MGR_ID</div>\n        <div class=\"c\">1</div><div class=\"c\">사장</div><div class=\"c\">E1</div><div class=\"c is-null\">NULL</div>\n        <div class=\"c\">2</div><div class=\"c\">매니저A</div><div class=\"c\">E2</div><div class=\"c\">E1</div>\n        <div class=\"c\">3</div><div class=\"c\">사원</div><div class=\"c\">E4</div><div class=\"c\">E2</div>\n        <div class=\"c\">2</div><div class=\"c\">매니저B</div><div class=\"c\">E3</div><div class=\"c\">E1</div>\n      </div>\n    </div>\n  </div>\n  <p class=\"reveal\"><code>START WITH MGR_ID IS NULL</code>이 사장(E1)을 루트로 잡고, <code>CONNECT BY PRIOR EMP_ID = MGR_ID</code>가 \"현재 행의 EMP_ID = 다음 행의 MGR_ID\"라는 부모-자식 규칙을 정의해 깊이 우선으로 트리를 펼친다. 그래서 매니저A 다음에 그 자식인 사원이 먼저 따라붙고, 그다음에야 매니저B가 출력된다(매니저B 자식이 없으면 거기서 가지 끝). 셀프 조인이라면 \"사원-매니저\" 1단계만 가능하지만, 계층형 질의는 깊이가 깊어져도 LEVEL과 SYS_CONNECT_BY_PATH로 재귀 추적이 가능하다는 점이 결정적인 차이다.</p>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-2-2-6\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c227: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    PIVOT은 <strong>세로 데이터를 가로</strong>로, UNPIVOT은 <strong>가로 데이터를 세로</strong>로 바꾼다. 데이터 모양 변환 도구다.\n  </blockquote>\n  <div class=\"ex-box reveal\">\n    \"(김철수, 수학, 3) / (김철수, 영어, 2)\" 같은 세로 카드 형태를 \"김철수 | 수학3 | 영어2\"의 가로 엑셀 표로 펼치는 작업이 PIVOT.\n  </div>\n\n  <!-- 개념 도식화 -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">PIVOT vs UNPIVOT</span>\n  </h2>\n  <div class=\"threeway cols-2 reveal\">\n    <div class=\"threeway-card t-info\">\n      <div class=\"glyph\">↕→↔</div>\n      <div class=\"name\">PIVOT (세로 → 가로)</div>\n      <div class=\"desc\"><strong>행을 컬럼</strong>으로 펼침. 집계함수 필수. 매칭 안 되는 칸은 NULL</div>\n    </div>\n    <div class=\"threeway-card t-warn\">\n      <div class=\"glyph\">↔→↕</div>\n      <div class=\"name\">UNPIVOT (가로 → 세로)</div>\n      <div class=\"desc\"><strong>컬럼을 행</strong>으로 접음. 기본 NULL 제외, <code>INCLUDE NULLS</code>로 포함</div>\n    </div>\n  </div>\n\n  <p class=\"reveal\">PIVOT과 UNPIVOT은 형식상 서로 역연산이지만, PIVOT은 집계함수가 끼고 UNPIVOT은 NULL을 기본으로 버린다는 비대칭이 있다.</p>\n\n  <div class=\"ba-flow reveal\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">세로형 (Long) — 원본</span>\n      <h4 class=\"ba-h\">행 단위로 쌓인 카드</h4>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">회원</div><div class=\"h\">과목</div><div class=\"h\">수</div>\n        <div class=\"c\">김</div><div class=\"c\">수학</div><div class=\"c\">3</div>\n        <div class=\"c\">김</div><div class=\"c\">영어</div><div class=\"c\">2</div>\n        <div class=\"c\">김</div><div class=\"c\">과학</div><div class=\"c\">1</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\">↔</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">가로형 (Wide) — 변환</span>\n      <h4 class=\"ba-h\">컬럼으로 펼쳐진 표</h4>\n      <div class=\"mini-table cols-4\">\n        <div class=\"h\">회원</div><div class=\"h\">수학</div><div class=\"h\">영어</div><div class=\"h\">과학</div>\n        <div class=\"c\">김</div><div class=\"c\">3</div><div class=\"c\">2</div><div class=\"c\">1</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- PIVOT -->\n  <h2 class=\"reveal\">PIVOT 절 — 세로 → 가로</h2>\n  <h3 class=\"reveal\">문법</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  *\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">원본테이블</span>\n        <span class=\"sql-kw\">PIVOT</span> (\n            <span class=\"sql-kw\">집계함수</span>(<span class=\"sql-type\">값컬럼</span>)\n            <span class=\"sql-kw\">FOR</span>  <span class=\"sql-type\">변환대상컬럼</span> <span class=\"sql-kw\">IN</span> (<span class=\"sql-str\">'값1'</span> <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">별칭1</span>, <span class=\"sql-str\">'값2'</span> <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">별칭2</span>, ...)\n        );</code></pre>\n  <h3 class=\"reveal\">예시</h3>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터</p>\n  <div class=\"ba-flow reveal\" style=\"grid-template-columns: 1fr 36px 1fr; align-items: stretch;\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">SCORE (Before)</span>\n      <h4 class=\"ba-h\">세로형 — 원본</h4>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">MEMBER</div><div class=\"h\">SUBJECT</div><div class=\"h\">POINT</div>\n        <div class=\"c\">김</div><div class=\"c\">수학</div><div class=\"c\">90</div>\n        <div class=\"c\">김</div><div class=\"c\">영어</div><div class=\"c\">80</div>\n        <div class=\"c\">김</div><div class=\"c\">과학</div><div class=\"c\">70</div>\n        <div class=\"c\">이</div><div class=\"c\">수학</div><div class=\"c\">100</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\" style=\"font-size: 22px; color: var(--point-500);\">→</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">PIVOT (After)</span>\n      <h4 class=\"ba-h\">가로형 — 변환</h4>\n      <div class=\"mini-table cols-4\">\n        <div class=\"h\">MEMBER</div><div class=\"h\">수학</div><div class=\"h\">영어</div><div class=\"h\">과학</div>\n        <div class=\"c\">김</div><div class=\"c\">90</div><div class=\"c\">80</div><div class=\"c\">70</div>\n        <div class=\"c\">이</div><div class=\"c\">100</div><div class=\"c is-null\">NULL</div><div class=\"c is-null\">NULL</div>\n      </div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span> *\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">SCORE</span>\n       <span class=\"sql-kw\">PIVOT</span> (\n           <span class=\"sql-kw\">SUM</span>(<span class=\"sql-type\">POINT</span>)\n           <span class=\"sql-kw\">FOR</span> <span class=\"sql-type\">SUBJECT</span> <span class=\"sql-kw\">IN</span> (<span class=\"sql-str\">'수학'</span> <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">수학</span>, <span class=\"sql-str\">'영어'</span> <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">영어</span>, <span class=\"sql-str\">'과학'</span> <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">과학</span>)\n       );</code></pre>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ SUBJECT의 값('수학'/'영어'/'과학')이 컬럼명으로 펼쳐진다. 이는 영어·과학 시험을 보지 않아 매칭 행이 없으므로 두 칸이 NULL.</p>\n\n  <!-- UNPIVOT -->\n  <h2 class=\"reveal\">UNPIVOT 절 — 가로 → 세로</h2>\n  <h3 class=\"reveal\">문법</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  *\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">가로테이블</span>\n        <span class=\"sql-kw\">UNPIVOT</span> (\n            <span class=\"sql-type\">값컬럼</span>\n            <span class=\"sql-kw\">FOR</span> <span class=\"sql-type\">새컬럼명</span> <span class=\"sql-kw\">IN</span> (<span class=\"sql-type\">가로컬럼1</span> <span class=\"sql-kw\">AS</span> <span class=\"sql-str\">'값1'</span>, <span class=\"sql-type\">가로컬럼2</span> <span class=\"sql-kw\">AS</span> <span class=\"sql-str\">'값2'</span>, ...)\n        );</code></pre>\n  <h3 class=\"reveal\">예시</h3>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터</p>\n  <div class=\"ba-flow reveal\" style=\"grid-template-columns: 1fr 36px 1fr; align-items: stretch;\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">SCORE_WIDE (Before)</span>\n      <h4 class=\"ba-h\">가로형 — 원본</h4>\n      <div class=\"mini-table cols-4\">\n        <div class=\"h\">MEMBER</div><div class=\"h\">수학</div><div class=\"h\">영어</div><div class=\"h\">과학</div>\n        <div class=\"c\">김</div><div class=\"c\">90</div><div class=\"c\">80</div><div class=\"c\">70</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\" style=\"font-size: 22px; color: var(--point-500);\">→</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">UNPIVOT (After)</span>\n      <h4 class=\"ba-h\">세로형 — 변환</h4>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">MEMBER</div><div class=\"h\">SUBJECT</div><div class=\"h\">POINT</div>\n        <div class=\"c\">김</div><div class=\"c\">수학</div><div class=\"c\">90</div>\n        <div class=\"c\">김</div><div class=\"c\">영어</div><div class=\"c\">80</div>\n        <div class=\"c\">김</div><div class=\"c\">과학</div><div class=\"c\">70</div>\n      </div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span> *\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">SCORE_WIDE</span>\n       <span class=\"sql-kw\">UNPIVOT</span> (\n           <span class=\"sql-type\">POINT</span>\n           <span class=\"sql-kw\">FOR</span> <span class=\"sql-type\">SUBJECT</span> <span class=\"sql-kw\">IN</span> (<span class=\"sql-type\">수학</span> <span class=\"sql-kw\">AS</span> <span class=\"sql-str\">'수학'</span>, <span class=\"sql-type\">영어</span> <span class=\"sql-kw\">AS</span> <span class=\"sql-str\">'영어'</span>, <span class=\"sql-type\">과학</span> <span class=\"sql-kw\">AS</span> <span class=\"sql-str\">'과학'</span>)\n       );</code></pre>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 가로의 수학·영어·과학 컬럼이 SUBJECT 값으로 접히고, 그 점수가 POINT 컬럼으로 풀린다. 1행이 3행으로 늘어남.</p>\n\n  <!-- CASE WHEN으로 PIVOT -->\n  <h2 class=\"reveal\">CASE WHEN으로 PIVOT 흉내내기 (전통 방식)</h2>\n  <p class=\"reveal\">PIVOT 절 없이도 같은 결과를 만들 수 있다.</p>\n  <div class=\"fn-grid cols-3 reveal\">\n    <div class=\"fn-card\">\n      <div class=\"name\">SUM(CASE WHEN ...)</div>\n      <div class=\"desc\">조건별로 더하는 컬럼을 만든다</div>\n      <div class=\"ex\">SUM(CASE WHEN SUBJECT='수학' THEN POINT END)</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">GROUP BY</div>\n      <div class=\"desc\">행 키를 묶어 한 줄로 모은다</div>\n      <div class=\"ex\">GROUP BY MEMBER</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">ROLLUP / CUBE</div>\n      <div class=\"desc\">소계까지 함께 뽑고 싶을 때</div>\n      <div class=\"ex\">GROUP BY ROLLUP(MEMBER)</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">SELECT</span>  <span class=\"sql-type\">MEMBER</span>,\n        <span class=\"sql-kw\">SUM</span>(<span class=\"sql-kw\">CASE WHEN</span> <span class=\"sql-type\">SUBJECT</span> = <span class=\"sql-str\">'수학'</span> <span class=\"sql-kw\">THEN</span> <span class=\"sql-type\">POINT</span> <span class=\"sql-kw\">END</span>) <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">수학</span>,\n        <span class=\"sql-kw\">SUM</span>(<span class=\"sql-kw\">CASE WHEN</span> <span class=\"sql-type\">SUBJECT</span> = <span class=\"sql-str\">'영어'</span> <span class=\"sql-kw\">THEN</span> <span class=\"sql-type\">POINT</span> <span class=\"sql-kw\">END</span>) <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">영어</span>,\n        <span class=\"sql-kw\">SUM</span>(<span class=\"sql-kw\">CASE WHEN</span> <span class=\"sql-type\">SUBJECT</span> = <span class=\"sql-str\">'과학'</span> <span class=\"sql-kw\">THEN</span> <span class=\"sql-type\">POINT</span> <span class=\"sql-kw\">END</span>) <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">과학</span>\n<span class=\"sql-kw\">FROM</span>    <span class=\"sql-name\">SCORE</span>\n<span class=\"sql-kw\">GROUP BY</span> <span class=\"sql-type\">MEMBER</span>;</code></pre>\n  <p class=\"reveal\">시험에서 단골: PIVOT 절을 모르고도 CASE + GROUP BY로 같은 효과를 낼 수 있다(소계까지 함께 뽑고 싶으면 <a href=\"#\" data-chapter=\"c223\">그룹 함수</a>의 ROLLUP/CUBE를 결합한다).</p>\n\n  <!-- NULL 처리 -->\n  <h2 class=\"reveal\">NULL 처리</h2>\n  <table class=\"reveal\">\n    <thead><tr><th>상황</th><th>결과</th></tr></thead>\n    <tbody>\n      <tr><td>PIVOT 후 매칭 없는 칸</td><td>NULL</td></tr>\n      <tr><td>UNPIVOT 시 NULL 값</td><td>기본 제외</td></tr>\n      <tr><td><code>INCLUDE NULLS</code> 옵션</td><td>NULL 값도 포함</td></tr>\n    </tbody>\n  </table>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- NULL도 포함시켜 UNPIVOT</span>\n... <span class=\"sql-kw\">UNPIVOT INCLUDE NULLS</span> (<span class=\"sql-type\">POINT</span> <span class=\"sql-kw\">FOR</span> <span class=\"sql-type\">SUBJECT</span> <span class=\"sql-kw\">IN</span> (...));</code></pre>\n\n  <!-- SQL 실전 추가 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">추가 예시</span>\n  </h2>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 부서별, 직무별 인원수를 가로로</span>\n<span class=\"sql-kw\">SELECT</span> *\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">EMP</span>\n       <span class=\"sql-kw\">PIVOT</span> (\n           <span class=\"sql-kw\">COUNT</span>(*)\n           <span class=\"sql-kw\">FOR</span> <span class=\"sql-type\">JOB</span> <span class=\"sql-kw\">IN</span> (<span class=\"sql-str\">'MGR'</span> <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">매니저</span>, <span class=\"sql-str\">'CLERK'</span> <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">사무직</span>, <span class=\"sql-str\">'SALES'</span> <span class=\"sql-kw\">AS</span> <span class=\"sql-type\">영업</span>)\n       );</code></pre>\n  <table class=\"reveal\">\n    <thead><tr><th>DEPT_ID</th><th>매니저</th><th>사무직</th><th>영업</th></tr></thead>\n    <tbody>\n      <tr><td>D1</td><td>1</td><td>2</td><td>0</td></tr>\n      <tr><td>D2</td><td>1</td><td>0</td><td>3</td></tr>\n    </tbody>\n  </table>\n\n  <!-- Before & After -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">CASE 방식과 PIVOT 절 비교</span>\n  </h2>\n  <p class=\"reveal\">분기·카테고리·매출이 세로로 쌓인 SALES 표를 분기별 가로 보고서로 바꾸는 상황. Q2에는 카테고리 B 매출이 없다는 점이 핵심으로, 이 빈 칸이 결과에서 NULL로 처리된다. 같은 변환을 Oracle PIVOT 절과 전통적인 CASE WHEN + GROUP BY 방식으로 동시에 표현해 비교한다.</p>\n  <h4 class=\"reveal\">원본</h4>\n  <table class=\"reveal\">\n    <thead><tr><th>분기</th><th>카테고리</th><th>매출</th></tr></thead>\n    <tbody>\n      <tr><td>Q1</td><td>A</td><td>100</td></tr>\n      <tr><td>Q1</td><td>B</td><td>200</td></tr>\n      <tr><td>Q2</td><td>A</td><td>150</td></tr>\n    </tbody>\n  </table>\n  <div class=\"ba-flow reveal\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">PIVOT 절</span>\n      <h4 class=\"ba-h\">선언적 — IN 절에 컬럼 명시</h4>\n      <div class=\"sql\">SELECT * FROM SALES PIVOT (SUM(매출) FOR 카테고리 IN ('A' AS A, 'B' AS B));</div>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">분기</div><div class=\"h\">A</div><div class=\"h\">B</div>\n        <div class=\"c\">Q1</div><div class=\"c\">100</div><div class=\"c\">200</div>\n        <div class=\"c\">Q2</div><div class=\"c\">150</div><div class=\"c is-null\">NULL</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\">↔</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">CASE WHEN 방식</span>\n      <h4 class=\"ba-h\">유연 — 컬럼 동적 조립</h4>\n      <div class=\"sql\">SELECT 분기, SUM(CASE WHEN 카테고리='A' THEN 매출 END) AS A, SUM(CASE WHEN 카테고리='B' THEN 매출 END) AS B FROM SALES GROUP BY 분기;</div>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">분기</div><div class=\"h\">A</div><div class=\"h\">B</div>\n        <div class=\"c\">Q1</div><div class=\"c\">100</div><div class=\"c\">200</div>\n        <div class=\"c\">Q2</div><div class=\"c\">150</div><div class=\"c is-null\">NULL</div>\n      </div>\n    </div>\n  </div>\n  <p class=\"reveal\">두 방식의 결과가 같은 이유는 PIVOT 절이 사실상 \"카테고리별 <code>SUM(CASE WHEN ...)</code>\"을 분기 GROUP BY로 묶는 동작을 문법적으로 단순화한 것이기 때문이다. Q2의 B 칸이 NULL이 되는 것도 같은 메커니즘으로, 매칭되는 원본 행이 없어 SUM의 입력이 비어 있기 때문이다. PIVOT은 IN 절에 변환할 값을 명시적으로 나열해야 하므로 \"어떤 컬럼이 만들어질지\"를 미리 알아야 하고, CASE 방식은 분기 컬럼을 동적으로 조립할 수 있어 더 유연하다는 점이 표현력의 차이로 남는다.</p>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-2-2-7\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c228: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    정규 표현식은 <strong>문자 패턴을 표현하는 짧은 식</strong>이다. LIKE보다 훨씬 강력하게 문자열을 검색·추출·교체할 수 있다.\n  </blockquote>\n  <div class=\"ex-box reveal\">\n    LIKE는 \"<code>'김%'</code>로 시작\" 정도지만, 정규식은 \"010-숫자4자리-숫자4자리\" / \"한글 3글자 이름\" / \"이메일 형식\" 같은 정밀 패턴을 표현한다.\n  </div>\n\n  <!-- 개념 도식화 -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">LIKE vs REGEXP</span>\n  </h2>\n  <div class=\"threeway cols-2 reveal\">\n    <div class=\"threeway-card t-info\">\n      <div class=\"glyph\">LIKE</div>\n      <div class=\"name\">LIKE</div>\n      <div class=\"desc\"><strong>%</strong> (0개 이상), <strong>_</strong> (1개) — 단순·기본 검색 · 빠름</div>\n    </div>\n    <div class=\"threeway-card t-correct\">\n      <div class=\"glyph\">.*+?</div>\n      <div class=\"name\">REGEXP</div>\n      <div class=\"desc\"><code>. * + ? [ ] ^ $ | { } \\d \\w \\s …</code> — 정밀·고급 검색 · 약간 느림</div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead><tr><th>비교</th><th>LIKE</th><th>REGEXP</th></tr></thead>\n    <tbody>\n      <tr><td>표현력</td><td>약함</td><td>강함</td></tr>\n      <tr><td>와일드카드</td><td><code>%</code>, <code>_</code></td><td><code>.</code>, <code>*</code>, <code>+</code>, <code>[]</code>, <code>^</code>, <code>$</code> 등 다수</td></tr>\n      <tr><td>성능</td><td>빠름</td><td>약간 느림</td></tr>\n    </tbody>\n  </table>\n\n  <!-- Oracle 정규식 함수 -->\n  <h2 class=\"reveal\">Oracle 정규식 <a href=\"#\" data-chapter=\"c213\">함수</a></h2>\n  <div class=\"fn-grid cols-3 reveal\">\n    <div class=\"fn-card\">\n      <div class=\"name\">REGEXP_LIKE(s, pattern)</div>\n      <div class=\"desc\">LIKE의 정규식 버전 — <strong>조건절</strong>용 (TRUE/FALSE)</div>\n      <div class=\"ex\">WHERE REGEXP_LIKE(NAME, '^[가-힣]+$')</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">REGEXP_REPLACE(s, p, r)</div>\n      <div class=\"desc\">패턴 매칭 부분을 <strong>교체</strong></div>\n      <div class=\"ex\">REGEXP_REPLACE(STR, '\\s+', '')</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">REGEXP_SUBSTR(s, p)</div>\n      <div class=\"desc\">패턴 일치 부분 <strong>추출</strong></div>\n      <div class=\"ex\">REGEXP_SUBSTR(STR, '\\d+')</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">REGEXP_INSTR(s, p)</div>\n      <div class=\"desc\">패턴이 처음 나타나는 <strong>위치</strong></div>\n      <div class=\"ex\">REGEXP_INSTR('abc123', '\\d')</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">REGEXP_COUNT(s, p)</div>\n      <div class=\"desc\">패턴 등장 <strong>횟수</strong></div>\n      <div class=\"ex\">REGEXP_COUNT(STR, '\\w+')</div>\n    </div>\n  </div>\n\n  <!-- 자주 쓰는 메타문자 -->\n  <h2 class=\"reveal\">자주 쓰는 메타문자</h2>\n  <div class=\"cls-row cols-4 reveal\">\n    <div class=\"cls-card\">\n      <span class=\"badge\">위치</span>\n      <div class=\"name\"><code>^</code> · <code>$</code></div>\n      <div class=\"ex\">문자열 시작 · 끝<br><code>^010</code> / <code>\\.com$</code></div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-info\">반복</span>\n      <div class=\"name\"><code>*</code> · <code>+</code> · <code>?</code></div>\n      <div class=\"ex\">0+ · 1+ · 0/1<br><code>ab+</code> → ab, abb</div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-warn\">집합</span>\n      <div class=\"name\"><code>[abc]</code> · <code>[^abc]</code></div>\n      <div class=\"ex\">중 하나 · 부정<br><code>[Aa]pple</code></div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-event\">임의</span>\n      <div class=\"name\"><code>.</code></div>\n      <div class=\"ex\">임의의 한 글자<br><code>a.c</code> → abc, aXc</div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge\">횟수</span>\n      <div class=\"name\"><code>{n}</code> · <code>{n,m}</code></div>\n      <div class=\"ex\">정확히 n번 · n~m번<br><code>\\d{2,4}</code></div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-info\">또는</span>\n      <div class=\"name\"><code>|</code></div>\n      <div class=\"ex\">택일<br><code>(cat|dog)</code></div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-warn\">문자류</span>\n      <div class=\"name\"><code>\\d</code> · <code>\\w</code> · <code>\\s</code></div>\n      <div class=\"ex\">숫자 · 단어문자 · 공백</div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-event\">한글</span>\n      <div class=\"name\"><code>[가-힣]</code></div>\n      <div class=\"ex\">한글 한 글자</div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead><tr><th>기호</th><th>의미</th><th>예</th></tr></thead>\n    <tbody>\n      <tr><td><code>.</code></td><td>임의의 한 글자</td><td><code>'a.c'</code> → 'abc', 'aXc'</td></tr>\n      <tr><td><code>*</code></td><td>0개 이상 반복</td><td><code>'ab*'</code> → 'a', 'ab', 'abb'</td></tr>\n      <tr><td><code>+</code></td><td>1개 이상 반복</td><td><code>'ab+'</code> → 'ab', 'abb' (a 안 됨)</td></tr>\n      <tr><td><code>?</code></td><td>0 또는 1</td><td><code>'colou?r'</code> → 'color', 'colour'</td></tr>\n      <tr><td><code>[abc]</code></td><td>a, b, c 중 하나</td><td><code>'[Aa]pple'</code></td></tr>\n      <tr><td><code>[^abc]</code></td><td>a, b, c가 아닌 것</td><td></td></tr>\n      <tr><td><code>[0-9]</code></td><td>숫자 한 글자</td><td></td></tr>\n      <tr><td><code>[a-z]</code></td><td>영소문자</td><td></td></tr>\n      <tr><td><code>^</code></td><td>문자열 시작</td><td><code>^010</code> (010으로 시작)</td></tr>\n      <tr><td><code>$</code></td><td>문자열 끝</td><td><code>\\.com$</code></td></tr>\n      <tr><td><code>|</code></td><td>또는</td><td><code>(cat|dog)</code></td></tr>\n      <tr><td><code>{n}</code></td><td>정확히 n번</td><td><code>\\d{4}</code></td></tr>\n      <tr><td><code>{n,m}</code></td><td>n~m번</td><td><code>\\d{2,4}</code></td></tr>\n      <tr><td><code>\\d</code></td><td>숫자 [0-9]</td><td>※ Oracle은 12c부터 일부 동작</td></tr>\n      <tr><td><code>\\w</code></td><td>단어문자 [A-Za-z0-9_]</td><td>※ Oracle 호환 제한</td></tr>\n      <tr><td><code>\\s</code></td><td>공백</td><td>※ Oracle 호환 제한</td></tr>\n    </tbody>\n  </table>\n  <blockquote class=\"reveal\">\n    <strong>Oracle 호환성</strong> — Oracle 정규식은 <strong>POSIX 1003.2 표준</strong> 기반이라 <code>\\d</code>·<code>\\w</code>·<code>\\s</code>(PCRE 단축 클래스)는 12c 이후 일부 버전에서만 동작합니다. 호환성 보장을 위해 <code>[0-9]</code>·<code>[A-Za-z0-9_]</code> 또는 POSIX 문자 클래스 <code>[[:digit:]]</code>·<code>[[:alpha:]]</code>·<code>[[:space:]]</code>를 사용하는 것이 안전.\n  </blockquote>\n\n  <!-- SQL 실전 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">함수별 사용 예</span>\n  </h2>\n  <h3 class=\"reveal\">REGEXP_LIKE (<a href=\"#\" data-chapter=\"c214\">WHERE</a> 조건절)</h3>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">MEMBER</span>\n    <h4 class=\"ba-h\">회원 테이블</h4>\n    <div class=\"mini-table cols-2\">\n      <div class=\"h\">NAME</div><div class=\"h\">PHONE</div>\n      <div class=\"c\">김철수</div><div class=\"c\">010-1234-5678</div>\n      <div class=\"c\">이영희</div><div class=\"c\">02-1234-5678</div>\n      <div class=\"c\">홍길동전</div><div class=\"c\">010-9876-5432</div>\n      <div class=\"c\">Jane</div><div class=\"c\">010-9999-1234</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 휴대폰 번호 형식 (010으로 시작, 3-4-4 자리)</span>\n<span class=\"sql-kw\">SELECT</span> *\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">MEMBER</span>\n<span class=\"sql-kw\">WHERE</span>  <span class=\"sql-kw\">REGEXP_LIKE</span>(<span class=\"sql-type\">PHONE</span>, <span class=\"sql-str\">'^010-\\d{3,4}-\\d{4}$'</span>);\n\n<span class=\"sql-cm\">-- 이메일 형식</span>\n<span class=\"sql-kw\">SELECT</span> *\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">MEMBER</span>\n<span class=\"sql-kw\">WHERE</span>  <span class=\"sql-kw\">REGEXP_LIKE</span>(<span class=\"sql-type\">EMAIL</span>, <span class=\"sql-str\">'^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$'</span>);\n\n<span class=\"sql-cm\">-- 한글 3글자 이름</span>\n<span class=\"sql-kw\">SELECT</span> *\n<span class=\"sql-kw\">FROM</span>   <span class=\"sql-name\">MEMBER</span>\n<span class=\"sql-kw\">WHERE</span>  <span class=\"sql-kw\">REGEXP_LIKE</span>(<span class=\"sql-type\">NAME</span>, <span class=\"sql-str\">'^[가-힣]{3}$'</span>);</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (한글 3글자 이름 쿼리)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NAME</th><th>매칭</th></tr></thead>\n    <tbody>\n      <tr><td>김철수</td><td>O</td></tr>\n      <tr><td>이영희</td><td>O</td></tr>\n      <tr><td>홍길동전</td><td>X (4글자)</td></tr>\n      <tr><td>Jane</td><td>X (영문)</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">REGEXP_REPLACE (교체)</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 모든 공백 제거</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-kw\">REGEXP_REPLACE</span>(<span class=\"sql-str\">'Hello   World'</span>, <span class=\"sql-str\">'\\s+'</span>, <span class=\"sql-str\">''</span>) <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">DUAL</span>;\n<span class=\"sql-cm\">-- 결과: 'HelloWorld'</span>\n\n<span class=\"sql-cm\">-- 전화번호 가운데를 마스킹</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-kw\">REGEXP_REPLACE</span>(<span class=\"sql-str\">'010-1234-5678'</span>, <span class=\"sql-str\">'(\\d{3})-(\\d{4})-(\\d{4})'</span>, <span class=\"sql-str\">'\\1-****-\\3'</span>) <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">DUAL</span>;\n<span class=\"sql-cm\">-- 결과: '010-****-5678'</span></code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과</p>\n  <table class=\"reveal\">\n    <thead><tr><th>입력</th><th>패턴 → 치환</th><th>결과</th></tr></thead>\n    <tbody>\n      <tr><td>'Hello   World'</td><td><code>\\s+</code> → <code>''</code></td><td>HelloWorld</td></tr>\n      <tr><td>'010-1234-5678'</td><td><code>(\\d{3})-(\\d{4})-(\\d{4})</code> → <code>\\1-****-\\3</code></td><td>010-****-5678</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">REGEXP_SUBSTR (추출)</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 첫 번째 숫자 묶음 추출</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-kw\">REGEXP_SUBSTR</span>(<span class=\"sql-str\">'주문번호 12345 입니다'</span>, <span class=\"sql-str\">'\\d+'</span>) <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">DUAL</span>;\n<span class=\"sql-cm\">-- 결과: '12345'</span></code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과</p>\n  <table class=\"reveal\">\n    <thead><tr><th>입력</th><th>패턴</th><th>추출 결과</th></tr></thead>\n    <tbody>\n      <tr><td>'주문번호 12345 입니다'</td><td><code>\\d+</code></td><td>12345</td></tr>\n      <tr><td>'no-digits'</td><td><code>\\d+</code></td><td>NULL</td></tr>\n      <tr><td>'abc 12 def 34'</td><td><code>\\d+</code></td><td>12 (첫 매치만)</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">REGEXP_INSTR / REGEXP_COUNT</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 처음 숫자가 나타나는 위치</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-kw\">REGEXP_INSTR</span>(<span class=\"sql-str\">'abc123def'</span>, <span class=\"sql-str\">'\\d'</span>) <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">DUAL</span>;  <span class=\"sql-cm\">-- 4</span>\n\n<span class=\"sql-cm\">-- 단어 개수</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-kw\">REGEXP_COUNT</span>(<span class=\"sql-str\">'one two three'</span>, <span class=\"sql-str\">'\\w+'</span>) <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">DUAL</span>;  <span class=\"sql-cm\">-- 3</span></code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과</p>\n  <table class=\"reveal\">\n    <thead><tr><th>함수</th><th>입력 / 패턴</th><th>결과</th></tr></thead>\n    <tbody>\n      <tr><td>REGEXP_INSTR</td><td>'abc123def' / <code>\\d</code></td><td>4 (1-based)</td></tr>\n      <tr><td>REGEXP_INSTR</td><td>'no digits' / <code>\\d</code></td><td>0 (없음)</td></tr>\n      <tr><td>REGEXP_COUNT</td><td>'one two three' / <code>\\w+</code></td><td>3</td></tr>\n      <tr><td>REGEXP_COUNT</td><td>'aaaa' / <code>a</code></td><td>4</td></tr>\n    </tbody>\n  </table>\n\n  <!-- Before & After -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">LIKE로는 까다로운 두 조건</span>\n  </h2>\n  <p class=\"reveal\">MEMBER 3건에서 \"한글 이름이고 동시에 010 휴대폰 번호인 회원\"만 골라내야 하는 상황. 2번은 휴대폰이 02 지역번호라 떨어지고, 3번은 이름이 영문이라 떨어진다. LIKE 두 개로는 표현하기 까다로운 두 조건을 REGEXP_LIKE로 정밀하게 거른다.</p>\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3); margin-top: 0;\">MEMBER 테이블</p>\n  <table class=\"reveal\">\n    <thead><tr><th>ID</th><th>NAME</th><th>PHONE</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td>김철수</td><td>010-1234-5678</td></tr>\n      <tr><td>2</td><td>이영희</td><td>02-1234-5678</td></tr>\n      <tr><td>3</td><td>Jane</td><td>010-9999-1234</td></tr>\n    </tbody>\n  </table>\n  <div class=\"ba-flow reveal\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">BEFORE (원본 3건)</span>\n      <h4 class=\"ba-h\">한글 이름 + 010 휴대폰만</h4>\n      <div class=\"sql\">SELECT * FROM MEMBER WHERE REGEXP_LIKE(NAME, '^[가-힣]+$') AND REGEXP_LIKE(PHONE, '^010-');</div>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">ID</div><div class=\"h\">NAME</div><div class=\"h\">PHONE</div>\n        <div class=\"c\">1</div><div class=\"c\">김철수</div><div class=\"c\">010-...</div>\n        <div class=\"c is-null\">2</div><div class=\"c is-null\">이영희</div><div class=\"c is-null\">02-...</div>\n        <div class=\"c is-null\">3</div><div class=\"c is-null\">Jane</div><div class=\"c is-null\">010-...</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\">→</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">AFTER (교집합 1건)</span>\n      <h4 class=\"ba-h\">두 정규식 AND</h4>\n      <div class=\"sql\">^[가-힣]+$ : 한글만 / ^010- : 010 시작</div>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">ID</div><div class=\"h\">NAME</div><div class=\"h\">PHONE</div>\n        <div class=\"c\">1</div><div class=\"c\">김철수</div><div class=\"c\">010-1234-5678</div>\n      </div>\n    </div>\n  </div>\n  <p class=\"reveal\"><code>^[가-힣]+$</code>는 문자열 처음(<code>^</code>)부터 끝(<code>$</code>)까지가 모두 한글 한 글자(<code>[가-힣]</code>)의 1회 이상 반복으로만 채워질 때만 매칭하므로, \"Jane\"은 영문이라 즉시 탈락하고 김철수·이영희는 통과한다. 다음 조건 <code>^010-</code>은 PHONE이 정확히 \"010-\"으로 시작할 때만 통과시키므로 02 지역번호인 이영희가 떨어진다. 두 정규식 조건을 AND로 조합해 \"한글 이름 + 010 휴대폰\" 교집합만 남는 셈이다. LIKE의 <code>%</code>·<code>_</code>로는 \"글자 종류(한글)\"를 표현할 수 없으니, 문자 종류·길이·위치를 동시에 검사해야 할 때는 정규식이 자연스러운 선택이다.</p>\n\n  <!-- 정규식 옵션 -->\n  <h2 class=\"reveal\">정규식 옵션 (4번째 인자)</h2>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">REGEXP_LIKE</span>(<span class=\"sql-str\">'ABC'</span>, <span class=\"sql-str\">'abc'</span>, <span class=\"sql-str\">'i'</span>)   <span class=\"sql-cm\">-- 대소문자 무시</span></code></pre>\n  <table class=\"reveal\">\n    <thead><tr><th>옵션</th><th>의미</th></tr></thead>\n    <tbody>\n      <tr><td><code>i</code></td><td>대소문자 무시</td></tr>\n      <tr><td><code>c</code></td><td>대소문자 구분(기본)</td></tr>\n      <tr><td><code>m</code></td><td>멀티라인</td></tr>\n      <tr><td><code>n</code></td><td><code>.</code>이 줄바꿈도 매칭</td></tr>\n      <tr><td><code>x</code></td><td>공백 무시</td></tr>\n    </tbody>\n  </table>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-2-2-8\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c231: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    DML은 <strong>테이블 안의 데이터를 입력·수정·삭제·조회</strong>하는 명령어들이다(INSERT, UPDATE, DELETE, MERGE, SELECT).\n  </blockquote>\n  <div class=\"ex-box reveal\">\n    테이블을 노트에 비유하면 INSERT는 새 줄 적기, UPDATE는 줄 고치기, DELETE는 줄 지우기, MERGE는 있으면 고치고 없으면 적기, SELECT는 읽기다.\n  </div>\n\n  <!-- 개념 도식화 -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">DML의 분류</span>\n  </h2>\n  <div class=\"cls-row cols-4 reveal\">\n    <div class=\"cls-card\">\n      <span class=\"badge\">INSERT</span>\n      <div class=\"name\">새 행 입력</div>\n      <div class=\"ex\">노트에 새 줄 적기 — <code>VALUES</code> · <code>SELECT</code> · <code>INSERT ALL</code></div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-info\">UPDATE</span>\n      <div class=\"name\">기존 행 수정</div>\n      <div class=\"ex\">줄 고치기 — <code>SET</code> · <code>WHERE</code> 누락 시 전 행 수정</div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-warn\">DELETE</span>\n      <div class=\"name\">행 삭제 (롤백 가능)</div>\n      <div class=\"ex\">줄 지우기 — DML이라 <code>ROLLBACK</code> 가능</div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-event\">MERGE</span>\n      <div class=\"name\">UPSERT</div>\n      <div class=\"ex\">있으면 UPDATE / 없으면 INSERT</div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead><tr><th>명령</th><th>용도</th></tr></thead>\n    <tbody>\n      <tr><td>INSERT</td><td>새 행 입력</td></tr>\n      <tr><td>UPDATE</td><td>기존 행 수정</td></tr>\n      <tr><td>DELETE</td><td>행 삭제</td></tr>\n      <tr><td>MERGE</td><td>UPSERT(있으면 UPDATE, 없으면 INSERT)</td></tr>\n      <tr><td>SELECT</td><td>조회</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">DML → 트랜잭션 시퀀스</h3>\n  <div class=\"mermaid reveal\">\nsequenceDiagram\n    participant U as User\n    participant DB as DB (메모리)\n    participant Disk as 디스크\n    U->>DB: INSERT INTO EMP ...\n    Note over DB: 행 추가 (메모리)\n    U->>DB: UPDATE EMP SET SAL = ...\n    Note over DB: 행 수정 (메모리)\n    U->>DB: DELETE FROM EMP WHERE ...\n    Note over DB: 행 삭제 (메모리)\n    alt 정상\n        U->>DB: COMMIT\n        DB->>Disk: 변경분 영구 반영\n        Note over Disk: 다른 사용자도 조회 가능\n    else 오류\n        U->>DB: ROLLBACK\n        Note over DB: 모든 DML 취소\n    end\n  </div>\n\n  <!-- SQL 실전 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">DML 5종</span>\n  </h2>\n\n  <h2 class=\"reveal\">INSERT — 데이터 입력</h2>\n  <h3 class=\"reveal\">기본 문법</h3>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — EMP 테이블 (변경 전, 비어있음)</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">EMP</span>\n    <h4 class=\"ba-h\">사원 테이블 (변경 전)</h4>\n    <div class=\"mini-table cols-4\">\n      <div class=\"h\">EMP_ID</div><div class=\"h\">NAME</div><div class=\"h\">DEPT_ID</div><div class=\"h\">SAL</div>\n      <div class=\"c\" style=\"grid-column: 1 / -1; color: var(--fg-4);\">(0행)</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 모든 컬럼에 입력</span>\n<span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">VALUES</span> (<span class=\"sql-num\">1</span>, <span class=\"sql-str\">'김철수'</span>, <span class=\"sql-str\">'D1'</span>, <span class=\"sql-num\">3000</span>);\n<span class=\"sql-cm\">-- 1 row inserted.</span>\n\n<span class=\"sql-cm\">-- 특정 컬럼만</span>\n<span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">EMP</span> (<span class=\"sql-type\">EMP_ID</span>, <span class=\"sql-type\">NAME</span>) <span class=\"sql-kw\">VALUES</span> (<span class=\"sql-num\">2</span>, <span class=\"sql-str\">'이영희'</span>);\n<span class=\"sql-cm\">-- 1 row inserted. (DEPT_ID, SAL은 NULL 또는 DEFAULT)</span></code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 실행 후</p>\n  <table class=\"reveal\">\n    <thead><tr><th>EMP_ID</th><th>NAME</th><th>DEPT_ID</th><th>SAL</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td>김철수</td><td>D1</td><td>3000</td></tr>\n      <tr><td>2</td><td>이영희</td><td style=\"color: var(--wrong-fg);\">NULL</td><td style=\"color: var(--wrong-fg);\">NULL</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 행 2개 추가. 컬럼을 명시하지 않으면 누락된 컬럼은 NULL/DEFAULT로 채워진다.</p>\n\n  <h3 class=\"reveal\">다른 테이블에서 가져오기</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">EMP_BACKUP</span>\n<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">DEPT_ID</span> = <span class=\"sql-str\">'D1'</span>;</code></pre>\n\n  <h3 class=\"reveal\">Multi-Insert (Oracle)</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">INSERT ALL</span>\n    <span class=\"sql-kw\">INTO</span> <span class=\"sql-name\">TBL_A</span> <span class=\"sql-kw\">VALUES</span> (<span class=\"sql-num\">1</span>, <span class=\"sql-str\">'A'</span>)\n    <span class=\"sql-kw\">INTO</span> <span class=\"sql-name\">TBL_B</span> <span class=\"sql-kw\">VALUES</span> (<span class=\"sql-num\">2</span>, <span class=\"sql-str\">'B'</span>)\n<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">DUAL</span>;</code></pre>\n\n  <h2 class=\"reveal\">UPDATE — 데이터 수정</h2>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — EMP 테이블 (변경 전)</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">EMP</span>\n    <h4 class=\"ba-h\">사원 테이블 (변경 전)</h4>\n    <div class=\"mini-table cols-4\">\n      <div class=\"h\">EMP_ID</div><div class=\"h\">NAME</div><div class=\"h\">DEPT_ID</div><div class=\"h\">SAL</div>\n      <div class=\"c\">1</div><div class=\"c\">김</div><div class=\"c\">D1</div><div class=\"c\">3000</div>\n      <div class=\"c\">2</div><div class=\"c\">이</div><div class=\"c\">D1</div><div class=\"c\">4000</div>\n      <div class=\"c\">3</div><div class=\"c\">박</div><div class=\"c\">D2</div><div class=\"c\">3500</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 모든 행 수정 (위험)</span>\n<span class=\"sql-kw\">UPDATE</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">SET</span> <span class=\"sql-type\">SAL</span> = <span class=\"sql-type\">SAL</span> * <span class=\"sql-num\">1.1</span>;\n\n<span class=\"sql-cm\">-- 조건부 수정</span>\n<span class=\"sql-kw\">UPDATE</span> <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">SET</span>    <span class=\"sql-type\">SAL</span> = <span class=\"sql-type\">SAL</span> * <span class=\"sql-num\">1.1</span>\n<span class=\"sql-kw\">WHERE</span>  <span class=\"sql-type\">DEPT_ID</span> = <span class=\"sql-str\">'D1'</span>;\n\n<span class=\"sql-cm\">-- 여러 컬럼 동시 수정</span>\n<span class=\"sql-kw\">UPDATE</span> <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">SET</span>    <span class=\"sql-type\">SAL</span> = <span class=\"sql-num\">5000</span>, <span class=\"sql-type\">DEPT_ID</span> = <span class=\"sql-str\">'D2'</span>\n<span class=\"sql-kw\">WHERE</span>  <span class=\"sql-type\">EMP_ID</span> = <span class=\"sql-num\">1</span>;\n\n<span class=\"sql-cm\">-- 서브쿼리로 수정</span>\n<span class=\"sql-kw\">UPDATE</span> <span class=\"sql-name\">EMP</span>\n<span class=\"sql-kw\">SET</span>    <span class=\"sql-type\">SAL</span> = (<span class=\"sql-kw\">SELECT</span> <span class=\"sql-kw\">AVG</span>(<span class=\"sql-type\">SAL</span>) <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span>)\n<span class=\"sql-kw\">WHERE</span>  <span class=\"sql-type\">EMP_ID</span> = <span class=\"sql-num\">1</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 실행 후 (조건부 UPDATE — D1 부서만 SAL × 1.1)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>EMP_ID</th><th>DEPT_ID</th><th>SAL (변경 전)</th><th>SAL (변경 후)</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td>D1</td><td>3000</td><td>3300</td></tr>\n      <tr><td>2</td><td>D1</td><td>4000</td><td>4400</td></tr>\n      <tr><td>3</td><td>D2</td><td>3500</td><td>3500 (변경 없음)</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 행 2개 수정 (D1 두 명). <code>WHERE</code>를 빼먹으면 <strong>모든 행이 수정</strong>되므로 항상 WHERE를 확인한다.</p>\n\n  <h2 class=\"reveal\">DELETE — 데이터 삭제</h2>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — EMP 테이블 (변경 전)</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">EMP</span>\n    <h4 class=\"ba-h\">사원 테이블 (변경 전)</h4>\n    <div class=\"mini-table cols-3\">\n      <div class=\"h\">EMP_ID</div><div class=\"h\">NAME</div><div class=\"h\">DEPT_ID</div>\n      <div class=\"c\">1</div><div class=\"c\">김</div><div class=\"c\">D1</div>\n      <div class=\"c\">2</div><div class=\"c\">이</div><div class=\"c\">D1</div>\n      <div class=\"c\">9</div><div class=\"c\">최</div><div class=\"c\">D9</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 조건부 삭제</span>\n<span class=\"sql-kw\">DELETE FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">DEPT_ID</span> = <span class=\"sql-str\">'D9'</span>;\n\n<span class=\"sql-cm\">-- 모든 행 삭제(구조는 유지)</span>\n<span class=\"sql-kw\">DELETE FROM</span> <span class=\"sql-name\">EMP</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 실행 후 (DEPT_ID='D9'만 삭제)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>EMP_ID</th><th>NAME</th><th>DEPT_ID</th><th>삭제 여부</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td>김</td><td>D1</td><td>유지</td></tr>\n      <tr><td>2</td><td>이</td><td>D1</td><td>유지</td></tr>\n      <tr><td>9</td><td>최</td><td>D9</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">삭제됨</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 행 1개 삭제. 테이블 구조는 그대로 남고, COMMIT 전이라면 ROLLBACK으로 되돌릴 수 있다.</p>\n\n  <h3 class=\"reveal\">DELETE vs TRUNCATE vs DROP</h3>\n  <div class=\"threeway reveal\">\n    <div class=\"threeway-card t-correct\">\n      <div class=\"glyph\">DELETE</div>\n      <div class=\"name\">DML · 롤백 가능</div>\n      <div class=\"desc\">데이터 삭제, 테이블 구조 <strong>유지</strong>. 행 단위 처리라 <strong>느림</strong>. <code>WHERE</code>로 조건 가능</div>\n    </div>\n    <div class=\"threeway-card t-warn\">\n      <div class=\"glyph\">TRUNC</div>\n      <div class=\"name\"><a href=\"#\" data-chapter=\"c233\">DDL</a> · 롤백 불가</div>\n      <div class=\"desc\">모든 데이터 삭제, 테이블 구조 <strong>유지</strong>. 자동 COMMIT, <strong>빠름</strong></div>\n    </div>\n    <div class=\"threeway-card t-danger\">\n      <div class=\"glyph\">DROP</div>\n      <div class=\"name\">DDL · 롤백 불가</div>\n      <div class=\"desc\">테이블 자체를 <strong>삭제</strong>. 구조까지 사라짐. <strong>매우 빠름</strong></div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead><tr><th>명령</th><th>분류</th><th>데이터</th><th>테이블 구조</th><th>롤백</th><th>속도</th></tr></thead>\n    <tbody>\n      <tr><td>DELETE</td><td>DML</td><td>삭제</td><td>유지</td><td>가능</td><td>느림</td></tr>\n      <tr><td>TRUNCATE</td><td><a href=\"#\" data-chapter=\"c233\">DDL</a></td><td>모두 삭제</td><td>유지</td><td>불가</td><td>빠름</td></tr>\n      <tr><td>DROP</td><td>DDL</td><td>삭제</td><td>삭제</td><td>불가</td><td>매우 빠름</td></tr>\n    </tbody>\n  </table>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">DELETE FROM</span> <span class=\"sql-name\">EMP</span>;       <span class=\"sql-cm\">-- 데이터만, 롤백 가능</span>\n<span class=\"sql-kw\">TRUNCATE TABLE</span> <span class=\"sql-name\">EMP</span>;    <span class=\"sql-cm\">-- 데이터만, 롤백 불가</span>\n<span class=\"sql-kw\">DROP TABLE</span> <span class=\"sql-name\">EMP</span>;        <span class=\"sql-cm\">-- 테이블 자체 삭제</span></code></pre>\n\n  <h2 class=\"reveal\">MERGE — 있으면 UPDATE, 없으면 INSERT (UPSERT)</h2>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터</p>\n  <div class=\"ba-flow reveal\" style=\"grid-template-columns: 1fr 36px 1fr; align-items: stretch;\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">EMP</span>\n      <h4 class=\"ba-h\">대상 테이블 (변경 전)</h4>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">EMP_ID</div><div class=\"h\">NAME</div><div class=\"h\">SAL</div>\n        <div class=\"c\">1</div><div class=\"c\">김</div><div class=\"c\">3000</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\" style=\"font-size: 22px; color: var(--point-500);\">+</div>\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">NEW_EMP</span>\n      <h4 class=\"ba-h\">소스 테이블</h4>\n      <div class=\"mini-table cols-3\">\n        <div class=\"h\">EMP_ID</div><div class=\"h\">NAME</div><div class=\"h\">SAL</div>\n        <div class=\"c\">1</div><div class=\"c\">김</div><div class=\"c\">5000</div>\n        <div class=\"c\">2</div><div class=\"c\">이</div><div class=\"c\">4000</div>\n      </div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">MERGE INTO</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-type\">E</span>\n<span class=\"sql-kw\">USING</span> <span class=\"sql-name\">NEW_EMP</span> <span class=\"sql-type\">N</span>\n   <span class=\"sql-kw\">ON</span> (<span class=\"sql-type\">E</span>.<span class=\"sql-type\">EMP_ID</span> = <span class=\"sql-type\">N</span>.<span class=\"sql-type\">EMP_ID</span>)\n<span class=\"sql-kw\">WHEN MATCHED THEN</span>\n    <span class=\"sql-kw\">UPDATE SET</span> <span class=\"sql-type\">E</span>.<span class=\"sql-type\">SAL</span> = <span class=\"sql-type\">N</span>.<span class=\"sql-type\">SAL</span>\n<span class=\"sql-kw\">WHEN NOT MATCHED THEN</span>\n    <span class=\"sql-kw\">INSERT</span> (<span class=\"sql-type\">EMP_ID</span>, <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">SAL</span>) <span class=\"sql-kw\">VALUES</span> (<span class=\"sql-type\">N</span>.<span class=\"sql-type\">EMP_ID</span>, <span class=\"sql-type\">N</span>.<span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">N</span>.<span class=\"sql-type\">SAL</span>);</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 실행 후 (EMP에 ID=1 있음, ID=2 없음)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>NEW_EMP (소스)</th><th>EMP에 매칭?</th><th>처리</th><th>EMP 결과</th></tr></thead>\n    <tbody>\n      <tr><td>(1, '김', 5000)</td><td>O (MATCHED)</td><td>UPDATE SAL</td><td>1번 SAL → 5000</td></tr>\n      <tr><td>(2, '이', 4000)</td><td>X (NOT MATCHED)</td><td>INSERT</td><td>2번 신규 추가</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 행 1개 수정 + 1개 추가. 같은 키가 있으면 UPDATE, 없으면 INSERT — 한 번의 명령으로 두 작업을 함께 처리한다.</p>\n\n  <h3 class=\"reveal\">시각화</h3>\n  <div class=\"step-flow cols-3 reveal\">\n    <div class=\"step-card\">\n      <div class=\"step\">STEP 1</div>\n      <div class=\"name\">NEW_EMP의 행</div>\n      <div class=\"ex\">소스 테이블의 한 행을 잡는다</div>\n      <div class=\"arrow-next\">›</div>\n    </div>\n    <div class=\"step-card\">\n      <div class=\"step\">STEP 2</div>\n      <div class=\"name\">E.EMP_ID 매칭?</div>\n      <div class=\"ex\">ON 조건으로 EMP에 같은 키가 있는지 검사</div>\n      <div class=\"arrow-next\">›</div>\n    </div>\n    <div class=\"step-card\">\n      <div class=\"step\">STEP 3</div>\n      <div class=\"name\">분기 처리</div>\n      <div class=\"ex\">있음 → <strong>UPDATE</strong> / 없음 → <strong>INSERT</strong></div>\n    </div>\n  </div>\n\n  <!-- DML과 트랜잭션 -->\n  <h2 class=\"reveal\">DML과 트랜잭션</h2>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">EMP</span> ...;\n<span class=\"sql-kw\">UPDATE</span> <span class=\"sql-name\">EMP</span> ...;\n<span class=\"sql-kw\">DELETE FROM</span> <span class=\"sql-name\">EMP</span> ...;\n<span class=\"sql-kw\">COMMIT</span>;        <span class=\"sql-cm\">-- 영구 반영</span>\n<span class=\"sql-cm\">-- 또는</span>\n<span class=\"sql-kw\">ROLLBACK</span>;      <span class=\"sql-cm\">-- 취소</span></code></pre>\n  <p class=\"reveal\">DML은 <a href=\"#\" data-chapter=\"c123\">트랜잭션</a>의 대상이며 COMMIT 전까지 메모리에만 있다. COMMIT/ROLLBACK 같은 트랜잭션 제어 명령은 <a href=\"#\" data-chapter=\"c232\">TCL</a>에서 다룬다.</p>\n\n  <!-- Before & After -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">INSERT → UPDATE → DELETE 흐름</span>\n  </h2>\n  <p class=\"reveal\">3행짜리 EMP 테이블에 INSERT → UPDATE → DELETE를 순서대로 적용해 본다. D1 부서 직원(김·이) 두 명에게만 10% 인상이 들어가고, 새로 추가했던 4번 직원(최)은 마지막에 다시 삭제되는 흐름이다.</p>\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3); margin-top: 0;\">EMP (초기 상태)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>EMP_ID</th><th>NAME</th><th>DEPT_ID</th><th>SAL</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td>김</td><td>D1</td><td>3000</td></tr>\n      <tr><td>2</td><td>이</td><td>D1</td><td>4000</td></tr>\n      <tr><td>3</td><td>박</td><td>D2</td><td>3500</td></tr>\n    </tbody>\n  </table>\n  <div class=\"step-flow cols-3 reveal\">\n    <div class=\"step-card\">\n      <div class=\"step\">STEP 1 · INSERT</div>\n      <div class=\"name\"><code>VALUES (4, '최', 'D2', 4500)</code></div>\n      <div class=\"ex\">최이 4번으로 추가됨 (4행)</div>\n      <div class=\"arrow-next\">›</div>\n    </div>\n    <div class=\"step-card\">\n      <div class=\"step\">STEP 2 · UPDATE</div>\n      <div class=\"name\"><code>SAL*1.1 WHERE DEPT_ID='D1'</code></div>\n      <div class=\"ex\">D1만 김 3300 / 이 4400 (10% 인상)</div>\n      <div class=\"arrow-next\">›</div>\n    </div>\n    <div class=\"step-card\">\n      <div class=\"step\">STEP 3 · DELETE</div>\n      <div class=\"name\"><code>WHERE EMP_ID = 4</code></div>\n      <div class=\"ex\">최(4번) 다시 삭제 → 3행으로 복귀</div>\n    </div>\n  </div>\n  <div class=\"ba-flow reveal\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">INSERT 후</span>\n      <h4 class=\"ba-h\">4행으로 늘어남</h4>\n      <div class=\"mini-table cols-4\">\n        <div class=\"h\">ID</div><div class=\"h\">NAME</div><div class=\"h\">DEPT</div><div class=\"h\">SAL</div>\n        <div class=\"c\">1</div><div class=\"c\">김</div><div class=\"c\">D1</div><div class=\"c\">3000</div>\n        <div class=\"c\">2</div><div class=\"c\">이</div><div class=\"c\">D1</div><div class=\"c\">4000</div>\n        <div class=\"c\">3</div><div class=\"c\">박</div><div class=\"c\">D2</div><div class=\"c\">3500</div>\n        <div class=\"c\">4</div><div class=\"c\">최</div><div class=\"c\">D2</div><div class=\"c\">4500</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\">→</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">UPDATE → DELETE 후</span>\n      <h4 class=\"ba-h\">D1 인상 + 4번 삭제 결과</h4>\n      <div class=\"mini-table cols-4\">\n        <div class=\"h\">ID</div><div class=\"h\">NAME</div><div class=\"h\">DEPT</div><div class=\"h\">SAL</div>\n        <div class=\"c\">1</div><div class=\"c\">김</div><div class=\"c\">D1</div><div class=\"c\">3300</div>\n        <div class=\"c\">2</div><div class=\"c\">이</div><div class=\"c\">D1</div><div class=\"c\">4400</div>\n        <div class=\"c\">3</div><div class=\"c\">박</div><div class=\"c\">D2</div><div class=\"c\">3500</div>\n      </div>\n    </div>\n  </div>\n  <p class=\"reveal\">DML은 행 단위로 데이터를 바꾸지만 테이블 구조 자체는 건드리지 않는다. 위 작업들은 모두 COMMIT 전까지는 메모리에만 머물러 있어서, 잘못 친 UPDATE나 DELETE는 ROLLBACK으로 되돌릴 수 있다. 반대로 같은 \"삭제\"라도 TRUNCATE/DROP은 DDL이라 자동 COMMIT되며 되돌릴 수 없으니, 데이터만 비울지·구조까지 없앨지·되돌릴 여지를 둘지를 항상 의식해서 명령을 골라야 한다.</p>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-2-3-1\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c232: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    TCL은 <strong>트랜잭션을 제어하는 명령어</strong>들이다 (<code>COMMIT</code>, <code>ROLLBACK</code>, <code>SAVEPOINT</code>).\n  </blockquote>\n  <div class=\"ex-box reveal\">\n    워드(Word)에서 작성 중인 내용은 메모리에만 있고, <strong>저장 버튼이 COMMIT</strong>(영구 반영), <strong>CTRL+Z가 ROLLBACK</strong>(취소), 임시 저장 지점이 <strong>SAVEPOINT</strong>(부분 취소)에 해당한다.\n  </div>\n\n  <!-- 개념 도식화 — TCL 3종 카드 -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">TCL 명령어 3종</span>\n  </h2>\n  <div class=\"cls-row cols-3 reveal\">\n    <div class=\"cls-card\">\n      <span class=\"badge\">COMMIT</span>\n      <div class=\"name\">영구 반영</div>\n      <div class=\"ex\">DML을 묶어 저장 · 락 해제 · 다른 사용자도 조회 가능</div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-event\">ROLLBACK</span>\n      <div class=\"name\">취소</div>\n      <div class=\"ex\">마지막 COMMIT 이후 모든 DML 취소 · SAVEPOINT 도 사라짐</div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-info\">SAVEPOINT</span>\n      <div class=\"name\">임시 저장 지점</div>\n      <div class=\"ex\"><code>ROLLBACK TO sp</code> 로 부분 취소 가능</div>\n    </div>\n  </div>\n\n  <h3 class=\"reveal\">트랜잭션의 흐름</h3>\n  <div class=\"step-flow cols-4 reveal\">\n    <div class=\"step-card\">\n      <div class=\"step\">STEP 1</div>\n      <div class=\"name\">트랜잭션 시작</div>\n      <div class=\"ex\">DML 작업 누적 (메모리에만 존재)</div>\n      <span class=\"arrow-next\">›</span>\n    </div>\n    <div class=\"step-card\">\n      <div class=\"step\">STEP 2</div>\n      <div class=\"name\">SAVEPOINT</div>\n      <div class=\"ex\">중간 지점 표시 (필요 시 부분 취소용)</div>\n      <span class=\"arrow-next\">›</span>\n    </div>\n    <div class=\"step-card\">\n      <div class=\"step\">STEP 3-A</div>\n      <div class=\"name\">COMMIT</div>\n      <div class=\"ex\">성공 → 영구 저장 / 락 해제</div>\n      <span class=\"arrow-next\">›</span>\n    </div>\n    <div class=\"step-card\">\n      <div class=\"step\">STEP 3-B</div>\n      <div class=\"name\">ROLLBACK</div>\n      <div class=\"ex\">실패 → 마지막 COMMIT 이후 모든 변경 취소</div>\n    </div>\n  </div>\n\n  <!-- COMMIT -->\n  <h2 class=\"reveal\">COMMIT — 영구 반영</h2>\n  <p class=\"reveal\"><a href=\"#\" data-chapter=\"c231\">DML</a> 작업을 묶어서 영구 반영한다.</p>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — ACCOUNT 테이블 (변경 전)</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">ACCOUNT</span>\n    <h4 class=\"ba-h\">계좌 테이블 (변경 전)</h4>\n    <div class=\"mini-table cols-3\">\n      <div class=\"h\">ID</div><div class=\"h\">NAME</div><div class=\"h\">BALANCE</div>\n      <div class=\"c\" style=\"grid-column: 1 / -1; color: var(--fg-4);\">(0행, 비어있음)</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">VALUES</span> (<span class=\"sql-num\">1</span>, <span class=\"sql-str\">'김'</span>, <span class=\"sql-num\">3000</span>);\n<span class=\"sql-kw\">UPDATE</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">SET</span> <span class=\"sql-type\">SAL</span> = <span class=\"sql-num\">4000</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">EMP_ID</span> = <span class=\"sql-num\">1</span>;\n<span class=\"sql-kw\">COMMIT</span>;     <span class=\"sql-cm\">-- 위 두 작업을 영구 반영</span></code></pre>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ COMMIT 시점에 INSERT·UPDATE가 디스크에 영구 반영되며, 락이 풀리고 다른 사용자도 변경 결과를 조회할 수 있다.</p>\n  <table class=\"reveal\">\n    <thead>\n      <tr><th>COMMIT 후</th><th>결과</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>다른 사용자도 변경 사항을 볼 수 있음</td><td>가능</td></tr>\n      <tr><td>ROLLBACK</td><td>불가</td></tr>\n      <tr><td>락(Lock) 해제</td><td>됨</td></tr>\n    </tbody>\n  </table>\n\n  <!-- ROLLBACK -->\n  <h2 class=\"reveal\">ROLLBACK — 취소</h2>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — ACCOUNT 테이블 (변경 전)</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">ACCOUNT</span>\n    <h4 class=\"ba-h\">계좌 테이블 (변경 전 · 마지막 COMMIT 직후)</h4>\n    <div class=\"mini-table cols-3\">\n      <div class=\"h\">ID</div><div class=\"h\">NAME</div><div class=\"h\">BALANCE</div>\n      <div class=\"c\">101</div><div class=\"c\">A</div><div class=\"c\">10000</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">VALUES</span> (<span class=\"sql-num\">1</span>, <span class=\"sql-str\">'김'</span>, <span class=\"sql-num\">3000</span>);\n<span class=\"sql-kw\">DELETE FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">EMP_ID</span> = <span class=\"sql-num\">999</span>;\n<span class=\"sql-kw\">ROLLBACK</span>;   <span class=\"sql-cm\">-- 위 두 작업 모두 취소</span></code></pre>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 마지막 <code>COMMIT</code> 이후의 모든 DML이 취소된다. 메모리 상태가 마지막 COMMIT 시점으로 되돌아간다.</p>\n\n  <!-- SAVEPOINT -->\n  <h2 class=\"reveal\">SAVEPOINT — 임시 저장 지점</h2>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — EMP 테이블 (변경 전, 비어있음)</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">EMP</span>\n    <h4 class=\"ba-h\">사원 테이블 (변경 전)</h4>\n    <div class=\"mini-table cols-3\">\n      <div class=\"h\">EMP_ID</div><div class=\"h\">NAME</div><div class=\"h\">SAL</div>\n      <div class=\"c\" style=\"grid-column: 1 / -1; color: var(--fg-4);\">(0행)</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">VALUES</span> (<span class=\"sql-num\">1</span>, <span class=\"sql-str\">'김'</span>, <span class=\"sql-num\">3000</span>);\n<span class=\"sql-kw\">SAVEPOINT</span> <span class=\"sql-name\">SP1</span>;\n\n<span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">VALUES</span> (<span class=\"sql-num\">2</span>, <span class=\"sql-str\">'이'</span>, <span class=\"sql-num\">4000</span>);\n<span class=\"sql-kw\">SAVEPOINT</span> <span class=\"sql-name\">SP2</span>;\n\n<span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">VALUES</span> (<span class=\"sql-num\">3</span>, <span class=\"sql-str\">'박'</span>, <span class=\"sql-num\">5000</span>);\n\n<span class=\"sql-cm\">-- SP2 시점으로 되돌리기 (3번 INSERT만 취소)</span>\n<span class=\"sql-kw\">ROLLBACK TO</span> <span class=\"sql-name\">SP2</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 행 1개 취소(박). SP2 이후의 DML만 되돌리므로 김·이는 그대로 남는다.</p>\n\n  <h3 class=\"reveal\">SAVEPOINT → ROLLBACK TO 시퀀스</h3>\n  <div class=\"mermaid reveal\">\nsequenceDiagram\n    participant U as User\n    participant DB\n    U->>DB: INSERT (1, '김')\n    Note over DB: 김\n    U->>DB: SAVEPOINT SP1\n    Note over DB: SP1 표시\n    U->>DB: INSERT (2, '이')\n    Note over DB: 김, 이\n    U->>DB: SAVEPOINT SP2\n    Note over DB: SP2 표시\n    U->>DB: INSERT (3, '박')\n    Note over DB: 김, 이, 박\n    U->>DB: ROLLBACK TO SP2\n    Note over DB: SP2 이후만 취소<br/>→ 김, 이\n    U->>DB: COMMIT\n    Note over DB: 영구 반영 (김, 이)\n  </div>\n\n  <h3 class=\"reveal\">시점별 상태 표</h3>\n  <table class=\"reveal\">\n    <thead>\n      <tr><th>시점</th><th>상태</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>시작</td><td>EMP 비어있음</td></tr>\n      <tr><td>SP1</td><td>김</td></tr>\n      <tr><td>SP2</td><td>김, 이</td></tr>\n      <tr><td>마지막 INSERT 후</td><td>김, 이, 박</td></tr>\n      <tr><td>ROLLBACK TO SP2</td><td>김, 이</td></tr>\n    </tbody>\n  </table>\n\n  <!-- ACID -->\n  <h2 class=\"reveal\"><a href=\"#\" data-chapter=\"c123\">트랜잭션</a>의 ACID</h2>\n  <div class=\"trait-grid cols-4 reveal\">\n    <div class=\"trait-card\">\n      <div class=\"glyph\">A</div>\n      <div class=\"label\">Atomicity<br>원자성</div>\n      <div class=\"desc\">전부 또는 전무</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"glyph\">C</div>\n      <div class=\"label\">Consistency<br>일관성</div>\n      <div class=\"desc\">규칙 유지</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"glyph\">I</div>\n      <div class=\"label\">Isolation<br>고립성</div>\n      <div class=\"desc\">동시 처리 격리</div>\n    </div>\n    <div class=\"trait-card\">\n      <div class=\"glyph\">D</div>\n      <div class=\"label\">Durability<br>지속성</div>\n      <div class=\"desc\">COMMIT 후 영구</div>\n    </div>\n  </div>\n\n  <!-- 자동 커밋 -->\n  <h2 class=\"reveal\">자동 커밋 vs 명시적 커밋</h2>\n  <table class=\"reveal\">\n    <thead>\n      <tr><th>상황</th><th>Oracle</th><th>MS-SQL</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>DML 후</td><td>수동 COMMIT 필요</td><td>자동 커밋(설정 따라)</td></tr>\n      <tr><td>DDL 후</td><td>자동 COMMIT</td><td>트랜잭션 가능</td></tr>\n      <tr><td>정상 종료</td><td>자동 COMMIT</td><td>—</td></tr>\n      <tr><td>비정상 종료</td><td>자동 ROLLBACK</td><td>—</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\">Oracle에서 <code>CREATE</code>, <code>DROP</code> 같은 DDL은 <strong>자동 COMMIT</strong>된다.</p>\n\n  <!-- SQL 실전 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">계좌 트랜잭션</span>\n  </h2>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — ACCOUNT 테이블 (변경 전, 비어있음)</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">ACCOUNT</span>\n    <h4 class=\"ba-h\">계좌 테이블 (트랜잭션 시작 전)</h4>\n    <div class=\"mini-table cols-3\">\n      <div class=\"h\">ID</div><div class=\"h\">NAME</div><div class=\"h\">BALANCE</div>\n      <div class=\"c\" style=\"grid-column: 1 / -1; color: var(--fg-4);\">(0행)</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 트랜잭션 1: 정상 처리</span>\n<span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">ACCOUNT</span> <span class=\"sql-kw\">VALUES</span> (<span class=\"sql-num\">101</span>, <span class=\"sql-str\">'A'</span>, <span class=\"sql-num\">10000</span>);\n<span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">ACCOUNT</span> <span class=\"sql-kw\">VALUES</span> (<span class=\"sql-num\">102</span>, <span class=\"sql-str\">'B'</span>, <span class=\"sql-num\">5000</span>);\n<span class=\"sql-kw\">COMMIT</span>;     <span class=\"sql-cm\">-- 둘 다 저장</span>\n\n<span class=\"sql-cm\">-- 트랜잭션 2: 중간 오류</span>\n<span class=\"sql-kw\">UPDATE</span> <span class=\"sql-name\">ACCOUNT</span> <span class=\"sql-kw\">SET</span> <span class=\"sql-type\">BALANCE</span> = <span class=\"sql-type\">BALANCE</span> - <span class=\"sql-num\">1000</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">ID</span> = <span class=\"sql-num\">101</span>;\n<span class=\"sql-kw\">SAVEPOINT</span> <span class=\"sql-name\">BEFORE_DEPOSIT</span>;\n\n<span class=\"sql-kw\">UPDATE</span> <span class=\"sql-name\">ACCOUNT</span> <span class=\"sql-kw\">SET</span> <span class=\"sql-type\">BALANCE</span> = <span class=\"sql-type\">BALANCE</span> + <span class=\"sql-num\">1000</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">ID</span> = <span class=\"sql-num\">999</span>;  <span class=\"sql-cm\">-- 존재 X</span>\n\n<span class=\"sql-cm\">-- 부분 취소 후 다른 처리</span>\n<span class=\"sql-kw\">ROLLBACK TO</span> <span class=\"sql-name\">BEFORE_DEPOSIT</span>;\n<span class=\"sql-kw\">UPDATE</span> <span class=\"sql-name\">ACCOUNT</span> <span class=\"sql-kw\">SET</span> <span class=\"sql-type\">BALANCE</span> = <span class=\"sql-type\">BALANCE</span> + <span class=\"sql-num\">1000</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">ID</span> = <span class=\"sql-num\">102</span>;\n<span class=\"sql-kw\">COMMIT</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 실행 후 (ACCOUNT 잔액 시점별 변화)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>시점</th><th>ID=101 잔액</th><th>ID=102 잔액</th><th>비고</th></tr></thead>\n    <tbody>\n      <tr><td>초기</td><td>10000</td><td>5000</td><td>COMMIT 직후</td></tr>\n      <tr><td>UPDATE 101 (-1000)</td><td>9000</td><td>5000</td><td>출금</td></tr>\n      <tr><td>SAVEPOINT BEFORE_DEPOSIT</td><td>9000</td><td>5000</td><td>지점 표시</td></tr>\n      <tr><td>UPDATE 999 (+1000)</td><td>9000</td><td>5000</td><td>대상 없음 (0행)</td></tr>\n      <tr><td>ROLLBACK TO BEFORE_DEPOSIT</td><td>9000</td><td>5000</td><td>SP 이후만 취소 (101 출금은 유지)</td></tr>\n      <tr><td>UPDATE 102 (+1000)</td><td>9000</td><td>6000</td><td>이체 완료</td></tr>\n      <tr><td>COMMIT</td><td>9000</td><td>6000</td><td>영구 반영</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 101 출금은 SAVEPOINT 이전이라 살아남고, 999 갱신만 ROLLBACK TO로 취소된 뒤 102 입금으로 이체가 마무리된다.</p>\n\n  <!-- Before & After — SAVEPOINT 동작 -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">SAVEPOINT 동작</span>\n  </h2>\n  <p class=\"reveal\">비어있는 EMP에 김·이·박을 차례로 INSERT하면서 SP1, SP2 두 지점을 찍어 둔다. 마지막에 <code>ROLLBACK TO SP1</code>을 걸면 어디까지 살아남는지, 그 뒤 COMMIT까지 어떻게 이어지는지를 시점별로 추적한다.</p>\n\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3);\">작업 시나리오</p>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">VALUES</span> (<span class=\"sql-num\">1</span>, <span class=\"sql-str\">'김'</span>);\n<span class=\"sql-kw\">SAVEPOINT</span> <span class=\"sql-name\">SP1</span>;\n<span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">VALUES</span> (<span class=\"sql-num\">2</span>, <span class=\"sql-str\">'이'</span>);\n<span class=\"sql-kw\">SAVEPOINT</span> <span class=\"sql-name\">SP2</span>;\n<span class=\"sql-kw\">INSERT INTO</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">VALUES</span> (<span class=\"sql-num\">3</span>, <span class=\"sql-str\">'박'</span>);\n<span class=\"sql-kw\">ROLLBACK TO</span> <span class=\"sql-name\">SP1</span>;\n<span class=\"sql-kw\">COMMIT</span>;</code></pre>\n\n  <div class=\"ba-flow large-after reveal\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">BEFORE</span>\n      <h4 class=\"ba-h\">ROLLBACK 직전 상태</h4>\n      <div class=\"sql\">3건 INSERT 누적 (김, 이, 박)</div>\n      <div class=\"mini-table\">\n        <div class=\"h\">EMP_ID</div><div class=\"h\">NAME</div>\n        <div class=\"c\">1</div><div class=\"c\">김</div>\n        <div class=\"c\">2</div><div class=\"c\">이</div>\n        <div class=\"c\">3</div><div class=\"c\">박</div>\n      </div>\n    </div>\n    <div class=\"ba-arrow\">→</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">AFTER</span>\n      <h4 class=\"ba-h\">ROLLBACK TO SP1 후 → COMMIT</h4>\n      <div class=\"sql\">SP1 이후 INSERT 만 취소</div>\n      <div class=\"mini-table\">\n        <div class=\"h\">EMP_ID</div><div class=\"h\">NAME</div>\n        <div class=\"c\">1</div><div class=\"c\">김</div>\n      </div>\n    </div>\n  </div>\n\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3);\">시점별 상태 표</p>\n  <table class=\"reveal\">\n    <thead>\n      <tr><th>시점</th><th>데이터</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>첫 INSERT 후</td><td>김</td></tr>\n      <tr><td>SP1</td><td>김</td></tr>\n      <tr><td>둘째 INSERT 후</td><td>김, 이</td></tr>\n      <tr><td>SP2</td><td>김, 이</td></tr>\n      <tr><td>셋째 INSERT 후</td><td>김, 이, 박</td></tr>\n      <tr><td>ROLLBACK TO SP1</td><td>김</td></tr>\n      <tr><td>COMMIT</td><td>김</td></tr>\n    </tbody>\n  </table>\n\n  <p class=\"reveal\"><code>ROLLBACK TO SP1</code>은 SP1 이후의 DML(이·박 INSERT)만 취소하고 그 이전 작업은 그대로 둔다. 그래서 최종 COMMIT 시점에는 김 한 행만 남는다. 트랜잭션 도중 일부만 되돌리고 싶을 때는 SAVEPOINT로 안전 지점을 미리 찍어두는 게 핵심 — 단, 전체 ROLLBACK이나 COMMIT이 일어나면 SAVEPOINT는 모두 사라진다는 점도 함께 기억해야 한다.</p>\n\n  <!-- 격리 수준 -->\n  <h2 class=\"reveal\">트랜잭션 격리 수준 (참고)</h2>\n  <table class=\"reveal\">\n    <thead>\n      <tr><th>수준</th><th>설명</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>READ UNCOMMITTED</td><td>커밋 안 된 것도 읽음</td></tr>\n      <tr><td>READ COMMITTED</td><td>커밋된 것만(Oracle 기본)</td></tr>\n      <tr><td>REPEATABLE READ</td><td>같은 쿼리는 같은 결과</td></tr>\n      <tr><td>SERIALIZABLE</td><td>완전 격리(가장 엄격)</td></tr>\n    </tbody>\n  </table>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-2-3-2\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c233: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    DDL은 테이블·뷰·인덱스 같은 <strong>객체를 만들고 바꾸고 지우는 명령어</strong>들이다 (<code>CREATE</code>, <code>ALTER</code>, <code>DROP</code>, <code>TRUNCATE</code>, <code>RENAME</code>).\n  </blockquote>\n\n  <!-- 개념 도식화 — DDL 5종 -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">DDL 명령 5종</span>\n  </h2>\n  <div class=\"cls-row cols-4 reveal\">\n    <div class=\"cls-card\">\n      <span class=\"badge\">CREATE</span>\n      <div class=\"name\">객체 생성</div>\n      <div class=\"ex\">테이블 / 뷰 / 인덱스 등</div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-info\">ALTER</span>\n      <div class=\"name\">구조 변경</div>\n      <div class=\"ex\">컬럼 · 제약조건 추가/변경/삭제</div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-event\">DROP</span>\n      <div class=\"name\">객체 자체 삭제</div>\n      <div class=\"ex\">테이블·뷰 그 자체가 사라짐</div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-warn\">TRUNCATE</span>\n      <div class=\"name\">데이터만 비움</div>\n      <div class=\"ex\">구조 유지 · 롤백 불가 · 매우 빠름</div>\n    </div>\n  </div>\n  <div class=\"cls-row cols-2 reveal\">\n    <div class=\"cls-card\">\n      <span class=\"badge\">RENAME</span>\n      <div class=\"name\">이름 변경</div>\n      <div class=\"ex\">테이블/객체 이름 바꾸기</div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-event\">자동 COMMIT</span>\n      <div class=\"name\">DDL 공통 특성</div>\n      <div class=\"ex\">실행 즉시 영구 반영 · <code>ROLLBACK</code> 불가</div>\n    </div>\n  </div>\n\n  <h3 class=\"reveal\">DDL 자동 COMMIT 시퀀스</h3>\n  <div class=\"mermaid reveal\">\nsequenceDiagram\n    participant U as User\n    participant DB\n    participant Disk\n    Note over U,DB: (사전 DML이 있다면 함께 묶여 COMMIT 됨)\n    U->>DB: ALTER TABLE EMP ADD ...\n    DB->>DB: 펜딩 트랜잭션 자동 COMMIT\n    DB->>Disk: DDL 영구 반영\n    Note over Disk: ROLLBACK 불가\n    DB-->>U: Table altered.\n  </div>\n\n  <!-- SQL 실전 -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">CREATE / ALTER / DROP / TRUNCATE / RENAME</span>\n  </h2>\n\n  <h3 class=\"reveal\">CREATE — 객체 생성</h3>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — 데이터베이스 스키마 (변경 전, 테이블 없음)</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">SCHEMA</span>\n    <h4 class=\"ba-h\">스키마 (변경 전)</h4>\n    <div class=\"mini-table\" style=\"grid-template-columns: 1fr;\">\n      <div class=\"h\">테이블 목록</div>\n      <div class=\"c\" style=\"color: var(--fg-4);\">(EMP 없음)</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">CREATE TABLE</span> <span class=\"sql-name\">EMP</span> (\n    <span class=\"sql-type\">EMP_ID</span>    <span class=\"sql-type\">NUMBER</span>       <span class=\"sql-kw\">PRIMARY KEY</span>,\n    <span class=\"sql-type\">NAME</span>      <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">50</span>) <span class=\"sql-kw\">NOT NULL</span>,\n    <span class=\"sql-type\">SAL</span>       <span class=\"sql-type\">NUMBER</span>       <span class=\"sql-kw\">DEFAULT</span> <span class=\"sql-num\">0</span>,\n    <span class=\"sql-type\">DEPT_ID</span>   <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">10</span>),\n    <span class=\"sql-type\">HIRE_DATE</span> <span class=\"sql-type\">DATE</span>         <span class=\"sql-kw\">DEFAULT</span> <span class=\"sql-kw\">SYSDATE</span>,\n    <span class=\"sql-kw\">CONSTRAINT</span> <span class=\"sql-name\">FK_EMP_DEPT</span> <span class=\"sql-kw\">FOREIGN KEY</span> (<span class=\"sql-type\">DEPT_ID</span>) <span class=\"sql-kw\">REFERENCES</span> <span class=\"sql-name\">DEPT</span>(<span class=\"sql-type\">DEPT_ID</span>)\n);\n<span class=\"sql-cm\">-- Table created.</span></code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 실행 후 (EMP 테이블 구조)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>컬럼</th><th>자료형</th><th>제약</th></tr></thead>\n    <tbody>\n      <tr><td>EMP_ID</td><td>NUMBER</td><td>PRIMARY KEY</td></tr>\n      <tr><td>NAME</td><td>VARCHAR2(50)</td><td>NOT NULL</td></tr>\n      <tr><td>SAL</td><td>NUMBER</td><td>DEFAULT 0</td></tr>\n      <tr><td>DEPT_ID</td><td>VARCHAR2(10)</td><td>FK → DEPT(DEPT_ID)</td></tr>\n      <tr><td>HIRE_DATE</td><td>DATE</td><td>DEFAULT SYSDATE</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 5개 컬럼·1개 FK 제약을 가진 빈 테이블 생성. DDL이라 실행 즉시 자동 COMMIT.</p>\n\n  <h4 class=\"reveal\">테이블 명명 규칙</h4>\n  <table class=\"reveal\">\n    <thead>\n      <tr><th>규칙</th><th>설명</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>영문/숫자/<code>_</code>만</td><td>한글, 특수문자 불가</td></tr>\n      <tr><td>첫 글자는 영문</td><td>숫자로 시작 불가</td></tr>\n      <tr><td>예약어 사용 불가</td><td>SELECT, FROM 등</td></tr>\n      <tr><td>길이 30바이트 이내</td><td>Oracle 11g 이하 30 / 12.2+ 128 (시험은 30 기준)</td></tr>\n      <tr><td>동일 사용자 내 중복 불가</td><td>—</td></tr>\n    </tbody>\n  </table>\n\n  <!-- 제약조건 — fn-grid 인포그래픽 -->\n  <h2 class=\"reveal\">제약조건 (Constraints)</h2>\n  <div class=\"fn-grid cols-3 reveal\">\n    <div class=\"fn-card\">\n      <div class=\"name\">PRIMARY KEY</div>\n      <div class=\"desc\">기본키 = <strong>UNIQUE + NOT NULL</strong>. <a href=\"#\" data-chapter=\"c115\">식별자</a> 역할 · 테이블당 1개</div>\n      <div class=\"ex\">EMP_ID NUMBER PRIMARY KEY</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">FOREIGN KEY</div>\n      <div class=\"desc\">외래키. 부모의 PK 또는 UNIQUE 컬럼을 참조</div>\n      <div class=\"ex\">FOREIGN KEY (DEPT_ID) REFERENCES DEPT(DEPT_ID)</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">UNIQUE</div>\n      <div class=\"desc\">중복 불가. <a href=\"#\" data-chapter=\"c124\">NULL</a>은 <strong>허용</strong> · 여러 개 가능</div>\n      <div class=\"ex\">EMAIL VARCHAR2(100) UNIQUE</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">NOT NULL</div>\n      <div class=\"desc\">NULL 입력 불가</div>\n      <div class=\"ex\">NAME VARCHAR2(50) NOT NULL</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">CHECK</div>\n      <div class=\"desc\">컬럼 값이 조건을 만족해야 함</div>\n      <div class=\"ex\">CHECK (SAL &gt; 0)</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">DEFAULT</div>\n      <div class=\"desc\">값 미지정 시 기본값으로 채움</div>\n      <div class=\"ex\">SAL NUMBER DEFAULT 0</div>\n    </div>\n  </div>\n\n  <h3 class=\"reveal\">PK vs UNIQUE</h3>\n  <table class=\"reveal\">\n    <thead>\n      <tr><th>비교</th><th>PRIMARY KEY</th><th>UNIQUE</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>중복</td><td>불가</td><td>불가</td></tr>\n      <tr><td>NULL</td><td>불가</td><td>허용</td></tr>\n      <tr><td>테이블당 개수</td><td>1개</td><td>여러 개</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">FK 옵션</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">FOREIGN KEY</span> (<span class=\"sql-type\">DEPT_ID</span>) <span class=\"sql-kw\">REFERENCES</span> <span class=\"sql-name\">DEPT</span>(<span class=\"sql-type\">DEPT_ID</span>)\n    <span class=\"sql-kw\">ON DELETE CASCADE</span>       <span class=\"sql-cm\">-- 부모 삭제 시 자식도 삭제</span>\n    <span class=\"sql-kw\">ON DELETE SET NULL</span>      <span class=\"sql-cm\">-- 부모 삭제 시 자식 FK NULL</span></code></pre>\n\n  <!-- ALTER -->\n  <h2 class=\"reveal\">ALTER — 구조 변경</h2>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — EMP 테이블 (변경 전)</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">EMP</span>\n    <h4 class=\"ba-h\">사원 테이블 구조 (변경 전)</h4>\n    <div class=\"mini-table cols-2\">\n      <div class=\"h\">컬럼</div><div class=\"h\">자료형</div>\n      <div class=\"c\">EMP_ID</div><div class=\"c\">NUMBER (PK)</div>\n      <div class=\"c\">NAME</div><div class=\"c\">VARCHAR2(50)</div>\n      <div class=\"c\">SAL</div><div class=\"c\">NUMBER</div>\n      <div class=\"c\">DEPT_ID</div><div class=\"c\">VARCHAR2(10)</div>\n      <div class=\"c\">HIRE_DATE</div><div class=\"c\">DATE</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 컬럼 추가</span>\n<span class=\"sql-kw\">ALTER TABLE</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">ADD</span> (<span class=\"sql-type\">PHONE</span> <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">20</span>));\n\n<span class=\"sql-cm\">-- 컬럼 변경</span>\n<span class=\"sql-kw\">ALTER TABLE</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">MODIFY</span> (<span class=\"sql-type\">PHONE</span> <span class=\"sql-type\">VARCHAR2</span>(<span class=\"sql-num\">30</span>));\n\n<span class=\"sql-cm\">-- 컬럼 이름 변경</span>\n<span class=\"sql-kw\">ALTER TABLE</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">RENAME COLUMN</span> <span class=\"sql-type\">PHONE</span> <span class=\"sql-kw\">TO</span> <span class=\"sql-type\">MOBILE</span>;\n\n<span class=\"sql-cm\">-- 컬럼 삭제</span>\n<span class=\"sql-kw\">ALTER TABLE</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">DROP COLUMN</span> <span class=\"sql-type\">MOBILE</span>;\n\n<span class=\"sql-cm\">-- 제약조건 추가/삭제</span>\n<span class=\"sql-kw\">ALTER TABLE</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">ADD CONSTRAINT</span> <span class=\"sql-name\">UQ_NAME</span> <span class=\"sql-kw\">UNIQUE</span> (<span class=\"sql-type\">NAME</span>);\n<span class=\"sql-kw\">ALTER TABLE</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">DROP CONSTRAINT</span> <span class=\"sql-name\">UQ_NAME</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 실행 후 (명령별 EMP 컬럼 변화)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>명령</th><th>EMP 컬럼 구성</th><th>비고</th></tr></thead>\n    <tbody>\n      <tr><td>CREATE TABLE EMP</td><td>EMP_ID, NAME, SAL, DEPT_ID, HIRE_DATE</td><td>초기 5개</td></tr>\n      <tr><td>ADD (PHONE VARCHAR2(20))</td><td>+ PHONE</td><td>6개 (VARCHAR2(20))</td></tr>\n      <tr><td>MODIFY (PHONE VARCHAR2(30))</td><td>(동일)</td><td>PHONE 길이 30으로 확장</td></tr>\n      <tr><td>RENAME COLUMN PHONE TO MOBILE</td><td>… MOBILE</td><td>이름 변경</td></tr>\n      <tr><td>DROP COLUMN MOBILE</td><td>다시 5개</td><td>컬럼 제거 (ROLLBACK 불가)</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ ADD/MODIFY/RENAME COLUMN/DROP COLUMN으로 구조만 바뀐다. 모두 DDL이라 실행 즉시 자동 COMMIT 되어 되돌릴 수 없다.</p>\n\n  <!-- DROP -->\n  <h2 class=\"reveal\">DROP — 객체 삭제</h2>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — EMP 테이블 (변경 전 · 데이터 일부 존재)</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">EMP</span>\n    <h4 class=\"ba-h\">사원 테이블 (변경 전)</h4>\n    <div class=\"mini-table cols-3\">\n      <div class=\"h\">EMP_ID</div><div class=\"h\">NAME</div><div class=\"h\">SAL</div>\n      <div class=\"c\">1</div><div class=\"c\">김</div><div class=\"c\">3000</div>\n      <div class=\"c\">2</div><div class=\"c\">이</div><div class=\"c\">4000</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">DROP TABLE</span> <span class=\"sql-name\">EMP</span>;                  <span class=\"sql-cm\">-- 테이블 자체 삭제</span>\n<span class=\"sql-kw\">DROP TABLE</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">CASCADE CONSTRAINTS</span>;  <span class=\"sql-cm\">-- 참조 제약까지 함께</span>\n<span class=\"sql-kw\">DROP TABLE</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">PURGE</span>;            <span class=\"sql-cm\">-- 휴지통도 비움(복구 불가)</span></code></pre>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 객체 자체가 사라짐. 컬럼 정의·데이터·인덱스 모두 함께 삭제되며 ROLLBACK 불가.</p>\n\n  <!-- TRUNCATE -->\n  <h2 class=\"reveal\">TRUNCATE — 데이터만 비우기</h2>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — EMP 테이블 (변경 전 · 데이터 존재)</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">EMP</span>\n    <h4 class=\"ba-h\">사원 테이블 (변경 전)</h4>\n    <div class=\"mini-table cols-3\">\n      <div class=\"h\">EMP_ID</div><div class=\"h\">NAME</div><div class=\"h\">SAL</div>\n      <div class=\"c\">1</div><div class=\"c\">김</div><div class=\"c\">3000</div>\n      <div class=\"c\">2</div><div class=\"c\">이</div><div class=\"c\">4000</div>\n      <div class=\"c\">3</div><div class=\"c\">박</div><div class=\"c\">3500</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">TRUNCATE TABLE</span> <span class=\"sql-name\">EMP</span>;\n<span class=\"sql-cm\">-- Table truncated.</span></code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 실행 후 (구조 유지, 데이터만 0행)</p>\n  <div class=\"ba-side after reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">EMP</span>\n    <h4 class=\"ba-h\">사원 테이블 (TRUNCATE 후)</h4>\n    <div class=\"mini-table cols-3\">\n      <div class=\"h\">EMP_ID</div><div class=\"h\">NAME</div><div class=\"h\">SAL</div>\n      <div class=\"c\" style=\"grid-column: 1 / -1; color: var(--fg-4);\">(0행 — 컬럼 정의는 유지)</div>\n    </div>\n  </div>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 행 전부 삭제, 구조는 그대로. 자동 COMMIT 되어 ROLLBACK 불가하지만 DELETE보다 빠르다.</p>\n  <table class=\"reveal\">\n    <thead>\n      <tr><th>TRUNCATE 특징</th><th>설명</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>데이터 모두 삭제</td><td>됨</td></tr>\n      <tr><td>테이블 구조</td><td>유지</td></tr>\n      <tr><td>롤백</td><td>불가</td></tr>\n      <tr><td>속도</td><td>매우 빠름</td></tr>\n    </tbody>\n  </table>\n\n  <!-- RENAME -->\n  <h2 class=\"reveal\">RENAME — 이름 변경</h2>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">RENAME</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">TO</span> <span class=\"sql-name\">EMPLOYEE</span>;\n<span class=\"sql-kw\">ALTER TABLE</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">RENAME TO</span> <span class=\"sql-name\">EMPLOYEE</span>;  <span class=\"sql-cm\">-- 동일</span></code></pre>\n\n  <!-- DELETE vs TRUNCATE vs DROP — threeway 인포그래픽 -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">비교</span>\n    <span class=\"label-rest\">DELETE vs TRUNCATE vs DROP</span>\n  </h2>\n  <div class=\"threeway cols-3 reveal\">\n    <div class=\"threeway-card t-info\">\n      <div class=\"glyph\">DELETE</div>\n      <div class=\"name\">DML · 행 단위 삭제</div>\n      <div class=\"desc\"><strong>WHERE 가능</strong> · ROLLBACK 가능 · 자동 COMMIT 없음 · 느림</div>\n    </div>\n    <div class=\"threeway-card t-warn\">\n      <div class=\"glyph\">TRUNCATE</div>\n      <div class=\"name\">DDL · 데이터 전부 삭제</div>\n      <div class=\"desc\">구조 <strong>유지</strong> · ROLLBACK 불가 · 자동 COMMIT · 빠름</div>\n    </div>\n    <div class=\"threeway-card t-danger\">\n      <div class=\"glyph\">DROP</div>\n      <div class=\"name\">DDL · 객체 자체 삭제</div>\n      <div class=\"desc\">구조까지 <strong>삭제</strong> · ROLLBACK 불가 · 자동 COMMIT · 매우 빠름</div>\n    </div>\n  </div>\n  <table class=\"reveal\">\n    <thead>\n      <tr><th>비교</th><th>DELETE</th><th>TRUNCATE</th><th>DROP</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>분류</td><td><a href=\"#\" data-chapter=\"c231\">DML</a></td><td>DDL</td><td>DDL</td></tr>\n      <tr><td>데이터</td><td>삭제</td><td>모두 삭제</td><td>삭제</td></tr>\n      <tr><td>구조</td><td>유지</td><td>유지</td><td>삭제</td></tr>\n      <tr><td>ROLLBACK</td><td>가능</td><td>불가</td><td>불가</td></tr>\n      <tr><td>WHERE</td><td>가능</td><td>불가</td><td>—</td></tr>\n      <tr><td>속도</td><td>느림</td><td>빠름</td><td>매우 빠름</td></tr>\n      <tr><td>자동 COMMIT</td><td>없음</td><td>있음</td><td>있음</td></tr>\n    </tbody>\n  </table>\n\n  <!-- VIEW -->\n  <h2 class=\"reveal\">VIEW (뷰)</h2>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">CREATE VIEW</span> <span class=\"sql-name\">V_EMP_HIGH</span> <span class=\"sql-kw\">AS</span>\n<span class=\"sql-kw\">SELECT</span> <span class=\"sql-type\">NAME</span>, <span class=\"sql-type\">SAL</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">WHERE</span> <span class=\"sql-type\">SAL</span> &gt; <span class=\"sql-num\">5000</span>;\n\n<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">V_EMP_HIGH</span>;     <span class=\"sql-cm\">-- 사용</span>\n<span class=\"sql-kw\">DROP VIEW</span> <span class=\"sql-name\">V_EMP_HIGH</span>;</code></pre>\n  <table class=\"reveal\">\n    <thead>\n      <tr><th>뷰의 장점</th><th></th></tr>\n    </thead>\n    <tbody>\n      <tr><td>복잡한 쿼리를 간단한 이름으로</td><td>됨</td></tr>\n      <tr><td>보안(특정 컬럼/행만 노출 — <a href=\"#\" data-chapter=\"c234\">DCL</a>과 함께 권한 통제)</td><td>됨</td></tr>\n      <tr><td>실제 테이블 아님(가상)</td><td>됨</td></tr>\n    </tbody>\n  </table>\n\n  <!-- 인덱스 -->\n  <h2 class=\"reveal\">인덱스 (INDEX)</h2>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">CREATE INDEX</span> <span class=\"sql-name\">IDX_EMP_NAME</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-name\">EMP</span>(<span class=\"sql-type\">NAME</span>);\n<span class=\"sql-kw\">DROP INDEX</span> <span class=\"sql-name\">IDX_EMP_NAME</span>;</code></pre>\n  <p class=\"reveal\">도서관의 목차 같은 역할이다. 검색 속도는 빨라지지만 입력·수정 속도는 느려질 수 있다.</p>\n\n  <!-- Before & After -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">CREATE → ALTER → TRUNCATE → DROP 추적</span>\n  </h2>\n  <p class=\"reveal\">EMP_ID(PK)·NAME(NOT NULL)·SAL(DEFAULT 0)을 가진 EMP 테이블을 만들고, 거기에 PHONE 컬럼을 더한 뒤, 같은 테이블에 TRUNCATE와 DROP을 차례로 적용해 본다. <strong>데이터·구조·테이블 자체</strong>가 어느 명령에서 사라지는지를 비교한다.</p>\n\n  <div class=\"step-flow cols-4 reveal\">\n    <div class=\"step-card\">\n      <div class=\"step\">CREATE 후</div>\n      <div class=\"name\">EMP 신규 생성</div>\n      <div class=\"ex\">EMP_ID (PK)<br>NAME (NOT NULL)<br>SAL (DEFAULT 0)</div>\n      <span class=\"arrow-next\">›</span>\n    </div>\n    <div class=\"step-card\">\n      <div class=\"step\">ALTER ADD</div>\n      <div class=\"name\">컬럼 추가</div>\n      <div class=\"ex\">EMP_ID (PK)<br>NAME · SAL<br><strong>PHONE (추가됨)</strong></div>\n      <span class=\"arrow-next\">›</span>\n    </div>\n    <div class=\"step-card\">\n      <div class=\"step\">TRUNCATE</div>\n      <div class=\"name\">데이터만 비움</div>\n      <div class=\"ex\">구조 유지<br>EMP_ID · NAME · SAL · PHONE<br><strong>데이터 0행</strong></div>\n      <span class=\"arrow-next\">›</span>\n    </div>\n    <div class=\"step-card\">\n      <div class=\"step\">DROP</div>\n      <div class=\"name\">테이블 자체 삭제</div>\n      <div class=\"ex\"><strong>객체가 사라짐</strong><br>(구조 + 데이터 모두)</div>\n    </div>\n  </div>\n\n  <table class=\"reveal\">\n    <thead>\n      <tr><th>명령</th><th>구조</th><th>데이터</th><th>ROLLBACK</th></tr>\n    </thead>\n    <tbody>\n      <tr><td><code>CREATE TABLE EMP</code></td><td>신규</td><td>0행</td><td>불가 (자동 COMMIT)</td></tr>\n      <tr><td><code>ALTER ... ADD PHONE</code></td><td>컬럼 추가</td><td>유지</td><td>불가</td></tr>\n      <tr><td><code>TRUNCATE TABLE EMP</code></td><td>유지</td><td>모두 비움</td><td>불가</td></tr>\n      <tr><td><code>DROP TABLE EMP</code></td><td>객체 삭제</td><td>—</td><td>불가</td></tr>\n    </tbody>\n  </table>\n\n  <p class=\"reveal\">ALTER는 컬럼을 추가해 구조를 키우고, TRUNCATE는 데이터만 비우되 컬럼 정의(EMP_ID·NAME·SAL·PHONE)는 그대로 남기며, DROP은 테이블 객체 자체를 지운다. 셋 다 DDL이라 실행 즉시 <strong>자동 COMMIT</strong>되어 ROLLBACK으로 되돌릴 수 없다는 점이 핵심이다. \"데이터만 비우고 싶다 → TRUNCATE\", \"테이블 자체가 필요 없다 → DROP\", \"구조만 바꾼다 → ALTER\" 식으로 의도와 명령을 정확히 매칭해야 한다.</p>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-2-3-3\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
  c234: "<!-- 핵심 요약 -->\n  <h2 class=\"section-label sec-summary reveal\">\n    <span class=\"label-tag\">핵심 요약</span>\n    <span class=\"label-rest\">정의</span>\n  </h2>\n  <blockquote class=\"reveal\">\n    DCL은 <strong>사용자에게 권한을 주거나 회수하는 명령어</strong>들이다 (<code>GRANT</code>, <code>REVOKE</code>).\n  </blockquote>\n  <div class=\"ex-box reveal\">\n    사무실 출입카드처럼 <strong>신입에게 발급(GRANT)</strong>·<strong>퇴사자 회수(REVOKE)</strong>·<strong>부서별 묶음(ROLE)</strong>으로 누가 어떤 테이블을 SELECT/INSERT/UPDATE 할 수 있는지를 통제한다.\n  </div>\n\n  <!-- 개념 도식화 — GRANT vs REVOKE -->\n  <h2 class=\"section-label sec-diagram reveal\">\n    <span class=\"label-tag\">개념 도식화</span>\n    <span class=\"label-rest\">DCL 명령 2종</span>\n  </h2>\n  <div class=\"cls-row cols-2 reveal\">\n    <div class=\"cls-card\">\n      <span class=\"badge\">GRANT</span>\n      <div class=\"name\">권한 부여</div>\n      <div class=\"ex\"><code>GRANT 권한 ON 객체 TO 사용자</code> · ROLE 부여도 GRANT 로 함</div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-event\">REVOKE</span>\n      <div class=\"name\">권한 회수</div>\n      <div class=\"ex\"><code>REVOKE 권한 ON 객체 FROM 사용자</code> · WITH GRANT OPTION 시 연쇄 회수</div>\n    </div>\n  </div>\n\n  <h3 class=\"reveal\">DCL 흐름</h3>\n  <div class=\"step-flow cols-4 reveal\">\n    <div class=\"step-card\">\n      <div class=\"step\">STEP 1</div>\n      <div class=\"name\">관리자 (DBA)</div>\n      <div class=\"ex\">권한 보유자</div>\n      <span class=\"arrow-next\">›</span>\n    </div>\n    <div class=\"step-card\">\n      <div class=\"step\">STEP 2</div>\n      <div class=\"name\">GRANT / REVOKE</div>\n      <div class=\"ex\">사용자에게 직접 부여 / 회수</div>\n      <span class=\"arrow-next\">›</span>\n    </div>\n    <div class=\"step-card\">\n      <div class=\"step\">STEP 3</div>\n      <div class=\"name\">ROLE 생성·부여</div>\n      <div class=\"ex\">권한 묶음을 한 번에 관리</div>\n      <span class=\"arrow-next\">›</span>\n    </div>\n    <div class=\"step-card\">\n      <div class=\"step\">STEP 4</div>\n      <div class=\"name\">일반 사용자</div>\n      <div class=\"ex\">SELECT/INSERT/UPDATE 등 수행</div>\n    </div>\n  </div>\n\n  <!-- 권한의 종류 — layer-stack 인포그래픽 -->\n  <h2 class=\"reveal\">권한의 종류</h2>\n  <div class=\"layer-stack reveal\">\n    <div class=\"layer-stack-track\">\n      <div class=\"layer-row\">\n        <div class=\"icon\">SYS</div>\n        <div class=\"body\">\n          <div class=\"name\">시스템 권한 <small>System Privilege</small></div>\n          <div class=\"desc\">DB 자체에 대한 권한 — 접속, 객체 생성, 사용자 생성 등. 부여 시 옵션은 <strong>WITH ADMIN OPTION</strong></div>\n        </div>\n        <div class=\"arrow\">↓</div>\n      </div>\n      <div class=\"layer-row\">\n        <div class=\"icon\">OBJ</div>\n        <div class=\"body\">\n          <div class=\"name\">객체 권한 <small>Object Privilege</small></div>\n          <div class=\"desc\">특정 객체(테이블/뷰 등)에 대한 권한 — SELECT/INSERT/UPDATE/DELETE/ALTER/EXECUTE/REFERENCES. 부여 시 옵션은 <strong>WITH GRANT OPTION</strong></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <h3 class=\"reveal\">시스템 권한 (System Privilege)</h3>\n  <table class=\"reveal\">\n    <thead>\n      <tr><th>권한</th><th>의미</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>CREATE SESSION</td><td>접속 권한</td></tr>\n      <tr><td>CREATE TABLE</td><td>테이블 생성 권한</td></tr>\n      <tr><td>CREATE VIEW</td><td>뷰 생성 권한</td></tr>\n      <tr><td>CREATE USER</td><td>사용자 생성 권한</td></tr>\n      <tr><td>DROP ANY TABLE</td><td>모든 테이블 삭제 권한</td></tr>\n    </tbody>\n  </table>\n\n  <h3 class=\"reveal\">객체 권한 (Object Privilege)</h3>\n  <table class=\"reveal\">\n    <thead>\n      <tr><th>권한</th><th>의미</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>SELECT</td><td>조회</td></tr>\n      <tr><td>INSERT</td><td>입력</td></tr>\n      <tr><td>UPDATE</td><td>수정</td></tr>\n      <tr><td>DELETE</td><td>삭제</td></tr>\n      <tr><td>ALTER</td><td>변경</td></tr>\n      <tr><td>EXECUTE</td><td>프로시저/함수 실행</td></tr>\n      <tr><td>REFERENCES</td><td>FK로 참조</td></tr>\n    </tbody>\n  </table>\n\n  <!-- GRANT -->\n  <h2 class=\"section-label sec-sql reveal\">\n    <span class=\"label-tag\">SQL 실전</span>\n    <span class=\"label-rest\">GRANT / REVOKE / ROLE</span>\n  </h2>\n\n  <h3 class=\"reveal\">GRANT — 권한 부여</h3>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — USER1 권한 표 (변경 전, 권한 없음)</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">PRIVS</span>\n    <h4 class=\"ba-h\">USER1 권한 (변경 전)</h4>\n    <div class=\"mini-table cols-2\">\n      <div class=\"h\">권한</div><div class=\"h\">상태</div>\n      <div class=\"c\">CREATE SESSION</div><div class=\"c\" style=\"color: var(--wrong-fg);\">없음</div>\n      <div class=\"c\">CREATE TABLE</div><div class=\"c\" style=\"color: var(--wrong-fg);\">없음</div>\n      <div class=\"c\">SELECT ON EMP</div><div class=\"c\" style=\"color: var(--wrong-fg);\">없음</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 시스템 권한</span>\n<span class=\"sql-kw\">GRANT CREATE SESSION</span> <span class=\"sql-kw\">TO</span> <span class=\"sql-name\">USER1</span>;\n<span class=\"sql-kw\">GRANT CREATE TABLE</span>   <span class=\"sql-kw\">TO</span> <span class=\"sql-name\">USER1</span>;\n\n<span class=\"sql-cm\">-- 객체 권한</span>\n<span class=\"sql-kw\">GRANT SELECT</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">TO</span> <span class=\"sql-name\">USER1</span>;\n<span class=\"sql-kw\">GRANT SELECT</span>, <span class=\"sql-kw\">INSERT</span>, <span class=\"sql-kw\">UPDATE</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">TO</span> <span class=\"sql-name\">USER1</span>;\n\n<span class=\"sql-cm\">-- 모든 사용자에게</span>\n<span class=\"sql-kw\">GRANT SELECT</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">TO</span> <span class=\"sql-kw\">PUBLIC</span>;\n\n<span class=\"sql-cm\">-- 권한 부여 가능 권한도 함께(재부여 가능)</span>\n<span class=\"sql-kw\">GRANT SELECT</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">TO</span> <span class=\"sql-name\">USER1</span> <span class=\"sql-kw\">WITH GRANT OPTION</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 실행 후 (USER1 권한 변화)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>권한</th><th>유형</th><th>USER1 상태</th></tr></thead>\n    <tbody>\n      <tr><td>CREATE SESSION</td><td>시스템</td><td style=\"color: var(--correct-fg); font-weight: 700;\">부여됨</td></tr>\n      <tr><td>CREATE TABLE</td><td>시스템</td><td style=\"color: var(--correct-fg); font-weight: 700;\">부여됨</td></tr>\n      <tr><td>SELECT, INSERT, UPDATE ON EMP</td><td>객체</td><td style=\"color: var(--correct-fg); font-weight: 700;\">부여됨</td></tr>\n      <tr><td>SELECT ON EMP (WITH GRANT OPTION)</td><td>객체</td><td style=\"color: var(--correct-fg); font-weight: 700;\">부여 + 재부여 가능</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 시스템 권한이 먼저 있어야 접속이 되고, 객체 권한으로 개별 테이블 작업 권한이 쌓인다.</p>\n\n  <!-- 옵션 — fn-grid -->\n  <div class=\"fn-grid reveal\">\n    <div class=\"fn-card\">\n      <div class=\"name\">WITH GRANT OPTION</div>\n      <div class=\"desc\"><strong>객체 권한</strong> 부여 옵션. 받은 사람이 다른 사람에게 다시 줄 수 있음</div>\n      <div class=\"ex\">GRANT SELECT ON EMP TO USER1 WITH GRANT OPTION</div>\n    </div>\n    <div class=\"fn-card\">\n      <div class=\"name\">WITH ADMIN OPTION</div>\n      <div class=\"desc\"><strong>시스템 권한</strong> 부여 옵션. 관리자처럼 다시 부여 가능</div>\n      <div class=\"ex\">GRANT CREATE TABLE TO USER1 WITH ADMIN OPTION</div>\n    </div>\n  </div>\n\n  <!-- REVOKE -->\n  <h3 class=\"reveal\">REVOKE — 권한 회수</h3>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — USER1 권한 표 (변경 전 · 권한 보유 상태)</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">PRIVS</span>\n    <h4 class=\"ba-h\">USER1 권한 (변경 전)</h4>\n    <div class=\"mini-table cols-2\">\n      <div class=\"h\">권한</div><div class=\"h\">상태</div>\n      <div class=\"c\">CREATE TABLE</div><div class=\"c\" style=\"color: var(--correct-fg);\">부여됨</div>\n      <div class=\"c\">SELECT ON EMP</div><div class=\"c\" style=\"color: var(--correct-fg);\">부여됨</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">REVOKE SELECT</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">USER1</span>;\n<span class=\"sql-kw\">REVOKE CREATE TABLE</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">USER1</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ 두 권한 모두 회수. 다른 권한은 영향 없으며, 회수된 권한으로는 더 이상 해당 작업을 수행할 수 없다.</p>\n\n  <h4 class=\"reveal\">연쇄 회수</h4>\n  <p class=\"reveal\"><code>WITH GRANT OPTION</code>으로 다른 사람에게 부여된 권한도 함께 회수된다.</p>\n  <pre class=\"reveal\"><code>관리자 → USER1 (WITH GRANT OPTION) → USER2\n        REVOKE 시 USER2 권한도 함께 사라짐</code></pre>\n\n  <h4 class=\"reveal\">GRANT 위임 시퀀스</h4>\n  <div class=\"mermaid reveal\">\nsequenceDiagram\n    participant DBA\n    participant U1 as USER1\n    participant U2 as USER2\n    DBA->>U1: GRANT SELECT ON EMP<br/>WITH GRANT OPTION\n    Note over U1: USER1 = SELECT 가능<br/>+ 재부여 권한 보유\n    U1->>U2: GRANT SELECT ON EMP TO USER2\n    Note over U2: USER2 = SELECT 가능<br/>(USER1 통해 받음)\n    DBA->>U1: REVOKE SELECT ON EMP FROM USER1\n    Note over U1: USER1 권한 회수\n    Note over U2: USER2도 연쇄 회수<br/>(WITH GRANT OPTION)\n  </div>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (시점별 권한 상태)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>시점</th><th>USER1</th><th>USER2</th></tr></thead>\n    <tbody>\n      <tr><td>초기</td><td>없음</td><td>없음</td></tr>\n      <tr><td>DBA → USER1 (WITH GRANT OPTION)</td><td>SELECT O · 재부여 가능</td><td>없음</td></tr>\n      <tr><td>USER1 → USER2</td><td>SELECT O</td><td>SELECT O</td></tr>\n      <tr><td>DBA REVOKE FROM USER1</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">없음</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">없음 (연쇄)</td></tr>\n    </tbody>\n  </table>\n\n  <!-- ROLE -->\n  <h2 class=\"reveal\">ROLE — 권한 묶음</h2>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">예시 데이터 — 권한 표 (변경 전 · ROLE 미생성)</p>\n  <div class=\"ba-side before reveal\" style=\"max-width: 460px;\">\n    <span class=\"ba-tag\">ROLES</span>\n    <h4 class=\"ba-h\">ROLE 목록 (변경 전)</h4>\n    <div class=\"mini-table cols-2\">\n      <div class=\"h\">ROLE</div><div class=\"h\">상태</div>\n      <div class=\"c\">DEV_ROLE</div><div class=\"c\" style=\"color: var(--fg-4);\">(없음)</div>\n    </div>\n  </div>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 1. 역할 만들기</span>\n<span class=\"sql-kw\">CREATE ROLE</span> <span class=\"sql-name\">DEV_ROLE</span>;\n\n<span class=\"sql-cm\">-- 2. 역할에 권한 부여</span>\n<span class=\"sql-kw\">GRANT SELECT</span>, <span class=\"sql-kw\">INSERT</span>, <span class=\"sql-kw\">UPDATE</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-name\">EMP</span> <span class=\"sql-kw\">TO</span> <span class=\"sql-name\">DEV_ROLE</span>;\n<span class=\"sql-kw\">GRANT SELECT</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-name\">DEPT</span>                <span class=\"sql-kw\">TO</span> <span class=\"sql-name\">DEV_ROLE</span>;\n\n<span class=\"sql-cm\">-- 3. 사용자에게 역할 부여</span>\n<span class=\"sql-kw\">GRANT</span> <span class=\"sql-name\">DEV_ROLE</span> <span class=\"sql-kw\">TO</span> <span class=\"sql-name\">USER1</span>;\n<span class=\"sql-kw\">GRANT</span> <span class=\"sql-name\">DEV_ROLE</span> <span class=\"sql-kw\">TO</span> <span class=\"sql-name\">USER2</span>;\n\n<span class=\"sql-cm\">-- 회수</span>\n<span class=\"sql-kw\">REVOKE</span> <span class=\"sql-name\">DEV_ROLE</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">USER1</span>;</code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 실행 후 (사용자별 권한 상태)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>사용자</th><th>DEV_ROLE</th><th>실제 보유 권한</th></tr></thead>\n    <tbody>\n      <tr><td>USER1</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">회수됨</td><td>없음</td></tr>\n      <tr><td>USER2</td><td style=\"color: var(--correct-fg); font-weight: 700;\">유지</td><td>SELECT/INSERT/UPDATE ON EMP, SELECT ON DEPT</td></tr>\n    </tbody>\n  </table>\n  <p class=\"reveal\" style=\"font-size: 12.5px; color: var(--fg-3); margin: 0 0 12px;\">→ ROLE에 권한을 묶어 두면 한 번의 GRANT로 여러 사용자에게 일괄 부여하고, 한 번의 REVOKE로 떼어낼 수 있다.</p>\n\n  <div class=\"step-flow cols-3 reveal\">\n    <div class=\"step-card\">\n      <div class=\"step\">권한 1</div>\n      <div class=\"name\">SELECT ON EMP</div>\n      <div class=\"ex\">묶음에 포함</div>\n      <span class=\"arrow-next\">›</span>\n    </div>\n    <div class=\"step-card\">\n      <div class=\"step\">ROLE</div>\n      <div class=\"name\">DEV_ROLE</div>\n      <div class=\"ex\">권한 묶음 (단일 객체로 관리)</div>\n      <span class=\"arrow-next\">›</span>\n    </div>\n    <div class=\"step-card\">\n      <div class=\"step\">사용자</div>\n      <div class=\"name\">USER1, USER2 …</div>\n      <div class=\"ex\">한 번의 GRANT로 일괄 부여</div>\n    </div>\n  </div>\n\n  <!-- 사용자 관리 -->\n  <h2 class=\"reveal\">사용자 관리 (참고)</h2>\n  <p class=\"reveal\">CREATE USER, ALTER USER, DROP USER 자체는 <a href=\"#\" data-chapter=\"c233\">DDL</a>이지만 권한 관리와 짝을 이룬다.</p>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 사용자 생성</span>\n<span class=\"sql-kw\">CREATE USER</span> <span class=\"sql-name\">USER1</span> <span class=\"sql-kw\">IDENTIFIED BY</span> <span class=\"sql-str\">password123</span>;\n\n<span class=\"sql-cm\">-- 비밀번호 변경</span>\n<span class=\"sql-kw\">ALTER USER</span> <span class=\"sql-name\">USER1</span> <span class=\"sql-kw\">IDENTIFIED BY</span> <span class=\"sql-str\">newpass</span>;\n\n<span class=\"sql-cm\">-- 사용자 삭제</span>\n<span class=\"sql-kw\">DROP USER</span> <span class=\"sql-name\">USER1</span>;\n<span class=\"sql-kw\">DROP USER</span> <span class=\"sql-name\">USER1</span> <span class=\"sql-kw\">CASCADE</span>;     <span class=\"sql-cm\">-- 소유 객체까지 모두 삭제</span></code></pre>\n  <p class=\"reveal\">Oracle에서 사용자 = 스키마(객체 모음). 사용자 생성 권한은 DBA가 가진다.</p>\n\n  <!-- SQL 실전 — 권한 흐름 -->\n  <h3 class=\"reveal\">권한 흐름 예시</h3>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-cm\">-- 관리자(DBA)로 접속</span>\n<span class=\"sql-kw\">CREATE USER</span> <span class=\"sql-name\">STAFF</span> <span class=\"sql-kw\">IDENTIFIED BY</span> <span class=\"sql-str\">pw1234</span>;\n\n<span class=\"sql-kw\">GRANT CREATE SESSION</span> <span class=\"sql-kw\">TO</span> <span class=\"sql-name\">STAFF</span>;       <span class=\"sql-cm\">-- 접속 권한</span>\n<span class=\"sql-kw\">GRANT SELECT</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-name\">HR.EMP</span> <span class=\"sql-kw\">TO</span> <span class=\"sql-name\">STAFF</span>;     <span class=\"sql-cm\">-- HR 스키마 EMP 조회 권한</span>\n\n<span class=\"sql-cm\">-- STAFF로 접속</span>\n<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">HR.EMP</span>;     <span class=\"sql-cm\">-- 가능</span>\n\n<span class=\"sql-cm\">-- 권한 회수</span>\n<span class=\"sql-kw\">REVOKE SELECT</span> <span class=\"sql-kw\">ON</span> <span class=\"sql-name\">HR.EMP</span> <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">STAFF</span>;\n\n<span class=\"sql-kw\">SELECT</span> * <span class=\"sql-kw\">FROM</span> <span class=\"sql-name\">HR.EMP</span>;     <span class=\"sql-cm\">-- 권한 부족 에러</span></code></pre>\n  <p class=\"reveal\" style=\"font-size: 13px; color: var(--fg-3); margin: 8px 0 4px;\">↓ 결과 (STAFF의 작업 가능 여부)</p>\n  <table class=\"reveal\">\n    <thead><tr><th>시점</th><th>접속</th><th>SELECT * FROM HR.EMP</th></tr></thead>\n    <tbody>\n      <tr><td>CREATE USER 직후</td><td style=\"color: var(--wrong-fg);\">불가 (CREATE SESSION 없음)</td><td style=\"color: var(--wrong-fg);\">불가</td></tr>\n      <tr><td>GRANT CREATE SESSION</td><td>가능</td><td style=\"color: var(--wrong-fg);\">불가 (객체 권한 없음)</td></tr>\n      <tr><td>GRANT SELECT ON HR.EMP</td><td>가능</td><td style=\"color: var(--correct-fg); font-weight: 700;\">가능</td></tr>\n      <tr><td>REVOKE SELECT</td><td>가능</td><td style=\"color: var(--wrong-fg); font-weight: 700;\">ORA-00942: 권한 부족</td></tr>\n    </tbody>\n  </table>\n\n  <!-- Before & After -->\n  <h2 class=\"section-label sec-compare reveal\">\n    <span class=\"label-tag\">Before &amp; After</span>\n    <span class=\"label-rest\">USER1 권한 변화 추적</span>\n  </h2>\n  <p class=\"reveal\">방금 만들어진 USER1 계정에 권한을 한 단계씩 부여하다가 마지막에 SELECT 한 가지만 회수해 본다. <strong>시스템 권한(CREATE SESSION)이 먼저 있어야 접속 자체가 되고</strong>, 그 위에 객체 권한(SELECT/INSERT)이 올라가는 순서를 따라간다.</p>\n\n  <div class=\"ba-flow large-after reveal\">\n    <div class=\"ba-side before\">\n      <span class=\"ba-tag\">BEFORE</span>\n      <h4 class=\"ba-h\">초기 — 권한 없음</h4>\n      <div class=\"sql\">USER1 계정 생성 직후</div>\n      <div class=\"ba-row\">접속 자체 불가</div>\n      <div class=\"ba-row\">EMP 조회 불가</div>\n      <div class=\"ba-row\">EMP 입력 불가</div>\n    </div>\n    <div class=\"ba-arrow\">→</div>\n    <div class=\"ba-side after\">\n      <span class=\"ba-tag\">AFTER</span>\n      <h4 class=\"ba-h\">GRANT 누적 → 마지막에 SELECT만 REVOKE</h4>\n      <div class=\"sql\">CREATE SESSION + SELECT + INSERT → REVOKE SELECT</div>\n      <div class=\"ba-row\">접속 가능 (CREATE SESSION 유지)</div>\n      <div class=\"ba-row\">EMP 조회 <strong>불가</strong> (SELECT 회수됨)</div>\n      <div class=\"ba-row\">EMP 입력 가능 (INSERT 유지)</div>\n    </div>\n  </div>\n\n  <p class=\"reveal\" style=\"font-size: 13.5px; color: var(--fg-3);\">시점별 권한 표</p>\n  <table class=\"reveal\">\n    <thead>\n      <tr><th>시점</th><th>가능한 작업</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>초기</td><td>접속도 불가</td></tr>\n      <tr><td>GRANT CREATE SESSION 후</td><td>접속 가능</td></tr>\n      <tr><td>GRANT SELECT ON EMP 후</td><td>EMP 조회 가능</td></tr>\n      <tr><td>GRANT INSERT ON EMP 후</td><td>EMP 입력 가능</td></tr>\n      <tr><td>REVOKE SELECT ON EMP 후</td><td>EMP 조회 불가 (INSERT는 유지)</td></tr>\n    </tbody>\n  </table>\n\n  <p class=\"reveal\">권한은 <strong>\"접속(시스템 권한) → 개별 객체 작업(객체 권한)\"</strong> 순으로 쌓인다. CREATE SESSION이 없으면 SELECT 권한이 있어도 접속 자체가 안 되고, REVOKE는 해당 권한만 정확히 떼어내므로 INSERT 권한은 그대로 남는다는 점에 주의한다. WITH GRANT OPTION으로 재부여된 권한이라면 REVOKE 한 번에 <strong>연쇄적으로 회수</strong>된다는 점까지 함께 기억하면 된다.</p>\n\n  <!-- DBA의 대표 ROLE -->\n  <h2 class=\"reveal\">DBA의 대표 ROLE</h2>\n  <table class=\"reveal\">\n    <thead>\n      <tr><th>ROLE</th><th>설명</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>CONNECT</td><td>접속 권한(CREATE SESSION 포함)</td></tr>\n      <tr><td>RESOURCE</td><td>객체 생성 권한(테이블, 시퀀스 등)</td></tr>\n      <tr><td>DBA</td><td>모든 권한</td></tr>\n    </tbody>\n  </table>\n  <pre class=\"reveal\"><button class=\"copy-btn\">복사</button><code><span class=\"sql-kw\">GRANT CONNECT</span>, <span class=\"sql-kw\">RESOURCE</span> <span class=\"sql-kw\">TO</span> <span class=\"sql-name\">USER1</span>;</code></pre>\n\n  <!-- DCL vs 다른 명령어 분류 -->\n  <h2 class=\"reveal\">DCL vs 다른 명령어 분류</h2>\n  <div class=\"cls-row cols-4 reveal\">\n    <div class=\"cls-card\">\n      <span class=\"badge b-info\">DDL</span>\n      <div class=\"name\">객체</div>\n      <div class=\"ex\">CREATE · ALTER · DROP · TRUNCATE · RENAME</div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge\">DML</span>\n      <div class=\"name\">데이터</div>\n      <div class=\"ex\">INSERT · UPDATE · DELETE · MERGE · SELECT</div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-warn\">TCL</span>\n      <div class=\"name\">트랜잭션</div>\n      <div class=\"ex\">COMMIT · ROLLBACK · SAVEPOINT</div>\n    </div>\n    <div class=\"cls-card\">\n      <span class=\"badge b-event\">DCL</span>\n      <div class=\"name\">권한</div>\n      <div class=\"ex\">GRANT · REVOKE</div>\n    </div>\n  </div>\n\n  <div class=\"reveal\" style=\"margin: 40px 0 0; padding: 22px 24px; background: linear-gradient(135deg, var(--point-050), var(--bg-card)); border: 1px solid var(--point-100); border-radius: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\">\n    <div>\n      <div style=\"font-size: 12px; font-weight: 800; color: var(--point-600); letter-spacing: 0.04em; margin-bottom: 4px;\">시험 대비</div>\n      <div style=\"font-size: 14px; color: var(--fg-2);\">이 챕터의 함정·정답과 30초 정리는 통합 시험 대비 페이지에서 볼 수 있습니다.</div>\n    </div>\n    <a href=\"./exam-review.html#ch-2-3-4\" style=\"font-size: 14px; font-weight: 700; color: var(--point-600); text-decoration: none; padding: 8px 14px; border: 1px solid var(--point-300); border-radius: 8px; background: var(--bg-card); white-space: nowrap;\">시험 대비 보기 →</a>\n  </div>",
};
